/****** Object:  StoredProcedure [dbo].[IMP_SW_VALIDATION_ITEM]    Script Date: 10/12/2018 15:04:11 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create procedure [dbo].[IMP_SW_VALIDATION_ITEM]
  (       
    
      @Jobno varchar(20),@Flag varchar(200),@Branch_Type varchar(150)
     ,@xmlString VARCHAR(MAX)
     ,@xmlString_A VARCHAR(MAX)
     ,@ErrorMsg nvarchar(max) output    
   )    
 AS    
begin try    
 begin transaction    
  set @ErrorMsg=''    
  --------------------------------------------------------
if(@Flag='Item_SW')
begin 
        Declare @Temp_Control table (Id int identity(1,1), INVOICE_SLNO int,ITEM_SLNO int,CTH_NO varchar(20),AGENCY_CODE varchar(10) )
        Declare @Temp_PQIS table (Id int identity(1,1),PLC_CODE varchar(20),PLP_CODE varchar(20),PQ_UQC varchar(20) )
       
        declare @i int ,@cnt int
        DECLARE @xmlHandle_Item_SW INT ,@xmlHandle_Item_SW_PQIS INT
        --------------------------------------------------------------------------------------------------------------------------
       
		EXEC sp_xml_preparedocument @xmlHandle_Item_SW output, @xmlString 
		insert into @Temp_Control	 SELECT  INVOICE_SLNO ,ITEM_SLNO,CTH_NO ,AGENCY_CODE FROM OPENXML 
		(@xmlHandle_Item_SW, '/NewDataSet/SampleDataTable',1)WITH (
		 [INVOICE_SLNO] nvarchar(10) '@INVOICE_SLNO' 
		,[ITEM_SLNO] VARCHAR(10) '@ITEM_SLNO' 
		,[CTH_NO] VARCHAR(10) '@CTH_NO' 
		,[AGENCY_CODE] VARCHAR(10) '@AGENCY_CODE' )
		
		--------------------------------------------------------------------------------------------------------------------------
		EXEC sp_xml_preparedocument @xmlHandle_Item_SW_PQIS output, @xmlString_A 
		insert into @Temp_PQIS SELECT  PLC_CODE ,PLP_CODE,PQ_UQC FROM OPENXML 
		(@xmlHandle_Item_SW_PQIS, '/NewDataSet/SampleDataTable',1)WITH (
		 [PLC_CODE] nvarchar(10) '@PLC_CODE' 
		,[PLP_CODE] VARCHAR(10) '@PLP_CODE' 
		,[PQ_UQC] VARCHAR(10) '@PQ_UQC' 
		)
		--------------------------------------------------------------------------------------------------------------------------
	    EXEC sp_xml_removedocument @xmlHandle_Item_SW
	    EXEC sp_xml_removedocument @xmlHandle_Item_SW_PQIS	
	    --------------------------------------------------------------------------------------------------------------------------
        --select * from @Temp_PQIS
        --------------------------------------------------------------------------------------------------------------------------
        select @cnt=COUNT(INVOICE_SLNO) from @Temp_Control
        set @i=1;
        while(@i <=@cnt)
        begin
              declare @a int , @b int , @CTH_NO varchar(10)  , @AGENCY_CODE varchar(10) ,@Info_type   varchar(10),@PEC_A int
              declare @aa int ,@bb int ,@cc int,@dd int ,@ee int ,@ff int, @gg int ,@hh int --,@ii int
--------------------------------------------------------------------------------------------------------------------------
              declare @Temp_Error table (Id int identity(1,1),INVOICE_SLNO int ,ITEM_SLNO int,AGENCY_CODE varchar(10),Flag varchar(10))
	          declare @C_Code varchar(20),@D_Code varchar(20),@E_Code varchar(20),@F_Cnt int  ,@G_Code varchar(20)    
	          declare @W_A_cnt int,@W_B_cnt int,@W_C_cnt int,@W_EX_A_cnt int,@W_EX_A_Cate varchar(20) 
	          declare @F_A_cnt int ,@F_B_cnt int
	          declare @A_A_cnt int  
	          declare @C_A_cnt int ,@C_EX_A_cnt int,@C_EX_A_Cate varchar(20)                
--------------------------------------------------------------------------------------------------------------------------   

              select @a=INVOICE_SLNO ,@b=ITEM_SLNO ,@CTH_NO=CTH_NO , @AGENCY_CODE=AGENCY_CODE from @Temp_Control where Id=@i
--------------------------------------------------------------------------------------------------------------------------
              if(@Branch_Type <>'')
              begin
              
                           if(@Agency_Code='PQIS')
                            begin
                           select @Info_type = INFO_TYPE  From BE_ITEM_SW_INFO_TYPE  
                           where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b and INFO_TYPE='PEC'  and DEPARTMENT=@Agency_Code
                           and BRANCH_CODE=@Branch_Type
                           
                           if(isnull(@Info_type,'') <>'PEC')
                           begin
                           
                             --------------------------------1------------------------------------------------------------------------------------------
	                         select @aa=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
	                         and INFO_TYPE='CTG' and DEPARTMENT=@Agency_Code and BRANCH_CODE=@Branch_Type--2
	                         select @bb=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
	                         and INFO_TYPE='CHR' and DEPARTMENT=@Agency_Code and BRANCH_CODE=@Branch_Type --1
	                         select @cc=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a 
	                         and ITEM_SLNO=@b and INFO_TYPE='PNM' and DEPARTMENT=@Agency_Code and BRANCH_CODE=@Branch_Type --2
	                         --------------------------------------1------------------------------------------------------------------------------------
	                         select @dd=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b  
	                         and INFO_TYPE='CTG' and INFO_QUALIFIER='PLC' and isnull(INFO_CODE,'')<>'' and isnull(INFO_TEXT,'')='' 
	                         and isnull(INFO_MSR,'')<>'' and isnull(INFO_UQC,'')<>'' and DEPARTMENT=@Agency_Code and BRANCH_CODE=@Branch_Type
	                         
	                         select @ee=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
	                         and INFO_TYPE='CTG' and INFO_QUALIFIER='PLP' and isnull(INFO_CODE,'')<>'' 
	                         and isnull(INFO_TEXT,'')='' and isnull(INFO_MSR,'')='' and isnull(INFO_UQC,'')='' and DEPARTMENT=@Agency_Code
	                         and BRANCH_CODE=@Branch_Type
	                         
	                         select @ff=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b  
	                         and INFO_TYPE='CHR' and INFO_QUALIFIER='PLV' and isnull(INFO_CODE,'')='' 
	                         and isnull(INFO_TEXT,'')<>'' and isnull(INFO_MSR,'')='' and isnull(INFO_UQC,'')='' and DEPARTMENT=@Agency_Code
	                         and BRANCH_CODE=@Branch_Type
	                         
	                         select @gg=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b  
	                         and INFO_TYPE='PNM' and INFO_QUALIFIER='PCN' and isnull(INFO_CODE,'')<>'' 
	                         and isnull(INFO_TEXT,'')='' and isnull(INFO_MSR,'')='' and isnull(INFO_UQC,'')='' and DEPARTMENT=@Agency_Code
	                         and BRANCH_CODE=@Branch_Type
	                         
	                         select @hh=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
	                         and INFO_TYPE='PNM' and INFO_QUALIFIER='SCI' and isnull(INFO_CODE,'')='' 
	                         and isnull(INFO_TEXT,'')<>'' and isnull(INFO_MSR,'')='' and isnull(INFO_UQC,'')='' and DEPARTMENT=@Agency_Code
	                         and BRANCH_CODE=@Branch_Type
	                         -----------------------------1---------------------------------------------------------------------------------------------
	                        -- declare @C_Code varchar(20),@D_Code varchar(20),@E_Code varchar(20),@F_Cnt int  ,@G_Code varchar(20)
	                         
	                         select  @C_Code=INFO_CODE
	                               , @G_Code =INFO_UQC 
	                         from BE_ITEM_SW_INFO_TYPE 
	                         where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
	                         and INFO_TYPE ='CTG' and INFO_QUALIFIER ='PLC' and isnull(INFO_MSR,'')<>'' and isnull(INFO_UQC,'')<>''
	                         and DEPARTMENT =@AGENCY_CODE
	                         and BRANCH_CODE=@Branch_Type
	                         ---------------------------------------------------------------------------------------------
	                         select  @D_Code=INFO_CODE from BE_ITEM_SW_INFO_TYPE 
	                         where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
	                         and INFO_TYPE ='CTG' and INFO_QUALIFIER ='PLP' and isnull(INFO_TEXT,'')=''
	                         and isnull(INFO_MSR,'')='' and isnull(INFO_UQC,'')='' 
	                         and DEPARTMENT =@AGENCY_CODE and BRANCH_CODE=@Branch_Type
	                         ----------------------1-----------------------------------------------------------------------
	                         select @F_Cnt=COUNT(PLC_CODE) from @Temp_PQIS where PLC_CODE=@C_Code and PLP_CODE=@D_Code and PQ_UQC=@G_Code
	                         --------------------------------------------------------------------------------------------- 
								if(@aa =2 and @bb=1 and @cc=2 and @dd=1 and @ee =1 and @ff=1 and @gg=1 and @hh =1 and @F_Cnt=1)
								begin
									   print 'r'
								end
								else
								begin
										insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
								end
	                                --select * from @Temp_Error
								
								end
                            else   ---- PEC
                            begin
                                    select @PEC_A =COUNT(INFO_TYPE) From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')<>''  and isnull(INFO_QUALIFIER ,'')<>'' and isnull(INFO_CODE,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE and BRANCH_CODE=@Branch_Type
                                     
                                    if(@PEC_A<>1)
                                    begin
                                            insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
                                    end
                                    
                                     
                            end
                            
                    end
                    
                            else if(@Agency_Code='WCCB')
                            begin
                          -------------------------------------
                            --declare @W_A_cnt int,@W_B_cnt int,@W_C_cnt int,@W_EX_A_cnt int,@W_EX_A_Cate varchar(20)
                          
                          select @W_EX_A_Cate = INFO_TYPE  From BE_ITEM_SW_INFO_TYPE  
                          where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b and INFO_TYPE='PEC'  
                          and DEPARTMENT=@Agency_Code and BRANCH_CODE=@Branch_Type
                          
                          if(isnull(@W_EX_A_Cate,'') <>'PEC')
                           begin
                                    select @W_A_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')='PNM'  and isnull(INFO_QUALIFIER ,'')<>'' and isnull(INFO_TEXT,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE and BRANCH_CODE=@Branch_Type --2 
                                    
                                    select @W_B_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')='PNM'  and isnull(INFO_QUALIFIER ,'')='COM' and isnull(INFO_TEXT,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE and BRANCH_CODE=@Branch_Type  --1 
                                    
                                    select @W_C_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')='PNM'  and isnull(INFO_QUALIFIER ,'')='SCI' and isnull(INFO_TEXT,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE and BRANCH_CODE=@Branch_Type  --1 
                                    
                                    if(@W_A_cnt=2 and @W_B_cnt=1 and  @W_C_cnt=1)
                                    begin
                                          print 'r'
                                    end
                                    else 
                                    begin
                                          insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
                                    end
                           end
                           else if(isnull(@W_EX_A_Cate,'') ='PEC')
                           begin
                                    select @W_EX_A_cnt =COUNT(INFO_TYPE) From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')<>''  and isnull(INFO_QUALIFIER ,'')<>'' and isnull(INFO_CODE,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE and BRANCH_CODE=@Branch_Type
                                     
                                    if(@W_EX_A_cnt<>1)
                                    begin
                                            insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
                                    end
                           end   
                          ----------------------------------
                    end
                    
                     else if(@Agency_Code='FSSAI')
                    begin
                           --declare @F_A_cnt int ,@F_B_cnt int
                        
                           select @F_A_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')='CTG'  and isnull(INFO_QUALIFIER ,'')='FSP' and isnull(INFO_CODE,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE  and BRANCH_CODE=@Branch_Type
                           select @F_B_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')='CHR'  and isnull(INFO_QUALIFIER ,'')='STC' and isnull(INFO_CODE,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE and BRANCH_CODE=@Branch_Type           
                                    
							 if(@F_A_cnt=1 and @F_B_cnt =1)
							 begin
								  print 'r'
							 end
							 else
							 begin
									insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
							 end
                    end
                    else if(@Agency_Code='AQCS')
                    begin
                         -- declare @A_A_cnt int 
                        
                          select @A_A_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')='PNM'  and isnull(INFO_QUALIFIER ,'')='COM' and isnull(INFO_TEXT,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE  and BRANCH_CODE=@Branch_Type 
                          
                          if(@A_A_cnt=1)
                                    begin
                                          print 'r'
                                    end
                                    else 
                                    begin
                                          insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
                                    end
                                    
                    end
                       else if(@Agency_Code='CDRUG')
                    begin
                              --declare @C_A_cnt int ,@C_EX_A_cnt int,@C_EX_A_Cate varchar(20)
							  select @C_EX_A_Cate = INFO_TYPE  From BE_ITEM_SW_INFO_TYPE  
							  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b and INFO_TYPE='PEC'  
							  and DEPARTMENT=@Agency_Code and BRANCH_CODE=@Branch_Type 
	                          
	                          
							  if(isnull(@C_EX_A_Cate,'') <>'PEC')
							   begin
										select @C_A_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
										and isnull(INFO_TYPE,'')='CTG'  and isnull(INFO_QUALIFIER ,'')='DRC' and isnull(INFO_CODE,'')<>''
										and DEPARTMENT = @AGENCY_CODE  and BRANCH_CODE=@Branch_Type 
	                                    
										if(@C_A_cnt=1)
										begin
											  print 'r'
										end
										else 
										begin
											  insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
										end
							   end
							   else if(isnull(@C_EX_A_Cate,'') ='PEC')
							   begin
										select @C_EX_A_cnt =COUNT(INFO_TYPE) From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
										and isnull(INFO_TYPE,'')<>''  and isnull(INFO_QUALIFIER ,'')<>'' and isnull(INFO_CODE,'')<>''
										and DEPARTMENT = @AGENCY_CODE and BRANCH_CODE=@Branch_Type 
	                                     
										if(@C_EX_A_cnt<>1)
										begin
												insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
										end
							   end  
                    end
                    
                     
              end-----br e
              else
              begin
                     
                    --select @a=INVOICE_SLNO ,@b=ITEM_SLNO ,@CTH_NO=CTH_NO , @AGENCY_CODE=AGENCY_CODE from @Temp_Control where Id=@i
                     
                    if(@Agency_Code='PQIS')
                    begin
                           select @Info_type = INFO_TYPE  From BE_ITEM_SW_INFO_TYPE  
                           where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b and INFO_TYPE='PEC'  and DEPARTMENT=@Agency_Code
                           
                           if(isnull(@Info_type,'') <>'PEC')
                           begin
                           
                             --------------------------------1------------------------------------------------------------------------------------------
	                         select @aa=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
	                         and INFO_TYPE='CTG' and DEPARTMENT=@Agency_Code --2
	                         select @bb=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
	                         and INFO_TYPE='CHR' and DEPARTMENT=@Agency_Code --1
	                         select @cc=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a 
	                         and ITEM_SLNO=@b and INFO_TYPE='PNM' and DEPARTMENT=@Agency_Code --2
	                         --------------------------------------1------------------------------------------------------------------------------------
	                         select @dd=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b  
	                         and INFO_TYPE='CTG' and INFO_QUALIFIER='PLC' and isnull(INFO_CODE,'')<>'' and isnull(INFO_TEXT,'')='' 
	                         and isnull(INFO_MSR,'')<>'' and isnull(INFO_UQC,'')<>'' and DEPARTMENT=@Agency_Code
	                         
	                         select @ee=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
	                         and INFO_TYPE='CTG' and INFO_QUALIFIER='PLP' and isnull(INFO_CODE,'')<>'' 
	                         and isnull(INFO_TEXT,'')='' and isnull(INFO_MSR,'')='' and isnull(INFO_UQC,'')='' and DEPARTMENT=@Agency_Code
	                         
	                         select @ff=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b  
	                         and INFO_TYPE='CHR' and INFO_QUALIFIER='PLV' and isnull(INFO_CODE,'')='' 
	                         and isnull(INFO_TEXT,'')<>'' and isnull(INFO_MSR,'')='' and isnull(INFO_UQC,'')='' and DEPARTMENT=@Agency_Code
	                         
	                         select @gg=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b  
	                         and INFO_TYPE='PNM' and INFO_QUALIFIER='PCN' and isnull(INFO_CODE,'')<>'' 
	                         and isnull(INFO_TEXT,'')='' and isnull(INFO_MSR,'')='' and isnull(INFO_UQC,'')='' and DEPARTMENT=@Agency_Code
	                         
	                         select @hh=COUNT(INFO_TYPE)  From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
	                         and INFO_TYPE='PNM' and INFO_QUALIFIER='SCI' and isnull(INFO_CODE,'')='' 
	                         and isnull(INFO_TEXT,'')<>'' and isnull(INFO_MSR,'')='' and isnull(INFO_UQC,'')='' and DEPARTMENT=@Agency_Code
	                         -----------------------------1---------------------------------------------------------------------------------------------
	                        -- declare @C_Code varchar(20),@D_Code varchar(20),@E_Code varchar(20),@F_Cnt int  ,@G_Code varchar(20)
	                         
	                         select  @C_Code=INFO_CODE, @G_Code =INFO_UQC from BE_ITEM_SW_INFO_TYPE 
	                         where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
	                         and INFO_TYPE ='CTG' and INFO_QUALIFIER ='PLC' and isnull(INFO_MSR,'')<>'' and isnull(INFO_UQC,'')<>''
	                         and DEPARTMENT =@AGENCY_CODE
	                         ---------------------------------------------------------------------------------------------
	                         select  @D_Code=INFO_CODE from BE_ITEM_SW_INFO_TYPE 
	                         where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
	                         and INFO_TYPE ='CTG' and INFO_QUALIFIER ='PLP' and isnull(INFO_TEXT,'')=''
	                         and isnull(INFO_MSR,'')='' and isnull(INFO_UQC,'')='' 
	                         and DEPARTMENT =@AGENCY_CODE
	                         ----------------------1-----------------------------------------------------------------------
	                         select @F_Cnt=COUNT(PLC_CODE) from @Temp_PQIS where PLC_CODE=@C_Code and PLP_CODE=@D_Code and PQ_UQC=@G_Code
	                         --------------------------------------------------------------------------------------------- 
								if(@aa =2 and @bb=1 and @cc=2 and @dd=1 and @ee =1 and @ff=1 and @gg=1 and @hh =1 and @F_Cnt=1)
								begin
									   print 'r'
								end
								else
								begin
										insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
								end
	                                select * from @Temp_Error
								
								end
                            else   ---- PEC
                            begin
                                    select @PEC_A =COUNT(INFO_TYPE) From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')<>''  and isnull(INFO_QUALIFIER ,'')<>'' and isnull(INFO_CODE,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE
                                     
                                    if(@PEC_A<>1)
                                    begin
                                            insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
                                    end
                                    
                                     
                            end
                            
                    end
                    else if(@Agency_Code='WCCB')
                    begin
                          -------------------------------------
                         -- declare @W_A_cnt int,@W_B_cnt int,@W_C_cnt int,@W_EX_A_cnt int,@W_EX_A_Cate varchar(20)
                          
                          select @W_EX_A_Cate = INFO_TYPE  From BE_ITEM_SW_INFO_TYPE  
                          where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b and INFO_TYPE='PEC'  
                          and DEPARTMENT=@Agency_Code
                          
                          if(isnull(@W_EX_A_Cate,'') <>'PEC')
                           begin
                                    select @W_A_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')='PNM'  and isnull(INFO_QUALIFIER ,'')<>'' and isnull(INFO_TEXT,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE --2 
                                    
                                    select @W_B_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')='PNM'  and isnull(INFO_QUALIFIER ,'')='COM' and isnull(INFO_TEXT,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE  --1 
                                    
                                    select @W_C_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')='PNM'  and isnull(INFO_QUALIFIER ,'')='SCI' and isnull(INFO_TEXT,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE  --1 
                                    
                                    if(@W_A_cnt=2 and @W_B_cnt=1 and  @W_C_cnt=1)
                                    begin
                                          print 'r'
                                    end
                                    else 
                                    begin
                                          insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
                                    end
                           end
                           else if(isnull(@W_EX_A_Cate,'') ='PEC')
                           begin
                                    select @W_EX_A_cnt =COUNT(INFO_TYPE) From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')<>''  and isnull(INFO_QUALIFIER ,'')<>'' and isnull(INFO_CODE,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE
                                     
                                    if(@W_EX_A_cnt<>1)
                                    begin
                                            insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
                                    end
                           end   
                          ----------------------------------
                    end
                    else if(@Agency_Code='FSSAI')
                    begin
                           --declare @F_A_cnt int ,@F_B_cnt int
                        
                           select @F_A_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')='CTG'  and isnull(INFO_QUALIFIER ,'')='FSP' and isnull(INFO_CODE,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE  
                           select @F_B_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')='CHR'  and isnull(INFO_QUALIFIER ,'')='STC' and isnull(INFO_CODE,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE           
                                    
							 if(@F_A_cnt=1 and @F_B_cnt =1)
							 begin
								  print 'r'
							 end
							 else
							 begin
									insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
							 end
                    end
                    else if(@Agency_Code='AQCS')
                    begin
                          --declare @A_A_cnt int 
                          select @A_A_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
                                    and isnull(INFO_TYPE,'')='PNM'  and isnull(INFO_QUALIFIER ,'')='COM' and isnull(INFO_TEXT,'')<>''
                                    and DEPARTMENT = @AGENCY_CODE  
                          
                          if(@A_A_cnt=1)
                                    begin
                                          print 'r'
                                    end
                                    else 
                                    begin
                                          insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
                                    end
                                    
                    end
                    else if(@Agency_Code='CDRUG')
                    begin
                              --declare @C_A_cnt int ,@C_EX_A_cnt int,@C_EX_A_Cate varchar(20)
							  select @C_EX_A_Cate = INFO_TYPE  From BE_ITEM_SW_INFO_TYPE  
							  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b and INFO_TYPE='PEC'  
							  and DEPARTMENT=@Agency_Code
	                          
	                          
							  if(isnull(@C_EX_A_Cate,'') <>'PEC')
							   begin
										select @C_A_cnt=COUNT(JOBNO)  from  BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
										and isnull(INFO_TYPE,'')='CTG'  and isnull(INFO_QUALIFIER ,'')='DRC' and isnull(INFO_CODE,'')<>''
										and DEPARTMENT = @AGENCY_CODE  
	                                    
										if(@C_A_cnt=1)
										begin
											  print 'r'
										end
										else 
										begin
											  insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
										end
							   end
							   else if(isnull(@C_EX_A_Cate,'') ='PEC')
							   begin
										select @C_EX_A_cnt =COUNT(INFO_TYPE) From BE_ITEM_SW_INFO_TYPE  where JOBNO=@Jobno and INVOICE_SLNO=@a and ITEM_SLNO=@b 
										and isnull(INFO_TYPE,'')<>''  and isnull(INFO_QUALIFIER ,'')<>'' and isnull(INFO_CODE,'')<>''
										and DEPARTMENT = @AGENCY_CODE
	                                     
										if(@C_EX_A_cnt<>1)
										begin
												insert into @Temp_Error select @a ,@b ,@AGENCY_CODE,'F'
										end
							   end  
                    end
                     
              end --brelse
              
              set @i=@i+1;
        end
        
        select * from @Temp_Error 
        
end	
--------------------------------------------------------
  commit    
end try    
begin catch    
rollback transaction    
 set @ErrorMsg=error_message()    
 --set @MStatus=0    
end catch

/****** Object:  StoredProcedure [dbo].[SP_EXPORT_CHECKLIST_SEARCH_HTMLVIEW]    Script Date: 10/12/2018 15:06:01 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create PROCEDURE [dbo].[SP_EXPORT_CHECKLIST_SEARCH_HTMLVIEW]

	@JOBNO	varchar(35),@Working_Period varchar(30),@name 	varchar(300),@TRANSPORT_MODE varchar(50),@CUSTOM_HOUSE varchar(50),	@Mstatus  int output,
	@STR_status  int output,@ErrorMsg nvarchar(max) output	
AS
begin try
	begin transaction
		set @ErrorMsg=''
		declare @jobid as bigint declare @AIR_JOBNO varchar(10),@SEA_JOBNO varchar(10) DECLARE @NewLineChar AS CHAR(2) = CHAR(13) + CHAR(10)

if(@Working_Period<>'')
begin
if(@name='select_jobno')
	begin
	    SELECT distinct(JOBNO),JOBNO_PS FROM EXPORT_GENERAL_DETAILS where  BRANCHCODE=@Working_Period order by JOBNO desc 
end
else if(@name='Select_Inv_Item_Value_Chk') 
begin
     select a.INVOICE_SLNO ,cast(a.INVOICE_VALUE AS decimal(18,2)) INVOICE_VALUE ,b.Product_Value from EXPORT_INVOICE_DETAILS a left outer join
	(select INVOICE_SLNO , cast( sum((cast(Convert(NUMERIC(25,5),CASE  WHEN ISNULL(ITEM_UNIT_PRICE,'') =''  THEN   '0' else ISNULL(ITEM_UNIT_PRICE,'0') end)
	 * Convert(NUMERIC(25,3),CASE  WHEN ISNULL(ITEM_QTY,'') =''  THEN   '0' else ISNULL(ITEM_QTY,'0') end) AS decimal(18,2)))
	 /Convert(NUMERIC(25,5),CASE  WHEN ISNULL(ITEM_PER,'') =''  THEN   '0' else ISNULL(ITEM_PER,'0') end)) as decimal(19,2)) as Product_Value
	from EXPORT_ITEM_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period group by INVOICE_SLNO  ) b on a.INVOICE_SLNO=b.INVOICE_SLNO
where a.JOBNO=@JOBNO and BRANCH_CODE=@Working_Period and case when cast(a.INVOICE_VALUE AS decimal(18,2)) =b.Product_Value  then 'T' else 'F' end ='F'  order by a.INVOICE_SLNO asc
end
else if(@name='select_FileRefNo_Dispatch')
	begin
	SELECT distinct(FILE_REF_NO) FROM EXPORT_GENERAL_DETAILS where  BRANCHCODE=@Working_Period order by FILE_REF_NO desc
end
else if(@name='select_jobno_CheckList')
	begin
		 SELECT CUSTOMS_HOUSE,TRANSPORT_MODE, EXPORTER_NAME,CONSIGNEE_NAME,Convert(varchar(11),JOBDATE, 112)JOBDATE
		  ,Convert(varchar(11),JOBDATE, 103)JOBDATE1,IEC_NO  FROM EXPORT_GENERAL_DETAILS where JOBNO=@JOBNO and BRANCHCODE=@Working_Period 
		SELECT ITEM_SCHEME_CODE FROM EXPORT_ITEM_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period 
		SELECT COUNT(INVOICE_NO) INVOICE_NO FROM EXPORT_INVOICE_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period 
		SELECT COUNT(ITEM_SLNO) ITEM_SLNO FROM EXPORT_ITEM_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period 
		SELECT null as PMV_VALUE FROM EXPORT_ITEM_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period  and isnull(PMV_VALUE,'')=''
end
else if(@name='select_Combine_jobno_Flatfile')
	begin
		SELECT CUSTOMS_HOUSE,TRANSPORT_MODE, EXPORTER_NAME,CONSIGNEE_NAME,Convert(varchar(11),JOBDATE, 112)JOBDATE 	,Convert(varchar(11),JOBDATE, 103)JOBDATE1,IEC_NO
		FROM EXPORT_GENERAL_DETAILS where JOBNO=@JOBNO and BRANCHCODE=@Working_Period 
		SELECT ITEM_SCHEME_CODE FROM EXPORT_ITEM_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period 
		SELECT COUNT(INVOICE_NO) INVOICE_NO	FROM EXPORT_INVOICE_DETAILS where JOBNO in(select item from dbo.fnSplit(@TRANSPORT_MODE, ','))  and BRANCH_CODE=@Working_Period 
		SELECT COUNT(ITEM_SLNO) ITEM_SLNO FROM EXPORT_ITEM_DETAILS where JOBNO in(select item from dbo.fnSplit(@TRANSPORT_MODE, ',')) and BRANCH_CODE=@Working_Period 
        SELECT null as PMV_VALUE FROM EXPORT_ITEM_DETAILS where JOBNO in(select item from dbo.fnSplit(@TRANSPORT_MODE, ',')) and BRANCH_CODE=@Working_Period  and isnull(PMV_VALUE,'')=''
end
else if(@name='Checklist')

-- TABLE =0
	begin
	SELECT @AIR_JOBNO=ANNEX_AIR_JOBNO  FROM EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO=@JOBNO and FLAG='Active' and BRANCH_CODE=@Working_Period
	SELECT @SEA_JOBNO=ANNEX_SEA_JOBNO  FROM EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO=@JOBNO and FLAG='Active' and BRANCH_CODE=@Working_Period
	if(@AIR_JOBNO!='')
	begin
		SELECT distinct
		Convert(varchar(11),JOBDATE, 103) JOBDATE,REPLACE(convert(VARCHAR,RBI_WAIVER_DATE,103),'01/01/1900','') as RBI_WAIVER_DATE,
		Air.ANNEX_AIR_GROSS_WEIGHT+' '+Air.ANNEX_AIR_GR_UNIT_CODE as GROSS_WEIGHT,Air.ANNEX_AIR_NET_WEIGHT+' '+Air.ANNEX_AIR_GR_UNIT_CODE AS NET_WEIGHT,
		Air.ANNEX_AIR_NATURE_OF_CARGO AS NATURE_OF_CARGO,
		case when Air.ANNEX_AIR_NATURE_OF_CARGO ='P' then 'P Packaged'
			 when Air.ANNEX_AIR_NATURE_OF_CARGO ='C' then 'C Containerized'
			 when Air.ANNEX_AIR_NATURE_OF_CARGO ='CP' then 'CP Containerized'
			 when Air.ANNEX_AIR_NATURE_OF_CARGO ='LB' then 'LB Liquid and Bulk'
			 when Air.ANNEX_AIR_NATURE_OF_CARGO ='DB' then 'DB Dry Bulk'
			 end as NATURE_OF_CARGO_NEW
		
		,Air.ANNEX_AIR_MARKS_NOS AS MARKS_NOS,Air.ANNEX_AIR_TOTAL_PACKAGES AS TOTAL_PACKAGES,
		Air.ANNEX_AIR_MAWB_NO AS ANNEX_AIR_MAWB_NO,Air.ANNEX_AIR_HAWB_NO AS ANNEX_AIR_HAWB_NO 
		,'' as SEAL_TYPE , '' as LOOSE_PACKETS , '' as NO_CONTAINERS
		,SB.SB_NO,Convert(varchar(11),SB.SB_DATE, 103)SB_DATE,CLIENT.IMP_EXP_PAN_NO,
		General.JOBID,General.JOBNO,General.JOBDATE,General.TRANSPORT_MODE,General.CUSTOMS_HOUSE,
		General.CUSTOMS_HOUSE_NAME,General.SB_TYPE,General.EXPORTER_NAME,General.BRANCH_NO,General.IEC_NO,
		General.ADDRESS1,General.ADDRESS2,General.ADDRESS3,General.ADDRESS4,General.ADDRESS5,General.ADCODE,
		General.BANK_ACCOUNT,General.DRAWBACK_ACCOUNT,General.CONSIGNEE_NAME,General.CONSIGNEE_ADD1,General.CONSIGNEE_ADD2,
		General.CONSIGNEE_ADD3,General.CONSIGNEE_ADD4,General.CONSIGNEE_ADD5,General.COUNTRY_DISCHARGE,General.PORT_DISCHARGE,
		General.COUNTRY_FINAL_DEST,General.PORT_FINAL_DEST,General.STATE_OF_EXPORT,General.NFEI,General.NFEI_TYPE,
		General.RBI_WAIVER_NO,REPLACE(convert(VARCHAR,General.RBI_WAIVER_DATE,103),'01/01/1900','')as RBI_WAIVER_DATE,General.MARKS_NO,General.BRANCHCODE,General.WORKINGPERIOD,
		General.FILE_REF_NO,General.JOB_STATUS,General.JOB_RELEASE,General.JOB_FILED_STATUS,
		General.TYPE_OF_EXPORTER,		
		case when General.TYPE_OF_EXPORTER='R' then '[R] - Merchant' else '[F] - Manufacturer' end as  TYPE_OF_EXPORTER_New,
		General.JOB_PREFIX,General.JOB_SUFFIX,General.JOBNO_PS,General.CONSIGNEE_BRANCHSLNO,
		General.GSTN_TYPE,General.GSTN_ID,General.PARTY_REF_NO,General.CARTING_POINT
		, convert(varchar(10),GETDATE(),103) printdate
		
		FROM EXPORT_GENERAL_DETAILS General join  EXPORT_ANNEXURE_C_AIR as Air on General.JOBNO=Air.ANNEX_AIR_JOBNO  and general.BRANCHCODE=Air.BRANCH_CODE
		left join
		EXPORT_SB_ENTRY SB on SB.SB_JOBNO=General.JOBNO  and general.BRANCHCODE=SB.BRANCH_CODE
		left join IMP_EXP_MASTER CLIENT ON CLIENT.IMP_EXP_NAME=General.EXPORTER_NAME and CLIENT.IMP_EXP_BRSLNO=General.BRANCH_NO
		where JOBNO=@JOBNO and BRANCHCODE=@Working_Period order by JOBNO
	
	
	set @MStatus=1
	end
	
	else if(@SEA_JOBNO!='')
	begin
	
		SELECT distinct
		Convert(varchar(11),JOBDATE, 103) JOBDATE,REPLACE(convert(VARCHAR,RBI_WAIVER_DATE,103),'01/01/1900','')as RBI_WAIVER_DATE,
		Sea.ANNEX_SEA_GROSS_WEIGHT+' '+ANNEX_SEA_UNIT_MEASUREMENT as GROSS_WEIGHT,
		Sea.ANNEX_SEA_NET_WEIGHT+' '+ANNEX_SEA_UNIT_MEASUREMENT as NET_WEIGHT,
		Sea.ANNEX_SEA_NATURE_OF_CARGO as NATURE_OF_CARGO,
		case when Sea.ANNEX_SEA_NATURE_OF_CARGO ='P' then 'P Packaged'
			 when Sea.ANNEX_SEA_NATURE_OF_CARGO ='C' then 'C Containerized'
			 when Sea.ANNEX_SEA_NATURE_OF_CARGO ='CP' then 'CP Containerized'
			 when Sea.ANNEX_SEA_NATURE_OF_CARGO ='LB' then 'LB Liquid and Bulk'
			 when Sea.ANNEX_SEA_NATURE_OF_CARGO ='DB' then 'DB Dry Bulk'
			 end as NATURE_OF_CARGO_NEW,
			 
		Sea.ANNEX_SEA_MARKS_NOS as MARKS_NOS,
		Sea.ANNEX_SEA_TOTAL_PACKAGES as TOTAL_PACKAGES,Sea.ANNEX_SEA_LOOSE_PACKETS as LOOSE_PACKETS,
		Sea.ANNEX_SEA_NO_CONTAINERS as NO_CONTAINERS, 
		Sea.ANNEX_SEA_SEAL_TYPE as SEAL_TYPE, 
		''  AS ANNEX_AIR_MAWB_NO,'' AS ANNEX_AIR_HAWB_NO ,
		SB.SB_NO,Convert(varchar(11),SB.SB_DATE, 103)SB_DATE,CLIENT.IMP_EXP_PAN_NO,
		General.JOBID,General.JOBNO,General.JOBDATE,General.TRANSPORT_MODE,General.CUSTOMS_HOUSE,
		General.CUSTOMS_HOUSE_NAME,General.SB_TYPE,General.EXPORTER_NAME,General.BRANCH_NO,General.IEC_NO,
		General.ADDRESS1,General.ADDRESS2,General.ADDRESS3,General.ADDRESS4,General.ADDRESS5,General.ADCODE,
		General.BANK_ACCOUNT,General.DRAWBACK_ACCOUNT,General.CONSIGNEE_NAME,General.CONSIGNEE_ADD1,General.CONSIGNEE_ADD2,
		General.CONSIGNEE_ADD3,General.CONSIGNEE_ADD4,General.CONSIGNEE_ADD5,General.COUNTRY_DISCHARGE,General.PORT_DISCHARGE,
		General.COUNTRY_FINAL_DEST,General.PORT_FINAL_DEST,General.STATE_OF_EXPORT,General.NFEI,General.NFEI_TYPE,
		General.RBI_WAIVER_NO,REPLACE(convert(VARCHAR,General.RBI_WAIVER_DATE,103),'01/01/1900','')as RBI_WAIVER_DATE,General.MARKS_NO,General.BRANCHCODE,General.WORKINGPERIOD,
		General.FILE_REF_NO,General.JOB_STATUS,General.JOB_RELEASE,General.JOB_FILED_STATUS,
		General.TYPE_OF_EXPORTER,
		case when General.TYPE_OF_EXPORTER='R' then '[R] - Merchant' else '[F] - Manufacturer' end as  TYPE_OF_EXPORTER_New,
		General.JOB_PREFIX,General.JOB_SUFFIX,General.JOBNO_PS,General.CONSIGNEE_BRANCHSLNO,
		General.GSTN_TYPE,General.GSTN_ID,General.PARTY_REF_NO,General.CARTING_POINT
		, convert(varchar(10),GETDATE(),103) printdate
		
		FROM EXPORT_GENERAL_DETAILS General 
		join  EXPORT_ANNEXURE_C_SEA as Sea on General.JOBNO=Sea.ANNEX_SEA_JOBNO   and general.BRANCHCODE=Sea.BRANCH_CODE
		left join
		EXPORT_SB_ENTRY SB on SB.SB_JOBNO=General.JOBNO  and general.BRANCHCODE=SB.BRANCH_CODE
		left join IMP_EXP_MASTER CLIENT ON CLIENT.IMP_EXP_NAME=General.EXPORTER_NAME and CLIENT.IMP_EXP_BRSLNO=General.BRANCH_NO
		where JOBNO=@JOBNO and BRANCHCODE=@Working_Period order by JOBNO

		set @MStatus=1
	end
	else
	begin
		SELECT distinct
		Convert(varchar(11),JOBDATE, 103)JOBDATE,REPLACE(convert(VARCHAR,RBI_WAIVER_DATE,103),'01/01/1900','')as RBI_WAIVER_DATE,
		
		'' as GROSS_WEIGHT,'' as NET_WEIGHT,'' as NATURE_OF_CARGO,'' as NATURE_OF_CARGO_NEW,'' as MARKS_NOS,
		'' as TOTAL_PACKAGES,'' as LOOSE_PACKETS,'' as NO_CONTAINERS, '' as SEAL_TYPE ,	
		''  AS ANNEX_AIR_MAWB_NO,'' AS ANNEX_AIR_HAWB_NO ,
		
		SB.SB_NO,Convert(varchar(11),SB.SB_DATE, 103)SB_DATE,CLIENT.IMP_EXP_PAN_NO,
		General.JOBID,General.JOBNO,General.JOBDATE,General.TRANSPORT_MODE,General.CUSTOMS_HOUSE,
		General.CUSTOMS_HOUSE_NAME,General.SB_TYPE,General.EXPORTER_NAME,General.BRANCH_NO,General.IEC_NO,
		General.ADDRESS1,General.ADDRESS2,General.ADDRESS3,General.ADDRESS4,General.ADDRESS5,General.ADCODE,
		General.BANK_ACCOUNT,General.DRAWBACK_ACCOUNT,General.CONSIGNEE_NAME,General.CONSIGNEE_ADD1,General.CONSIGNEE_ADD2,
		General.CONSIGNEE_ADD3,General.CONSIGNEE_ADD4,General.CONSIGNEE_ADD5,General.COUNTRY_DISCHARGE,General.PORT_DISCHARGE,
		General.COUNTRY_FINAL_DEST,General.PORT_FINAL_DEST,General.STATE_OF_EXPORT,General.NFEI,General.NFEI_TYPE,
		General.RBI_WAIVER_NO,REPLACE(convert(VARCHAR,General.RBI_WAIVER_DATE,103),'01/01/1900','')as RBI_WAIVER_DATE,General.MARKS_NO,General.BRANCHCODE,General.WORKINGPERIOD,
		General.FILE_REF_NO,General.JOB_STATUS,General.JOB_RELEASE,General.JOB_FILED_STATUS,
		General.TYPE_OF_EXPORTER,
		case when General.TYPE_OF_EXPORTER='R' then '[R] - Merchant' else '[F] - Manufacturer' end as  TYPE_OF_EXPORTER_New,
		General.JOB_PREFIX,General.JOB_SUFFIX,General.JOBNO_PS,General.CONSIGNEE_BRANCHSLNO,
		General.GSTN_TYPE,General.GSTN_ID,General.PARTY_REF_NO,General.CARTING_POINT
		, convert(varchar(10),GETDATE(),103) printdate
		 
		FROM EXPORT_GENERAL_DETAILS General
		left join
		EXPORT_SB_ENTRY SB on SB.SB_JOBNO=General.JOBNO and general.BRANCHCODE=SB.BRANCH_CODE
		left join IMP_EXP_MASTER CLIENT ON CLIENT.IMP_EXP_NAME=General.EXPORTER_NAME and CLIENT.IMP_EXP_BRSLNO=General.BRANCH_NO
		where JOBNO=@JOBNO and General.BRANCHCODE=@Working_Period order by JOBNO
	set @MStatus=2
	end
		

---------EXPORT INVOICE_DETAILS-------------------------

-- TABLE =1
SELECT (SELECT  count(INVOICE_NO) FROM EXPORT_INVOICE_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period )No_Of_Invoices,
	INVOICE_NO,	Convert(varchar(11),INVOICE_DATE, 103)INVOICE_DATE,INVOICE_VALUE,
 * FROM EXPORT_INVOICE_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period order by JOBNO,INVOICE_SLNO
 
 
 --------EXPORT ITEM DETAILS----------------------------
 -- TABLE =2
	SELECT Convert(varchar(11),ITEM_AR4_DATE, 103) ITEM_AR4_DATE,ITEM_ID, JOBNO, INVOICE_SLNO, INVOICE_NO, ITEM_SLNO, ITEM_DESCRIPTION, RITCNO, ITEM_QTY, ITEM_QTY_CODE, ITEM_UNIT_PRICE, ITEM_PER, ITEM_AMOUNT, ITEM_PMVVALUE, ITEM_SCHEME_CODE, ITEM_ACCESSORIES_DESC, ITEM_AR4_NO, ITEM_AR4_DATE, ITEM_COMMISSION_RATE, ITEM_DIVISION, ITEM_RANGE, ITEM_REMARKS, ITEM_IECCODE, ITEM_EXPORTER_NAME, BR_SLNO, ADDRESS1, ADDRESS2, ADDRESS3, ADDRESS4, ADDRESS5, ITEM_STR_CODE, REWARD_POINTS,  BRANCH_CODE,  	PMV_VALUE, FOB_VALUE, DRAWBACK_VALUE, CESS_YN, STR_RATE, STR_AMOUNT, MANUFACTURER_PRODUCER, M_P_GROWER_CODE, M_P_GROWER_ADD1, M_P_GROWER_ADD2, M_P_GROWER_CITY, M_P_GROWER_COUNTRY_SUBDIV, M_P_GROWER_PIN, M_P_GROWER_COUNTRY, SOURCE_STATE, TRANSIT_COUNTRY, ACCESSORY_STATUS, HAWB_NO, TOTAL_PKGS, ENDUSE_ITEM, IGST_PAYMENT, TAXABLE_VALUE, IGST_AMT, GSTN_TYPE, GSTN_ID
	 FROM EXPORT_ITEM_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period order by JOBNO,INVOICE_SLNO,ITEM_SLNO
	
 --------EXPORT LICENSE DETAILS-------------------------
 
 -- TABLE =3
 SELECT Convert(varchar(11),LICENSE_DATE, 103)LICENSE_DATE,* FROM EXPORT_LICENSE_DETAILS 
 where JOB_NO=@JOBNO and BRANCH_CODE=@Working_Period order by JOB_NO,INV_SL_NO,ITEM_SL_NO
 
 ;with ss as(
 SELECT distinct a.*
FROM EXPORT_LICENSE_IMP_EXP_DETAILS a, EXPORT_LICENSE_DETAILS b
WHERE  a.JOB_NO=@JOBNO  and a.BRANCH_CODE=@Working_Period 
 )select * from ss order by  LICENSE_E_SL_NO,CAST( LICENSE_IMP_ITEM_SL_NO as int) 
 
 --------EXPORT DRAWBACK DETAILS------------------------
 SELECT * FROM EXPORT_DRAWBACK_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period order by JOBNO,INVOICE_SLNO,ITEM_SLNO
 --------EXPORT JOBBING DETAILS-------------------------
 SELECT Convert(varchar(11),BE_DATE, 103)BE_DATE,* FROM EXPORT_JOBBING where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period order by JOBNO,INVOICE_SLNO,ITEM_SLNO
 --------EXPORT STR DETAILS-------------------------
if not exists(SELECT ITEM_STR_CODE FROM EXPORT_ITEM_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period)
begin
set @STR_status=1
end
else
begin
set @STR_status=2
end
 --------EXPORT ANNEXURE C1 DETAILS-------------------------
SELECT Convert(varchar(11),ANNEX_EXAM_DATE, 103)ANNEX_EXAM_DATE, 
ANNEX_ID,  ANNEX_JOBNO,  ANNEX_EXPORTERNAME,  ANNEX_IECCODE,  ANNEX_BR_SLNO,  ANNEX_EXAM_DATE,  ANNEX_EXAM_OFFICER,  ANNEX_EXAM_DESIGN,  ANNEX_SUPER_NAME,  ANNEX_SUPER_DESIGN,  ANNEX_COMMISSION_RATE,  ANNEX_DIVISION,  ANNEX_RANGE,  ANNEX_VERIFIED_EXAM_OFFICER,  ANNEX_SAMPLE_DRAWN,  ANNEX_SEAL_NO,  ANNEX_ADDRESS1,  ANNEX_ADDRESS2,  ANNEX_ADDRESS3,  
ANNEX_ADDRESS4 , case when Substring(annex_address4, 1,Charindex('--', annex_address4)+1) ='--' then '' 
else Substring(annex_address4, 1,Charindex('--', annex_address4)+1)
end as ANNEX_ADDRESS4New,
Substring(annex_address4, Charindex('--', annex_address4)+2, LEN(annex_address4)) as  ANNEX_ADDRESS5New

 FROM ANNEXURE_C1_DETAILS 
where ANNEX_JOBNO=@JOBNO and BRANCH_CODE=@WORKING_PERIOD
---------------------------------------------FOR EXPORT ANNEXURE REPORT------------------------------------------------------------------
select top 1 ITEM_EXPORTER_NAME from EXPORT_ITEM_DETAILS 
where JOBNO=@JOBNO and BRANCH_CODE=@WORKING_PERIOD and ITEM_EXPORTER_NAME NOT IN('')
---------------------------------------------FOR EXPORT AR4 DETAILS------------------------------------------------------------------
select Convert(varchar(11),AR4_DATE, 103) AR4_DATE,* from EXPORT_AR4_TBL
where AR4_JOBNO=@JOBNO and BRANCH_CODE=@WORKING_PERIOD order by AR4_INVOICE_SLNO
--------------------------------FOR EXPORT CONTAINER,ANNEXURE_SEA,PACKAGE DETAILS------------------------------------------------------------------

select Convert(varchar(11),ANNEX_SEA_CON_SEAL_DATE, 103) ANNEX_SEA_CON_SEAL_DATE,
