  SELECT * FROM EXP_SW_INFO_TYPE WHERE  JOBNO=@JOBNO and BRANCH_CODE=@Working_Period order by JOBNO,INVOICE_SLNO,ITEM_SLNO
  
  SELECT CONSTITUENT_SRNO AS SLNO,SW_CONST_ID ,JOBNO,INVOICE_SLNO,ITEM_SLNO,CONSTITUENT_SRNO,CONSTITUENT_ELEMENT_NAME,
CONSTITUENT_ELEMENT_CODE,CONSTITUENT_PERCENTAGE,CONSTITUENT_YIELD_PERCENTAGE,ACTIVE_INGREDIENT
 FROM EXP_SW_CONST WHERE  JOBNO=@JOBNO and BRANCH_CODE=@Working_Period order by JOBNO,INVOICE_SLNO,ITEM_SLNO
  
  SELECT 
  JOBNO,INVOICE_SLNO,ITEM_SLNO,SLNO,PRODUCTION_BATCH_IDENTIFIER,PRODUCTION_BATCH_QUANTITY,UNIT_QTY_CODE,
  convert(varchar, case when DATE_OF_MANUFACTURING ='1900-01-01 00:00:00.000' then null else DATE_OF_MANUFACTURING end,103) as DATE_OF_MANUFACTURING,
  convert(varchar, case when DATE_OF_EXPIRY ='1900-01-01 00:00:00.000' then null else DATE_OF_EXPIRY end,103) as DATE_OF_EXPIRY,
  convert(varchar, case when BEST_BEFORE ='1900-01-01 00:00:00.000' then null else BEST_BEFORE end,103) as BEST_BEFORE 
  FROM EXP_SW_PROD WHERE  JOBNO=@JOBNO and BRANCH_CODE=@Working_Period order by JOBNO,INVOICE_SLNO,ITEM_SLNO
  
  SELECT 
   JOBNO,INVOICE_SLNO,ITEM_SLNO,SLNO,CONTROL_TYPE_CODE,CONTROL_LOCATION,CONTROL_RESULT_CODE,CONTROL_RESULT_TEXT,
   convert(varchar, case when CONTROL_START_DATE ='1900-01-01 00:00:00.000' then null else CONTROL_START_DATE end,103) as CONTROL_START_DATE,
   convert(varchar, case when CONTROL_END_DATE ='1900-01-01 00:00:00.000' then null else CONTROL_END_DATE end,103) as CONTROL_END_DATE
   FROM EXP_SW_CONTROL WHERE  JOBNO=@JOBNO and BRANCH_CODE=@Working_Period order by JOBNO,INVOICE_SLNO,ITEM_SLNO
  
  SELECT 
  JOBNO,INVOICE_SLNO,ITEM_SLNO,SLNO,STMT_TYPE,STMT_CODE,STMT_TEXT 
  FROM EXP_SW_STMT WHERE  JOBNO=@JOBNO and BRANCH_CODE=@Working_Period order by JOBNO,INVOICE_SLNO,ITEM_SLNO
  
  select   
 convert(varchar, case when DOC_ISSUE_DATE ='1900-01-01 00:00:00.000' then null else DOC_ISSUE_DATE end,103) as DOC_ISSUE_DATE,
  convert(varchar, case when DOC_EXPIRY_DATE ='1900-01-01 00:00:00.000' then null else DOC_EXPIRY_DATE end,103) as DOC_EXPIRY_DATE,
  JOBNO,INVOICE_SLNO,ITEM_SLNO,SLNO,UNIQUE_DOC_NUMBER,DOC_TYPE_CODE,DOC_ISSUING_PARTY_CODE ,DOC_ISSUING_PARTY_NAME_ADD1,DOC_ISSUING_PARTY_NAME_ADD2,DOC_ISSUING_PARTY_CITY,DOC_ISSUING_PARTY_PIN,DOC_REF_NUMBER,PLACE_OF_ISSUE,BENEFICIARY_PARTY_CODE
,BENEFICIARY_PARTY_ADDRESS1,BENEFICIARY_PARTY_ADDRESS2,BENEFICIARY_PARTY_CITY,BENEFICIARY_PARTY_PIN,FILE_TYPE from EXP_SW_SUP_DOC  where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period  order by JOBNO,INVOICE_SLNO,ITEM_SLNO
         
 -------------------------------Export Single Window implementation on 19June2017--------------------------- 

