  SELECT 
  convert(varchar, case when SB_DATE ='1900-01-01 00:00:00.000' then null else SB_DATE end,103) as SB_DATE,
  convert(varchar, case when BE_DUTY_PAYMENT_DATE ='1900-01-01 00:00:00.000' then null else BE_DUTY_PAYMENT_DATE end,103) as BE_DUTY_PAYMENT_DATE,
  convert(varchar, case when BE_DATE ='1900-01-01 00:00:00.000' then null else BE_DATE end,103) as BE_DATE,
  
