SELECT Convert(varchar(11),A.LICENSE_DATE, 103)LICENSE_DATE,
A.LICENSE_ID ,A.JOB_NO,A.INV_SL_NO,A.ITEM_SL_NO,A.SCHEME,A.SCHEME_CODE,A.LICENSE_R_SL_NO,A.LICENSE_NO,B.* 
FROM EXPORT_LICENSE_DETAILS A
left join (select LICENSE_NO ,LICENSE_ID ,LICENSE_E_SL_NO, LICENSE_EXP_QTY, LICENSE_EXP_UNIT,LICENSE_IMP_ITEM_SL_NO,
LICENSE_IMP_DESC, LICENSE_IMP_QTY,LICENSE_IMP_UNIT,LICENSE_IMP_TYPE
, case when LICENSE_IMP_TYPE='N' then  'Indigenous'
when LICENSE_IMP_TYPE='M' then  'Imported'
else '' end as LICENSE_IMP_TYPENew
from EXPORT_LICENSE_IMP_EXP_DETAILS ) B on (a.LICENSE_NO=B.LICENSE_NO and a.LICENSE_ID=B.LICENSE_ID )
where a.JOB_NO=@JOBNO order by A.JOB_NO,A.INV_SL_NO,A.ITEM_SL_NO

