--and ITEM_ACCESSORIES_DESC <>'' 

select 
(select COUNT(ITEM_ACCESSORIES_DESC)  from    EXPORT_ITEM_DETAILS where JOBNO=@JOBNO and ITEM_ACCESSORIES_DESC is not null 
and ITEM_ACCESSORIES_DESC <>''  ) CntAcc,
(select COUNT(ITEM_IECCODE)  from    EXPORT_ITEM_DETAILS where JOBNO=@JOBNO and ITEM_IECCODE is not null 
and ITEM_IECCODE <>''  ) CntIECode,
(select COUNT(ACCESSORY_STATUS)  from    EXPORT_ITEM_DETAILS where JOBNO=@JOBNO and ACCESSORY_STATUS is not null 
and ACCESSORY_STATUS <>''  ) CntAccStatus,
(select COUNT(ITEM_STR_CODE)  from    EXPORT_ITEM_DETAILS where JOBNO=@JOBNO and ITEM_STR_CODE is not null 
and ITEM_STR_CODE <>''  ) CntStrCode
 

end
