GOODS_AIR_SB_NO GOODS_SB_NO,GOODS_AIR_SEAL_TYPE GOODS_SEAL_TYPE,GOODS_AIR_NATURE_OF_CARGO GOODS_NATURE_OF_CARGO,GOODS_AIR_GROSS_WEIGHT GOODS_GROSS_WEIGHT,GOODS_AIR_NET_WEIGHT GOODS_NET_WEIGHT,
GOODS_AIR_UNIT_MESUR GOODS_UNIT_MESUR,GOODS_AIR_TOTAL_PACKAGES GOODS_TOTAL_PACKAGES,GOODS_AIR_MARKS_NOS GOODS_MARKS_NOS,GOODS_AIR_MAWB_NO GOODS_MAWB_NO,GOODS_AIR_HAWB_NO GOODS_HAWB_NO,
* from EXPORT_GOODS_REG_AIR where GOODS_AIR_JOBNO=@JOBNO end
else 
begin
select Convert(varchar(11),GOODS_SEA_SB_DATE, 103)GOODS_SB_DATE,Convert(varchar(11),GOODS_SEA_ROTATION_DATE, 103)GOODS_ROTATION_DATE,GOODS_SEA_SB_NO GOODS_SB_NO,
GOODS_SEA_SEAL_TYPE GOODS_SEAL_TYPE,GOODS_SEA_NATURE_OF_CARGO GOODS_NATURE_OF_CARGO,GOODS_SEA_MARKS_NOS GOODS_MARKS_NOS,GOODS_SEA_TOTAL_PACKAGES GOODS_TOTAL_PACKAGES,
GOODS_SEA_LOOSE_PACKETS GOODS_LOOSE_PACKETS,GOODS_SEA_NO_CONTAINERS GOODS_NO_OF_CONTAINERS,GOODS_SEA_GROSS_WEIGHT GOODS_GROSS_WEIGHT,GOODS_SEA_NET_WEIGHT GOODS_NET_WEIGHT,
GOODS_SEA_UNIT_MEASUREMENT GOODS_UNIT_MESUR,GOODS_SEA_ROTATION_NO GOODS_ROTATION_NO,* from EXPORT_GOODS_REG_SEA where GOODS_SEA_JOBNO=@JOBNO 
end

select TERMS,WHEATHER_UNIT_PRICE,INVOICE_SLNO,INVOICE_NO,Convert(varchar(11),INVOICE_DATE, 103)INVOICE_DATE,FREIGHT_CHARGES,FREIGHT_CURRENCY,INSURANCE_CHARGES,INSURANCE_CURRENCY,INSURANCE_RATE
from EXPORT_INVOICE_DETAILS where JOBNO=@JOBNO  order by INVOICE_SLNO
select Convert(varchar(11),GOODS_SEA_CON_SEAL_DATE, 103)GOODS_SEA_CON_SEAL_DATE,* from EXPORT_GOODS_REG_SEA_CONTAINER where GOODS_SEA_CON_JOBNO=@JOBNO 

select * from EXPORT_GOODS_REG_PACKAGE where GOODS_PACK_JOBNO=@JOBNO and GOODS_PACK_MODE=@TRANSPORT_MODE 

select Convert(varchar(11),GOODS_EOU_EXAM_DATE, 103)GOODS_EOU_EXAM_DATE,* from EXPORT_GOODS_REG_EOU where GOODS_EOU_JOBNO=@JOBNO 
select Convert(varchar(11),AR4_DATE, 103) AR4_DATE,* from EXPORT_AR4_TBL where AR4_JOBNO=@JOBNO  order by AR4_ID
end
--------------------------------------------GOODS REGISTRATION CHECKLIST-------------------------------------------------------------
else if(@name='select_certificate_of_origin')
	begin
		if not exists(SELECT JOBNO  FROM EXPORT_CERTIFICATE_OF_ORGIN_DETAILS where JOBNO=@JOBNO )	
	begin		
	
	SELECT @AIR_JOBNO=ANNEX_AIR_JOBNO  FROM EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO=@JOBNO and FLAG='Active' 
	SELECT @SEA_JOBNO=ANNEX_SEA_JOBNO  FROM EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO=@JOBNO and FLAG='Active' 
	
	SELECT FILE_REF_NO,EXPORTER_NAME,BRANCH_NO,IEC_NO,ADDRESS1,ADDRESS2,ADDRESS3,ADDRESS4,ADDRESS5,CONSIGNEE_NAME,CONSIGNEE_ADD1,CONSIGNEE_ADD2,CONSIGNEE_ADD3,CONSIGNEE_ADD4,
	CONSIGNEE_ADD5,CUSTOMS_HOUSE,TRANSPORT_MODE,PORT_DISCHARGE,COUNTRY_FINAL_DEST FROM EXPORT_GENERAL_DETAILS where JOBNO=@JOBNO 

SELECT top 1 ITEM_DESCRIPTION
FROM EXPORT_ITEM_DETAILS
where JOBNO=@JOBNO 

SELECT top 1 INVOICE_NO,Convert(varchar(11),INVOICE_DATE, 103)INVOICE_DATE FROM EXPORT_INVOICE_DETAILS where JOBNO=@JOBNO 

	if(@AIR_JOBNO!='')
	begin
	SELECT distinct	ANNEX_AIR_MARKS_NOS,ANNEX_AIR_GROSS_WEIGHT +' '+ANNEX_AIR_GR_UNIT_CODE as GROSS_WEIGHT from
	 EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO =@JOBNO
	end
	else if(@SEA_JOBNO!='')
	begin
	SELECT distinct	ANNEX_SEA_MARKS_NOS,ANNEX_SEA_TOTAL_PACKAGES,ANNEX_SEA_GROSS_WEIGHT+' '+ANNEX_SEA_UNIT_MEASUREMENT as GROSS_WEIGHT
	from  EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO =@JOBNO
	end

set @MStatus=1
set @STR_status=0
end
else
begin 
select * from EXPORT_CERTIFICATE_OF_ORGIN_DETAILS where JOBNO=@JOBNO 
set @MStatus=2
set @STR_status=0
end
end
else if(@name='select_gsp_details')
	begin
		if not exists(SELECT JOBNO  FROM EXPORT_GSP_DETAILS where JOBNO=@JOBNO )	
	begin		
	
	SELECT @AIR_JOBNO=ANNEX_AIR_JOBNO  FROM EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO=@JOBNO and FLAG='Active' 
	SELECT @SEA_JOBNO=ANNEX_SEA_JOBNO  FROM EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO=@JOBNO and FLAG='Active' 
	SELECT FILE_REF_NO,EXPORTER_NAME,BRANCH_NO,IEC_NO,ADDRESS1,ADDRESS2,ADDRESS3,ADDRESS4,ADDRESS5,CONSIGNEE_NAME,CONSIGNEE_ADD1,CONSIGNEE_ADD2,CONSIGNEE_ADD3,CONSIGNEE_ADD4,
	CONSIGNEE_ADD5,CUSTOMS_HOUSE,TRANSPORT_MODE,PORT_DISCHARGE,COUNTRY_FINAL_DEST FROM EXPORT_GENERAL_DETAILS where JOBNO=@JOBNO 
SELECT top 1 ITEM_DESCRIPTION FROM EXPORT_ITEM_DETAILS where JOBNO=@JOBNO 
SELECT top 1 INVOICE_NO,Convert(varchar(11),INVOICE_DATE, 103)INVOICE_DATE FROM EXPORT_INVOICE_DETAILS where JOBNO=@JOBNO 
	if not exists(SELECT ANNEX_AIR_JOBNO  FROM EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO=@JOBNO and FLAG='Active' and WORKING_PERIOD=@Working_Period)
	if(@AIR_JOBNO!='')
	begin
	SELECT distinct	ANNEX_AIR_MARKS_NOS,ANNEX_AIR_GROSS_WEIGHT +' '+ANNEX_AIR_GR_UNIT_CODE as GROSS_WEIGHT from	 EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO =@JOBNO
	end
	if not exists(SELECT ANNEX_SEA_JOBNO  FROM EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO=@JOBNO and FLAG='Active' and WORKING_PERIOD=@Working_Period)
	 if(@SEA_JOBNO!='')
	begin
	
	SELECT distinct	ANNEX_SEA_MARKS_NOS,ANNEX_SEA_TOTAL_PACKAGES,ANNEX_SEA_GROSS_WEIGHT+' '+ANNEX_SEA_UNIT_MEASUREMENT as GROSS_WEIGHT
	from  EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO =@JOBNO
	end

set @MStatus=1
set @STR_status=0
end
else
begin 

  select * from EXPORT_GSP_DETAILS where JOBNO=@JOBNO 
set @MStatus=2
set @STR_status=0
end
end
else if(@name='GSP_Front_details_Delete')
begin
 delete from EXPORT_GSP_DETAILS where JOBNO=@JOBNO 
 set @MStatus=1
end
else if(@name='GSP_Front_details_Report')
begin
 SELECT EXPORTER_NAME as EXPORTER_NAME_NAME,EXPORTER_NAME+ @NewLineChar+ ADDRESS1+ADDRESS2+ @NewLineChar+ ADDRESS3+ADDRESS4+@NewLineChar+ADDRESS5 as EXPORTER_NAME,
CONSIGNEE_NAME+@NewLineChar+ CONSIGNEE_ADD1+CONSIGNEE_ADD2+@NewLineChar+CONSIGNEE_ADD3+CONSIGNEE_ADD4+@NewLineChar+CONSIGNEE_ADD5 as CONSIGNEE_NAME,FILE_REF_NO,
BRANCH_NO,IEC_NO,EXPORTER_COUNTRY,IMPORTER_COUNTRY,convert(varchar,PLACE_DATE,103) PLACE_DATE,ENTERED_BY,REPLACE(convert(VARCHAR,DEPATURE_DATE,103),'01/01/1900','')as DEPATURE_DATE,		  
VESSEL_AIRCRAFT_NAME,PORT_DISCHARGE,TRANSPORT_ROUTE,ITEM_NO,MARKS_NOS,DESCRIPTION,ORIGIN,GROSS_WEIGHT,INVOICE_NO_DATE,DEC1,DEC2,DEC3,SPE1,SPE2,SPE3,SPE4,SPE5,SUB1,
SUB2,SUB3,SUB4,REQ1,REQ2,REQ3,REQ4,REQ5,REQ6 from EXPORT_GSP_DETAILS where JOBNO=@JOBNO  set @MStatus=2
end
else if(@name='select_Invoice_Rpt')
begin
		if not exists(SELECT JOBNO  FROM EXPORT_INVOICE_REPORT_DETAILS where JOBNO=@JOBNO )	begin		
select * from EXPORT_GENERAL_DETAILS gen inner join INVOICE_DETAILS inv on inv.jobno=gen.JOBNO inner join EXPORT_ITEM_DETAILS item on item.jobno=inv.JOBNO
where gen.JOBNO=@JOBNO set @MStatus=1 set @STR_status=0
end
else
begin 
select * from EXPORT_INVOICE_REPORT_DETAILS where JOBNO=@JOBNO set @MStatus=2 set @STR_status=0 end end
ELSE IF(@name='BIND_ALL_INVALID_RITC_FROM_JOB')
BEGIN
  SELECT DISTINCT(RITCNO) FROM EXPORT_ITEM_DETAILS WHERE JOBNO=@JOBNO
END

ELSE IF(@name='BIND_ALL_JOB_INV_ITEM_INVALID_RITC')
BEGIN
  select JOBNO,INVOICE_SLNO,ITEM_SLNO from EXPORT_ITEM_DETAILS where RITCNO=@TRANSPORT_MODE AND JOBNO=@JOBNO 

END

end


commit
end try
begin catch
rollback transaction
	set @ErrorMsg=error_message()
	set @MStatus=0
end catch

/****** Object:  StoredProcedure [dbo].[IMP_MULTIPLE_INVOICE_SPLIT_WITH_MISC_SPLIT]    Script Date: 10/12/2018 15:07:19 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create procedure [dbo].[IMP_MULTIPLE_INVOICE_SPLIT_WITH_MISC_SPLIT](
 @Jobno varchar(20),@Inv_slno varchar(max),@Item_slno varchar(max),@xmlString VARCHAR(MAX),@Branch VARCHAR(100),@User_id VARCHAR(100)
 ,@Flag varchar(200),@Branch_Type varchar(150),@ErrorMsg nvarchar(max) output,@MISC_tot_Amt varchar(20) )    
 AS    
begin try    
 begin transaction    
  set @ErrorMsg=''    
  --------------------------------------------------------
   declare @temp table ( INVOICE_SLNO int, ITEM_SLNO int,SCHEME_CODE varchar(50))
   
DECLARE @xmlHandle INT ,@cnt int,@i int
DECLARE @stagingTable TABLE (Id int identity(1,1),INVOICE_SLNO int,ITEM_SLNO int,DEBIT_QTY VARCHAR(30),UNIT_QTY VARCHAR(30))
		
 if(@Flag='IMP_Inv_Select')
begin
		 if(@Branch_Type<>'')
		  begin
		          select INVOICE_NO
		          	,INVOICE_SLNO
					,TERMS
					,INVOICE_CURRENCY
					,INVOICE_VALUE
					,MIS_FREIGHT_CURRENCY
					,MIS_FREIGHT_RATE
					,MIS_FREIGHT_CHARGES
					,MIS_INSURANCE_CURRENCY
					,MIS_INSURANCE_RATE
					,MIS_INSURANCE_CHARGES
					,case when isnull(MI_FREIGHT,'')='' then 'Amt' else MI_FREIGHT end as MI_FREIGHT 
					,case when isnull(MI_INSURANCE,'')='' then 'Amt' else MI_INSURANCE end as MI_INSURANCE 
					,case when isnull(MI_MISC,'')='' then 'Amt' else MI_MISC end as MI_MISC 
					,MIS_CURRENCY
					,MIS_RATE
					,MIS_CHARGES					
		 from INVOICE_DETAILS where JOBNO=@Jobno and BRANCH_CODE=@Branch_Type order by INVOICE_Slno asc
		 
		          select MULTIPLE_FRIEGHT_AMOUNT,MULTIPLE_INSURANCE_AMOUNT,MULTIPLE_MISC_AMT from MULTIPLE_INVOICE
		          where MULTIPLE_JOBNO=@Jobno and BRANCH_CODE=@Branch_Type
		          
		     select isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(INVOICE_VALUE,'') =''  THEN   '0' else ISNULL(INVOICE_VALUE,'0') end)),0) INVOICE_VALUE
		      from INVOICE_DETAILS where JOBNO=@Jobno and BRANCH_CODE=@Branch_Type
		  end
		  else
		  begin
		         select 
		         	INVOICE_NO
		         	,INVOICE_SLNO
					,TERMS
					,INVOICE_CURRENCY
					,INVOICE_VALUE
					,MIS_FREIGHT_CURRENCY
					,MIS_FREIGHT_RATE
					,MIS_FREIGHT_CHARGES
					,MIS_INSURANCE_CURRENCY
					,MIS_INSURANCE_RATE
					,MIS_INSURANCE_CHARGES
					,case when isnull(MI_FREIGHT,'')='' then 'Amt' else MI_FREIGHT end as MI_FREIGHT 
					,case when isnull(MI_INSURANCE,'')='' then 'Amt' else MI_INSURANCE end as MI_INSURANCE 
					,case when isnull(MI_MISC,'')='' then 'Amt' else MI_MISC end as MI_MISC 
					,MIS_CURRENCY
					,MIS_RATE
					,MIS_CHARGES					
				 from INVOICE_DETAILS where JOBNO=@Jobno  order by INVOICE_Slno asc
				 
		         select MULTIPLE_FRIEGHT_AMOUNT,MULTIPLE_INSURANCE_AMOUNT,MULTIPLE_MISC_AMT from MULTIPLE_INVOICE where MULTIPLE_JOBNO=@Jobno 
		         select isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(INVOICE_VALUE,'') =''  THEN   '0' else ISNULL(INVOICE_VALUE,'0') end)),0) INVOICE_VALUE
		      from INVOICE_DETAILS where JOBNO=@Jobno 
		  end
end
else if(@Flag='Imp_Update_Multi_Inv_Update')
begin
		DECLARE @stagingTable_Inv TABLE ( Id int identity(1,1),INVOICE_SLNO int
		,TERMS VARCHAR(10),INVOICE_CURRENCY VARCHAR(10)	,INVOICE_VALUE VARCHAR(25),MI_FREIGHT VARCHAR(10),MIS_FREIGHT_CURRENCY VARCHAR(10)
		,MIS_FREIGHT_RATE VARCHAR(20),MIS_FREIGHT_CHARGES  VARCHAR(20),MI_INSURANCE  VARCHAR(20),MIS_INSURANCE_CURRENCY VARCHAR(20)
		,MIS_INSURANCE_RATE  VARCHAR(20),MIS_INSURANCE_CHARGES VARCHAR(20),MI_MISC VARCHAR(20),MIS_CURRENCY VARCHAR(10),MIS_RATE VARCHAR(20),MIS_CHARGES VARCHAR(20))
		if(@xmlString<>'')
		begin 
				 EXEC sp_xml_preparedocument @xmlHandle output, @xmlString 
			     INSERT INTO @stagingTable_Inv
				 SELECT INVOICE_SLNO ,TERMS,INVOICE_CURRENCY,INVOICE_VALUE,MI_FREIGHT,MIS_FREIGHT_CURRENCY,MIS_FREIGHT_RATE,MIS_FREIGHT_CHARGES,MI_INSURANCE
				,MIS_INSURANCE_CURRENCY,MIS_INSURANCE_RATE,MIS_INSURANCE_CHARGES,MI_MISC,MIS_CURRENCY,MIS_RATE,MIS_CHARGES FROM OPENXML (@xmlHandle, '/NewDataSet/SampleDataTable',1)WITH (
				[INVOICE_SLNO] nvarchar(30) '@INVOICE_SLNO' ,[TERMS] VARCHAR(10) '@TERMS' ,[INVOICE_CURRENCY] varchar(10) '@INVOICE_CURRENCY'
				,[INVOICE_VALUE] nvarchar(30) '@INVOICE_VALUE' ,[MI_FREIGHT] nvarchar(10) '@MI_FREIGHT' ,[MIS_FREIGHT_CURRENCY] nvarchar(10) '@MIS_FREIGHT_CURRENCY' 
				,[MIS_FREIGHT_RATE] nvarchar(10) '@MIS_FREIGHT_RATE' ,[MIS_FREIGHT_CHARGES] nvarchar(20) '@MIS_FREIGHT_CHARGES',[MI_INSURANCE] nvarchar(10) '@MI_INSURANCE'
				,[MIS_INSURANCE_CURRENCY] nvarchar(10) '@MIS_INSURANCE_CURRENCY',[MIS_INSURANCE_RATE] nvarchar(20) '@MIS_INSURANCE_RATE' ,[MIS_INSURANCE_CHARGES] nvarchar(30) '@MIS_INSURANCE_CHARGES'
				,[MI_MISC] nvarchar(20) '@MI_MISC',[MIS_CURRENCY] nvarchar(10) '@MIS_CURRENCY',[MIS_RATE] nvarchar(20) '@MIS_RATE',[MIS_CHARGES] nvarchar(20) '@MIS_CHARGES')
				 EXEC sp_xml_removedocument @xmlHandle 	 select @cnt=COUNT(*) from @stagingTable_Inv set @i=1;
				 declare @INVOICE_SLNO int,@TERMS VARCHAR(10),@INVOICE_CURRENCY VARCHAR(10),@INVOICE_VALUE VARCHAR(25),@MI_FREIGHT VARCHAR(10)
				,@MIS_FREIGHT_CURRENCY VARCHAR(10),@MIS_FREIGHT_RATE VARCHAR(20),@MIS_FREIGHT_CHARGES  VARCHAR(20)	,@MI_INSURANCE  VARCHAR(20)
				,@MIS_INSURANCE_CURRENCY VARCHAR(20),@MIS_INSURANCE_RATE  VARCHAR(20) ,@MIS_INSURANCE_CHARGES VARCHAR(20)
				,@MI_MISC VARCHAR(20),@MIS_CURRENCY VARCHAR(10),@MIS_RATE VARCHAR(20),@MIS_CHARGES VARCHAR(20)
				
	
while(@i<=@cnt) begin      select @INVOICE_SLNO =INVOICE_SLNO,@TERMS =TERMS,@INVOICE_CURRENCY =INVOICE_CURRENCY,@INVOICE_VALUE=INVOICE_VALUE
,@MI_FREIGHT=MI_FREIGHT,@MIS_FREIGHT_CURRENCY =MIS_FREIGHT_CURRENCY,@MIS_FREIGHT_RATE =MIS_FREIGHT_RATE,@MIS_FREIGHT_CHARGES= MIS_FREIGHT_CHARGES
,@MI_INSURANCE =MI_INSURANCE,@MIS_INSURANCE_CURRENCY =MIS_INSURANCE_CURRENCY,@MIS_INSURANCE_RATE  =MIS_INSURANCE_RATE,@MIS_INSURANCE_CHARGES =MIS_INSURANCE_CHARGES
,@MI_MISC=MI_MISC,@MIS_CURRENCY=MIS_CURRENCY,@MIS_RATE=MIS_RATE,@MIS_CHARGES=MIS_CHARGES from @stagingTable_Inv where Id=@i

declare @MI_Misc_Tick varchar(10)
if(@MISC_tot_Amt!='')
begin
 set @MI_Misc_Tick='Amt'
end

if(@Branch_Type<>'') begin  
	update INVOICE_DETAILS set
	 --INVOICE_SLNO=@INVOICE_SLNO ,
	 TERMS=@TERMS,INVOICE_CURRENCY=@INVOICE_CURRENCY
	,INVOICE_VALUE=@INVOICE_VALUE 
	 ,MI_FREIGHT=@MI_FREIGHT  ,MIS_FREIGHT_CURRENCY=@MIS_FREIGHT_CURRENCY
	,MIS_FREIGHT_RATE=@MIS_FREIGHT_RATE ,MIS_FREIGHT_CHARGES=@MIS_FREIGHT_CHARGES
	,MI_INSURANCE=@MI_INSURANCE ,MIS_INSURANCE_CURRENCY=@MIS_INSURANCE_CURRENCY
	,MIS_INSURANCE_RATE=@MIS_INSURANCE_RATE ,MIS_INSURANCE_CHARGES=@MIS_INSURANCE_CHARGES
	,MIS_SINGLE_OR_MULITIPLE='T',MIS_CURRENCY=@MIS_CURRENCY,MIS_RATE=@MIS_RATE,MIS_CHARGES=@MIS_CHARGES
	--,MI_MISC=@MI_Misc_Tick
	,MI_MISC=@MI_MISC
	where JOBNO=@Jobno and BRANCH_CODE=@Branch_Type and INVOICE_SLNO=@INVOICE_SLNO
end  
else  
begin 
	update INVOICE_DETAILS set --INVOICE_SLNO=@INVOICE_SLNO ,
	TERMS=@TERMS ,INVOICE_CURRENCY=@INVOICE_CURRENCY
	,INVOICE_VALUE=@INVOICE_VALUE ,MI_FREIGHT=@MI_FREIGHT ,MIS_FREIGHT_CURRENCY=@MIS_FREIGHT_CURRENCY
	,MIS_FREIGHT_RATE=@MIS_FREIGHT_RATE ,MIS_FREIGHT_CHARGES=@MIS_FREIGHT_CHARGES
	,MI_INSURANCE=@MI_INSURANCE ,MIS_INSURANCE_CURRENCY=@MIS_INSURANCE_CURRENCY
	,MIS_INSURANCE_RATE=@MIS_INSURANCE_RATE ,MIS_INSURANCE_CHARGES=@MIS_INSURANCE_CHARGES
	,MIS_SINGLE_OR_MULITIPLE='T',MIS_CURRENCY=@MIS_CURRENCY,MIS_RATE=@MIS_RATE,MIS_CHARGES=@MIS_CHARGES
	--,MI_MISC=@MI_Misc_Tick
	,MI_MISC=@MI_MISC
	where JOBNO=@Jobno and INVOICE_SLNO=@INVOICE_SLNO
end
set @i=@i+1;
				 end
		end
		
		
						 declare @jobid as bigint
                 declare @a varchar(20),@b varchar(20),@c varchar(20),@d varchar(20),@e varchar(20),@f varchar(20)
if(@Branch_Type<>'') 
begin 
			if exists(select null from MULTIPLE_INVOICE where MULTIPLE_JOBNO =@Jobno and BRANCH_CODE=@Branch_Type)
			begin
				  	update MULTIPLE_INVOICE set MULTIPLE_FRIEGHT_AMOUNT=@Inv_slno,MULTIPLE_INSURANCE_AMOUNT=@Item_slno,MULTIPLE_MISC_AMT=@MISC_tot_Amt
				    where MULTIPLE_JOBNO=@Jobno and BRANCH_CODE=@Branch_Type 
			end
			else
			begin
				       select @a = MIS_FREIGHT_CURRENCY,@b = MIS_FREIGHT_EXRATE,@c = MIS_INSURANCE_CURRENCY
				             ,@d =MIS_INSURANCE_EXRATE,@e=MIS_CURRENCY from INVOICE_DETAILS 
					   WHERE JOBNO=@JOBNO and INVOICE_SLNO=1 and BRANCH_CODE=@Branch_Type
						
				    set @jobid=(SELECT isnull(max(isnull(MUITIPLE_ID,0)),0)+1   FROM MULTIPLE_INVOICE)
				    
				    insert into MULTIPLE_INVOICE (MUITIPLE_ID,MULTIPLE_JOBNO,MULTIPLE_FRIEGHT_CURRENCY,MULTIPLE_FRIEGHT_EXCH_RATE,MULTIPLE_FRIEGHT_RATE
					,MULTIPLE_FRIEGHT_AMOUNT,MULTIPLE_INSURANCE_CURRENCY,MULTIPLE_INSURANCE_EXCH_RATE,MULTIPLE_INSURANCE_RATE,MULTIPLE_INSURANCE_AMOUNT
					,USER_ID,DATE_TIME,STATUS,BRANCH_CODE,YEAR,WORKING_PERIOD,MULTIPLE_MISC_AMT,MULTIPLE_HSS_AMT,MODIFIEDBY,MODIFIEDON)values(
					 @jobid ,@Jobno,@a,@b,'0.00',@Inv_slno,@c,@d,'0.00',@Item_slno,@User_id,GETDATE(),'N',@Branch,YEAR(GETDATE()),'',@MISC_tot_Amt,'','','01/01/1900')
			end
end	
else 
begin 
---update MULTIPLE_INVOICE set MULTIPLE_FRIEGHT_AMOUNT=@Inv_slno,MULTIPLE_INSURANCE_AMOUNT=@Item_slno  where MULTIPLE_JOBNO=@Jobno 
				if exists(select null from MULTIPLE_INVOICE where MULTIPLE_JOBNO =@Jobno )
				begin
				  		update MULTIPLE_INVOICE set MULTIPLE_FRIEGHT_AMOUNT=@Inv_slno,MULTIPLE_INSURANCE_AMOUNT=@Item_slno  ,MULTIPLE_MISC_AMT=@MISC_tot_Amt
						where MULTIPLE_JOBNO=@Jobno  
				end else	begin
						 select @a = MIS_FREIGHT_CURRENCY,@b = MIS_FREIGHT_EXRATE,@c = MIS_INSURANCE_CURRENCY
						 ,@d =MIS_INSURANCE_EXRATE,@e=MIS_CURRENCY from INVOICE_DETAILS WHERE JOBNO=@JOBNO and INVOICE_SLNO=1 
							
						 set @jobid=(SELECT isnull(max(isnull(MUITIPLE_ID,0)),0)+1   FROM MULTIPLE_INVOICE)
					    
						 insert into MULTIPLE_INVOICE (MUITIPLE_ID,MULTIPLE_JOBNO,MULTIPLE_FRIEGHT_CURRENCY,MULTIPLE_FRIEGHT_EXCH_RATE,MULTIPLE_FRIEGHT_RATE
						,MULTIPLE_FRIEGHT_AMOUNT,MULTIPLE_INSURANCE_CURRENCY,MULTIPLE_INSURANCE_EXCH_RATE,MULTIPLE_INSURANCE_RATE,MULTIPLE_INSURANCE_AMOUNT
						,USER_ID,DATE_TIME,STATUS,BRANCH_CODE,YEAR,WORKING_PERIOD,MULTIPLE_MISC_AMT,MULTIPLE_HSS_AMT,MODIFIEDBY,MODIFIEDON)values(
						 @jobid ,@Jobno,@a,@b,'0.00',@Inv_slno,@c,@d,'0.00',@Item_slno,@User_id,GETDATE(),'N',@Branch,YEAR(GETDATE()),'',@MISC_tot_Amt,'','','01/01/1900')
				end

end	
end
 --------------------------------------------------------
  commit    
end try    
begin catch    
rollback transaction    
 set @ErrorMsg=error_message()    
 --set @MStatus=0    
end catch


   
   
   
   /****** Object:  StoredProcedure [dbo].[DSC_LOGIN_CHECK]    Script Date: 10/12/2018 15:28:45 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
ALTER PROCEDURE [dbo].[DSC_LOGIN_CHECK]

(
	 @User_ID varchar(50)
	,@Branch_Common varchar(30)
	,@Password varchar(30)
	,@Mflag varchar(100)
	
	,@From_Date varchar(20)
    ,@To_Date varchar(20)
    ,@Type varchar(20)
	,@ErrorMsg nvarchar(max) output
 )
AS
begin try
	begin transaction
	set @ErrorMsg=''
		
if(@Mflag='DSC')
	begin
			if exists(select USER_NAME,PWD from USER_CREATION where USER_NAME =@User_ID and PWD=@Password ) 
			begin
			       --select BRANCH from USER_BRANCH where USER_BRANCHID =(select USER_CREATION_ID from USER_CREATION where USER_NAME =@User_ID )
			       
			       if(@Branch_Common='B')
			       begin
					   SELECT STUFF(( SELECT  '~' + E.BRANCH FROM USER_BRANCH AS E	
					   where USER_CREATION_ID =(select USER_CREATION_ID from USER_CREATION where USER_NAME =@User_ID )
					   FOR XML PATH('')) , 1, 1, '')  AS [Branch]
			       end
			       else
			       begin
			              select '1'
			       end
			       
			end
			else
			begin
			         select '0'
			end
 end
 
else if(@Mflag='DSC_GET_JOB_LIST')
begin
        if(@Type='I')
        begin
				if(@From_Date <>'' and @To_Date='' and @Branch_Common='' )
				begin
					  select a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'I' TYPE,IMPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  GENERAL_DETAILS b  on a.JOBNO=b.JOBNO
					  where JOB_DATE =@From_Date and JOB_TYPE=@Type order by a.JOBNO desc
					  
				end
				else if(@From_Date ='' and @To_Date<>''  and @Branch_Common='')
				begin
					  select  a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'I' TYPE,IMPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					   from DSC_FLAT_FILE_DETAILS a  inner join  GENERAL_DETAILS b  on a.JOBNO=b.JOBNO
					   where JOB_DATE =@To_Date and JOB_TYPE=@Type order by a.JOBNO desc
				end
				else if(@From_Date ='' and @To_Date=''  and @Branch_Common<>'')
				begin
					  select  a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'I' TYPE,IMPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  GENERAL_DETAILS b  on a.JOBNO=b.JOBNO  and a.BRANCH_CODE=b.BRANCHCODE
					  where BRANCHCODE=@Branch_Common and JOB_TYPE=@Type order by a.JOBNO desc	 
				end
				-------------------
				else if(@From_Date <>'' and @To_Date<>''  and @Branch_Common='')
				begin
					  select  a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'I' TYPE,IMPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  GENERAL_DETAILS b  on a.JOBNO=b.JOBNO
					  where JOB_DATE between 	@From_Date and @To_Date and JOB_TYPE=@Type order by a.JOBNO desc
				end
				else if(@From_Date <>'' and @To_Date=''  and @Branch_Common<>'')
				begin
					   select  a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'I' TYPE,IMPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					   ,FILE_REF_NO,JOBNO_PS
					   from DSC_FLAT_FILE_DETAILS a  inner join  GENERAL_DETAILS b  on a.JOBNO=b.JOBNO  and a.BRANCH_CODE=b.BRANCHCODE
					   where JOB_DATE =@From_Date	 and BRANCHCODE=@Branch_Common  and JOB_TYPE=@Type order by a.JOBNO desc
				end
				else if(@From_Date ='' and @To_Date<>''  and @Branch_Common<>'')
				begin
					  select  a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'I' TYPE,IMPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  GENERAL_DETAILS b  on a.JOBNO=b.JOBNO  and a.BRANCH_CODE=b.BRANCHCODE
					  where JOB_DATE =@To_Date and BRANCHCODE=@Branch_Common and JOB_TYPE=@Type order by a.JOBNO desc
				end
				-------------------
				else if(@From_Date <>'' and @To_Date<>''  and @Branch_Common<>'')
				begin
					  select  a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'I' TYPE,IMPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  GENERAL_DETAILS b  on a.JOBNO=b.JOBNO  and a.BRANCH_CODE=b.BRANCHCODE
					  where JOB_DATE between 	@From_Date and @To_Date  and BRANCHCODE=@Branch_Common and JOB_TYPE=@Type order by a.JOBNO desc
				end
				else if(@From_Date ='' and @To_Date=''  and @Branch_Common='')
				begin
					  select  a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'I' TYPE,IMPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  GENERAL_DETAILS b  on a.JOBNO=b.JOBNO where JOB_TYPE=@Type
					  order by a.JOBNO desc
				end
				 
        end----IE
        else
        begin
               if(@From_Date <>'' and @To_Date='' and @Branch_Common='' )
				begin
					  select  a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'E' TYPE,EXPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  EXPORT_GENERAL_DETAILS b  on a.JOBNO=b.JOBNO 
					  where JOB_DATE =@From_Date and JOB_TYPE=@Type order by a.JOBNO desc
				end
				else if(@From_Date ='' and @To_Date<>''  and @Branch_Common='')
				begin
					  select a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'E' TYPE,EXPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  EXPORT_GENERAL_DETAILS b  on a.JOBNO=b.JOBNO 
					   where JOB_DATE =@To_Date and JOB_TYPE=@Type order by a.JOBNO desc
				end
				else if(@From_Date ='' and @To_Date=''  and @Branch_Common<>'')
				begin
					  select a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'E' TYPE,EXPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  EXPORT_GENERAL_DETAILS b  on a.JOBNO=b.JOBNO and a.BRANCH_CODE=b.BRANCHCODE
					   where BRANCHCODE=@Branch_Common	and JOB_TYPE=@Type  order by a.JOBNO desc
				end
				-------------------
				else if(@From_Date <>'' and @To_Date<>''  and @Branch_Common='')
				begin
					  select a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'E' TYPE,EXPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  EXPORT_GENERAL_DETAILS b  on a.JOBNO=b.JOBNO 
					  where JOB_DATE between 	@From_Date and @To_Date  and JOB_TYPE=@Type order by a.JOBNO desc 
				end
				else if(@From_Date <>'' and @To_Date=''  and @Branch_Common<>'')
				begin
					   select a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'E' TYPE,EXPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					   ,FILE_REF_NO,JOBNO_PS
					   from DSC_FLAT_FILE_DETAILS a  inner join  EXPORT_GENERAL_DETAILS b  on a.JOBNO=b.JOBNO and a.BRANCH_CODE=b.BRANCHCODE
					   where JOB_DATE =@From_Date	 and BRANCHCODE=@Branch_Common  and JOB_TYPE=@Type order by a.JOBNO desc
				end
				else if(@From_Date ='' and @To_Date<>''  and @Branch_Common<>'')
				begin
					  select a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'E' TYPE,EXPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  EXPORT_GENERAL_DETAILS b  on a.JOBNO=b.JOBNO and a.BRANCH_CODE=b.BRANCHCODE
					  where JOB_DATE =@To_Date and BRANCHCODE=@Branch_Common and JOB_TYPE=@Type order by a.JOBNO desc
				end
				-------------------
				else if(@From_Date <>'' and @To_Date<>''  and @Branch_Common<>'')
				begin
					  select a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'E' TYPE,EXPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  EXPORT_GENERAL_DETAILS b  on a.JOBNO=b.JOBNO and a.BRANCH_CODE=b.BRANCHCODE
					  where JOB_DATE between 	@From_Date and @To_Date  and BRANCHCODE=@Branch_Common and JOB_TYPE=@Type order by a.JOBNO desc
				end
				else if(@From_Date ='' and @To_Date=''  and @Branch_Common='')
				begin
					  select a.JOBNO,convert(varchar(20),JOB_DATE,105)as JOBDATE ,TRANSPORT_MODE ,'E' TYPE,EXPORTER_NAME as CLIENT_NAME,FOLDER_PATH as FILE_PATH,CUSTOMS_HOUSE as CUSTOMS_HOUSE_CODE
					  ,FILE_REF_NO,JOBNO_PS
					  from DSC_FLAT_FILE_DETAILS a  inner join  EXPORT_GENERAL_DETAILS b  on a.JOBNO=b.JOBNO  where JOB_TYPE=@Type
					  order by a.JOBNO desc
				end
        end
end
------------------------------
commit
end try
begin catch
rollback transaction
	set @ErrorMsg=error_message()
end catch




/****** Object:  StoredProcedure [dbo].[DSC_FLATFILE_INSERT_UPDATE]    Script Date: 02/22/2018 19:30:56 ******/
