ALTER procedure [dbo].[IMP_CHECKLIST_SELECT]
  (    
       @Jobno varchar(20)
      ,@Inv_Slno  varchar(20)
      ,@Branch_Common varchar(150)
      ,@COMPANY_LICENSE varchar(20) 
      ,@flag varchar(50)
      
      ,@ErrorMsg nvarchar(max) output    
   )    
 AS    
begin try    
 begin transaction    
  set @ErrorMsg=''  
  SET NOCOUNT OFF; 
--
 if(@flag='Jobno')
  begin
          if(@Branch_Common <>'')
          begin
                SELECT distinct(JOBNO)JOBNO , JOBNO_PS FROM GENERAL_DETAILS where  BRANCHCODE=@Branch_Common order by JOBNO desc
          end
          else
          begin
                SELECT distinct(JOBNO)JOBNO , JOBNO_PS FROM GENERAL_DETAILS order by JOBNO desc        
          end 
  end
  else if(@flag='Jobno_Item_Cnt')
  begin
          if(@Branch_Common <>'')
          begin
                select COUNT(JOBNO)as Item_Cnt  from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno  and BRANCH_CODE=@Branch_Common
          end
          else
          begin
                select COUNT(JOBNO)as Item_Cnt  from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno     
          end 
  end
  else if(@flag='Checklist_NOTN_Chk_Paramount')
  begin
           declare @temp_item table (Id int identity(1,1),JOBNO int ,INVOICE_SLNO int ,INVOICE_NO varchar(30),ITEM_SLNO int,COUNTRY_OF_ORIGIN varchar(30)
		  ,PRODUCT_BCD_NOTN varchar(30), PRODUCT_BCD_SLNO varchar(30))
          if(@Branch_Common <>'')
          begin
				/*insert into @temp_item
				select JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,COUNTRY_OF_ORIGIN,PRODUCT_BCD_NOTN , PRODUCT_BCD_SLNO from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno and  BRANCH_CODE =@Branch_Common 
				and  isnull(PRODUCT_BCD_NOTN,'')in('085/2004','046/2011','069/2011','152/2009','151/2009','050/2018') 
				and (COUNTRY_OF_ORIGIN ='THAILAND' or COUNTRY_OF_ORIGIN ='JAPAN' 
					or COUNTRY_OF_ORIGIN = 'KOREA' or COUNTRY_OF_ORIGIN = 'CHINA')
				order by INVOICE_SLNO ,ITEM_SLNO asc
				*/
				insert into @temp_item
				select JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,COUNTRY_OF_ORIGIN,PRODUCT_BCD_NOTN , PRODUCT_BCD_SLNO from ITEM_PRODUCT_DETAILS 
				where JOBNO=@Jobno and  BRANCH_CODE =@Branch_Common 
				 and isnull(PRODUCT_BCD_NOTN,'')in('085/2004','046/2011','069/2011','152/2009','151/2009','050/2018')
				insert into @temp_item
				select JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,COUNTRY_OF_ORIGIN,PRODUCT_BCD_NOTN , PRODUCT_BCD_SLNO from ITEM_PRODUCT_DETAILS 
				where JOBNO=@Jobno and  BRANCH_CODE =@Branch_Common 
				 and isnull(COUNTRY_OF_ORIGIN,'')in('THAILAND' ,'JAPAN','KOREA,REPUBLIC OF','CHINA')
				 
				order by INVOICE_SLNO ,ITEM_SLNO asc

				delete from  @temp_item where isnull(PRODUCT_BCD_NOTN,'')='085/2004' and isnull(COUNTRY_OF_ORIGIN,'')='THAILAND'
				delete from  @temp_item where isnull(PRODUCT_BCD_NOTN,'')='046/2011' and isnull(COUNTRY_OF_ORIGIN,'')='THAILAND'
				delete from  @temp_item where isnull(PRODUCT_BCD_NOTN,'')='069/2011' and isnull(COUNTRY_OF_ORIGIN,'')='JAPAN'
				delete from  @temp_item where isnull(PRODUCT_BCD_NOTN,'')='152/2009' and isnull(COUNTRY_OF_ORIGIN,'')='KOREA,REPUBLIC OF' 
				delete from  @temp_item where isnull(PRODUCT_BCD_NOTN,'')='151/2009' and isnull(COUNTRY_OF_ORIGIN,'')='KOREA,REPUBLIC OF' 
				delete from  @temp_item where isnull(PRODUCT_BCD_NOTN,'')='050/2018' and isnull(COUNTRY_OF_ORIGIN,'')='CHINA'                

				select  distinct JOBNO ,INVOICE_SLNO  ,INVOICE_NO,ITEM_SLNO ,COUNTRY_OF_ORIGIN ,PRODUCT_BCD_NOTN ,PRODUCT_BCD_SLNO ,'F' as Flag from @temp_item order by INVOICE_SLNO ,ITEM_SLNO asc
          end
          else
          begin
                /*insert into @temp_item
				select JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,COUNTRY_OF_ORIGIN,PRODUCT_BCD_NOTN , PRODUCT_BCD_SLNO from ITEM_PRODUCT_DETAILS 
				where JOBNO=@Jobno  
				and  isnull(PRODUCT_BCD_NOTN,'')in('085/2004','046/2011','069/2011','152/2009','151/2009','050/2018')
				and (COUNTRY_OF_ORIGIN ='THAILAND' or COUNTRY_OF_ORIGIN ='JAPAN' 
					or COUNTRY_OF_ORIGIN = 'KOREA' or COUNTRY_OF_ORIGIN = 'CHINA')
				order by INVOICE_SLNO ,ITEM_SLNO asc
				*/
				insert into @temp_item
				select JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,COUNTRY_OF_ORIGIN,PRODUCT_BCD_NOTN , PRODUCT_BCD_SLNO from ITEM_PRODUCT_DETAILS 
				where JOBNO=@Jobno 
				 and isnull(PRODUCT_BCD_NOTN,'')in('085/2004','046/2011','069/2011','152/2009','151/2009','050/2018')
				insert into @temp_item
				select JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,COUNTRY_OF_ORIGIN,PRODUCT_BCD_NOTN , PRODUCT_BCD_SLNO from ITEM_PRODUCT_DETAILS 
				where JOBNO=@Jobno 
				 and isnull(COUNTRY_OF_ORIGIN,'')in('THAILAND' ,'JAPAN','KOREA,REPUBLIC OF','CHINA')
				 
				order by INVOICE_SLNO ,ITEM_SLNO asc

				delete from  @temp_item where isnull(PRODUCT_BCD_NOTN,'')='085/2004' and isnull(COUNTRY_OF_ORIGIN,'')='THAILAND'
				delete from  @temp_item where isnull(PRODUCT_BCD_NOTN,'')='046/2011' and isnull(COUNTRY_OF_ORIGIN,'')='THAILAND'
				delete from  @temp_item where isnull(PRODUCT_BCD_NOTN,'')='069/2011' and isnull(COUNTRY_OF_ORIGIN,'')='JAPAN'
				delete from  @temp_item where isnull(PRODUCT_BCD_NOTN,'')='152/2009' and isnull(COUNTRY_OF_ORIGIN,'')='KOREA,REPUBLIC OF' 
				delete from  @temp_item where isnull(PRODUCT_BCD_NOTN,'')='151/2009' and isnull(COUNTRY_OF_ORIGIN,'')='KOREA,REPUBLIC OF' 
				delete from  @temp_item where isnull(PRODUCT_BCD_NOTN,'')='050/2018' and isnull(COUNTRY_OF_ORIGIN,'')='CHINA'                

				select distinct INVOICE_SLNO  ,INVOICE_NO,ITEM_SLNO ,COUNTRY_OF_ORIGIN ,PRODUCT_BCD_NOTN ,PRODUCT_BCD_SLNO ,'F' as Flag from @temp_item order by INVOICE_SLNO ,ITEM_SLNO asc     
          end 
  end
  else if(@flag='Checklist_NOTN_Chk_Skylift')
  begin
         declare @temp_item_Sky table (Id int identity(1,1),JOBNO int ,INVOICE_SLNO int ,INVOICE_NO varchar(30),ITEM_SLNO int,COUNTRY_OF_ORIGIN varchar(30)
		  ,PRODUCT_BCD_NOTN varchar(30), PRODUCT_BCD_SLNO varchar(30))
          if(@Branch_Common <>'')
          begin
				/*insert into @temp_item_Sky
				select JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,COUNTRY_OF_ORIGIN,PRODUCT_BCD_NOTN , PRODUCT_BCD_SLNO from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno and  BRANCH_CODE =@Branch_Common 
				and  isnull(PRODUCT_BCD_NOTN,'')in('046/2011','085/2004')
				and (COUNTRY_OF_ORIGIN ='malaysia' or COUNTRY_OF_ORIGIN ='thailand')
				order by INVOICE_SLNO ,ITEM_SLNO asc
				*/
				insert into @temp_item_Sky
				select JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,COUNTRY_OF_ORIGIN,PRODUCT_BCD_NOTN , PRODUCT_BCD_SLNO from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno and  BRANCH_CODE =@Branch_Common 
				and  isnull(PRODUCT_BCD_NOTN,'')in('046/2011','085/2004')
				order by INVOICE_SLNO ,ITEM_SLNO asc
				
				insert into @temp_item_Sky
				select JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,COUNTRY_OF_ORIGIN,PRODUCT_BCD_NOTN , PRODUCT_BCD_SLNO from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno and  BRANCH_CODE =@Branch_Common 
				and isnull(COUNTRY_OF_ORIGIN,'')in('MALAYSIA' ,'THAILAND')
				order by INVOICE_SLNO ,ITEM_SLNO asc
				
				

				delete from  @temp_item_Sky where isnull(PRODUCT_BCD_NOTN,'')='046/2011' and isnull(COUNTRY_OF_ORIGIN,'')='MALAYSIA' and isnull(PRODUCT_BCD_SLNO,'')='992(I)'
				delete from  @temp_item_Sky where isnull(PRODUCT_BCD_NOTN,'')='085/2004' and isnull(COUNTRY_OF_ORIGIN,'')='THAILAND' and isnull(PRODUCT_BCD_SLNO,'')='41'
				
				select distinct JOBNO ,INVOICE_SLNO  ,INVOICE_NO,ITEM_SLNO ,COUNTRY_OF_ORIGIN ,PRODUCT_BCD_NOTN ,PRODUCT_BCD_SLNO  from @temp_item_Sky order by INVOICE_SLNO ,ITEM_SLNO asc
          end
          else
          begin
               insert into @temp_item_Sky
				select JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,COUNTRY_OF_ORIGIN,PRODUCT_BCD_NOTN , PRODUCT_BCD_SLNO from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno 
				and  isnull(PRODUCT_BCD_NOTN,'')in('046/2011','085/2004')
				order by INVOICE_SLNO ,ITEM_SLNO asc
				
				insert into @temp_item_Sky
				select JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,COUNTRY_OF_ORIGIN,PRODUCT_BCD_NOTN , PRODUCT_BCD_SLNO from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno  
				and isnull(COUNTRY_OF_ORIGIN,'')in('MALAYSIA' ,'THAILAND')
				order by INVOICE_SLNO ,ITEM_SLNO asc

				delete from  @temp_item_Sky where isnull(PRODUCT_BCD_NOTN,'')='046/2011' and isnull(COUNTRY_OF_ORIGIN,'')='MALAYSIA' and isnull(PRODUCT_BCD_SLNO,'')='992(I)'
				delete from  @temp_item_Sky where isnull(PRODUCT_BCD_NOTN,'')='085/2004' and isnull(COUNTRY_OF_ORIGIN,'')='THAILAND' and isnull(PRODUCT_BCD_SLNO,'')='41'
				
				select distinct JOBNO ,INVOICE_SLNO  ,INVOICE_NO,ITEM_SLNO ,COUNTRY_OF_ORIGIN ,PRODUCT_BCD_NOTN ,PRODUCT_BCD_SLNO  from @temp_item_Sky order by INVOICE_SLNO ,ITEM_SLNO asc
          end 
  end
  
 else if(@flag='General')
  begin
        declare @IMP_EXP_PAN_NO varchar(150)
        declare @ADCODE_FULL varchar(50)
        
        if(@Branch_Common <>'')
        begin
                select @IMP_EXP_PAN_NO=IMP_EXP_PAN_NO from IMP_EXP_MASTER where IMP_EXP_NAME=(select IMPORTER_NAME From GENERAL_DETAILS where JOBNO=@Jobno and BRANCHCODE=@Branch_Common )
				and IMP_EXP_BRSLNO =(select BRANCH_NO From GENERAL_DETAILS where JOBNO=@Jobno and BRANCHCODE=@Branch_Common) 
				
                SELECT Convert(varchar(11),JOBDATE, 103)JOBDATE, TRANSPORT_MODE,BE_TYPE,CUSTOMS_HOUSE,CUSTOMS_HOUSE_NAME,FILING_STATUS,SECTION46,FIRSTCHECK,GREEN_CHANNEL
                ,case when isnull(KACHHA_BE,'')='Y' then '(KACHHA BE)' else '' end KACHHA_BE
