		@REGISTRATION_DATE	datetime,
		@LICENSE_NO	varchar	(50),
		@LICENSE_DATE datetime,
		@EXCEMPTION	varchar(1),
		@LICENSE_TYPE varchar(20),
		@TOTAL_DEBIT_AMT varchar(19),
		@REMAINING_AMT	varchar(19),
		@TOTAL_DEBIT_QTY	varchar(19),
		@UNIT_QTY		varchar(3),
		@LICENSE_ITEM_NO	varchar(4),
		@PORT_OF_LICENSE	varchar(6),
		@USER_ID	varchar(30),
		@DATE_TIME	datetime,
		@STATUS	varchar(1),
		@BRANCH_CODE varchar(20),
		@YEAR	varchar(9),
		@WORKING_PERIOD	varchar(30),
		@MODIFIEDBY	varchar(50),
		@MODIFIEDON	datetime,
		@REMAINING_QTY VARCHAR(19),
		@PARTY_NAME VARCHAR(50),
		@LICENSE_DESC varchar(120),
		@SINGLE_DUTY_Y_N VARCHAR(1),
		@TOTAL_FC_VALUE varchar(20),
		@REMAINING_FC	varchar(20),
		@EX_RATE varchar(8),
		@TOTAL_CIF_VALUE varchar(20),
		@REMAINING_CIF	varchar(20),
		@LICENSE_CURRENCY VARCHAR(3),

           @Mflag varchar(100),
	       @Mstatus  int output,
	       @ErrorMsg nvarchar(max) output,
	       @Update_Id bigint output
AS
begin try
	begin transaction
		set @ErrorMsg=''
		declare @jobid as bigint
		declare @cnt int
		
if(@Mflag='S')
	begin
	if not exists(select null from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@REGISTRATION_NO and LICENSE_ITEM_NO=@LICENSE_ITEM_NO) 
		begin
		    set @jobid=(SELECT isnull(max(isnull(LICENSE_ID,0)),0)+1   FROM IMPORT_LICENSE_MASTER )
			INSERT INTO IMPORT_LICENSE_MASTER
					   (LICENSE_ID
						,REGISTRATION_NO
						,REGISTRATION_DATE
						,LICENSE_NO
						,LICENSE_DATE
						,EXCEMPTION
						,LICENSE_TYPE
						,TOTAL_DEBIT_AMT
						,REMAINING_AMT
						,TOTAL_DEBIT_QTY
						,UNIT_QTY
						,LICENSE_ITEM_NO
						,PORT_OF_LICENSE
						,USER_ID
						,DATE_TIME
						,STATUS
						,BRANCH_CODE
						,YEAR
						,WORKING_PERIOD
						,MODIFIEDBY
						,MODIFIEDON
						,REMAINING_QTY
						,PARTY_NAME
						,LICENSE_DESC
						,SINGLE_DUTY_Y_N
						,TOTAL_FC_VALUE
						,REMAINING_FC
						,EX_RATE
						,TOTAL_CIF_VALUE
						,REMAINING_CIF
						,LICENSE_CURRENCY
						)
			
				 VALUES
					   (
					   @jobid,
					@REGISTRATION_NO,
					@REGISTRATION_DATE,
					@LICENSE_NO,
					@LICENSE_DATE,
					@EXCEMPTION,
					@LICENSE_TYPE,
					@TOTAL_DEBIT_AMT,
					@REMAINING_AMT,
					@TOTAL_DEBIT_QTY,
					@UNIT_QTY,
					@LICENSE_ITEM_NO,
					@PORT_OF_LICENSE,
					@USER_ID,
					GETDATE(),
					'N',
					@BRANCH_CODE,
					@YEAR,
					@WORKING_PERIOD,
					@MODIFIEDBY,
					@MODIFIEDON,
					@REMAINING_QTY,
					@PARTY_NAME,
					@LICENSE_DESC,
					@SINGLE_DUTY_Y_N
					,@TOTAL_FC_VALUE
					,@REMAINING_FC
					,@EX_RATE
					,@TOTAL_CIF_VALUE
					,@REMAINING_CIF
					,@LICENSE_CURRENCY
				)


		    select @Mstatus=1
			select @Update_Id=@jobid
		end
				else
				begin
					  select @Mstatus=2
				end
end
	

else if(@Mflag='U')
	begin
	    select @cnt= COUNT(*) from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@REGISTRATION_NO and LICENSE_ITEM_NO=@LICENSE_ITEM_NO and LICENSE_ID <> @LICENSE_ID   
	    if (@cnt=0) 
		begin
					UPDATE IMPORT_LICENSE_MASTER
					   SET 
					    REGISTRATION_NO	=	@REGISTRATION_NO,	
						REGISTRATION_DATE	=	@REGISTRATION_DATE,	
						LICENSE_NO	=	@LICENSE_NO,	
						LICENSE_DATE	=	@LICENSE_DATE,	
						EXCEMPTION	=	@EXCEMPTION,	
						LICENSE_TYPE	=	@LICENSE_TYPE,	
						TOTAL_DEBIT_AMT	=	@TOTAL_DEBIT_AMT,	
						REMAINING_AMT	=	@REMAINING_AMT,	
						TOTAL_DEBIT_QTY	=	@TOTAL_DEBIT_QTY,	
						UNIT_QTY	=	@UNIT_QTY,	
						LICENSE_ITEM_NO	=	@LICENSE_ITEM_NO,	
						PORT_OF_LICENSE	=	@PORT_OF_LICENSE,	
						STATUS	=	'U',	
						BRANCH_CODE	=	@BRANCH_CODE,	
						YEAR	=	@YEAR,	
						WORKING_PERIOD	=	@WORKING_PERIOD,	
						MODIFIEDBY	=	@USER_ID,	
						MODIFIEDON	=	GETDATE(),
						REMAINING_QTY = @REMAINING_QTY,	
						PARTY_NAME = @PARTY_NAME,
						LICENSE_DESC =@LICENSE_DESC,
						SINGLE_DUTY_Y_N=@SINGLE_DUTY_Y_N,
						TOTAL_FC_VALUE=@TOTAL_FC_VALUE,
						REMAINING_FC=@REMAINING_FC,
						EX_RATE=@EX_RATE,
						TOTAL_CIF_VALUE=@TOTAL_CIF_VALUE,
					    REMAINING_CIF=@REMAINING_CIF,
					    LICENSE_CURRENCY=@LICENSE_CURRENCY
					      
					 WHERE LICENSE_ID = @LICENSE_ID  
 
		select @Mstatus=1
 
 end
     else
		begin
		    select @Mstatus=2
		end
end

 
------------------------------------------------------------------------------------------------------------------------------------------------------
commit
end try
begin catch
rollback transaction
	set @ErrorMsg=error_message()
	set @MStatus=0
end catch

/****** Object:  StoredProcedure [dbo].[IMPORT_LICENSE_MASTER__SEARCH_SELECT]    Script Date: 10/12/2018 15:33:06 ******/
