ALTER PROCEDURE [dbo].[IMPORT_LICENSE_MASTER__SEARCH_SELECT]
	@LICENSE_ID	varchar(35),
	@LICENSE_WORKING_PERIOD varchar(30),
	@name 	varchar(300),
	@LICENSE_NO varchar(10),
	@LICENSE_DATE varchar(20),
	@SCHEME_CODE varchar(40),
	@PARTY_NAME varchar(50),
	@LICENSE_DESC varchar(50),
	

	@Mstatus  int output,
	@startRowIndex int,
@maximumRows int,
@totalRows int OUTPUT,
	@ErrorMsg nvarchar(max) output
AS
begin try
	begin transaction
		set @ErrorMsg=''

/*
DECLARE @LICENSE_ID	varchar(35),
	@LICENSE_WORKING_PERIOD varchar(30),
	@name 	varchar(300),
	@LICENSE_NO varchar(10),
	@LICENSE_DATE varchar(20),
	@SCHEME_CODE varchar(40),
	@PARTY_NAME varchar(50),
	@LICENSE_DESC varchar(50),
	

	@Mstatus  int ,
	@startRowIndex int,
@maximumRows int,
@totalRows int ,
	@ErrorMsg nvarchar(max)
	
	SET @LICENSE_ID='3'
	SET @LICENSE_WORKING_PERIOD=''
	SET @name='Get_Remaining_Debit_Amt'
	--SET @LICENSE_NO='0000000000'
	--SET @LICENSE_DATE='12/01/2017'
	--SET @SCHEME_CODE='12-EPCG'
	
		SET @LICENSE_NO='0987651234'
	SET @LICENSE_DATE=''
	SET @SCHEME_CODE='03-DEEC'
	
	SET @PARTY_NAME=''
	SET @LICENSE_DESC='Y'
	SET @ErrorMsg=''
*/	
	
		declare @jobid as bigint
DECLARE @first_id int, @startRow int

DECLARE @TOTAL_DEBIT_AMT  numeric(19,6)
declare @Current_Amt  numeric(19,6)

DECLARE @TOTAL_DEBIT_QTY  numeric(19,6)
declare @Current_QTY  numeric(19,6)

DECLARE @TOTAL_FC  numeric(19,6)
declare @Current_FC  numeric(19,6)

declare @REMAINING_AMT  numeric(19,6)
declare @REMAINING_QTY  numeric(19,6)
declare @REMAINING_FC  numeric(19,6)
declare @REMAINING_CIF  numeric(19,6)

DECLARE @TOTAL_CIF  numeric(19,6)
declare @Current_CIF  numeric(19,6)

--DECLARE @tbl_FC table(CURRENT_FC VARCHAR(50))
DECLARE @tbl_FC table(JOBNO VARCHAR(50),INV_EXRATE VARCHAR(50),CIF_AMOUNT VARCHAR(50),CURRENT_FC VARCHAR(50))

SET @startRowIndex =  (@startRowIndex - 1)  * @maximumRows+1

IF @startRowIndex = 0
SET @startRowIndex = 1
if(@name='autoid')
	begin
	
		--SELECT max(LICENSE_ID)  as LICENSE_ID FROM IMPORT_LICENSE_MASTER where LICENSE_WORKING_PERIOD=@Working_Period
		
		SELECT max(LICENSE_ID)  as LICENSE_ID FROM IMPORT_LICENSE_MASTER
		
		end
	else if(@name='select_conwithcode')
	begin
	SELECT Convert(varchar(11),LICENSE_DATE, 103)LICENSE_DATE,Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,* FROM IMPORT_LICENSE_MASTER where LICENSE_ID=@LICENSE_ID
	SELECT @totalRows =0
end

else if(@name='select_con')
	begin
	
	SET ROWCOUNT @startRowIndex
SELECT @first_id =LICENSE_ID FROM IMPORT_LICENSE_MASTER 
where REGISTRATION_NO like @LICENSE_NO+'%' and LICENSE_TYPE like @SCHEME_CODE+'%' and  isnull(PARTY_NAME,'') like @PARTY_NAME+'%'
and  isnull(LICENSE_DESC,'') like +'%'+@LICENSE_DESC+'%' ORDER BY LICENSE_ID

PRINT @first_id
SET ROWCOUNT @maximumRows
SELECT Convert(varchar(11),LICENSE_DATE, 103)LICENSE_DATE,Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,* 
FROM IMPORT_LICENSE_MASTER where REGISTRATION_NO like @LICENSE_NO+'%' and LICENSE_TYPE like @SCHEME_CODE+'%'  and  isnull(PARTY_NAME,'') like @PARTY_NAME+'%' and  isnull(LICENSE_DESC,'') like +'%'+@LICENSE_DESC+'%' and
LICENSE_ID >= @first_id
ORDER BY LICENSE_ID
 
SET ROWCOUNT 0
SELECT @totalRows = COUNT(LICENSE_ID) FROM IMPORT_LICENSE_MASTER  
where REGISTRATION_NO like @LICENSE_NO+'%' and LICENSE_TYPE like @SCHEME_CODE+'%'  and  isnull(PARTY_NAME,'') like @PARTY_NAME+'%' and  isnull(LICENSE_DESC,'') like +'%'+@LICENSE_DESC+'%'
end

else if(@name='select_License')
	begin
	          
	SET ROWCOUNT @startRowIndex
SELECT @first_id =LICENSE_ID FROM IMPORT_LICENSE_MASTER 
where REGISTRATION_NO like @LICENSE_NO+'%' and LICENSE_TYPE like @SCHEME_CODE+'%' and  isnull(PARTY_NAME,'') like @PARTY_NAME+'%' and  isnull(LICENSE_DESC,'') like +'%'+@LICENSE_DESC+'%'
 ORDER BY LICENSE_ID


PRINT @first_id
SET ROWCOUNT @maximumRows
SELECT Convert(varchar(11),LICENSE_DATE, 103)LICENSE_DATE,Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,* 
FROM IMPORT_LICENSE_MASTER where REGISTRATION_NO like @LICENSE_NO+'%' and LICENSE_TYPE like @SCHEME_CODE+'%' and  isnull(PARTY_NAME,'') like @PARTY_NAME+'%' and  isnull(LICENSE_DESC,'') like +'%'+@LICENSE_DESC+'%'
and
LICENSE_ID >= @first_id
ORDER BY LICENSE_ID
 
SET ROWCOUNT 0
SELECT @totalRows = COUNT(LICENSE_ID) FROM IMPORT_LICENSE_MASTER  
where REGISTRATION_NO like @LICENSE_NO+'%' and LICENSE_TYPE like @SCHEME_CODE+'%' and  isnull(PARTY_NAME,'') like @PARTY_NAME+'%' 	 and  isnull(LICENSE_DESC,'') like +'%'+@LICENSE_DESC+'%'
end

else if(@name='delete')
	begin
	delete from IMPORT_LICENSE_MASTER where LICENSE_ID=@LICENSE_ID 
	select @Mstatus=1
end


else if(@name='Get_Remaining_Debit_Amt')
	begin

		 
if not exists(select null from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO and SINGLE_DUTY_Y_N='Y')
begin 
--here sum the all Debit amt
        set @TOTAL_DEBIT_AMT=(select  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_DEBIT_AMT,'') =''  THEN   '0' else ISNULL(TOTAL_DEBIT_AMT,'0') end)),0)  from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO and LICENSE_TYPE=@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID)
		set @Current_Amt=(select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ENTRY_DEBIT_DUTY,'') =''  THEN   '0' else ISNULL(ENTRY_DEBIT_DUTY,'0') end)),0)  FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO and SCHEME_CODE=@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID)
		
		--SELECT @TOTAL_DEBIT_AMT,@Current_Amt
			if(@Current_Amt>1)
			begin
		       SELECT   isnull(sum(CONVERT(numeric(19,2),@TOTAL_DEBIT_AMT)),0) - isnull(sum(CONVERT(numeric(19,2),@Current_Amt)),0) as REMAINING_AMT 
		    end
		    else
		    begin
		     --set @REMAINING_AMT= '0.00'  --hide by Chithra on 10-09-2018 for PARAMOUNT
		     SET @REMAINING_AMT= @TOTAL_DEBIT_AMT --NEW
		     SELECT @REMAINING_AMT AS REMAINING_AMT
		    end
		----------------------------------------------------------------------------------------------------------    
		set @TOTAL_DEBIT_QTY=(select isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_DEBIT_QTY,'') =''  THEN   '0' else ISNULL(TOTAL_DEBIT_QTY,'0') end)),0)  from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO and LICENSE_TYPE=@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID)
		set @Current_QTY=(select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DEBIT_QTY,'') =''  THEN   '0' else ISNULL(DEBIT_QTY,'0') end)),0)   FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO and SCHEME_CODE=@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID)
		
		if(@Current_QTY>1)
		begin
		   SELECT   isnull(sum(CONVERT(numeric(19,2),@TOTAL_DEBIT_QTY)),0) - isnull(sum(CONVERT(numeric(19,2),@Current_QTY)),0) as REMAINING_QTY 
		end
		else
		begin
		   --set @REMAINING_QTY= '0.00' --hide by Chithra on 10-09-2018 for PARAMOUNT
		   set @REMAINING_QTY= @TOTAL_DEBIT_QTY--NEW
		     SELECT @REMAINING_QTY AS REMAINING_QTY
		end
		
		--select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DEBIT_DUTY,'') =''  THEN   '0' else ISNULL(DEBIT_DUTY,'0') end)),0) as DEBIT_AMT  FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO and SCHEME_CODE=@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID
		select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ENTRY_DEBIT_DUTY,'') =''  THEN   '0' else ISNULL(ENTRY_DEBIT_DUTY,'0') end)),0) as DEBIT_AMT  FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO and SCHEME_CODE=@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID
		select isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_DEBIT_AMT,'') =''  THEN   '0' else ISNULL(TOTAL_DEBIT_AMT,'0') end)),0) as TOTAL_DEBIT_AMT from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO and LICENSE_TYPE=@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID
		
		select  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DEBIT_QTY,'') =''  THEN   '0' else ISNULL(DEBIT_QTY,'0') end)),0) AS DEBIT_QTY FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO  and SCHEME_CODE=@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID
		select isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_DEBIT_QTY,'') =''  THEN   '0' else ISNULL(TOTAL_DEBIT_QTY,'0') end)),0) as TOTAL_DEBIT_QTY from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO  and LICENSE_TYPE=@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID
--------------------------------------------------------------------------------------------------------------------
		
		INSERT INTO @tbl_FC
				--SELECT JOBNO,isnull(CONVERT(numeric(19,2),EX_RATE),0),DEBIT_AMT, 
				--isnull(sum(CONVERT(numeric(19,2),DEBIT_AMT)),0)/isnull(CONVERT(numeric(19,2),EX_RATE),0) as CURRENT_FC FROM LICENSE_DETAILS
				--where REGISTRATION_NO = @LICENSE_NO  and SCHEME_CODE like '%'+@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID 
				--AND isnull(CONVERT(numeric(19,2),EX_RATE),0)>0 group by EX_RATE,JOBNO,DEBIT_AMT
				
				SELECT JOBNO,case when EX_RATE ='' then '0' else isnull(CONVERT(numeric(19,2),EX_RATE),0) end,DEBIT_AMT, 
				isnull(sum(CONVERT(numeric(19,2),DEBIT_AMT)),0)/case when EX_RATE ='' then '0' else isnull(CONVERT(numeric(19,2),EX_RATE),0) end as CURRENT_FC FROM LICENSE_DETAILS
				where REGISTRATION_NO = @LICENSE_NO  and SCHEME_CODE like '%'+@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID 
				AND case when EX_RATE ='' then '0' else isnull(CONVERT(numeric(19,2),EX_RATE),0) end>0 group by EX_RATE,JOBNO,DEBIT_AMT
				
		--SELECT * FROM @tbl_FC
		
				set @TOTAL_FC=(select  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_FC_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_FC_VALUE,'0') end)),0)  from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO and LICENSE_TYPE=@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID)
				set @CURRENT_FC=(select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CURRENT_FC,'') =''  THEN   '0' else ISNULL(CURRENT_FC,'0') end)),0)  FROM @tbl_FC )
				--SELECT @TOTAL_FC,@CURRENT_FC

				if(@CURRENT_FC>1)
				begin
				   SELECT   isnull(sum(CONVERT(numeric(19,2),@TOTAL_FC)),0) - isnull(sum(CONVERT(numeric(19,2),@CURRENT_FC)),0) as REMAINING_FC
				end
				else
				begin
				 --set @REMAINING_AMT= '0.00'  --hide by Chithra on 10-09-2018 for PARAMOUNT
				 SET @REMAINING_FC= @TOTAL_FC --NEW
				 SELECT @REMAINING_FC AS REMAINING_FC
				end
		 
-------------------------------------------------------------------------------------------------------------------
		    set @TOTAL_CIF=(select  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_CIF_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_CIF_VALUE,'0') end)),0)  from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO and LICENSE_TYPE=@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID)	
		    set @Current_CIF=(select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DEBIT_AMT,'') =''  THEN   '0' else ISNULL(DEBIT_AMT,'0') end)),0)  FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO and SCHEME_CODE=@SCHEME_CODE AND LICENSE_ITEM_NO=@LICENSE_ID)
		--SELECT @TOTAL_CIF,@Current_CIF
			if(@Current_CIF>1)
			begin
		       SELECT   isnull(sum(CONVERT(numeric(19,2),@TOTAL_CIF)),0) - isnull(sum(CONVERT(numeric(19,2),@Current_CIF)),0) as REMAINING_CIF
		    end
		    else
		    begin
		     --set @REMAINING_AMT= '0.00'  --hide by Chithra on 10-09-2018 for PARAMOUNT
		     SET @REMAINING_CIF= @TOTAL_CIF --NEW
		     SELECT @REMAINING_CIF AS REMAINING_CIF
		   end
	  
			
			SELECT Convert(varchar(11),LICENSE_DATE, 103)LICENSE_DATE,Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,* 
		 FROM IMPORT_LICENSE_MASTER where REGISTRATION_NO like @LICENSE_NO+'%' and LICENSE_TYPE like @SCHEME_CODE+'%'
		ORDER BY REGISTRATION_NO
	select @Mstatus=1	
		
end
else
begin   
   set @TOTAL_DEBIT_AMT=(select  isnull(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_DEBIT_AMT,'') =''  THEN   '0' else ISNULL(TOTAL_DEBIT_AMT,'0') end),0)  from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO and LICENSE_TYPE=@SCHEME_CODE and SINGLE_DUTY_Y_N='Y')
		--set @Current_Amt=(select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DEBIT_AMT,'') =''  THEN   '0' else ISNULL(DEBIT_AMT,'0') end)),0)  FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO and SCHEME_CODE=@SCHEME_CODE)
		set @Current_Amt=(select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ENTRY_DEBIT_DUTY,'') =''  THEN   '0' else ISNULL(ENTRY_DEBIT_DUTY,'0') end)),0)  FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO and SCHEME_CODE=@SCHEME_CODE)
		--SELECT @TOTAL_DEBIT_AMT,@Current_Amt
		
		SELECT   isnull(sum(CONVERT(numeric(19,2),@TOTAL_DEBIT_AMT)),0) - isnull(sum(CONVERT(numeric(19,2),@Current_Amt)),0) as REMAINING_AMT 
		
		set @TOTAL_DEBIT_QTY=(select isnull(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_DEBIT_QTY,'') =''  THEN   '0' else ISNULL(TOTAL_DEBIT_QTY,'0') end),0)  from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO and LICENSE_TYPE=@SCHEME_CODE and SINGLE_DUTY_Y_N='Y')
		set @Current_QTY=(select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DEBIT_QTY,'') =''  THEN   '0' else ISNULL(DEBIT_QTY,'0') end)),0)   FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO and SCHEME_CODE=@SCHEME_CODE)
		SELECT   isnull(sum(CONVERT(numeric(19,2),@TOTAL_DEBIT_QTY)),0) - isnull(sum(CONVERT(numeric(19,2),@Current_QTY)),0) as REMAINING_QTY 
		
		--select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DEBIT_DUTY,'') =''  THEN   '0' else ISNULL(DEBIT_DUTY,'0') end)),0) as DEBIT_AMT  FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO and SCHEME_CODE=@SCHEME_CODE
		select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ENTRY_DEBIT_DUTY,'') =''  THEN   '0' else ISNULL(ENTRY_DEBIT_DUTY,'0') end)),0) as DEBIT_AMT  FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO and SCHEME_CODE=@SCHEME_CODE
		select isnull(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_DEBIT_AMT,'') =''  THEN   '0' else ISNULL(TOTAL_DEBIT_AMT,'0') end),0) as TOTAL_DEBIT_AMT from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO and LICENSE_TYPE=@SCHEME_CODE  and SINGLE_DUTY_Y_N='Y'
		
		select  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DEBIT_QTY,'') =''  THEN   '0' else ISNULL(DEBIT_QTY,'0') end)),0) AS DEBIT_QTY FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO  and SCHEME_CODE=@SCHEME_CODE
		select isnull(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_DEBIT_QTY,'') =''  THEN   '0' else ISNULL(TOTAL_DEBIT_QTY,'0') end),0) as TOTAL_DEBIT_QTY from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO  and LICENSE_TYPE=@SCHEME_CODE  and SINGLE_DUTY_Y_N='Y'
			
			
		------------------------------------------------------------------------------------------------------------------
		/*
		   INSERT INTO @tbl_FC
			SELECT isnull(sum(CONVERT(numeric(19,2),DEBIT_AMT)),0)/isnull(CONVERT(numeric(19,2),INVOICE_EXRATE),0) as CURRENT_FC
			FROM LICENSE_DETAILS a left outer join INVOICE_DETAILS b on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO
			where REGISTRATION_NO = @LICENSE_NO and a.SCHEME_CODE=@SCHEME_CODE group by INVOICE_EXRATE


			set @TOTAL_FC=(select  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_FC_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_FC_VALUE,'0') end)),0)  from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO and LICENSE_TYPE=@SCHEME_CODE  and SINGLE_DUTY_Y_N='Y')
			set @CURRENT_FC=(select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CURRENT_FC,'') =''  THEN   '0' else ISNULL(CURRENT_FC,'0') end)),0)  FROM @tbl_FC )
			--SELECT @TOTAL_FC,@CURRENT_FC

			if(@CURRENT_FC>1)
			begin
		       SELECT   isnull(sum(CONVERT(numeric(19,2),@TOTAL_FC)),0) - isnull(sum(CONVERT(numeric(19,2),@CURRENT_FC)),0) as REMAINING_FC
		    end
		    else
		    begin
		     --set @REMAINING_AMT= '0.00'  --hide by Chithra on 10-09-2018 for PARAMOUNT
		     SET @REMAINING_FC= @TOTAL_FC --NEW
		     SELECT @REMAINING_FC AS REMAINING_FC
		    end
		 */   
		 
		
		INSERT INTO @tbl_FC
				SELECT JOBNO,isnull(CONVERT(numeric(19,2),EX_RATE),0),DEBIT_AMT, 
				isnull(sum(CONVERT(numeric(19,2),DEBIT_AMT)),0)/isnull(CONVERT(numeric(19,2),EX_RATE),0) as CURRENT_FC FROM LICENSE_DETAILS
				where REGISTRATION_NO = @LICENSE_NO  and SCHEME_CODE like '%'+@SCHEME_CODE 
				AND isnull(CONVERT(numeric(19,2),EX_RATE),0)>0 group by EX_RATE,JOBNO,DEBIT_AMT
		--SELECT * FROM @tbl_FC
		
				set @TOTAL_FC=(select  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_FC_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_FC_VALUE,'0') end)),0)  from IMPORT_LICENSE_MASTER 
				               where REGISTRATION_NO=@LICENSE_NO and LICENSE_TYPE=@SCHEME_CODE   and SINGLE_DUTY_Y_N='Y')
				set @CURRENT_FC=(select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CURRENT_FC,'') =''  THEN   '0' else ISNULL(CURRENT_FC,'0') end)),0)  FROM @tbl_FC )
				--SELECT @TOTAL_FC,@CURRENT_FC

				if(@CURRENT_FC>1)
				begin
				   SELECT   isnull(sum(CONVERT(numeric(19,2),@TOTAL_FC)),0) - isnull(sum(CONVERT(numeric(19,2),@CURRENT_FC)),0) as REMAINING_FC
				end
				else
				begin
				 --set @REMAINING_AMT= '0.00'  --hide by Chithra on 10-09-2018 for PARAMOUNT
				 SET @REMAINING_FC= @TOTAL_FC --NEW
				 SELECT @REMAINING_FC AS REMAINING_FC
				end
		 
		----------------------------------------------------------------------------------------------------------------
		    
		 set @TOTAL_CIF=(select  isnull(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_CIF_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_CIF_VALUE,'0') end),0)  from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@LICENSE_NO and LICENSE_TYPE=@SCHEME_CODE and SINGLE_DUTY_Y_N='Y')
		 set @Current_CIF=(select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DEBIT_AMT,'') =''  THEN   '0' else ISNULL(DEBIT_AMT,'0') end)),0)  FROM LICENSE_DETAILS where  REGISTRATION_NO=@LICENSE_NO and SCHEME_CODE=@SCHEME_CODE)

		  if(@Current_CIF>1)
			begin
		        SELECT   isnull(sum(CONVERT(numeric(19,2),@TOTAL_CIF)),0) - isnull(sum(CONVERT(numeric(19,2),@Current_CIF)),0) as REMAINING_CIF
		    end
		    else
		    begin
		     --set @REMAINING_AMT= '0.00'  --hide by Chithra on 10-09-2018 for PARAMOUNT
		     SET @REMAINING_CIF= @TOTAL_CIF --NEW
		     SELECT @REMAINING_CIF AS REMAINING_CIF
		    end
		
		----------------------------------------------------------------------------------------------------------------------
		    
			SELECT Convert(varchar(11),LICENSE_DATE, 103)LICENSE_DATE,Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,* 
		 FROM IMPORT_LICENSE_MASTER where REGISTRATION_NO like @LICENSE_NO+'%' and LICENSE_TYPE like @SCHEME_CODE+'%'
		ORDER BY REGISTRATION_NO
	select @Mstatus=1
end
		
		
end

else if(@name='Get_License_with_SchemeCode')
	begin
		SELECT * FROM IMPORT_LICENSE_MASTER where REGISTRATION_NO like @LICENSE_NO+'%' and LICENSE_TYPE like @SCHEME_CODE+'%'
		ORDER BY REGISTRATION_NO
	end

else if(@name='Get_License_SINGLE_DUTY_VALUE')
	begin
		SELECT TOTAL_DEBIT_AMT,TOTAL_DEBIT_QTY FROM IMPORT_LICENSE_MASTER where REGISTRATION_NO like @LICENSE_NO+'%'  AND SINGLE_DUTY_Y_N='Y' and LICENSE_TYPE='36-MEIS'
		
	end
	
else if(@name='Check_License_SINGLE_DUTY_Available')
	begin
		SELECT SINGLE_DUTY_Y_N FROM IMPORT_LICENSE_MASTER where REGISTRATION_NO like @LICENSE_NO+'%'  and LICENSE_TYPE='36-MEIS' and SINGLE_DUTY_Y_N='Y'
		set @Mstatus=1
	end   

commit
end try
begin catch
rollback transaction
	set @ErrorMsg=error_message()
	set @MStatus=0
end catch

/****** Object:  StoredProcedure [dbo].[IMP_LICENSE_DEBIT_RPT_SEARCH_SELECT]    Script Date: 10/12/2018 15:35:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
ALTER PROCEDURE [dbo].[IMP_LICENSE_DEBIT_RPT_SEARCH_SELECT]

   @LICENSE_NO varchar(50),
   @PartyName varchar(100),
   @PORT_OF_LICNESE varchar(15),
   @SCHEME_CODE varchar(40),
   @BRANCH_CODE  varchar(50),
   @Ename varchar(50),
   @Mstatus  int output,
   @ErrorMsg nvarchar(max) output
   
	AS
	begin try
	begin transaction
	set @ErrorMsg=''

/*
DECLARE @LICENSE_NO varchar(50),
   @PartyName varchar(100),
   @PORT_OF_LICNESE varchar(15),
   @BRANCH_CODE  varchar(50),
   @SCHEME_CODE varchar(40),
   @Ename varchar(50),
   @Mstatus  int ,
   @ErrorMsg nvarchar(max)
		
set @ErrorMsg=''
	set @LICENSE_NO='1234509877'
	--set @LICENSE_NO='0000000000'
	--set @LICENSE_NO=''
	set @PartyName=''

	SET @Ename='SELECT_LICENSE_PARTYWISE'
  --set @LICENSE_NO=''
  set @PartyName=''
  --set @PORT_OF_LICNESE='INMAA1'
  --SET @BRANCH_CODE='CusHouse, Chennai'
  
  set @PORT_OF_LICNESE=''
  --SET @BRANCH_CODE='CusHouse, JNPT'
  
  --set @PORT_OF_LICNESE='INMAA4'
  SET @BRANCH_CODE='ACC, Chennai'
  
  --set @PORT_OF_LICNESE=''
  --SET @BRANCH_CODE=''
  --SET @SCHEME_CODE='12-EPCG'
--SET @SCHEME_CODE='36-MEIS'
SET @SCHEME_CODE=''
*/

  declare @i int set @i=0;
	declare @tbl_jobno table(slno int identity(1,1),RegnNo varchar(20))
	declare @tbl_Final table(slno int identity(1,1),Jobno varchar(20),License_RegNo varchar(15),License_No varchar(15),Scheme Varchar(20),ImporterName varchar(100),File_Ref_no varchar(20),BE_NO varchar(10), BE_DATE datetime,BranchCode  varchar(50),License_Value varchar(50),Balance varchar(50),Debit_amt varchar(50),PORT VARCHAR(30),Lic_ItemNo varchar(10),slno_order int
	                        ,License_FC varchar(50),Debit_FC Varchar(50),Remaining_FC varchar(50),TOTAL_CIF varchar(50),Debit_CIF Varchar(50),Remaining_CIF varchar(50))
	declare @tbl_lic_ItemNo table(slno int identity(1,1),RegnNo varchar(20),Lic_ItemNo varchar(10),PORT VARCHAR(30))
	DECLARE @tbl_FC table(JOBNO VARCHAR(50),INV_EXRATE VARCHAR(50),CIF_AMOUNT VARCHAR(50),CURRENT_FC VARCHAR(50))
	
	DECLARE @tbl_CIF table(JOBNO VARCHAR(50),INV_EXRATE VARCHAR(50),DEBIT_AMT VARCHAR(50),CURRENT_CIF VARCHAR(50))
	
	
	declare @id VARCHAR(25)
	declare @run int set @run=1;
	declare @port varchar(50)
	declare @branch varchar(50)
	declare @min int
	
declare @lic_no varchar(20)
DECLARE @License_Value decimal(15,2)
DECLARE @debit_amt decimal(15,2)
DECLARE @LESS_DEBIT decimal(15,2)
declare @k int
declare @cnt int
DECLARE @lIC_debit_amt decimal(15,2)
declare @lic_ItemNo  varchar(10)
DECLARE @TOTAL_FC  decimal(15,2)
declare @Current_FC  decimal(15,2)
declare @REMAINING_FC  decimal(15,2)

DECLARE @TOTAL_CIF  decimal(15,2)
declare @Current_CIF  decimal(15,2)
declare @REMAINING_CIF  decimal(15,2)

declare @min_itemNo int
declare @COUNT_itemNo int
declare @regno_master varchar(20)
declare @licItemno_master varchar(20)
declare @licPORT_master varchar(20)
declare @xx int
declare @EXRATE varchar(20)
declare @chk_EXRATE varchar(20)

	/**************************************** set Branchwise='' - for all branch license value calc Refd by Bala sir on 06-10-2018***************************/
	SET @BRANCH_CODE=''
	/**************************************** set Branchwise='' - for all branch license value calc ***************************/
	
	
if(@Ename='SELECT_LICENSE_PARTYWISE')
begin

  IF(@BRANCH_CODE<>'')
  BEGIN

	insert into @tbl_jobno
	SELECT DISTINCT REGISTRATION_NO FROM LICENSE_DETAILS WHERE REGISTRATION_NO like '%'+@LICENSE_NO and SCHEME_CODE like '%'+@SCHEME_CODE AND BRANCH_CODE=@BRANCH_CODE order by REGISTRATION_NO 
	set @i=(select COUNT(RegnNo) from @tbl_jobno)
	
	--select * from @tbl_jobno

	if(@i>=1)
	begin
		while(@i>=@run)
		begin
		  set @id=(select RegnNo from @tbl_jobno where slno=@run)

		    IF(@PORT_OF_LICNESE<>'')
		    BEGIN 
				insert into  @tbl_Final
				select distinct a.JOBNO,c.REGISTRATION_NO,c.LICENSE_NO,SCHEME_CODE,IMPORTER_NAME,FILE_REF_NO,BE_NO,BE_DATE,a.BRANCHCODE,'','','',c.PORT_OF_LICENSE,c.LICENSE_ITEM_NO,'0'
				,case when ISNULL(TOTAL_FC_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_FC_VALUE,'0') end,'','' 
				,case when ISNULL(d.TOTAL_CIF_VALUE,'') =''  THEN   '0' else ISNULL(d.TOTAL_CIF_VALUE,'0') end,'',''
				FROM GENERAL_DETAILS a  
				 left outer join BE_ENTRY b on a.JOBNO=b.BE_JOBNO AND a.BRANCHCODE=b.BRANCH_CODE
				 Left outer join LICENSE_DETAILS c on a.JOBNO=c.JOBNO and a.BRANCHCODE=c.BRANCH_CODE
				 Left outer join IMPORT_LICENSE_MASTER d on c.REGISTRATION_NO=d.REGISTRATION_NO and c.LICENSE_ITEM_NO=d.LICENSE_ITEM_NO and c.SCHEME_CODE=d.LICENSE_TYPE
			   WHERE c.REGISTRATION_NO=@id and IMPORTER_NAME  like '%'+@PartyName and c.PORT_OF_LICENSE like '%'+@PORT_OF_LICNESE and a.BRANCHCODE=@BRANCH_CODE  order by LICENSE_ITEM_NO
			END
			ELSE
			BEGIN  
			   insert into  @tbl_Final
				select distinct a.JOBNO,c.REGISTRATION_NO,c.LICENSE_NO,SCHEME_CODE,IMPORTER_NAME,FILE_REF_NO,BE_NO,BE_DATE,a.BRANCHCODE,'','','',c.PORT_OF_LICENSE,c.LICENSE_ITEM_NO,'0'
				,case when ISNULL(TOTAL_FC_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_FC_VALUE,'0') end,'','' 
				,case when ISNULL(d.TOTAL_CIF_VALUE,'') =''  THEN   '0' else ISNULL(d.TOTAL_CIF_VALUE,'0') end,'',''
				FROM GENERAL_DETAILS a  
				 left outer join BE_ENTRY b on a.JOBNO=b.BE_JOBNO AND a.BRANCHCODE=b.BRANCH_CODE
				 Left outer join LICENSE_DETAILS c on a.JOBNO=c.JOBNO and a.BRANCHCODE=c.BRANCH_CODE
				 Left outer join IMPORT_LICENSE_MASTER d on c.REGISTRATION_NO=d.REGISTRATION_NO and c.LICENSE_ITEM_NO=d.LICENSE_ITEM_NO and c.SCHEME_CODE=d.LICENSE_TYPE
			   WHERE c.REGISTRATION_NO=@id and IMPORTER_NAME  like '%'+@PartyName  and a.BRANCHCODE=@BRANCH_CODE order by LICENSE_ITEM_NO
			END   
		  set @run=@run+1;
	   end
	end

	--select * from @tbl_Final
 
set @run=1;
set @i=(select COUNT(License_RegNo) from @tbl_Final)
--select @i
set  @min_itemNo=1
			
if(@i>=1)
	begin
	set @cnt=1

			SET @COUNT_itemNo=(select COUNT(LICENSE_ITEM_NO) from IMPORT_LICENSE_MASTER where REGISTRATION_NO like '%'+@LICENSE_NO)
			--SELECT @COUNT_itemNo
			
					--IF(@COUNT_itemNo>1)
					--BEGIN
						 insert into  @tbl_lic_ItemNo
						 SELECT REGISTRATION_NO,LICENSE_ITEM_NO,PORT_OF_LICENSE FROM IMPORT_LICENSE_MASTER WHERE REGISTRATION_NO like '%'+@LICENSE_NO order by REGISTRATION_NO,LICENSE_ITEM_NO
					--END
					--SELECT * FROM @tbl_lic_ItemNo 
			
 while(@COUNT_itemNo>=@min_itemNo)
begin
			set @regno_master=( select RegnNo  from @tbl_lic_ItemNo where slno=@min_itemNo)
			set @licItemno_master=( select Lic_ItemNo  from @tbl_lic_ItemNo where slno=@min_itemNo)
			set @licPORT_master=( select PORT  from @tbl_lic_ItemNo where slno=@min_itemNo)
			
			 
			set @i=0;
			set @i=( select COUNT(License_RegNo) from @tbl_Final where License_RegNo=@regno_master and Lic_ItemNo=@licItemno_master and BranchCode=@BRANCH_CODE)
			SET @License_Value=(select TOP 1 case when ISNULL(TOTAL_FC_VALUE,'') ='' then '0.00' else TOTAL_DEBIT_AMT  end from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@regno_master and LICENSE_ITEM_NO=@licItemno_master)
			--select @regno_master,@licPORT_master,@licItemno_master,@licPORT_master,'MASTER'
			set @TOTAL_FC=(select  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_FC_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_FC_VALUE,'0') end)),0)  from IMPORT_LICENSE_MASTER where REGISTRATION_NO =@regno_master and LICENSE_TYPE like '%'+ @SCHEME_CODE  AND LICENSE_ITEM_NO=@licItemno_master)
			set @TOTAL_CIF=(select  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_CIF_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_CIF_VALUE,'0') end)),0)  from IMPORT_LICENSE_MASTER where REGISTRATION_NO =@regno_master and LICENSE_TYPE like '%'+ @SCHEME_CODE  AND LICENSE_ITEM_NO=@licItemno_master)

			set @xx=(select min(slno) from @tbl_Final  where License_RegNo=@regno_master and Lic_ItemNo=@licItemno_master)
			SET @run=1
			while(@i>=@run)
			begin
				  set @id=(select Jobno from @tbl_Final where slno=@xx and License_RegNo=@regno_master)
				  update @tbl_Final set slno_order=@run where slno=@xx and License_RegNo=@regno_master
				  
				  
			/******************************TO CALCULATE REMAINING debit duty VALUE  *******************************/	  
						set  @debit_amt =(select isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ENTRY_DEBIT_DUTY,'') =''  THEN   '0' else ISNULL(ENTRY_DEBIT_DUTY,'0') end)),0) as DEBIT_DUTY 
											from LICENSE_DETAILS where  PORT_OF_LICENSE like '%'+@PORT_OF_LICNESE and REGISTRATION_NO=@regno_master AND JOBNO=@id and LICENSE_ITEM_NO=@licItemno_master AND BRANCH_CODE=@BRANCH_CODE)
						--select @debit_amt
						SET @LESS_DEBIT=@License_Value-@debit_amt
						
			
			/******************************TO CALCULATE REMAINING FC VALUE FOR PARAMOUNT 15-09-2018 *******************************/						
			
			--SELECT a.JOBNO,INVOICE_EXRATE,ENTRY_DEBIT_DUTY, isnull(sum(CONVERT(numeric(19,2),DEBIT_AMT)),0)/isnull(CONVERT(numeric(19,2),INVOICE_EXRATE),0) as CURRENT_FC
			--FROM LICENSE_DETAILS a left outer join INVOICE_DETAILS b on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO
			--where REGISTRATION_NO = @regno_master AND a.JOBNO=@id and a.SCHEME_CODE like '%'+@SCHEME_CODE AND LICENSE_ITEM_NO=@licItemno_master group by INVOICE_EXRATE,a.JOBNO,ENTRY_DEBIT_DUTY
			
			--SET @EXRATE=(SELECT  top 1 isnull(CONVERT(numeric(19),EX_RATE),0) as EX_RATE FROM LICENSE_DETAILS where REGISTRATION_NO = @regno_master AND JOBNO=@id and SCHEME_CODE like '%'+@SCHEME_CODE AND LICENSE_ITEM_NO=@licItemno_master AND BRANCH_CODE=@BRANCH_CODE)
			SET @EXRATE=(SELECT  top 1 case when ISNULL(EX_RATE,'') ='' then '0' else isnull(CONVERT(numeric(19),EX_RATE),0)  end as EX_RATE FROM LICENSE_DETAILS where REGISTRATION_NO = @regno_master AND JOBNO=@id and SCHEME_CODE like '%'+@SCHEME_CODE AND LICENSE_ITEM_NO=@licItemno_master AND BRANCH_CODE=@BRANCH_CODE)
		
			IF(@EXRATE>0)
			BEGIN
			--SELECT @EXRATE,@regno_master,@licItemno_master
				INSERT INTO @tbl_FC
				SELECT JOBNO,isnull(CONVERT(numeric(19,2),EX_RATE),0),DEBIT_AMT, isnull(sum(CONVERT(numeric(19,2),DEBIT_AMT)),0)/isnull(CONVERT(numeric(19,2),EX_RATE),0) as CURRENT_FC
				FROM LICENSE_DETAILS --a left outer join INVOICE_DETAILS b on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO
				where REGISTRATION_NO = @regno_master AND JOBNO=@id and SCHEME_CODE like '%'+@SCHEME_CODE AND LICENSE_ITEM_NO=@licItemno_master AND BRANCH_CODE=@BRANCH_CODE group by EX_RATE,JOBNO,DEBIT_AMT

				--select * from @tbl_FC

				set @CURRENT_FC=(select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CURRENT_FC,'') =''  THEN   '0' else ISNULL(CURRENT_FC,'0') end)),0)  FROM @tbl_FC WHERE  JOBNO=@id )
				
				SET @REMAINING_FC=@TOTAL_FC-@CURRENT_FC
			--SELECT @TOTAL_FC,@CURRENT_FC,@REMAINING_FC
			
			END
			ELSE
			BEGIN
			   set @CURRENT_FC=0.00;
			   SET @REMAINING_FC=@TOTAL_FC-@CURRENT_FC
			END
			/******************************TO CALCULATE REMAINING FC VALUE FOR PARAMOUNT 15-09-2018 *******************************/
			
			
			/******************************TO CALCULATE REMAINING CIF VALUE FOR PARAMOUNT 15-09-2018 *******************************/						
			set @CURRENT_CIF =(select isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DEBIT_AMT,'') =''  THEN   '0' else ISNULL(DEBIT_AMT,'0') end)),0) as DEBIT_AMT 
											from LICENSE_DETAILS where  PORT_OF_LICENSE like '%'+@PORT_OF_LICNESE and REGISTRATION_NO=@regno_master AND JOBNO=@id  AND LICENSE_ITEM_NO=@licItemno_master AND BRANCH_CODE=@BRANCH_CODE)	 
											
			SET @REMAINING_CIF=@TOTAL_CIF-@Current_CIF
			--SELECT @TOTAL_CIF,@REMAINING_CIF,@CURRENT_CIF	 
			
			/******************************TO CALCULATE REMAINING CIF VALUE FOR PARAMOUNT 15-09-2018 *******************************/
			
									
								
						--(doubt)update @tbl_Final set License_Value=@License_Value, Debit_amt=@debit_amt,Balance=@LESS_DEBIT where Jobno=@id and License_RegNo=@regno_master  and PORT=@licPORT_master  and Lic_ItemNo=@licItemno_master
						update @tbl_Final set License_Value=@License_Value, Debit_amt=@debit_amt,Balance=@LESS_DEBIT,Debit_FC=@CURRENT_FC,Remaining_FC=@REMAINING_FC,TOTAL_CIF=@TOTAL_CIF,Debit_CIF=@Current_CIF,Remaining_CIF=@REMAINING_CIF where Jobno=@id and License_RegNo=@regno_master   and Lic_ItemNo=@licItemno_master
						
						SET  @License_Value=@LESS_DEBIT
						SET @TOTAL_FC=@REMAINING_FC
						SET @TOTAL_CIF=@REMAINING_CIF
						--------------------------------- UPDATE EMPTY FIELDS FOR DUPLICATE LICNESE NUMBER-------------------------------------------
						if(@run>=2)
							begin
							--set @min=(select min(slno) from @tbl_Final where License_RegNo=@lic_no and lic_ItemNo=@lic_ItemNo)
							--SELECT @min+10
							  update @tbl_Final set License_RegNo='',License_No='',Scheme='',License_Value='',Lic_ItemNo='',License_FC='',TOTAL_CIF='' where  License_RegNo=@regno_master and slno=@xx  and lic_ItemNo=@licItemno_master
							end
					     --------------------------------- UPDATE EMPTY FIELDS FOR DUPLICATE LICNESE NUMBER-------------------------------------------
						
						SET @LESS_DEBIT='0.00';
						SET @lIC_debit_amt='0.00';
						SET @debit_amt='0.00';	
						set @CURRENT_FC='0.00'	
						SET @CURRENT_CIF='0.00'
					set @run+=1;
					set @xx+=1;	
			 end
			 
			set @min_itemNo+=1;
			end   
	end
END

ELSE
BEGIN
 
 insert into @tbl_jobno
	SELECT DISTINCT REGISTRATION_NO FROM LICENSE_DETAILS WHERE REGISTRATION_NO like '%'+@LICENSE_NO and SCHEME_CODE like '%'+@SCHEME_CODE order by REGISTRATION_NO
	set @i=(select COUNT(RegnNo) from @tbl_jobno)
--SELECT * FROM @tbl_jobno
	if(@i>=1)
	begin
		while(@i>=@run)
		begin
		  set @id=(select RegnNo from @tbl_jobno where slno=@run)

		    IF(@PORT_OF_LICNESE<>'')
		    BEGIN
				insert into  @tbl_Final
				select distinct a.JOBNO,c.REGISTRATION_NO,c.LICENSE_NO,SCHEME_CODE,IMPORTER_NAME,FILE_REF_NO,BE_NO,BE_DATE,a.BRANCHCODE,'','','',c.PORT_OF_LICENSE,c.LICENSE_ITEM_NO,'0'
				,case when ISNULL(TOTAL_FC_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_FC_VALUE,'0') end,'','' 
				,case when ISNULL(d.TOTAL_CIF_VALUE,'') =''  THEN   '0' else ISNULL(d.TOTAL_CIF_VALUE,'0') end,'',''
				FROM GENERAL_DETAILS a  
				 left outer join BE_ENTRY b on a.JOBNO=b.BE_JOBNO 
				 --Left outer join LICENSE_DETAILS c on a.JOBNO=c.JOBNO AND a.BRANCHCODE=c.BRANCH_CODE
				 Left outer join LICENSE_DETAILS c on a.JOBNO=c.JOBNO
				 Left outer join IMPORT_LICENSE_MASTER d on c.REGISTRATION_NO=d.REGISTRATION_NO and c.LICENSE_ITEM_NO=d.LICENSE_ITEM_NO and c.SCHEME_CODE=d.LICENSE_TYPE
			   WHERE c.REGISTRATION_NO=@id and IMPORTER_NAME  like '%'+@PartyName   order by c.LICENSE_ITEM_NO 
			   
			   
			END
			ELSE
			BEGIN  
			   insert into  @tbl_Final
				select distinct a.JOBNO,c.REGISTRATION_NO,c.LICENSE_NO,SCHEME_CODE,IMPORTER_NAME,FILE_REF_NO,BE_NO,BE_DATE,a.BRANCHCODE,'','','',c.PORT_OF_LICENSE,c.LICENSE_ITEM_NO,'0'
				,case when ISNULL(TOTAL_FC_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_FC_VALUE,'0') end,'','' 
				,case when ISNULL(d.TOTAL_CIF_VALUE,'') =''  THEN   '0' else ISNULL(d.TOTAL_CIF_VALUE,'0') end,'',''
				FROM GENERAL_DETAILS a  
				 left outer join BE_ENTRY b on a.JOBNO=b.BE_JOBNO
				 --Left outer join LICENSE_DETAILS c on a.JOBNO=c.JOBNO AND a.BRANCHCODE=c.BRANCH_CODE
				 Left outer join LICENSE_DETAILS c on a.JOBNO=c.JOBNO
				 Left outer join IMPORT_LICENSE_MASTER d on c.REGISTRATION_NO=d.REGISTRATION_NO and c.LICENSE_ITEM_NO=d.LICENSE_ITEM_NO and c.SCHEME_CODE=d.LICENSE_TYPE
			   WHERE c.REGISTRATION_NO=@id and IMPORTER_NAME  like '%'+@PartyName order by LICENSE_ITEM_NO
			   
			END   
		  set @run=@run+1;
	   end
	end

	--select * from @tbl_Final
 
set @run=1;
set @i=(select COUNT(License_RegNo) from @tbl_Final)
set  @min_itemNo=1
		
if(@i>=1)
	begin
	set @cnt=1

			SET @COUNT_itemNo=(select COUNT(LICENSE_ITEM_NO) from IMPORT_LICENSE_MASTER where REGISTRATION_NO like '%'+@LICENSE_NO)
			--SELECT @COUNT_itemNo
			
					--IF(@COUNT_itemNo>1)
					--BEGIN
						 insert into  @tbl_lic_ItemNo
						 SELECT REGISTRATION_NO,LICENSE_ITEM_NO,PORT_OF_LICENSE FROM IMPORT_LICENSE_MASTER WHERE REGISTRATION_NO like '%'+@LICENSE_NO order by REGISTRATION_NO,LICENSE_ITEM_NO
					--END
					--SELECT * FROM @tbl_lic_ItemNo 
			
 while(@COUNT_itemNo>=@min_itemNo)
begin
			set @regno_master=( select RegnNo  from @tbl_lic_ItemNo where slno=@min_itemNo)
			set @licItemno_master=( select Lic_ItemNo  from @tbl_lic_ItemNo where slno=@min_itemNo)
			set @licPORT_master=( select PORT  from @tbl_lic_ItemNo where slno=@min_itemNo)
			
			 
			set @i=0;
			set @i=( select COUNT(License_RegNo) from @tbl_Final where License_RegNo=@regno_master and Lic_ItemNo=@licItemno_master)
			--select @regno_master
			 --SET @License_Value=(select TOP 1 TOTAL_DEBIT_AMT from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@regno_master  and LICENSE_ITEM_NO=@licItemno_master)
			 SET @License_Value=(select TOP 1 case when ISNULL(TOTAL_FC_VALUE,'') ='' then '0.00' else TOTAL_DEBIT_AMT  end from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@regno_master  and LICENSE_ITEM_NO=@licItemno_master)
			--select @regno_master,@licPORT_master,@licItemno_master,@licPORT_master,'MASTER'
			set @TOTAL_FC=(select  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_FC_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_FC_VALUE,'0') end)),0)  from IMPORT_LICENSE_MASTER where REGISTRATION_NO=@regno_master and LICENSE_TYPE like '%'+@SCHEME_CODE AND LICENSE_ITEM_NO=@licItemno_master)
			set @TOTAL_CIF=(select  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_CIF_VALUE,'') =''  THEN   '0' else ISNULL(TOTAL_CIF_VALUE,'0') end)),0)  from IMPORT_LICENSE_MASTER where REGISTRATION_NO =@regno_master and LICENSE_TYPE like '%'+ @SCHEME_CODE  AND LICENSE_ITEM_NO=@licItemno_master)
			
			set @xx=(select min(slno) from @tbl_Final  where License_RegNo=@regno_master and Lic_ItemNo=@licItemno_master)
			SET @run=1
			while(@i>=@run)
			begin
				  set @id=(select Jobno from @tbl_Final where slno=@xx and License_RegNo=@regno_master)
				  update @tbl_Final set slno_order=@run where slno=@xx and License_RegNo=@regno_master
				  
/******************************TO CALCULATE REMAINING debit duty VALUE*******************************/		
						set  @debit_amt =(select isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ENTRY_DEBIT_DUTY,'') =''  THEN   '0' else ISNULL(ENTRY_DEBIT_DUTY,'0') end)),0) as DEBIT_DUTY 
											from LICENSE_DETAILS where  PORT_OF_LICENSE like '%'+@PORT_OF_LICNESE and REGISTRATION_NO=@regno_master AND JOBNO=@id and LICENSE_ITEM_NO=@licItemno_master)
						--select @debit_amt	 
						SET @LESS_DEBIT=@License_Value-@debit_amt

/******************************TO CALCULATE REMAINING FC VALUE FOR PARAMOUNT 15-09-2018 *******************************/						
			--INSERT INTO @tbl_FC
			--SELECT a.JOBNO,INVOICE_EXRATE,ENTRY_DEBIT_DUTY, isnull(sum(CONVERT(numeric(19,2),DEBIT_AMT)),0)/isnull(CONVERT(numeric(19,2),INVOICE_EXRATE),0) as CURRENT_FC
			--FROM LICENSE_DETAILS a left outer join INVOICE_DETAILS b on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO
			--where REGISTRATION_NO = @regno_master AND a.JOBNO=@id and a.SCHEME_CODE like '%'+@SCHEME_CODE AND LICENSE_ITEM_NO=@licItemno_master group by INVOICE_EXRATE,a.JOBNO,ENTRY_DEBIT_DUTY
			--select * from @tbl_FC
			
			
				--SET @EXRATE=(SELECT  top 1 isnull(CONVERT(numeric(19),EX_RATE),0) as EX_RATE FROM LICENSE_DETAILS where REGISTRATION_NO = @regno_master AND JOBNO=@id and SCHEME_CODE like '%'+@SCHEME_CODE AND LICENSE_ITEM_NO=@licItemno_master )
				SET @EXRATE=(SELECT  top 1 case when ISNULL(EX_RATE,'') ='' then '0' else isnull(CONVERT(numeric(19),EX_RATE),0)  end as EX_RATE FROM LICENSE_DETAILS where REGISTRATION_NO = @regno_master AND JOBNO=@id and SCHEME_CODE like '%'+@SCHEME_CODE AND LICENSE_ITEM_NO=@licItemno_master )
			
				IF(@EXRATE>0)
				BEGIN
				--SELECT @EXRATE
					INSERT INTO @tbl_FC
					SELECT JOBNO,isnull(CONVERT(numeric(19,2),EX_RATE),0),DEBIT_AMT, isnull(sum(CONVERT(numeric(19,2),DEBIT_AMT)),0)/isnull(CONVERT(numeric(19,2),EX_RATE),0) as CURRENT_FC
					FROM LICENSE_DETAILS --a left outer join INVOICE_DETAILS b on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO
					where REGISTRATION_NO = @regno_master AND JOBNO=@id and SCHEME_CODE like '%'+@SCHEME_CODE AND LICENSE_ITEM_NO=@licItemno_master group by EX_RATE,JOBNO,DEBIT_AMT

					--select * from @tbl_FC

					set @CURRENT_FC=(select   isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CURRENT_FC,'') =''  THEN   '0' else ISNULL(CURRENT_FC,'0') end)),0)  FROM @tbl_FC WHERE  JOBNO=@id )
					
					SET @REMAINING_FC=@TOTAL_FC-@CURRENT_FC
				--SELECT @id, @TOTAL_FC,@CURRENT_FC,@REMAINING_FC,@licItemno_master
				
				END
				ELSE
				BEGIN
				   set @CURRENT_FC=0.00;
				   SET @REMAINING_FC=@TOTAL_FC-@CURRENT_FC
				END
			
			
			/******************************TO CALCULATE REMAINING FC VALUE FOR PARAMOUNT 15-09-2018 *******************************/						
		
		
		    /******************************TO CALCULATE REMAINING CIF VALUE FOR PARAMOUNT 15-09-2018 *******************************/						
			set @CURRENT_CIF =(select isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DEBIT_AMT,'') =''  THEN   '0' else ISNULL(DEBIT_AMT,'0') end)),0) as DEBIT_AMT 
											from LICENSE_DETAILS where  PORT_OF_LICENSE like '%'+@PORT_OF_LICNESE and REGISTRATION_NO=@regno_master AND JOBNO=@id  and LICENSE_ITEM_NO=@licItemno_master)	 
											
			SET @REMAINING_CIF=@TOTAL_CIF-@Current_CIF
			--SELECT @TOTAL_CIF,@REMAINING_CIF,@CURRENT_CIF	 
			
			/******************************TO CALCULATE REMAINING CIF VALUE FOR PARAMOUNT 15-09-2018 *******************************/
							
									
						--(doubt)update @tbl_Final set License_Value=@License_Value, Debit_amt=@debit_amt,Balance=@LESS_DEBIT where Jobno=@id and License_RegNo=@regno_master  and PORT=@licPORT_master  and Lic_ItemNo=@licItemno_master
						update @tbl_Final set License_Value=@License_Value, Debit_amt=@debit_amt,Balance=@LESS_DEBIT,Debit_FC=@CURRENT_FC,Remaining_FC=@REMAINING_FC,TOTAL_CIF=@TOTAL_CIF,Debit_CIF=@Current_CIF,Remaining_CIF=@REMAINING_CIF where Jobno=@id and License_RegNo=@regno_master   and Lic_ItemNo=@licItemno_master
						SET  @License_Value=@LESS_DEBIT
						SET @TOTAL_FC=@REMAINING_FC
						SET @TOTAL_CIF=@REMAINING_CIF
						--------------------------------- UPDATE EMPTY FIELDS FOR DUPLICATE LICNESE NUMBER-------------------------------------------
						if(@run>=2)
							begin
							--set @min=(select min(slno) from @tbl_Final where License_RegNo=@lic_no and lic_ItemNo=@lic_ItemNo)
							--SELECT @min+10
							  update @tbl_Final set License_RegNo='',License_No='',Scheme='',License_Value='',Lic_ItemNo='',License_FC='',TOTAL_CIF='' where  License_RegNo=@regno_master and slno=@xx  and lic_ItemNo=@licItemno_master
							end
					     --------------------------------- UPDATE EMPTY FIELDS FOR DUPLICATE LICNESE NUMBER-------------------------------------------
						
						SET @LESS_DEBIT='0.00';
						SET @lIC_debit_amt='0.00';
						SET @debit_amt='0.00';
						SET @CURRENT_FC='0.00'	
						SET @CURRENT_CIF='0.00'	
					set @run+=1;
					set @xx+=1;	
			 end
			 
			set @min_itemNo+=1;
			end   
	end
END
--select * from @tbl_Final

--select Convert(varchar(11),BE_DATE, 103)BE_DATE,*  from @tbl_Final order by slno
select License_RegNo,License_No,Scheme,Jobno,File_Ref_no,Lic_ItemNo,License_Value,Debit_amt as Debit_Duty,Balance ,
       License_FC,Debit_FC,Remaining_FC,TOTAL_CIF,Debit_CIF,Remaining_CIF,BE_NO, Convert(varchar(11),BE_DATE, 103)BE_DATE,PORT  from @tbl_Final  
end	
------------------------------------------------------------------------------------------------------------------------------------------------- 

else if(@Ename='select_License_JOBNO_TO_IMPORTER_NAME')
begin

	--declare @i int 
	set @i=0;
	declare @tbl_jobno1 table(slno int identity(1,1),Jobno varchar(20))
	declare @tbl_Final1 table(slno int identity(1,1),Jobno varchar(20),ImporterName varchar(100))

	insert into @tbl_jobno1
	SELECT DISTINCT JOBNO FROM LICENSE_DETAILS WHERE REGISTRATION_NO=@LICENSE_NO

	set @i=(select COUNT(Jobno) from @tbl_jobno1)

	--declare @id int
	--declare @run int
	set @run=1;

	if(@i>=1)
	begin
		while(@i>=@run)
		begin
		  set @id=(select Jobno from @tbl_jobno1 where slno=@run)
		  insert into  @tbl_Final1
		  select JOBNO,IMPORTER_NAME FROM GENERAL_DETAILS WHERE JOBNO=@id
		  set @run=@run+1;
	   end
	end

	select distinct(ImporterName) from @tbl_Final1

	SELECT DISTINCT PORT_OF_LICENSE FROM LICENSE_DETAILS WHERE REGISTRATION_NO=@LICENSE_NO
	SELECT DISTINCT SCHEME_CODE FROM LICENSE_DETAILS WHERE REGISTRATION_NO=@LICENSE_NO
  
end

else if(@Ename='select_General_IMPORTER_NAME')
begin
 select distinct(IMPORTER_NAME) from GENERAL_DETAILS order by IMPORTER_NAME asc
 SELECT DISTINCT PORT_OF_LICENSE FROM LICENSE_DETAILS  order by PORT_OF_LICENSE asc
 SELECT DISTINCT SCHEME_CODE FROM LICENSE_DETAILS  order by SCHEME_CODE asc
 
 
end



commit
end try
begin catch
rollback transaction
	set @ErrorMsg=error_message()
	set @MStatus=0
end catch

