ALTER PROCEDURE [dbo].[SP_LICENSE_DETAILS_INSERT_UPDATE]

		   @LICENSE_ID bigint,
           @JOBNO bigint, 
           @INVOICE_SLNO bigint,
           @ITEM_SLNO bigint,
           @SCHEME_CODE varchar(50),
           @REGISTRATION_NO varchar(10), 
           @REGISTRATION_DATE datetime, 
           @EXCEMPTION varchar(1), 
           @DEBIT_AMT varchar(19), 
           @DEBIT_QTY varchar(19), 
           @UNIT_QTY varchar(3), 
           @LICENSE_ITEM_NO varchar(4), 
           @PORT_OF_LICENSE varchar(6), 
          @LICENSE_NO varchar(50), 
          @LICENSE_DATE datetime, 
          @TOTAL_CIF_VALUE varchar(50), 
          @TOTAL_DEBIT_DUTY varchar(50), 
          @ENTRY_DEBIT_DUTY varchar(50), 
          @DEBIT_DUTY varchar(50), 
          
           @USER_ID varchar(30), 
           
           @BRANCH_CODE varchar(20), 
           @YEAR varchar(9), 
           @WORKING_PERIOD varchar(30),
           @BRANCH_COMMON varchar(100),
           @LIC_DESC VARCHAR(500),
           @LICENSE_CURRENCY varchar(3),
           @EX_RATE VARCHAR(14),
           
            @Mflag varchar(100),
	        @Mstatus  int output,
	        @ErrorMsg nvarchar(max) output,
	        @Update_Id bigint output
	        
AS
begin try
	begin transaction
		set @ErrorMsg=''
		declare @autoid as bigint,@LICENSE_SLNO as bigint

if(@BRANCH_COMMON<>'')
begin
		
if(@Mflag='S')
	begin
	
set @autoid=(SELECT isnull(max(isnull(LICENSE_ID,0)),0)+1  FROM LICENSE_DETAILS where WORKING_PERIOD=@WORKING_PERIOD)
set @LICENSE_SLNO=(SELECT isnull(max(isnull(LICENSE_SLNO,0)),0)+1  FROM LICENSE_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@BRANCH_COMMON)

	IF not EXISTS(SELECT NULL FROM LICENSE_DETAILS where JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO and REGISTRATION_NO=@REGISTRATION_NO and LICENSE_ITEM_NO=@LICENSE_ITEM_NO and BRANCH_CODE=@BRANCH_COMMON)
	  BEGIN	
			
			INSERT INTO LICENSE_DETAILS
			   (
				LICENSE_ID,
			   JOBNO,
			   INVOICE_SLNO,
			   ITEM_SLNO,
			   SCHEME_CODE,
			   LICENSE_SLNO,
			   REGISTRATION_NO,
			   REGISTRATION_DATE,
			   EXCEMPTION,
			   DEBIT_AMT,
			   DEBIT_QTY,
			   UNIT_QTY,
			   LICENSE_ITEM_NO,
			   PORT_OF_LICENSE,
			   USER_ID,
			   DATE_TIME,
			   STATUS,
			   BRANCH_CODE,
			   YEAR,
			   WORKING_PERIOD,
			   DEBIT_DUTY,
			   LICENSE_NO,
			   LICENSE_DATE,
			   TOTAL_CIF_VALUE,
			   TOTAL_DEBIT_DUTY,
			   ENTRY_DEBIT_DUTY,
			   LIC_DESC,
			   LICENSE_CURRENCY,
			   EX_RATE
			   )
				 VALUES
			   (@autoid,
			   @JOBNO,
			   @INVOICE_SLNO,
	          
			   @ITEM_SLNO,
			   @SCHEME_CODE,
			   @LICENSE_SLNO,
			   @REGISTRATION_NO,
			   @REGISTRATION_DATE,
			   @EXCEMPTION,
			   @DEBIT_AMT,
			   @DEBIT_QTY,
			   @UNIT_QTY,
			   @LICENSE_ITEM_NO,
			   @PORT_OF_LICENSE,
			   @USER_ID, 
			   GETDATE(),
			   'N' ,
			   @BRANCH_CODE , 
			   @YEAR,
			   @WORKING_PERIOD,
			   @DEBIT_DUTY,
			   @LICENSE_NO,
			   @LICENSE_DATE,
			   @TOTAL_CIF_VALUE,
			   @TOTAL_DEBIT_DUTY,
			   @ENTRY_DEBIT_DUTY,
			   @LIC_DESC,
			   @LICENSE_CURRENCY,
			   @EX_RATE
				)
			--select * from RE_IMPORT_DETAILS where JOBNO=@JOBNO  and WORKING_PERIOD=@WORKING_PERIOD    
			SELECT 	Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,* FROM LICENSE_DETAILS 
			where JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  and BRANCH_CODE=@BRANCH_COMMON
			select @Mstatus=1
			select @Update_Id=@autoid
			
			
	 END
	 ELSE
	 BEGIN
	   select @Mstatus=2
	 END
 
 end		
	
else if(@Mflag='U')
	begin
	
	UPDATE LICENSE_DETAILS
   SET 
   
		
		JOBNO=@JOBNO,
			 
			   REGISTRATION_NO=@REGISTRATION_NO,
			   REGISTRATION_DATE=@REGISTRATION_DATE,
			   EXCEMPTION=@EXCEMPTION,
			   DEBIT_AMT=@DEBIT_AMT,
			   DEBIT_QTY=@DEBIT_QTY,
			   UNIT_QTY=@UNIT_QTY,
			   LICENSE_ITEM_NO=@LICENSE_ITEM_NO,
			   PORT_OF_LICENSE=@PORT_OF_LICENSE,
	                
		--USER_ID=@USER_ID,
		--DATE_TIME=getdate(),
		STATUS='U',
		BRANCH_CODE=@BRANCH_CODE,
		YEAR=@YEAR,
		WORKING_PERIOD=@WORKING_PERIOD,
		DEBIT_DUTY=@DEBIT_DUTY,
		LICENSE_NO=@LICENSE_NO,
		LICENSE_DATE=@LICENSE_DATE,
		TOTAL_CIF_VALUE=@TOTAL_CIF_VALUE,
			   TOTAL_DEBIT_DUTY=@TOTAL_DEBIT_DUTY,
			   ENTRY_DEBIT_DUTY=@ENTRY_DEBIT_DUTY,
		MODIFIEDBY=@USER_ID,
        MODIFIEDON=getdate(),
        LIC_DESC =@LIC_DESC,
        LICENSE_CURRENCY=@LICENSE_CURRENCY,
		EX_RATE=@EX_RATE
	
      
 WHERE JOBNO = @JOBNO and LICENSE_ID=@LICENSE_ID and BRANCH_CODE=@BRANCH_COMMON
 
 SELECT 	Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,* FROM LICENSE_DETAILS 
		where JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  and BRANCH_CODE=@BRANCH_COMMON
		select @Mstatus=1
		
 
 
 end
end

else
begin

if(@Mflag='S')
	begin
	
set @autoid=(SELECT isnull(max(isnull(LICENSE_ID,0)),0)+1  FROM LICENSE_DETAILS where WORKING_PERIOD=@WORKING_PERIOD)
set @LICENSE_SLNO=(SELECT isnull(max(isnull(LICENSE_SLNO,0)),0)+1  FROM LICENSE_DETAILS where JOBNO=@JOBNO and WORKING_PERIOD=@WORKING_PERIOD)

IF not EXISTS(SELECT NULL FROM LICENSE_DETAILS where JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO and REGISTRATION_NO=@REGISTRATION_NO and LICENSE_ITEM_NO=@LICENSE_ITEM_NO )
	  BEGIN	
		
		
		INSERT INTO LICENSE_DETAILS
           (
            LICENSE_ID,
           JOBNO,
           INVOICE_SLNO,
           ITEM_SLNO,
           SCHEME_CODE,
           LICENSE_SLNO,
           REGISTRATION_NO,
           REGISTRATION_DATE,
           EXCEMPTION,
           DEBIT_AMT,
           DEBIT_QTY,
           UNIT_QTY,
           LICENSE_ITEM_NO,
           PORT_OF_LICENSE,
           USER_ID,
           DATE_TIME,
           STATUS,
           BRANCH_CODE,
           YEAR,
           WORKING_PERIOD,
           DEBIT_DUTY,
           LICENSE_NO,
           LICENSE_DATE,
           TOTAL_CIF_VALUE,
			   TOTAL_DEBIT_DUTY,
			   ENTRY_DEBIT_DUTY,
			   LIC_DESC,
			   LICENSE_CURRENCY,
			   EX_RATE
           )
             VALUES
           (@autoid,
           @JOBNO,
           @INVOICE_SLNO,
          
           @ITEM_SLNO,
           @SCHEME_CODE,
           @LICENSE_SLNO,
           @REGISTRATION_NO,
           @REGISTRATION_DATE,
           @EXCEMPTION,
           @DEBIT_AMT,
           @DEBIT_QTY,
           @UNIT_QTY,
           @LICENSE_ITEM_NO,
           @PORT_OF_LICENSE,
           @USER_ID, 
           GETDATE(),
           'N' ,
           @BRANCH_CODE , 
           @YEAR,
           @WORKING_PERIOD,
           @DEBIT_DUTY,
           @LICENSE_NO,
           @LICENSE_DATE,
           @TOTAL_CIF_VALUE,
			   @TOTAL_DEBIT_DUTY,
			   @ENTRY_DEBIT_DUTY,
			   @LIC_DESC,
			   @LICENSE_CURRENCY,
			   @EX_RATE
			   
            )
		--select * from RE_IMPORT_DETAILS where JOBNO=@JOBNO  and WORKING_PERIOD=@WORKING_PERIOD    
		SELECT 	Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,* FROM LICENSE_DETAILS 
		where JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  and WORKING_PERIOD=@WORKING_PERIOD
		select @Mstatus=1
		select @Update_Id=@autoid
	 END
	 ELSE
	 BEGIN
	   select @Mstatus=2
	 END
end
	
else if(@Mflag='U')
	begin
	
	UPDATE LICENSE_DETAILS
   SET 
   
		
		JOBNO=@JOBNO,
			 
			   REGISTRATION_NO=@REGISTRATION_NO,
			   REGISTRATION_DATE=@REGISTRATION_DATE,
			   EXCEMPTION=@EXCEMPTION,
			   DEBIT_AMT=@DEBIT_AMT,
			   DEBIT_QTY=@DEBIT_QTY,
			   UNIT_QTY=@UNIT_QTY,
			   LICENSE_ITEM_NO=@LICENSE_ITEM_NO,
			   PORT_OF_LICENSE=@PORT_OF_LICENSE,
	                
		--USER_ID=@USER_ID,
		--DATE_TIME=getdate(),
		STATUS='U',
		BRANCH_CODE=@BRANCH_CODE,
		YEAR=@YEAR,
		WORKING_PERIOD=@WORKING_PERIOD,
		DEBIT_DUTY=@DEBIT_DUTY,
		LICENSE_NO=@LICENSE_NO,
		LICENSE_DATE=@LICENSE_DATE,
		TOTAL_CIF_VALUE=@TOTAL_CIF_VALUE,
			   TOTAL_DEBIT_DUTY=@TOTAL_DEBIT_DUTY,
			   ENTRY_DEBIT_DUTY=@ENTRY_DEBIT_DUTY,
		MODIFIEDBY=@USER_ID,
        MODIFIEDON=getdate(),
        LIC_DESC=@LIC_DESC,
        LICENSE_CURRENCY=@LICENSE_CURRENCY,
		EX_RATE=@EX_RATE
	
      
 WHERE JOBNO = @JOBNO and LICENSE_ID=@LICENSE_ID and WORKING_PERIOD = @WORKING_PERIOD
 
 SELECT 	Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,* FROM LICENSE_DETAILS 
		where JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  and WORKING_PERIOD=@WORKING_PERIOD
		select @Mstatus=1
		
 
 
 end

end

commit
end try
begin catch
rollback transaction
	set @ErrorMsg=error_message()
	set @MStatus=0
end catch

/****** Object:  StoredProcedure [dbo].[SP_LICENSE_DETAILS_SELECT]    Script Date: 10/12/2018 15:46:50 ******/
SET ANSI_NULLS ON
