ALTER PROCEDURE [dbo].[SP_LICENSE_DETAILS_SELECT]
	-- Add the parameters for the stored procedure here
	@LICENSE_ID bigint,
	@JOBNO varchar(20), 
    @INVOICE_SLNO  varchar(20),
       
     @ITEM_SLNO  varchar(20),
    --@RE_IMPORT_SLNO bigint,
	@DEBIT_AMT varchar(19),
	@DEBIT_DUTY varchar(19),
	@Working_Period varchar(30),
	@name 	varchar(300),
	
	@Mstatus  int output,
	@ErrorMsg nvarchar(max) output
AS
begin try
	begin transaction
		set @ErrorMsg=''
		--declare @jobid as bigint

if(@Working_Period<>'')
begin

if(@name='select_con')
	begin
	SELECT 	Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,REPLACE(Convert(varchar(11),LICENSE_DATE, 103),'01/01/1900','')LICENSE_DATE,* FROM LICENSE_DETAILS 
	where JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  and BRANCH_CODE=@Working_Period order by ITEM_SLNO
end
else if(@name='delete')
	begin
	delete from LICENSE_DETAILS where JOBNO=@JOBNO and LICENSE_ID=@LICENSE_ID and BRANCH_CODE=@Working_Period
	SELECT 	Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,Convert(varchar(11),LICENSE_DATE, 103)LICENSE_DATE,* FROM LICENSE_DETAILS 
	where JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  and BRANCH_CODE=@Working_Period order by ITEM_SLNO
	select @Mstatus=1
end

else if(@name='Update_Debit_Amt')
	begin
	if(@DEBIT_AMT<>'')
	begin
	update LICENSE_DETAILS set DEBIT_AMT=@DEBIT_AMT,DEBIT_DUTY=@DEBIT_DUTY where LICENSE_ID=@LICENSE_ID and JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  and BRANCH_CODE=@Working_Period 
	   -----------------------------UPDATE ENTRY_DEBIT_DUTY-------------------
		IF EXISTS(SELECT NULL FROM LICENSE_DETAILS WHERE LICENSE_ID=@LICENSE_ID and JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  and BRANCH_CODE=@Working_Period AND   ISNULL(ENTRY_DEBIT_DUTY,'0.00')='0.00')
		BEGIN
		  update LICENSE_DETAILS set ENTRY_DEBIT_DUTY=@DEBIT_DUTY where LICENSE_ID=@LICENSE_ID and JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  and BRANCH_CODE=@Working_Period 
		END
		----------------------------------------------------------------------
	select @Mstatus=1
	end
	else
	begin
	update LICENSE_DETAILS set DEBIT_DUTY=@DEBIT_DUTY where LICENSE_ID=@LICENSE_ID and JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  and BRANCH_CODE=@Working_Period 
	 -----------------------------UPDATE ENTRY_DEBIT_DUTY-------------------
		IF EXISTS(SELECT NULL FROM LICENSE_DETAILS WHERE LICENSE_ID=@LICENSE_ID and JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  and BRANCH_CODE=@Working_Period AND ISNULL(ENTRY_DEBIT_DUTY,'0.00')='0.00')
		BEGIN
		  update LICENSE_DETAILS set ENTRY_DEBIT_DUTY=@DEBIT_DUTY where LICENSE_ID=@LICENSE_ID and JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  and BRANCH_CODE=@Working_Period 
		END
		----------------------------------------------------------------------
	select @Mstatus=1
	end
end
-----------------------------------------------------GET LICENSE DETAILS AFTER UPDATE DEBIT AMOUNT-----FROM CHECKLIST---------------------
else if(@name='Get_Update_Debitamt_License_Details')
	begin
	
	SELECT Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,Convert(varchar(11),LICENSE_DATE, 103)LICENSE_DATE, LEFT(SCHEME_CODE,2)SCHEME_CODE,* FROM LICENSE_DETAILS 
	where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period order by JOBNO,INVOICE_SLNO,ITEM_SLNO
	
	select @Mstatus=1
end
-----------------------------------------------------GET LICENSE DETAILS AFTER UPDATE DEBIT AMOUNT-----FROM CHECKLIST---------------------

else if(@name='select_ExRate_Grid_UpdateAll')
	begin
	SELECT distinct Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,REGISTRATION_NO,PORT_OF_LICENSE,isnull(LICENSE_CURRENCY,'')as LICENSE_CURRENCY,isnull(EX_RATE,'') as EX_RATE FROM LICENSE_DETAILS 
	where JOBNO=@JOBNO  and BRANCH_CODE=@Working_Period --order by INVOICE_SLNO,ITEM_SLNO
end

else if(@name='UpdateAll_ExRate_Job')
	begin
	update LICENSE_DETAILS set LICENSE_CURRENCY=@DEBIT_AMT , EX_RATE=@DEBIT_DUTY
	where JOBNO=@JOBNO and REGISTRATION_NO=@INVOICE_SLNO  and BRANCH_CODE=@Working_Period --order by INVOICE_SLNO,ITEM_SLNO
	set @Mstatus=1
end

end
else
begin

if(@name='select_con')
	begin
	SELECT 	Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,REPLACE(Convert(varchar(11),LICENSE_DATE, 103),'01/01/1900','')LICENSE_DATE,* FROM LICENSE_DETAILS 
	where JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO   order by ITEM_SLNO
end
else if(@name='delete')
	begin
	delete from LICENSE_DETAILS where JOBNO=@JOBNO and LICENSE_ID=@LICENSE_ID 
	SELECT 	Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,Convert(varchar(11),LICENSE_DATE, 103)LICENSE_DATE,* FROM LICENSE_DETAILS 
	where JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO   order by ITEM_SLNO
	select @Mstatus=1
end

else if(@name='Update_Debit_Amt')
	begin
	
	if(@DEBIT_AMT<>'')
	begin
	update LICENSE_DETAILS set DEBIT_AMT=@DEBIT_AMT,DEBIT_DUTY=@DEBIT_DUTY where LICENSE_ID=@LICENSE_ID and JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  
	 -----------------------------UPDATE ENTRY_DEBIT_DUTY-------------------
		IF EXISTS(SELECT NULL FROM LICENSE_DETAILS WHERE LICENSE_ID=@LICENSE_ID and JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  AND ISNULL(ENTRY_DEBIT_DUTY,'0.00')='0.00')
		BEGIN
		  update LICENSE_DETAILS set ENTRY_DEBIT_DUTY=@DEBIT_DUTY where LICENSE_ID=@LICENSE_ID and JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO 
		END
		----------------------------------------------------------------------
	select @Mstatus=1
	end
	else
	begin
	update LICENSE_DETAILS set DEBIT_DUTY=@DEBIT_DUTY where LICENSE_ID=@LICENSE_ID and JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO   
	 -----------------------------UPDATE ENTRY_DEBIT_DUTY-------------------
		IF EXISTS(SELECT NULL FROM LICENSE_DETAILS WHERE LICENSE_ID=@LICENSE_ID and JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  AND ISNULL(ENTRY_DEBIT_DUTY,'0.00')='0.00')
		BEGIN
		  update LICENSE_DETAILS set ENTRY_DEBIT_DUTY=@DEBIT_DUTY where LICENSE_ID=@LICENSE_ID and JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO 
		END
		----------------------------------------------------------------------
	select @Mstatus=1
	end
	
	--update LICENSE_DETAILS set DEBIT_AMT=@DEBIT_AMT,DEBIT_DUTY=@DEBIT_DUTY where JOBNO=@JOBNO and ITEM_SLNO=@ITEM_SLNO and INVOICE_SLNO=@INVOICE_SLNO  
	
	select @Mstatus=1
end
-----------------------------------------------------GET LICENSE DETAILS AFTER UPDATE DEBIT AMOUNT-----FROM CHECKLIST---------------------
else if(@name='Get_Update_Debitamt_License_Details')
	begin
	
	SELECT Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,Convert(varchar(11),LICENSE_DATE, 103)LICENSE_DATE, LEFT(SCHEME_CODE,2)SCHEME_CODE,* FROM LICENSE_DETAILS 
	where JOBNO=@JOBNO  order by JOBNO,INVOICE_SLNO,ITEM_SLNO
	
	select @Mstatus=1
end

else if(@name='select_ExRate_Grid_UpdateAll')
	begin
	SELECT 	distinct Convert(varchar(11),REGISTRATION_DATE, 103)REGISTRATION_DATE,REGISTRATION_NO,PORT_OF_LICENSE,isnull(LICENSE_CURRENCY,'')as LICENSE_CURRENCY,isnull(EX_RATE,'') as EX_RATE FROM LICENSE_DETAILS 
	where JOBNO=@JOBNO  --order by INVOICE_SLNO,ITEM_SLNO
end

else if(@name='UpdateAll_ExRate_Job')
	begin
	update LICENSE_DETAILS set LICENSE_CURRENCY=@DEBIT_AMT , EX_RATE=@DEBIT_DUTY
	where JOBNO=@JOBNO and REGISTRATION_NO=@INVOICE_SLNO   --order by INVOICE_SLNO,ITEM_SLNO
	set @Mstatus=1
end

end


commit
end try
begin catch
rollback transaction
	set @ErrorMsg=error_message()
	set @MStatus=0
end catch

/****** Object:  StoredProcedure [dbo].[IMP_VALIDATION_GEN_IGM]    Script Date: 10/12/2018 15:47:33 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
ALTER procedure [dbo].[IMP_VALIDATION_GEN_IGM]   
  (        
      @Jobno varchar(20),@Flag varchar(200),@Branch_Type varchar(150),@xmlString VARCHAR(MAX),@ErrorMsg nvarchar(max) output    
   )    
 AS    
begin try    
 begin transaction  set @ErrorMsg=''   
 declare @Con_type varchar(20) ,@Ex_Bond varchar(20)
 declare @a varchar(5), @b varchar(5), @c varchar(5), @d varchar(5), @e varchar(5), @f varchar(5),@g varchar(5), @h varchar(5),@j varchar(5)  
  --------------------------------------------------------
if(@Flag='IMP_GENERAL_DETAILS')
begin
         if(@Branch_Type<>'')
		  begin
		         select 
                        case when len(IEC_NO)> 10 then 'F' else 'T' end  as IEC_NO
                       ,case when len(BRANCH_NO)> 3 then 'F' else 'T' end  as BRANCH_NO
                       ,case when TRANSPORT_MODE ='Air'  then REPLACE( RIGHT( PORT_ORIGIN ,4) ,'-','' )    
                             when TRANSPORT_MODE ='Sea' or  TRANSPORT_MODE ='Land' then REPLACE( RIGHT( PORT_ORIGIN ,6) ,'-','' )  end as PORT_ORIGIN
                             
                       ,COUNTRY_ORIGIN
                       ,COUNTRY_SHIPMENT
                        , case when TRANSPORT_MODE ='Air'  then
                                   REPLACE( RIGHT( PORT_SHIPMENT ,4) ,'-','' )    
                             when TRANSPORT_MODE ='Sea' or  TRANSPORT_MODE ='Land' then 
                                  REPLACE( RIGHT( PORT_SHIPMENT ,6) ,'-','' )  
                             end as PORT_SHIPMENT
                      -- ,case when isnull((select top 1 ADCODE_IEC_ADCODE  from ADCODE_MASTER where ADCODE_IEC_ADCODE=ADCODE) ,'')='' then 'F' else 'T' end ADCODE
                       --,case when len(ADCODE)> 10 then 'F' else 'T' end  as ADCODE
                       ,case when len(ADCODE) between 7 and 10 then 'T' else 'F' end as ADCODE
                       ,case when len(PAYMENT_METHOD_CODE)> 3 then 'F' else 'T' end  as PAYMENT_METHOD_CODE
                       /*
                       ,case when (case when TRANSPORT_MODE ='Air'  then
                                  case when  LEN( REPLACE( RIGHT( PORT_ORIGIN ,4) ,'-','' )) >3 then 0 else 1 end     
                             when TRANSPORT_MODE ='Sea' or  TRANSPORT_MODE ='Land' then 
                                  case when  LEN( REPLACE( RIGHT( PORT_ORIGIN ,6) ,'-','' )) >5 then 0 else 1 end 
                             end)=0 then'F' else 'T' end as PORT_ORIGIN
                             
                       ,case when (case when TRANSPORT_MODE ='Air'  then
                                  case when  LEN( REPLACE( RIGHT( PORT_SHIPMENT ,4) ,'-','' )) >3 then 0 else 1 end     
                             when TRANSPORT_MODE ='Sea' or  TRANSPORT_MODE ='Land' then 
                                  case when  LEN( REPLACE( RIGHT( PORT_SHIPMENT ,6) ,'-','' )) >5 then 0 else 1 end 
                             end)=0 then'F' else 'T' end as PORT_SHIPMENT    
                             */
                 from GENERAL_DETAILS where JOBNO=@Jobno and BRANCHCODE=@Branch_Type 
                 
                
		  end
		     else
		         begin
		               /*
		               JOBNO,IMPORTER_NAME,BE_TYPE ,BRANCH_NO --,'Class' as Class
                 ,TRANSPORT_MODE,IMP_EXP_TYPE,KACHHA_BE,HIGH_SEA_SALE,PORT_ORIGIN,'CHA_Code' as CHA_Code ,COUNTRY_ORIGIN,COUNTRY_SHIPMENT,PORT_SHIPMENT
                 ,GREEN_CHANNEL,SECTION48,FILING_STATUS,FIRSTCHECK,ADCODE,PAYMENT_METHOD_CODE
                 */
		            select
                       case when len(IEC_NO)> 10 then 'F' else 'T' end  as IEC_NO
                       ,case when len(BRANCH_NO)> 3 then 'F' else 'T' end  as BRANCH_NO
                       ,case when TRANSPORT_MODE ='Air'  then
                                   REPLACE( RIGHT( PORT_ORIGIN ,4) ,'-','' )    
                             when TRANSPORT_MODE ='Sea' or  TRANSPORT_MODE ='Land' then 
                                  REPLACE( RIGHT( PORT_ORIGIN ,6) ,'-','' )  
                             end as PORT_ORIGIN
                             
                       ,COUNTRY_ORIGIN
                       ,COUNTRY_SHIPMENT
                        , case when TRANSPORT_MODE ='Air'  then
                                   REPLACE( RIGHT( PORT_SHIPMENT ,4) ,'-','' )    
                             when TRANSPORT_MODE ='Sea' or  TRANSPORT_MODE ='Land' then 
                                  REPLACE( RIGHT( PORT_SHIPMENT ,6) ,'-','' )  
                             end as PORT_SHIPMENT
                      -- ,case when isnull((select top 1 ADCODE_IEC_ADCODE  from ADCODE_MASTER where ADCODE_IEC_ADCODE=ADCODE) ,'')='' then 'F' else 'T' end ADCODE      
                      -- ,case when len(ADCODE)> 10 then 'F' else 'T' end  as ADCODE
                      ,case when len(ADCODE) between 7 and 10 then 'T' else 'F' end as ADCODE
                       ,case when len(PAYMENT_METHOD_CODE)> 3 then 'F' else 'T' end  as PAYMENT_METHOD_CODE
                       /*
                       ,case when (case when TRANSPORT_MODE ='Air'  then
                                  case when  LEN( REPLACE( RIGHT( PORT_ORIGIN ,4) ,'-','' )) >3 then 0 else 1 end     
                             when TRANSPORT_MODE ='Sea' or  TRANSPORT_MODE ='Land' then 
                                  case when  LEN( REPLACE( RIGHT( PORT_ORIGIN ,6) ,'-','' )) >5 then 0 else 1 end 
                             end)=0 then'F' else 'T' end as PORT_ORIGIN
                             
                       ,case when (case when TRANSPORT_MODE ='Air'  then
                                  case when  LEN( REPLACE( RIGHT( PORT_SHIPMENT ,4) ,'-','' )) >3 then 0 else 1 end     
                             when TRANSPORT_MODE ='Sea' or  TRANSPORT_MODE ='Land' then 
                                  case when  LEN( REPLACE( RIGHT( PORT_SHIPMENT ,6) ,'-','' )) >5 then 0 else 1 end 
                             end)=0 then'F' else 'T' end as PORT_SHIPMENT    
                             */
                      
                       from GENERAL_DETAILS where JOBNO=@Jobno
		         end
end
else if(@Flag='IMP_IGM_DETAILS')
begin
     declare @F_Mode varchar(10) 

Declare @temp_Pkg table (PACKAGETYPE varchar(3))
Declare @temp_Unit_Code table (Unit_Code varchar(3))
declare @Pkg_values varchar(max),@Unit_Code varchar(max)
set @Pkg_values ='BDL,BGS,BLK,BLO,BLS,BOX,BRL,BUL,CAN,CAS,CHT,CLS,COL,CON,CRT,CSK,CTN,CYL,DRM,ENV,FLK,FUT,HBK,JBL,JTA,KEG,LFT,LOG,NGT,PAL,PCS,PKG,PLT,QDS,REL,RLS,SKD,SLB,TBL,TIN,TRK,UNT'
insert into @temp_Pkg  select item from dbo.fnSplit(@Pkg_values, ',') 
set @Unit_Code ='BAG,BAL,BDL,BGS,BKL,BLK,BOU,BOX,BRL,BTL,BUN,CAN,CAS,CBM,CCM,CFT,CLS,CMS,COL,CON,CRT,CSK,CTN,DOZ,DRM,FTS,GGR,GMS,GRS,GYD,JRS,KGS,KIT,KLR,KME,LBS,LOT,LTR,MGS,MLT,MOU,MTR,MTS,NOS,PAC,PCS,PKG,PLT,PRS,QTL,RLS,ROL,SAC,SET,SHT,SLB,SQF,SQM,SQY,TBS,TGM,THD,TON,TUB,UGS,UNT,VLS,YDS'
insert into @temp_Unit_Code  select item from dbo.fnSplit(@Unit_Code, ',') 


declare @temp_Igm table (Id int identity(1,1),IGM_SLNO int,IGM_NO varchar(2),IGM_DATE	varchar(2),IGM_FLIGHT_VESSELDATE	varchar(2),IGM_GATEWAY_IGM_NO	varchar(2)
,IGM_GATEWAY_IGM_DATE	varchar(2),IGM_GATEWAY_PORT_CODE	varchar(2),IGM_MAWB_MBL	varchar(2),IGM_MAWB_MBLDATE	varchar(2)
,IGM_NOOFPACKAGE	varchar(2),IGM_GROSSWEIGHT	varchar(2),IGM_PACKAGETYPE	varchar(2),IGM_TYPEOFWEIGHT	varchar(2),IGM_MARKSNOS	varchar(2))


declare @Temp_G_IGM table (Id int identity(1,1),IGM_SLNO int)
declare @cnt_IGM int , @i int 
set @i=1
declare @FILING_STATUS varchar(50)


if(@Branch_Type <>'')
begin
       insert into @Temp_G_IGM select IGM_SLNO from IGM_DETAILS  where JOBNO=@Jobno and IGM_BRANCH_CODE=@Branch_Type order by IGM_SLNO asc
	   select @cnt_IGM =COUNT(*) from @Temp_G_IGM
	   
	   if(@cnt_IGM >0)
	   begin
	   select @FILING_STATUS=FILING_STATUS from GENERAL_DETAILS where JOBNO=@Jobno and BRANCHCODE=@Branch_Type
	   if(@FILING_STATUS ='Advanced')
begin
        while (@i<=@cnt_IGM)
		begin
		      ;with summary_A1
		      as(
			  select
				   IGM_SLNO
				  ,case when IGM_TRANSPORTMODE ='Air' then 
							 case when  len (IGM_NO )>3  and len (IGM_NO )<8 then 'T' else 'F' end
							 when IGM_TRANSPORTMODE ='Sea' or IGM_TRANSPORTMODE ='land'  then 'T'
				   end as IGM_NO
		           
				   ,case when IGM_TRANSPORTMODE ='Air' then 
							 case when  len (IGM_DATE )>3  then 'T' else 'F' end
							 when IGM_TRANSPORTMODE ='Sea' or IGM_TRANSPORTMODE ='land'  then 'T'
				   end as IGM_DATE
				  ,'T' as IGM_FLIGHT_VESSELDATE
		          
				  ,case when IGM_TRANSPORTMODE ='Air' or IGM_TRANSPORTMODE ='Sea'  then 'T' when IGM_TRANSPORTMODE ='Land' then 
				   case when LEN (IGM_GATEWAY_IGM_NO) between 2 and 7 then 'T' else 'F' end end IGM_GATEWAY_IGM_NO
		           
				  ,case when IGM_TRANSPORTMODE ='Air' or IGM_TRANSPORTMODE ='Sea'  then 'T' when IGM_TRANSPORTMODE ='Land' then 
				   case when LEN (IGM_GATEWAY_IGM_DATE) >2then 'T' else 'F' end end IGM_GATEWAY_IGM_DATE
		           
				  ,case when IGM_TRANSPORTMODE ='Air' or IGM_TRANSPORTMODE ='Sea'  then 'T' when IGM_TRANSPORTMODE ='Land' then 
				   case when LEN (IGM_GATEWAY_PORT_CODE) between 2 and 6 then 'T' else 'F' end end IGM_GATEWAY_PORT_CODE
		          
				  ,case when len(IGM_MAWB_MBL) between 2 and 20 then 'T' else 'F' end IGM_MAWB_MBL
				  ,case when len(IGM_MAWB_MBLDATE) >3 then 'T' else 'F' end IGM_MAWB_MBLDATE
				  ,case when len(IGM_NOOFPACKAGE) between 1 and 8 then 'T' else 'F' end as IGM_NOOFPACKAGE
				  ,case when ISNUMERIC(IGM_GROSSWEIGHT)=1 then Case when len(IGM_GROSSWEIGHT)>13 then 'F' else 'T' end else 'F' end IGM_GROSSWEIGHT
		          
				  ,case when len(IGM_PACKAGETYPE) between 3 and 3 then 
					 case when isnull( (select IGM_PACKAGETYPE from @temp_Pkg where PACKAGETYPE =IGM_PACKAGETYPE) ,'F')='F' then 'F' else 'T' end else 'F' end as IGM_PACKAGETYPE
					,case when len(IGM_TYPEOFWEIGHT) between 3 and 3 then 
					case when isnull( (select Unit_Code from @temp_Unit_Code where Unit_Code =IGM_TYPEOFWEIGHT) ,'F')='F' then 'F' else 'T' end else 'F' end as IGM_TYPEOFWEIGHT
				  ,case when len(IGM_MARKSNOS) between 3 and 40 then 'T' else 'F' end as IGM_MARKSNOS
			 
			  from IGM_DETAILS where JOBNO=@Jobno and IGM_BRANCH_CODE =@Branch_Type and IGM_SLNO= (select IGM_SLNO from  @Temp_G_IGM  where Id =@i)
		     )
		    insert into @temp_Igm select * from summary_A1 
		    where IGM_NO='F' or IGM_DATE ='F' or IGM_FLIGHT_VESSELDATE ='F' or IGM_GATEWAY_IGM_NO ='F' or IGM_GATEWAY_IGM_DATE ='F' or IGM_GATEWAY_PORT_CODE
		    ='F' or  IGM_MAWB_MBL  ='F' or IGM_MAWB_MBLDATE ='F' or IGM_NOOFPACKAGE ='F' or IGM_GROSSWEIGHT  ='F' or IGM_PACKAGETYPE  ='F' or IGM_TYPEOFWEIGHT
		     ='F' or IGM_MARKSNOS  ='F' 
		      set @i=@i+1;
		end	  
		
		select IGM_SLNO as [IGM. Sl.no] ,IGM_NO as [IGM No.],IGM_DATE as [IGM Date],IGM_FLIGHT_VESSELDATE [Inward Date],IGM_GATEWAY_IGM_NO as [Gate Way IGM No.]
		      ,IGM_GATEWAY_IGM_DATE as [GateWay IGM Date],IGM_GATEWAY_PORT_CODE as [GateWay Port Code],IGM_MAWB_MBL as [IGM MAWB/MBL],IGM_MAWB_MBLDATE as [IGM MAWB MBLDATE]
		      ,IGM_NOOFPACKAGE as [No. of Pkg],IGM_GROSSWEIGHT as [Gross wgt],IGM_PACKAGETYPE as [Pkg Type],IGM_TYPEOFWEIGHT as [Weight Type] ,IGM_MARKSNOS  as [Marks Nos] From @temp_Igm order by IGM_SLNO asc
end
else if(@FILING_STATUS ='Normal')
begin
		select @F_Mode =case when TRANSPORT_MODE ='Sea' then case when FILING_STATUS ='Normal'  then 'T' else 'F' end else 'F' end
		from GENERAL_DETAILS where JOBNO =@Jobno and BRANCHCODE=@Branch_Type 
       
        while (@i<=@cnt_IGM)
		begin
		      ;with summary_N1
		      as(
             select
				   IGM_SLNO
				  ,case when  len (IGM_NO )>3 and len (IGM_NO )<8 then 'T' else 'F' end IGM_NO
				  ,case when  len (IGM_DATE )>3  then 'T' else 'F' end IGM_DATE
				  --,case when  len (IGM_FLIGHT_VESSELDATE )>3  then 'T' else 'F' end IGM_FLIGHT_VESSELDATE
				  ,case when @F_Mode ='T' then case when CONVERT(varchar(20), IGM_FLIGHT_VESSELDATE ,103)='01/01/1900' then 'F' else 'T' end 
				    else 'T' end IGM_FLIGHT_VESSELDATE
		          
				  ,case when IGM_TRANSPORTMODE ='Air' or IGM_TRANSPORTMODE ='Sea'  then 'T' when IGM_TRANSPORTMODE ='Land' then 
				   case when LEN (IGM_GATEWAY_IGM_NO) between 2 and 7 then 'T' else 'F' end end IGM_GATEWAY_IGM_NO
		           
				  ,case when IGM_TRANSPORTMODE ='Air' or IGM_TRANSPORTMODE ='Sea'  then 'T' when IGM_TRANSPORTMODE ='Land' then 
				   case when LEN (IGM_GATEWAY_IGM_DATE) >2 then 'T' else 'F' end end IGM_GATEWAY_IGM_DATE
		           
				  ,case when IGM_TRANSPORTMODE ='Air' or IGM_TRANSPORTMODE ='Sea'  then 'T' when IGM_TRANSPORTMODE ='Land' then 
				   case when LEN (IGM_GATEWAY_PORT_CODE) between 2 and 6 then 'T' else 'F' end end IGM_GATEWAY_PORT_CODE
		           
				   ,case when len(IGM_MAWB_MBL) between 2 and 20 then 'T' else 'F' end IGM_MAWB_MBL
				  ,case when len(IGM_MAWB_MBLDATE) >3 then 'T' else 'F' end IGM_MAWB_MBLDATE
				  ,case when len(IGM_NOOFPACKAGE) between 1 and 8 then 'T' else 'F' end as IGM_NOOFPACKAGE
				  ,case when ISNUMERIC(IGM_GROSSWEIGHT)=1 then Case when len(IGM_GROSSWEIGHT)>13 then 'F' else 'T' end else 'F' end IGM_GROSSWEIGHT
		          
				  ,case when len(IGM_PACKAGETYPE) between 3 and 3 then 
					 case when isnull( (select IGM_PACKAGETYPE from @temp_Pkg where PACKAGETYPE =IGM_PACKAGETYPE) ,'F')='F' then 'F' else 'T' end else 'F' end as IGM_PACKAGETYPE
					,case when len(IGM_TYPEOFWEIGHT) between 3 and 3 then 
					case when isnull( (select Unit_Code from @temp_Unit_Code where Unit_Code =IGM_TYPEOFWEIGHT) ,'F')='F' then 'F' else 'T' end else 'F' end as IGM_TYPEOFWEIGHT
				  ,case when len(IGM_MARKSNOS) between 3 and 40 then 'T' else 'F' end as IGM_MARKSNOS
		      
			  from IGM_DETAILS where JOBNO=@Jobno and IGM_BRANCH_CODE =@Branch_Type and IGM_SLNO= (select IGM_SLNO from  @Temp_G_IGM  where Id =@i)
			      )
		    insert into @temp_Igm select * from summary_N1 
