					insert @Temp_All_Entry  select 'Container Details' ,case when (select COUNT(jobno)  from CONTAINER_DETAILS 
					where JOBNO =@Jobno   and BRANCH_CODE =@Branch_Type)>0 then 'T' else 'F' end      
				end
		end 
 end



