and a.INVOICE_SLNO=b.INVOICE_SLNO and a.ITEM_SLNO=b.ITEM_SLNO  where a.JOBNO=@Jobno and a.BRANCH_CODE=@Branch_Type 
and a.SCHEME_CODE not in('08-REP','09-DIL','20-JBG','21-EOU' ,'00 - DUTIABLE')  )
            
select INVOICE_SLNO as [Inv. Slno] ,ITEM_SLNO as [Item Sl.no] ,SCHEME_CODE as [Item Scheme Code] ,License from surmmay_lic where License='F' order by INVOICE_SLNO ,ITEM_SLNO asc

end 
   else 
       begin
			select @Mode = TRANSPORT_MODE ,@Con_type=CONTAINER_TYPE ,@Ex_Bond=BE_TYPE from GENERAL_DETAILS where JOBNO=@Jobno 
			
			if(@Ex_Bond ='Ex-Bond')
			begin
					select @a =case when len(EXBOND_INBOND_BE_NO) between 1 and 7 then 'T'else 'F' end  
					,@b =case when len(EXBOND_INBOND_BE_DATE) >0 then 'T'else 'F' end   
					,@c =case when len(EXBOND_BOND_NO) >0 then 'T'else 'F' end   
					,@d =case when len(EXBOND_BOND_DATE) >0 then 'T'else 'F' end   
					,@e =case when len(EXBOND_WAREHOUSE_CUSTOMS) between 1 and 6 then 'T'else 'F' end  
					,@f =case when len(EXBOND_NOOFPACKAGE) >0 then 'T'else 'F' end  
					,@g =case when len(EXBOND_NOOFPACKAGE_UNITCODE) between 1 and 3 then 'T'else 'F' end  
					,@h=case when len(EXBOND_GROSS_WEIGHT) >0 then 'T'else 'F' end  
					,@j=case when len(EXBOND_GROSS_WEIGHT_UNITCODE) between 1 and 3 then 'T'else 'F' end  
				   From GENERAL_DETAILS where JOBNO =@Jobno   
			      
				   if(isnull(@a,'F')='T' and isnull(@b,'F')='T' and isnull(@c,'F')='T' and isnull(@d,'F')='T' and isnull(@e,'F')='T' and isnull(@f,'F')='T' and isnull(@g,'F')='T' and isnull(@h,'F')='T' and isnull(@j,'F')='T' )
				   begin
						 print ''
				   end
				   else
				   begin
						 insert @Temp_All_Entry  select 'Ex-Bond Details','F'
				   end
			end
			   else
			   begin
					insert @Temp_All_Entry  
					select 'IGM Details',case when (select COUNT(JOBNO) from IGM_DETAILS where JOBNO=@Jobno )>0 then 'T' else 'F' end


					if(@Mode ='Sea' or @Mode ='Land' )
					begin 
							if(@Con_type<>'Bulk') 
							begin 
								insert @Temp_All_Entry  select 'Container Details' ,case when (select COUNT(jobno)  from CONTAINER_DETAILS 
								where JOBNO =@Jobno )>0 then 'T' else 'F' end      
							end
					end 
			 end
			        
			        
			        
			        
			        
			insert @Temp_All_Entry select 'Invoice Details' 
			,case when (select COUNT(jobno) from INVOICE_DETAILS where JOBNO =@Jobno)>0 then 'T' else 'F' end
			insert @Temp_All_Entry select 'Item Details' 
			,case when ( select COUNT(jobno) from ITEM_PRODUCT_DETAILS where JOBNO =@Jobno )>0 then 'T' else 'F' end
			
			insert @Temp_All_Entry 
			select 'Sup. Doc. Details' ,case when ( select COUNT(jobno) from BE_ITEM_SW_SUP_DOC where JOBNO =@Jobno )>0 then 'T' else 'F' end
			
			select * from @Temp_All_Entry where Flag ='F'

			;with Surmmay_lic as(   
					   select a.INVOICE_SLNO  ,a.ITEM_SLNO 
					   ,a.SCHEME_CODE
					   ,case when isnull (b.SCHEME_CODE ,'')='' then 'F' else 'T' end as License
						from ITEM_PRODUCT_DETAILS a left outer join LICENSE_DETAILS b
						on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO and a.ITEM_SLNO=b.ITEM_SLNO
						where a.JOBNO=@Jobno and a.SCHEME_CODE not in('08-REP','09-DIL','20-JBG','21-EOU' ,'00 - DUTIABLE')  )
						select INVOICE_SLNO as [Inv. Slno] 
							  ,ITEM_SLNO as [Item Sl.no] 
							  ,SCHEME_CODE as [Item Scheme Code] 
							  ,License 
						 from surmmay_lic where License='F' order by INVOICE_SLNO ,ITEM_SLNO asc
					 
	  end
end

else if(@Flag='Check_Exbond_Job')
begin
         if(@Branch_Type<>'')
         begin
              select BE_TYPE from GENERAL_DETAILS where JOBNO=@Jobno and BRANCHCODE=@Branch_Type and BE_TYPE='Ex-Bond'
         end 
         else
         begin
              select BE_TYPE from GENERAL_DETAILS where JOBNO=@Jobno and BE_TYPE='Ex-Bond'
         end
end
else if(@Flag='Validate_Exbond_Job')
begin
        if(@Branch_Type <>'')
        begin

	          select @a =case when len(EXBOND_INBOND_BE_NO) between 1 and 7 then 'T'else 'F' end  
			  ,@b =case when len(EXBOND_INBOND_BE_DATE) >0 then 'T'else 'F' end   
			  ,@c =case when len(EXBOND_BOND_NO) >0 then 'T'else 'F' end   
			  ,@d =case when len(EXBOND_BOND_DATE) >0 then 'T'else 'F' end   
			  ,@e =case when len(EXBOND_WAREHOUSE_CUSTOMS) between 1 and 6 then 'T'else 'F' end  
			  ,@f =case when len(EXBOND_NOOFPACKAGE) >0 then 'T'else 'F' end  
			  ,@g =case when len(EXBOND_NOOFPACKAGE_UNITCODE) between 1 and 3 then 'T'else 'F' end  
              ,@h=case when len(EXBOND_GROSS_WEIGHT) >0 then 'T'else 'F' end  
			  ,@j=case when len(EXBOND_GROSS_WEIGHT_UNITCODE) between 1 and 3 then 'T'else 'F' end  
				From GENERAL_DETAILS where JOBNO =@Jobno   and BRANCHCODE =@Branch_Type
			      
				   if(isnull(@a,'F')='T' and isnull(@b,'F')='T' and isnull(@c,'F')='T' and isnull(@d,'F')='T' and isnull(@e,'F')='T' and isnull(@f,'F')='T' and isnull(@g,'F')='T' and isnull(@h,'F')='T' and isnull(@j,'F')='T' )
				   begin
						  select '' Empty where 1=0
				   end
				   else
				   begin
						 select case when len(EXBOND_INBOND_BE_NO) between 1 and 7 then 'T'else 'F' end  as InBond_BENO
						       ,case when len(EXBOND_INBOND_BE_DATE) >0 then 'T'else 'F' end  as InBond_BEDate  
						       ,case when len(EXBOND_BOND_NO) >0 then 'T'else 'F' end  as Bond_No  
						       ,case when len(EXBOND_BOND_DATE) >0 then 'T'else 'F' end  Bond_Date 
						       ,case when len(EXBOND_WAREHOUSE_CUSTOMS) between 1 and 6 then 'T'else 'F' end  WH_Customs
						       ,case when len(EXBOND_NOOFPACKAGE) >0 then 'T'else 'F' end  as No_of_Pkg 
						       ,case when len(EXBOND_NOOFPACKAGE_UNITCODE) between 1 and 3 then 'T'else 'F' end  as Uint_Code
						       ,case when len(EXBOND_GROSS_WEIGHT) >0 then 'T'else 'F' end  as Gross_Wgt
						       ,case when len(EXBOND_GROSS_WEIGHT_UNITCODE) between 1 and 3 then 'T'else 'F' end  as Wgt_UnitCOde
						   From GENERAL_DETAILS where JOBNO =@Jobno   and BRANCHCODE =@Branch_Type
				   end
				   
		end
			else
				begin
			  select @a =case when len(EXBOND_INBOND_BE_NO) between 1 and 7 then 'T'else 'F' end  
			  ,@b =case when len(EXBOND_INBOND_BE_DATE) >0 then 'T'else 'F' end   
			  ,@c =case when len(EXBOND_BOND_NO) >0 then 'T'else 'F' end   
			  ,@d =case when len(EXBOND_BOND_DATE) >0 then 'T'else 'F' end   
			  ,@e =case when len(EXBOND_WAREHOUSE_CUSTOMS) between 1 and 6 then 'T'else 'F' end  
			  ,@f =case when len(EXBOND_NOOFPACKAGE) >0 then 'T'else 'F' end  
			  ,@g =case when len(EXBOND_NOOFPACKAGE_UNITCODE) between 1 and 3 then 'T'else 'F' end  
              ,@h=case when len(EXBOND_GROSS_WEIGHT) >0 then 'T'else 'F' end  
			  ,@j=case when len(EXBOND_GROSS_WEIGHT_UNITCODE) between 1 and 3 then 'T'else 'F' end  
				From GENERAL_DETAILS where JOBNO =@Jobno   
			      
				   if(isnull(@a,'F')='T' and isnull(@b,'F')='T' and isnull(@c,'F')='T' and isnull(@d,'F')='T' and isnull(@e,'F')='T' and isnull(@f,'F')='T' and isnull(@g,'F')='T' and isnull(@h,'F')='T' and isnull(@j,'F')='T' )
				   begin
						  select '' Empty where 1=0
				   end
				   else
				   begin
						 select case when len(EXBOND_INBOND_BE_NO) between 1 and 7 then 'T'else 'F' end  as InBond_BENO
						       ,case when len(EXBOND_INBOND_BE_DATE) >0 then 'T'else 'F' end  as InBond_BEDate  
						       ,case when len(EXBOND_BOND_NO) >0 then 'T'else 'F' end  as Bond_No  
						       ,case when len(EXBOND_BOND_DATE) >0 then 'T'else 'F' end  Bond_Date 
						       ,case when len(EXBOND_WAREHOUSE_CUSTOMS) between 1 and 6 then 'T'else 'F' end  WH_Customs
						       ,case when len(EXBOND_NOOFPACKAGE) >0 then 'T'else 'F' end  as No_of_Pkg 
						       ,case when len(EXBOND_NOOFPACKAGE_UNITCODE) between 1 and 3 then 'T'else 'F' end  as Uint_Code
						       ,case when len(EXBOND_GROSS_WEIGHT) >0 then 'T'else 'F' end  as Gross_Wgt
						       ,case when len(EXBOND_GROSS_WEIGHT_UNITCODE) between 1 and 3 then 'T'else 'F' end  as Wgt_UnitCOde
						   From GENERAL_DETAILS where JOBNO =@Jobno  
				   end
				   
			end
		
		    end		   
	   

 --------------------------------------------------------
  commit    
end try    
begin catch    
rollback transaction    
 set @ErrorMsg=error_message()    
 --set @MStatus=0    
end catch


   
   
   
   /****** Object:  StoredProcedure [dbo].[IMP_VALIDATION_ITEM]    Script Date: 10/12/2018 15:50:38 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

ALTER procedure [dbo].[IMP_VALIDATION_ITEM]
  (        
      @Jobno varchar(20),@Flag varchar(200),@Branch_Type varchar(150),@xmlString VARCHAR(MAX), @ErrorMsg nvarchar(max) output    
   )    
 AS    
begin try    
 begin transaction    
  set @ErrorMsg=''    
  --------------------------------------------------------
if(@Flag='IMP_ITEM_DETAILS_ADMIN')
begin 

	if(@Branch_Type<>'') 
	begin 
	      --insert into @temp_Item
		  SELECT INVOICE_SLNO,ITEM_SLNO 
			    ,case when isnumeric(ITEM_QTY)=1 then  case when  charindex('.',ITEM_QTY)=0 then 'T' else 
                 case when  len(PARSENAME(ITEM_QTY,1))>6 then 'F' else 'T' end  end  else 'F' end  ITEM_QTY --,ITEM_QTY as [Item Qty] 
                ,ITEM_QTY_CODE,PRODUCT_RITC
			    ,case when  (len(ITEM_DESCRIPTION)>120 or len(ITEM_DESCRIPTION)=0)  then 'F' else 'T' end ITEM_DESCRIPTION
			    
			    ,case when len (BRAND) between 1 and 20 then 'T' else 'F' end  BRAND ,case when len (MODEL) between 1 and 20 then 'T' else 'F' end  MODEL
		        ,END_USE_OF_ITEM ,COUNTRY_OF_ORIGIN ,PRODUCT_CTH,PRODUCT_CETH  
			    ,case when isnumeric(ITEM_UNIT_PRICE)=1 then  case when  charindex('.',ITEM_UNIT_PRICE)=0 then 'T' else 
                 case when  len(PARSENAME(ITEM_UNIT_PRICE,1))>6 then 'F' else 'T' end  end  else 'F' end ITEM_UNIT_PRICE
		        ,case when  isnull(RSP_APPLICABLE,'')='Y' or isnull(RSP_APPLICABLE,'')='N' or isnull(RSP_APPLICABLE,'')='Q' or isnull(RSP_APPLICABLE,'')='T' 
                  or isnull(RSP_APPLICABLE,'')='D'  then 'T' else 'F' end RSP_APPLICABLE
                ,case when isnull(RSP_APPLICABLE,'')='Y' then (case when isnull(PRODUCT_MRP_AMOUNT,'')<>'' then 'T' else 'F' end )else  'T' end  MRP_AMOUNT
                ,case when isnull(SCHEME_CODE,'')<>'' then 'T' else 'F' end Scheme_Code
				,case when isnull(SCHEME_CODE,'')<>'00 - DUTIABLE' then (case when isnull(SCHEME_NOTN,'')<>'' Then 'T' else 'F' end)
                  else (case when isnull(SCHEME_NOTN,'')='' Then 'T' else 'F' end) end Scheme_Notn
			   ,case when isnull(SCHEME_CODE,'')<>'00 - DUTIABLE' then (case when isnull(SCHEME_NOTN_SLNO,'')<>'' Then 'T' else 'F' end)
				 when isnull(SCHEME_CODE,'')='00 - DUTIABLE' then 'T' else (case when isnull(SCHEME_NOTN_SLNO,'')='' Then 'T' else 'F' end) end Scheme_Notn_Slno
				
			FROM  ITEM_PRODUCT_DETAILS where JOBNO =@Jobno and BRANCH_CODE=@Branch_Type order by INVOICE_SLNO ,ITEM_SLNO asc 
			
		  /* update @temp_Item set ITEM_DESCRIPTION ='F'
	       where INVOICE_SLNO in(select INVOICE_SLNO from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno and BRANCH_CODE=@Branch_Type and ITEM_DESCRIPTION LIKE '%' + CHAR(9) + '%')
	       and ITEM_SLNO in(select ITEM_SLNO from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno and BRANCH_CODE=@Branch_Type and ITEM_DESCRIPTION LIKE '%' + CHAR(9) + '%')
	       select * from @temp_Item order by INVOICE_SLNO ,ITEM_SLNO asc */
	end 
		else 
			begin 
				  SELECT INVOICE_SLNO,ITEM_SLNO 
						,case when isnumeric(ITEM_QTY)=1 then  case when  charindex('.',ITEM_QTY)=0 then 'T' else 
						 case when  len(PARSENAME(ITEM_QTY,1))>6 then 'F' else 'T' end  end  else 'F' end  ITEM_QTY --,ITEM_QTY as [Item Qty] 
						,ITEM_QTY_CODE,PRODUCT_RITC
						,case when  (len(ITEM_DESCRIPTION)>120 or len(ITEM_DESCRIPTION)=0)  then 'F' else 'T' end ITEM_DESCRIPTION
						,case when len (BRAND) between 1 and 20 then 'T' else 'F' end  BRAND  
						,case when len (MODEL) between 1 and 20 then 'T' else 'F' end  MODEL
						,END_USE_OF_ITEM,COUNTRY_OF_ORIGIN ,PRODUCT_CTH,PRODUCT_CETH  
						,case when isnumeric(ITEM_UNIT_PRICE)=1 then  case when  charindex('.',ITEM_UNIT_PRICE)=0 then 'T' else 
						 case when  len(PARSENAME(ITEM_UNIT_PRICE,1))>6 then 'F' else 'T' end  end  else 'F' end ITEM_UNIT_PRICE
						,case when  isnull(RSP_APPLICABLE,'')='Y' or isnull(RSP_APPLICABLE,'')='N' or isnull(RSP_APPLICABLE,'')='Q' or isnull(RSP_APPLICABLE,'')='T' 
						  or isnull(RSP_APPLICABLE,'')='D'  then 'T' else 'F' end RSP_APPLICABLE
						,case when isnull(RSP_APPLICABLE,'')='Y' then (case when isnull(PRODUCT_MRP_AMOUNT,'')<>'' then 'T' else 'F' end )else  'T' end  MRP_AMOUNT
						,case when isnull(SCHEME_CODE,'')<>'' then 'T' else 'F' end Scheme_Code
						,case when isnull(SCHEME_CODE,'')<>'00 - DUTIABLE' then (case when isnull(SCHEME_NOTN,'')<>'' Then 'T' else 'F' end)
						 else (case when isnull(SCHEME_NOTN,'')='' Then 'T' else 'F' end) end Scheme_Notn
						,case when isnull(SCHEME_CODE,'')<>'00 - DUTIABLE' then (case when isnull(SCHEME_NOTN_SLNO,'')<>'' Then 'T' else 'F' end)
				        when isnull(SCHEME_CODE,'')='00 - DUTIABLE' then 'T' else (case when isnull(SCHEME_NOTN_SLNO,'')='' Then 'T' else 'F' end) end Scheme_Notn_Slno
					 FROM  ITEM_PRODUCT_DETAILS where JOBNO =@Jobno order by INVOICE_SLNO ,ITEM_SLNO asc
				   
			end  
end

else if(@Flag='IMP_ITEM_Lic')
begin if(@Branch_Type <>'' )  begin
        select INVOICE_SLNO,ITEM_SLNO,LICENSE_SLNO
,PORT_OF_LICENSE
,case when (len(rtrim(ltrim(REGISTRATION_NO)))>10 or len(rtrim(ltrim(REGISTRATION_NO)))=0) then 'F' else 'T' end REGISTRATION_NO
,case when CONVERT(varchar(20), REGISTRATION_DATE ,103)='01/01/1900' then 'F' else 'T' end REGISTRATION_DATE
 from LICENSE_DETAILS where JOBNO=@Jobno and BRANCH_CODE=@Branch_Type
  order by INVOICE_SLNO,ITEM_SLNO,LICENSE_SLNO asc
   end
       else
       begin
             select INVOICE_SLNO,ITEM_SLNO,LICENSE_SLNO
			,PORT_OF_LICENSE
			,case when (len(rtrim(ltrim(REGISTRATION_NO)))>10 or len(rtrim(ltrim(REGISTRATION_NO)))=0) then 'F' else 'T' end REGISTRATION_NO
			,case when CONVERT(varchar(20), REGISTRATION_DATE ,103)='01/01/1900' then 'F' else 'T' end REGISTRATION_DATE
			 from LICENSE_DETAILS where JOBNO=@Jobno 
			order by INVOICE_SLNO,ITEM_SLNO,LICENSE_SLNO asc
       end
end  
else if(@Flag='Item_Special_Character')
begin if(@Branch_Type <>'' ) begin
select INVOICE_SLNO as [Inv. Slno], ITEM_SLNO as [Item Slno] ,'F' as [Description] from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno and BRANCH_CODE=@Branch_Type and
(ITEM_DESCRIPTION not like '%''''%' and ITEM_DESCRIPTION like '%''%' or ITEM_DESCRIPTION like ('%Š%')or ITEM_DESCRIPTION like ('%Ž%')or ITEM_DESCRIPTION like ('%š%')
or ITEM_DESCRIPTION like ('%œ%')or ITEM_DESCRIPTION like ('%ž%')or ITEM_DESCRIPTION like ('%Ÿ%')or ITEM_DESCRIPTION like ('%¢%')or ITEM_DESCRIPTION like ('%£%')
or ITEM_DESCRIPTION like ('%¥%')or ITEM_DESCRIPTION like ('%©%')or ITEM_DESCRIPTION like ('%®%')or ITEM_DESCRIPTION like ('%À%')or ITEM_DESCRIPTION like ('%Á%')
or ITEM_DESCRIPTION like ('%Â%')or ITEM_DESCRIPTION like ('%Ã%')or ITEM_DESCRIPTION like ('%Ä%')or ITEM_DESCRIPTION like ('%Å%')or ITEM_DESCRIPTION like ('%È%')
or ITEM_DESCRIPTION like ('%É%')or ITEM_DESCRIPTION like ('%Ê%')or ITEM_DESCRIPTION like ('%Ë%')or ITEM_DESCRIPTION like ('%Ì%')or ITEM_DESCRIPTION like ('%Í%')
or ITEM_DESCRIPTION like ('%Î%')or ITEM_DESCRIPTION like ('%Ï%')or ITEM_DESCRIPTION like ('%Ñ%')or ITEM_DESCRIPTION like ('%Ò%')or ITEM_DESCRIPTION like ('%Ó%')
or ITEM_DESCRIPTION like ('%Ô%')or ITEM_DESCRIPTION like ('%Õ%')or ITEM_DESCRIPTION like ('%Ö%')or ITEM_DESCRIPTION like ('%Ù%')or ITEM_DESCRIPTION like ('%Ú%')
or ITEM_DESCRIPTION like ('%Û%')or ITEM_DESCRIPTION like ('%Ü%')or ITEM_DESCRIPTION like ('%ß%')or ITEM_DESCRIPTION like ('%à%')or ITEM_DESCRIPTION like ('%á%')
or ITEM_DESCRIPTION like ('%â%')or ITEM_DESCRIPTION like ('%ã%')or ITEM_DESCRIPTION like ('%ä%')or ITEM_DESCRIPTION like ('%å%')or ITEM_DESCRIPTION like ('%è%')
or ITEM_DESCRIPTION like ('%é%')or ITEM_DESCRIPTION like ('%ê%')or ITEM_DESCRIPTION like ('%ë%')or ITEM_DESCRIPTION like ('%ì%')or ITEM_DESCRIPTION like ('%í%')
or ITEM_DESCRIPTION like ('%î%')or ITEM_DESCRIPTION like ('%ï%')or ITEM_DESCRIPTION like ('%ð%')or ITEM_DESCRIPTION like ('%ñ%')or ITEM_DESCRIPTION like ('%ò%')
or ITEM_DESCRIPTION like ('%ó%')or ITEM_DESCRIPTION like ('%ô%')or ITEM_DESCRIPTION like ('%õ%')or ITEM_DESCRIPTION like ('%ö%')or ITEM_DESCRIPTION like ('%ø%')
or ITEM_DESCRIPTION like ('%ù%')or ITEM_DESCRIPTION like ('%ú%')or ITEM_DESCRIPTION like ('%û%')or ITEM_DESCRIPTION like ('%ü%')or ITEM_DESCRIPTION like ('%ý%')
or ITEM_DESCRIPTION like ('%”%')or ITEM_DESCRIPTION like ('%ÿ%')or ITEM_DESCRIPTION LIKE '%' + CHAR(9) + '%' )order by INVOICE_SLNO ,ITEM_SLNO asc end else begin
select INVOICE_SLNO as [Inv. Slno], ITEM_SLNO as [Item Slno] ,'F'  as [Description] from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno and
  (ITEM_DESCRIPTION not like '%''''%' and ITEM_DESCRIPTION like '%''%' or ITEM_DESCRIPTION like ('%Š%')or ITEM_DESCRIPTION like ('%Ž%')or ITEM_DESCRIPTION like ('%š%')
or ITEM_DESCRIPTION like ('%œ%')or ITEM_DESCRIPTION like ('%ž%')or ITEM_DESCRIPTION like ('%Ÿ%')or ITEM_DESCRIPTION like ('%¢%')or ITEM_DESCRIPTION like ('%£%')
or ITEM_DESCRIPTION like ('%¥%')or ITEM_DESCRIPTION like ('%©%')or ITEM_DESCRIPTION like ('%®%')or ITEM_DESCRIPTION like ('%À%')or ITEM_DESCRIPTION like ('%Á%')
or ITEM_DESCRIPTION like ('%Â%')or ITEM_DESCRIPTION like ('%Ã%')or ITEM_DESCRIPTION like ('%Ä%')or ITEM_DESCRIPTION like ('%Å%')or ITEM_DESCRIPTION like ('%È%')
or ITEM_DESCRIPTION like ('%É%')or ITEM_DESCRIPTION like ('%Ê%')or ITEM_DESCRIPTION like ('%Ë%')or ITEM_DESCRIPTION like ('%Ì%')or ITEM_DESCRIPTION like ('%Í%')
or ITEM_DESCRIPTION like ('%Î%')or ITEM_DESCRIPTION like ('%Ï%')or ITEM_DESCRIPTION like ('%Ñ%')or ITEM_DESCRIPTION like ('%Ò%')or ITEM_DESCRIPTION like ('%Ó%')
or ITEM_DESCRIPTION like ('%Ô%')or ITEM_DESCRIPTION like ('%Õ%')or ITEM_DESCRIPTION like ('%Ö%')or ITEM_DESCRIPTION like ('%Ù%')or ITEM_DESCRIPTION like ('%Ú%')
or ITEM_DESCRIPTION like ('%Û%')or ITEM_DESCRIPTION like ('%Ü%')or ITEM_DESCRIPTION like ('%ß%')or ITEM_DESCRIPTION like ('%à%')or ITEM_DESCRIPTION like ('%á%')
or ITEM_DESCRIPTION like ('%â%')or ITEM_DESCRIPTION like ('%ã%')or ITEM_DESCRIPTION like ('%ä%')or ITEM_DESCRIPTION like ('%å%')or ITEM_DESCRIPTION like ('%è%')
or ITEM_DESCRIPTION like ('%é%')or ITEM_DESCRIPTION like ('%ê%')or ITEM_DESCRIPTION like ('%ë%')or ITEM_DESCRIPTION like ('%ì%')or ITEM_DESCRIPTION like ('%í%')
or ITEM_DESCRIPTION like ('%î%')or ITEM_DESCRIPTION like ('%ï%')or ITEM_DESCRIPTION like ('%ð%')or ITEM_DESCRIPTION like ('%ñ%')or ITEM_DESCRIPTION like ('%ò%')
or ITEM_DESCRIPTION like ('%ó%')or ITEM_DESCRIPTION like ('%ô%')or ITEM_DESCRIPTION like ('%õ%')or ITEM_DESCRIPTION like ('%ö%')or ITEM_DESCRIPTION like ('%ø%')
or ITEM_DESCRIPTION like ('%ù%')or ITEM_DESCRIPTION like ('%ú%')or ITEM_DESCRIPTION like ('%û%')or ITEM_DESCRIPTION like ('%ü%')or ITEM_DESCRIPTION like ('%ý%')
or ITEM_DESCRIPTION like ('%”%')or ITEM_DESCRIPTION like ('%ÿ%')or ITEM_DESCRIPTION LIKE '%' + CHAR(9) + '%') order by INVOICE_SLNO ,ITEM_SLNO asc
	  end
end
else if(@Flag='SW_Control_Table')
begin 
        Declare @Temp_Control table (Id int identity(1,1), INVOICE_SLNO int,ITEM_SLNO int,CTH_NO varchar(20),AGENCY_CODE varchar(10) )
        Declare @aaa varchar(20),@bbb int ,@RR int
        
        DECLARE @xmlHandle_Item_SW_Control INT
		EXEC sp_xml_preparedocument @xmlHandle_Item_SW_Control output, @xmlString 
		insert into @Temp_Control	 SELECT  INVOICE_SLNO ,ITEM_SLNO,CTH_NO ,AGENCY_CODE FROM OPENXML 
		(@xmlHandle_Item_SW_Control, '/NewDataSet/SampleDataTable',1)WITH (
		[INVOICE_SLNO] nvarchar(10) '@INVOICE_SLNO' ,[ITEM_SLNO] VARCHAR(10) '@ITEM_SLNO' ,[CTH_NO] VARCHAR(10) '@CTH_NO' ,[AGENCY_CODE] VARCHAR(10) '@AGENCY_CODE' )
        select @aaa=(AGENCY_CODE)From @Temp_control where AGENCY_CODE='PQIS'
        if(@aaa<>'')
        begin
               if(@Branch_Type <>'')
               begin
               select @bbb=COUNT(INVOICE_SLNO) from BE_ITEM_SW_CONTROL where JOBNO=@Jobno and BRANCH_CODE=@Branch_Type
               if(@bbb=0) begin
                Select @Jobno as Jobno, 'F' as [Entry SW Control] 
               end
               else  begin
