else if(@Flag='IMP_Single_Window_Admin_Select')
begin 
	  if(@Branch_Type <>'')  
	  begin
		   select a.INVOICE_SLNO as Item_Inv_slno ,a.ITEM_SLNO as Item_Item_slno , a.CTH_NO ,b.INVOICE_SLNO as InfoType_Inv_slno ,b.ITEM_SLNO as InfoType_Item_slno
				 ,c.INVOICE_SLNO as Smt_Inv_slno ,c.ITEM_SLNO as Smt_Item_slno 
				 ,CENTRAL_EXCISE_FLAG,M_P_GROWER_ADD1,M_P_GROWER_ADD2,M_P_GROWER_CITY,M_P_GROWER_COUNTRY_SUBDIV,M_P_GROWER_PIN,M_P_GROWER_COUNTRY,SOURCE_COUNTRY
				 ,TRANSIT_COUNTRY,ACCESSORY_STATUS from ITEM_PRODUCT_DETAILS a
		  left outer join (select distinct INVOICE_SLNO ,ITEM_SLNO from BE_ITEM_SW_INFO_TYPE where JOBNO =@Jobno and BRANCH_CODE =@Branch_Type  )
		  b on a.INVOICE_SLNO=b.INVOICE_SLNO and a.ITEM_SLNO=b.ITEM_SLNO  left outer join    (select distinct INVOICE_SLNO ,ITEM_SLNO from IMP_SINGLE_WINDOW_STMT where JOBNO =@Jobno and BRANCH_CODE =@Branch_Type  )
		  c on  a.INVOICE_SLNO=c.INVOICE_SLNO and  a.ITEM_SLNO=c.ITEM_SLNO  where a.JOBNO=@Jobno  and a.BRANCH_CODE=@Branch_Type  order by a.INVOICE_SLNO ,a.ITEM_SLNO asc
		end
		else
		begin
		     select a.INVOICE_SLNO as Item_Inv_slno ,a.ITEM_SLNO as Item_Item_slno , a.CTH_NO ,b.INVOICE_SLNO as InfoType_Inv_slno ,b.ITEM_SLNO as InfoType_Item_slno
			,c.INVOICE_SLNO as Smt_Inv_slno ,c.ITEM_SLNO as Smt_Item_slno ,CENTRAL_EXCISE_FLAG,M_P_GROWER_ADD1,M_P_GROWER_ADD2,M_P_GROWER_CITY,M_P_GROWER_COUNTRY_SUBDIV
			,M_P_GROWER_PIN,M_P_GROWER_COUNTRY,SOURCE_COUNTRY,TRANSIT_COUNTRY,ACCESSORY_STATUS from ITEM_PRODUCT_DETAILS a
		    left outer join (select distinct INVOICE_SLNO ,ITEM_SLNO from BE_ITEM_SW_INFO_TYPE where JOBNO =@Jobno   )
		    b on a.INVOICE_SLNO=b.INVOICE_SLNO and a.ITEM_SLNO=b.ITEM_SLNO  left outer join    (select distinct INVOICE_SLNO ,ITEM_SLNO from IMP_SINGLE_WINDOW_STMT where JOBNO =@Jobno )
		    c on  a.INVOICE_SLNO=c.INVOICE_SLNO and  a.ITEM_SLNO=c.ITEM_SLNO  where a.JOBNO=@Jobno  order by a.INVOICE_SLNO ,a.ITEM_SLNO asc
		end   

end
