else if(@Flag='IMP_Invoice_Item_Select')
begin 
	  if(@Branch_Type <>'')  
	  begin
	        select a.INVOICE_SLNO as [Invoice Sl. no] ,'F' as [Item Page]  from INVOICE_DETAILS a 
			left outer join (select distinct(INVOICE_SLNO)INVOICE_SLNO from ITEM_PRODUCT_DETAILS  where JOBNO=@Jobno and BRANCH_CODE=@Branch_Type)b
			on a.INVOICE_SLNO =b.INVOICE_SLNO where JOBNO=@Jobno and isnull(b.INVOICE_SLNO,'') ='' and BRANCH_CODE=@Branch_Type order by a.INVOICE_SLNO asc
	  end
	  else
	  begin
	        select a.INVOICE_SLNO as [Invoice Sl. no] ,'F' as [Item Page]  from INVOICE_DETAILS a 
