        ,SW_Constituent varchar(5),SW_Production varchar(5),SW_Control varchar(5),SW_Statement varchar(5))
        Declare @temp_Ritc table (Id int identity(1,1), INVOICE_SLNO int,ITEM_SLNO int,CTH_NO varchar(20),AGENCY_CODE varchar(10) )
        declare @aa int,@bb int, @cnt int ,@D_INVOICE_SLNO int,@D_ITEM_SLNO int,@D_CTH_NO varchar(20),@D_AGENCY_CODE varchar(10)
        set @aa=1
        declare @M int , @N int, @O int, @P int ,@Q int ,@R int ,@S int ,@T varchar(5),@EE int ,@E int ,@IT varchar(10) 
        
        DECLARE @xmlHandle_Item_Ritc INT
		EXEC sp_xml_preparedocument @xmlHandle_Item_Ritc output, @xmlString 
		insert into @temp_Ritc	 SELECT  INVOICE_SLNO ,ITEM_SLNO,CTH_NO ,AGENCY_CODE FROM OPENXML 
		(@xmlHandle_Item_Ritc, '/NewDataSet/SampleDataTable',1)WITH (
		[INVOICE_SLNO] nvarchar(10) '@INVOICE_SLNO' ,[ITEM_SLNO] VARCHAR(10) '@ITEM_SLNO' ,[CTH_NO] VARCHAR(10) '@CTH_NO' ,[AGENCY_CODE] VARCHAR(10) '@AGENCY_CODE' )
		    
