		                  and ITEM_SLNO=@D_ITEM_SLNO and DEPARTMENT=@D_AGENCY_CODE  and BRANCH_CODE=@Branch_Type
		                  
		                  select @EE=COUNT(INVOICE_SLNO) from BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and BRANCH_CODE=@Branch_Type
						  and INFO_TYPE ='PEC' and ITEM_SLNO =@D_ITEM_SLNO and INVOICE_SLNO=@D_INVOICE_SLNO 
								
						  if(@EE>0)		
