							    set @bb=0
						  end
		                  if(@bb =5)
		                  begin
		                         select @M=COUNT(INVOICE_SLNO) from BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@D_INVOICE_SLNO 
		                         and ITEM_SLNO=@D_ITEM_SLNO and DEPARTMENT=@D_AGENCY_CODE  and BRANCH_CODE=@Branch_Type 
		                         and  INFO_TYPE='CTG' and  INFO_QUALIFIER='PLC' and isnull(INFO_CODE,'')<>'' and isnull(INFO_TEXT,'')='' and isnull(INFO_UQC,'') <>''
		                         
		                         select @N=COUNT(INVOICE_SLNO) from BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@D_INVOICE_SLNO 
		                         and ITEM_SLNO=@D_ITEM_SLNO and DEPARTMENT=@D_AGENCY_CODE  and BRANCH_CODE=@Branch_Type 
		                         and  INFO_TYPE='CTG' and  INFO_QUALIFIER='PLP' and isnull(INFO_CODE,'')<>'' and isnull(INFO_TEXT,'')='' and isnull(INFO_UQC,'') =''
		                          
		                         select @O=COUNT(INVOICE_SLNO) from BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@D_INVOICE_SLNO 
		                         and ITEM_SLNO=@D_ITEM_SLNO and DEPARTMENT=@D_AGENCY_CODE  and BRANCH_CODE=@Branch_Type 
		                         and  INFO_TYPE='CHR' and  INFO_QUALIFIER='PLV' and isnull(INFO_CODE,'')='' and isnull(INFO_TEXT,'')<>'' and isnull(INFO_UQC,'') =''
		                          
		                         select @P=COUNT(INVOICE_SLNO) from BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@D_INVOICE_SLNO 
		                         and ITEM_SLNO=@D_ITEM_SLNO and DEPARTMENT=@D_AGENCY_CODE  and BRANCH_CODE=@Branch_Type 
		                         and  INFO_TYPE='PNM' and  INFO_QUALIFIER='PCN' and isnull(INFO_CODE,'')<>'' and isnull(INFO_TEXT,'')='' and isnull(INFO_UQC,'') =''
		                         
		                         select @Q=COUNT(INVOICE_SLNO) from BE_ITEM_SW_INFO_TYPE where JOBNO=@Jobno and INVOICE_SLNO=@D_INVOICE_SLNO 
		                         and ITEM_SLNO=@D_ITEM_SLNO and DEPARTMENT=@D_AGENCY_CODE  and BRANCH_CODE=@Branch_Type 
		                         and  INFO_TYPE='PNM' and  INFO_QUALIFIER='SCI' and isnull(INFO_CODE,'')='' and isnull(INFO_TEXT,'')<>'' and isnull(INFO_UQC,'') =''
		                          
		                         if(@M =1 and  @N =1  and @O  =1  and @P =1  and @Q  =1)
		                         begin
		                                 set @T='T'   
		                         end  
		                            else
		                               begin
		                                       set @T='F'   
		                               end
		                               
		                         select @R= COUNT(INVOICE_SLNO) from BE_ITEM_SW_CONTROL where JOBNO=@Jobno 
