								 and isnull(CONTROL_TYPE_CODE,'') <>'' and isnull(CONTROL_START_DATE,'') <>'' and isnull(CONTROL_LOCATION,'') <>''
								 and isnull(CONTROL_END_DATE,'') <>'' and isnull(CONTROL_RESULT_CODE,'')  <>'' and BRANCH_CODE=@Branch_Type 
		                               
		                         select  @S =COUNT(INVOICE_SLNO) from IMP_SINGLE_WINDOW_STMT where JOBNO=@Jobno and BRANCH_CODE=@Branch_Type 
		                         and isnull(STMT_TYPE ,'') <>'' and isnull(STMT_CODE,'') <>'' and  isnull(STMT_TEXT ,'') <>''    
		                        
		                        
		                         if (@T ='T' and @R <>1 and @S>0 )
