		                         end
		                         else if (@T ='F' and @R <>1 and @S>0 )
		                         begin
		                                insert into  @Temp_1 values( @D_INVOICE_SLNO ,@D_ITEM_SLNO,@D_AGENCY_CODE ,'F' ,'-','-' ,'F','T' )  
