						  ELSE
							  BEGIN
							         if(@COMPANYID='293')
							         begin
							               if(len(@Name_Search)>5)
							               begin
												;With summ as( select case when ISNULL(JOBNO_PS,'')='' then cast (JOBNO as varchar(20)) else JOBNO_PS end as jobno
												 from general_details ) select jobno from summ where jobno like @Name_Search +'%'  order by JOBNO desc
										   end
										   else
										   begin
										        select ''jobno  where 1=0
										   end
							         end
							         else
							         begin
										;With summ as( select case when ISNULL(JOBNO_PS,'')='' then cast (JOBNO as varchar(20)) else JOBNO_PS end as jobno
										from general_details ) select jobno from summ where jobno like @Name_Search +'%'  order by JOBNO desc
									 end
							  END
			END  			else if(@Flag='Imp_Name')			BEGIN					 IF(@Branch<>'')					  BEGIN						    select distinct IMPORTER_NAME as Imp_Name from GENERAL_DETAILS where IMPORTER_NAME like @Name_Search +'%'  and BRANCHCODE=@Branch  order by Imp_Name desc
					  END
						  ELSE
							  BEGIN
									 select distinct IMPORTER_NAME as Imp_Name from GENERAL_DETAILS where IMPORTER_NAME like @Name_Search +'%'   order by Imp_Name desc
							  END			END
							  else if(@Flag='INV_NO')
							  BEGIN
							       IF(@Branch<>'')
									  BEGIN
											select INVOICE_NO from INVOICE_DETAILS where INVOICE_NO like @Name_Search +'%'  and branch_code=@Branch  order by JOBNO desc
									  END
										  ELSE
											  BEGIN
													 select INVOICE_NO from INVOICE_DETAILS where INVOICE_NO like @Name_Search +'%' order by JOBNO desc
											  END
			                 END  
			else if(@Flag='CON_NO')			BEGIN					 IF(@Branch<>'')					  BEGIN						    select CONTAINER_NO from CONTAINER_DETAILS where  CONTAINER_NO like @Name_Search +'%' and branch_code=@Branch  order by JOBNO desc
					  END						  ELSE							  BEGIN
									 select CONTAINER_NO from CONTAINER_DETAILS where CONTAINER_NO like @Name_Search +'%' order by JOBNO desc
							  END
			END  
			else if(@Flag='MAWB_NO')			BEGIN					 IF(@Branch<>'')					  BEGIN						    select IGM_MAWB_MBL from IGM_DETAILS where IGM_MAWB_MBL like @Name_Search +'%'  and IGM_BRANCH_CODE =@Branch order by JOBNO desc
					  END
						  ELSE
							  BEGIN
									 select IGM_MAWB_MBL from IGM_DETAILS where IGM_MAWB_MBL like @Name_Search +'%' order by JOBNO desc
							  END			END  			else if(@Flag='HAWB_NO')			BEGIN
					 IF(@Branch<>'')					  BEGIN						    select IGM_HAWB_HBLNO from IGM_DETAILS where IGM_HAWB_HBLNO like @Name_Search +'%' and IGM_BRANCH_CODE =@Branch order by JOBNO desc
					  END
						  ELSE
							  BEGIN									 select IGM_HAWB_HBLNO from IGM_DETAILS where IGM_HAWB_HBLNO like @Name_Search +'%'  order by JOBNO desc
							  END
			END  
			
			
			else if(@Flag='BE_NO')			BEGIN
					 IF(@Branch<>'')					  BEGIN
						    select BE_NO from BE_ENTRY where BE_NO like @Name_Search +'%' and BRANCH_CODE =@Branch  order by BE_JOBNO desc
					  END
						  ELSE
							  BEGIN
									 select BE_NO from BE_ENTRY where BE_NO like @Name_Search +'%' order by BE_JOBNO desc
							  END
			END  
			else if(@Flag='BOND_NO')			BEGIN
					 IF(@Branch<>'')					  BEGIN
						    select distinct BOND_NO from BOND_DETAILS where  BOND_NO like @Name_Search +'%' and BRANCH_CODE=@Branch 
					  END
						  ELSE
							  BEGIN
									 select distinct BOND_NO from BOND_DETAILS where BOND_NO like @Name_Search +'%'
							  END
			END 
			else if(@Flag='WH_To_Ex_Bond')			BEGIN
					 IF(@Branch<>'')					  BEGIN
					 ;With summ as( select case when ISNULL(JOBNO_PS,'')='' then cast (JOBNO as varchar(20)) else JOBNO_PS end as jobno
					 from general_details where branchcode= @Branch and BE_TYPE='Warehouse')
					 select jobno from summ where jobno like @Name_Search +'%'  order by JOBNO desc
					 END 	  ELSE  BEGIN
					;With summ as( select case when ISNULL(JOBNO_PS,'')='' then cast (JOBNO as varchar(20)) else JOBNO_PS end as jobno
					 from general_details where BE_TYPE='Warehouse')
					 select jobno from summ where jobno like @Name_Search +'%'  order by JOBNO desc
							  END
			END  
			else if(@Flag='FILE_REF_NO')			BEGIN
					 IF(@Branch<>'')					  BEGIN
						    select FILE_REF_NO from GENERAL_DETAILS where FILE_REF_NO like @Name_Search +'%' and ISNULL(FILE_REF_NO ,' ')<>''  and BRANCHCODE =@Branch  order by JOBNO desc
					  END
						  ELSE
							  BEGIN
									  select FILE_REF_NO from GENERAL_DETAILS where FILE_REF_NO like @Name_Search +'%' and ISNULL(FILE_REF_NO ,' ')<>''   order by JOBNO desc
							  END			END  			else if(@Flag='S_NAME')
			BEGIN
					 IF(@Branch<>'')					  BEGIN
						    select DISTINCT(supplier_name)supplier_name from INVOICE_DETAILS  where supplier_name like @Name_Search +'%' and BRANCH_CODE =@Branch  order by supplier_name Asc 
					  END
						  ELSE							  BEGIN
									 select DISTINCT(supplier_name)supplier_name from INVOICE_DETAILS where supplier_name like @Name_Search +'%'  order by supplier_name desc 
							  END			END  			else if(@Flag='ITEM_DESC')
			BEGIN
					 IF(@Branch<>'')					  BEGIN
						    select DISTINCT(item_description)item_description from item_product_details  where item_description like @Name_Search +'%' and BRANCH_CODE =@Branch  order by item_description desc 
					  END
						  ELSE
							  BEGIN
									 select DISTINCT(item_description)item_description from item_product_details where item_description like @Name_Search +'%' order by item_description desc 
							  END			END  			ELSE if(@Flag='IMP_GENERAL_EMPTY')
	        BEGIN
	           SELECT  '' as [Empty]	        END  
	        
	       else if(@Flag='Select_JobNo_Exbond')			BEGIN
					 IF(@Branch<>'')
					  BEGIN					        select BE_JOBNO from BE_ENTRY where BE_JOBNO like @Name_Search +'%' and BRANCH_CODE=@Branch  and BE_TYPE='Warehouse' order by BE_JOBNO desc
						   
					  END						  ELSE
							  BEGIN									select BE_JOBNO from BE_ENTRY where BE_JOBNO like @Name_Search +'%'  and BE_TYPE='Warehouse' order by BE_JOBNO desc
							  END
			END  
			 else if(@Flag='Select_BENO_Exbond')			BEGIN
					 IF(@Branch<>'')					  BEGIN
					        select BE_NO from BE_ENTRY where BE_NO like @Name_Search +'%' and BRANCH_CODE=@Branch  and BE_TYPE='Warehouse' order by BE_NO desc
						   
					  END						  ELSE							  BEGIN
									select BE_NO from BE_ENTRY where BE_NO like @Name_Search +'%'  and BE_TYPE='Warehouse' order by BE_NO desc
							  END
			END   
			else if(@Flag='LICENSE_NO')			BEGIN
					 IF(@Branch<>'')					  BEGIN
						    select distinct REGISTRATION_NO from LICENSE_DETAILS where  REGISTRATION_NO like @Name_Search +'%' and BRANCH_CODE=@Branch 
					  END
						  ELSE
							  BEGIN
									 select distinct REGISTRATION_NO from LICENSE_DETAILS where REGISTRATION_NO like @Name_Search +'%'
							  END
			END 		
   end
   else if(@Type='Export')
          begin
                  if(@Flag='JOB_NO')
			BEGIN
					 IF(@Branch<>'')
					  BEGIN
					         ;With summ as(
						    select 
						    case when ISNULL(JOBNO_PS,'')='' then cast (JOBNO as varchar(20)) else JOBNO_PS end as jobno
						     from EXPORT_GENERAL_DETAILS where branchcode= @Branch)
						     select jobno from summ where jobno like @Name_Search +'%'  order by JOBNO desc
					  END
						  ELSE
							  BEGIN
									  ;With summ2 as(
										select 
										case when ISNULL(JOBNO_PS,'')='' then cast (JOBNO as varchar(20)) else JOBNO_PS end as jobno
										 from EXPORT_GENERAL_DETAILS )
										 select jobno from summ2 where jobno like @Name_Search +'%'  order by JOBNO desc
							  END
			END  
	        else if(@Flag='INV_NO')
			BEGIN
					 IF(@Branch<>'')
					  BEGIN
						    select INVOICE_NO from export_invoice_details where INVOICE_NO like @Name_Search +'%'  and branch_code=@Branch  order by JOBNO desc
					  END
						  ELSE
							  BEGIN
									 select INVOICE_NO from export_invoice_details where INVOICE_NO like @Name_Search +'%' order by JOBNO desc
							  END
			END  
			else if(@Flag='CON_NO')
			BEGIN
					 IF(@Branch<>'')
					  BEGIN
						    select ANNEX_SEA_CON_CONTAINERNO as CONTAINER_NO from EXPORT_ANNEXURE_C_SEA_CONTAINER where  ANNEX_SEA_CON_CONTAINERNO like @Name_Search +'%' and branch_code=@Branch  order by ANNEX_SEA_CON_JOBNO desc
					  END
						  ELSE
							  BEGIN
									 select ANNEX_SEA_CON_CONTAINERNO as CONTAINER_NO from EXPORT_ANNEXURE_C_SEA_CONTAINER where ANNEX_SEA_CON_CONTAINERNO like @Name_Search +'%' order by ANNEX_SEA_CON_JOBNO desc
							  END
			END  
			else if(@Flag='MAWB_NO')
			BEGIN
					 IF(@Branch<>'')
					  BEGIN
						    select ANNEX_AIR_MAWB_NO as MAWB_NO from EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_MAWB_NO like @Name_Search +'%'  and BRANCH_CODE =@Branch order by ANNEX_AIR_JOBNO desc
					  END
						  ELSE
							  BEGIN
									 select ANNEX_AIR_MAWB_NO as MAWB_NO from EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_MAWB_NO like @Name_Search +'%' order by ANNEX_AIR_JOBNO desc
							  END
			END  
			else if(@Flag='HAWB_NO')
			BEGIN
					 IF(@Branch<>'')
					  BEGIN
						    select ANNEX_AIR_HAWB_NO as HAWB_NO from EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_HAWB_NO like @Name_Search +'%' and BRANCH_CODE =@Branch order by ANNEX_AIR_JOBNO desc
					  END
						  ELSE
							  BEGIN
									 select ANNEX_AIR_HAWB_NO as HAWB_NO from EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_HAWB_NO like @Name_Search +'%'  order by ANNEX_AIR_JOBNO desc
							  END
			END  
			else if(@Flag='SB_NO')
			BEGIN
					 IF(@Branch<>'')
					  BEGIN
						    select SB_NO from EXPORT_SB_ENTRY where SB_NO like @Name_Search +'%' and BRANCH_CODE =@Branch  order by SB_JOBNO desc
					  END
						  ELSE
							  BEGIN
									 select SB_NO from EXPORT_SB_ENTRY where SB_NO like @Name_Search +'%' order by SB_JOBNO desc
							  END
			END  
			else if(@Flag='FILE_REF_NO')
			BEGIN
					 IF(@Branch<>'')
					  BEGIN
						    select FILE_REF_NO from EXPORT_GENERAL_DETAILS where FILE_REF_NO like @Name_Search +'%' and ISNULL(FILE_REF_NO ,' ')<>''  and BRANCHCODE =@Branch  order by JOBNO desc
					  END
						  ELSE
							  BEGIN
									  select FILE_REF_NO from EXPORT_GENERAL_DETAILS where FILE_REF_NO like @Name_Search +'%' and ISNULL(FILE_REF_NO ,' ')<>''   order by JOBNO desc
							  END
			END 
			else if(@Flag='STR_CODE')
			BEGIN
					 IF(@Branch<>'')
					  BEGIN
						    select DISTINCT(ITEM_STR_CODE)STR_CODE from EXPORT_ITEM_DETAILS  where ITEM_STR_CODE like @Name_Search +'%' and BRANCH_CODE =@Branch  and ISNULL(ITEM_STR_CODE ,' ')<>'' order by STR_CODE Asc 
					  END
						  ELSE
							  BEGIN
									 select DISTINCT(ITEM_STR_CODE)STR_CODE from EXPORT_ITEM_DETAILS where ITEM_STR_CODE like @Name_Search +'%'and ISNULL(ITEM_STR_CODE ,' ')<>'' order by STR_CODE desc 
							  END
			END  
			
			else if(@Flag='ITEM_DESC')
			BEGIN
					 IF(@Branch<>'')
					  BEGIN
						    select DISTINCT(ITEM_DESCRIPTION)item_description from EXPORT_ITEM_DETAILS  where ITEM_DESCRIPTION like @Name_Search +'%' and BRANCH_CODE =@Branch  order by item_description desc 
					 
					  END
						  ELSE
							  BEGIN
									 select DISTINCT(ITEM_DESCRIPTION)item_description from EXPORT_ITEM_DETAILS where ITEM_DESCRIPTION like @Name_Search +'%' order by item_description desc 
							  END
			END  
			else if(@Flag='Consignee_Name')
			BEGIN
					 IF(@Branch<>'')
					  BEGIN
					        select DISTINCT(CONSIGNEE_NAME)CONSIGNEE_NAME from EXPORT_GENERAL_DETAILS where CONSIGNEE_NAME like  LTRIM(RTRIM(@Name_Search)) + '%'   and BRANCHCODE =@Branch  order by CONSIGNEE_NAME Asc 
					  END
						  ELSE
							  BEGIN
									 select DISTINCT(CONSIGNEE_NAME)CONSIGNEE_NAME from EXPORT_GENERAL_DETAILS where CONSIGNEE_NAME like  LTRIM(RTRIM(@Name_Search)) + '%'  order by CONSIGNEE_NAME Asc 
							  END
			END  
			else if(@Flag='Port_Discharge')
			BEGIN
					 IF(@Branch<>'')
					  BEGIN
						    select DISTINCT(PORT_DISCHARGE)PORT_DISCHARGE from EXPORT_GENERAL_DETAILS where PORT_DISCHARGE like  LTRIM(RTRIM(@Name_Search)) + '%'   and BRANCHCODE =@Branch  order by PORT_DISCHARGE Asc 
					 
					  END
						  ELSE
							  BEGIN
									 select DISTINCT(PORT_DISCHARGE)PORT_DISCHARGE from EXPORT_GENERAL_DETAILS where PORT_DISCHARGE like  LTRIM(RTRIM(@Name_Search)) + '%'  order by PORT_DISCHARGE Asc 
							  END
			END  
			
			ELSE if(@Flag='EXP_GENERAL_EMPTY')
	        BEGIN
	           SELECT  '' as [Empty]
	        END  
          end
               
    
  
  
  commit    
end try    
begin catch    
rollback transaction    
 set @ErrorMsg=error_message()    
 --set @MStatus=0    
end catch
/****** Object:  StoredProcedure [dbo].[SP_GENERAL_DETAILS_SEARCH_SELECT]    Script Date: 10/12/2018 15:51:54 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
ALTER PROCEDURE  [dbo].[SP_GENERAL_DETAILS_SEARCH_SELECT]       
    
 @JOBID varchar(35),@JOBNO varchar(35),@IMPORTER_NAME varchar(100),@TRANSPORT_MODE varchar(10),@CUSTOMS_HOUSE varchar(50),@Working_Period varchar(30),@name  varchar(300),   
 @SEARCH_CAT Varchar(50),@SEARCH_ITEM Varchar(max),@Mstatus  int output,@startRowIndex int,@maximumRows int,@totalRows int OUTPUT, @ErrorMsg nvarchar(max) output      
AS      
begin try      
 begin transaction      
  set @ErrorMsg=''      
    
DECLARE @first_id int, @startRow int      
declare @temp_Job table( Id int identity(1,1) , Jobno  bigint  )  
      
if(@Working_Period<>'')      
begin      
      
if(@IMPORTER_NAME ='' or @TRANSPORT_MODE ='' or @CUSTOMS_HOUSE ='' or @JOBNO ='')      
begin      
IF(@startRowIndex = 100000000)      
begin      
SELECT @startRowIndex = count(JOBID) FROM GENERAL_DETAILS where BRANCHCODE=@Working_Period       
if(@startRowIndex>=23)      
SET @startRowIndex = (@startRowIndex+1)-23      
else      
begin      
set @maximumRows=@startRowIndex      
set @startRowIndex=1      
end      
end      
else if(@startRowIndex = 100000001)      
SET @startRowIndex = 1      
end      
else      
begin      
SET @startRowIndex =  (@startRowIndex - 1)  * @maximumRows      
      
IF @startRowIndex = 0      
SET @startRowIndex = 1      
end      
      
if(@name='select_con')      
 begin      
SET ROWCOUNT @startRowIndex      
/*
SELECT @first_id = JOBID FROM GENERAL_DETAILS       where JOBNO like @JOBNO+ '%' and  IMPORTER_NAME like @IMPORTER_NAME+'%' and TRANSPORT_MODE       
 like @TRANSPORT_MODE+'%' and CUSTOMS_HOUSE like @CUSTOMS_HOUSE+'%'  and  BRANCHCODE=@Working_Period ORDER BY JOBID   
     */ 
SELECT @first_id = JOBNO FROM GENERAL_DETAILS       where JOBNO like @JOBNO+ '%' and  IMPORTER_NAME like @IMPORTER_NAME+'%' and TRANSPORT_MODE       
 like @TRANSPORT_MODE+'%' and CUSTOMS_HOUSE like @CUSTOMS_HOUSE+'%'  and  BRANCHCODE=@Working_Period ORDER BY CAST(JOBNO as int) 
      
PRINT @first_id      
      
SET ROWCOUNT @maximumRows      
if(@SEARCH_CAT<>'' and  @SEARCH_ITEM <>'' and @SEARCH_CAT<>'0') begin
        if(@SEARCH_CAT='JOB_NO')begin
		;with summary as (select jobno ,case when ISNULL(JOBNO_PS,'')='' then cast (JOBNO as varchar(20)) else JOBNO_PS end  as JOBNO_PS from GENERAL_DETAILS where BRANCHCODE=@Working_Period )	
		insert into @temp_Job   select jobno from summary  where JOBNO_PS =@SEARCH_ITEM set @JOBNO=''end  
else if(@SEARCH_CAT='INV_NO')  
begin insert into @temp_Job select JOBNO from INVOICE_DETAILS where INVOICE_NO = LTRIM(RTRIM(@SEARCH_ITEM))  and BRANCH_CODE=@Working_Period  end else if(@SEARCH_CAT='CON_NO')begin  insert into @temp_Job  select JOBNO from CONTAINER_DETAILS where CONTAINER_NO=LTRIM(RTRIM(@SEARCH_ITEM)) and BRANCH_CODE= @Working_Period  end  else if(@SEARCH_CAT='MAWB_NO')  
begin insert into @temp_Job select JOBNO from IGM_DETAILS where IGM_MAWB_MBL =LTRIM(RTRIM(@SEARCH_ITEM)) 
and IGM_BRANCH_CODE = @Working_Period  end  else if(@SEARCH_CAT='HAWB_NO')  
begin  insert into @temp_Job select JOBNO from IGM_DETAILS where IGM_HAWB_HBLNO =LTRIM(RTRIM(@SEARCH_ITEM)) and IGM_BRANCH_CODE = @Working_Period  end  else if(@SEARCH_CAT='BE_NO')   begin  insert into @temp_Job  
select BE_JOBNO from BE_ENTRY where BE_NO= LTRIM(RTRIM(@SEARCH_ITEM)) and BRANCH_CODE =@Working_Period end  else if(@SEARCH_CAT='FILE_REF_NO') begin  
insert into @temp_Job select JOBNO from GENERAL_DETAILS where ISNULL(FILE_REF_NO ,' ')<>'' and FILE_REF_NO=LTRIM(RTRIM(@SEARCH_ITEM))and BRANCHCODE =@Working_Period  end 
else if(@SEARCH_CAT='S_NAME') begin insert into @temp_Job  select distinct(JOBNO)  from INVOICE_DETAILS where SUPPLIER_NAME= LTRIM(RTRIM(@SEARCH_ITEM))and BRANCH_CODE =@Working_Period 
end 
else if(@SEARCH_CAT='ITEM_DESC') begin insert into @temp_Job  select distinct(JOBNO) from item_product_details where ITEM_DESCRIPTION=LTRIM(RTRIM(@SEARCH_ITEM))and BRANCH_CODE =@Working_Period 
end 
else if(@SEARCH_CAT='BOND_NO')
begin 
    insert into @temp_Job select distinct (JOBNO) from BOND_DETAILS where BOND_NO=LTRIM(RTRIM(@SEARCH_ITEM)) and BRANCH_CODE=@Working_Period
end 
else if(@SEARCH_CAT='LICENSE_NO')
begin 
    insert into @temp_Job select distinct (JOBNO) from LICENSE_DETAILS where REGISTRATION_NO=LTRIM(RTRIM(@SEARCH_ITEM)) and BRANCH_CODE=@Working_Period
end 

else if(@SEARCH_CAT='WH_To_Ex_Bond')
 begin 
;with summary as (
select jobno ,case when ISNULL(JOBNO_PS,'')='' then cast (JOBNO as varchar(20)) else JOBNO_PS end  as JOBNO_PS from GENERAL_DETAILS 
where BRANCHCODE=@Working_Period and BE_TYPE='Warehouse')	
insert into @temp_Job select jobno from summary  where JOBNO_PS =@SEARCH_ITEM

insert into @temp_Job   select  distinct(JOBNO) from ITEM_PRODUCT_DETAILS where isnull(WAREHOUSE_JOBNO,0) in( select Jobno from @temp_Job)
and BRANCH_CODE=@Working_Period


end 

; with summary as( SELECT  JOBID ,GEN.JOBNO  ,TRANSPORT_MODE  ,GEN.CUSTOMS_HOUSE  ,IMPORTER_NAME  ,Convert(varchar(11),JOBDATE, 103)JOBDATE  ,BE.BE_NO ,(case when convert(varchar(10),BE.BE_DATE,103)='01/01/1900' then null else convert(varchar(10),BE.BE_DATE,103) end ) as BE_DATE
,BE.BE_ASSESSABLE_VALUE ,BE.BE_DUTY ,IGM.IGM_NO ,REPLACE(CONVERT(VARCHAR,igm.IGM_DATE,103),'01/01/1900','') IGM_DATE ,IGM.IGM_AIRLINENAME ,igm.IGM_MAWB_MBL  
,IGM.IGM_HAWB_HBLNO,inv.INVOICE_NO ,Convert(varchar(11),Inv.INVOICE_DATE, 103)INVOICE_DATE ,inv.INVOICE_CURRENCY,INV.SUPPLIER_NAME ,INV.OTHER_PURCHASE_ORDER   
,case when (LEN(INV.ITEM_DESCRIPTION)>40) then SUBSTRING(INV.ITEM_DESCRIPTION,0,40)+'...'  ELSE INV.ITEM_DESCRIPTION END AS ITEM_DESCRIPTION
,INV.CTH_NO  
,INV.ITEM_QTY  
,INV.SCHEME_CODE  
,GEN.JOBNO as JOB_DUP  
,gen.FILE_REF_NO as FILE_REF_NO
, case when isnull(JOBNO_PS ,'')='' then cast ( GEN.JOBNO AS varchar(20)) else JOBNO_PS end JOBNO_PS
,left(IMPORTER_NAME ,18)+'...' as Imp_Name_Short
,GEN.BE_TYPE
,GEN.FILING_STATUS
,GEN.PORT_ORIGIN

FROM GENERAL_DETAILS GEN       
left join BE_ENTRY BE on BE.BE_JOBNO=GEN.JOBNO and GEN.BRANCHCODE=BE.BRANCH_CODE  
OUTER APPLY       
(SELECT TOP 1 IGM.IGM_NO,igm.IGM_DATE,IGM.IGM_AIRLINENAME,igm.IGM_MAWB_MBL,IGM.IGM_HAWB_HBLNO      
FROM IGM_DETAILS IGM      
WHERE GEN.JOBNO=IGM.JOBNO and GEN.BRANCHCODE=IGM.IGM_BRANCH_CODE      
) AS IGM      
OUTER APPLY       
(SELECT TOP 1 inv.INVOICE_NO  
,Convert(varchar(11),Inv.INVOICE_DATE, 103)INVOICE_DATE,inv.INVOICE_CURRENCY,      
INV.SUPPLIER_NAME,INV.OTHER_PURCHASE_ORDER,ITEM.ITEM_DESCRIPTION,ITEM.CTH_NO,ITEM.ITEM_QTY,ITEM.SCHEME_CODE      
FROM INVOICE_DETAILS INV      
INNER JOIN ITEM_PRODUCT_DETAILS ITEM  ON     
INV.JOBNO=ITEM.JOBNO        
WHERE GEN.JOBNO=INV.JOBNO  and GEN.BRANCHCODE=INV.BRANCH_CODE    
) AS INV   WHERE GEN.JOBNO like @JOBNO+ '%' and  IMPORTER_NAME like @IMPORTER_NAME+'%' and TRANSPORT_MODE       
like @TRANSPORT_MODE+'%' and CUSTOMS_HOUSE like @CUSTOMS_HOUSE+'%'  and  BRANCHCODE=@Working_Period   
)  
select    JOBID  ,a.JOBNO ,TRANSPORT_MODE  ,CUSTOMS_HOUSE,IMPORTER_NAME ,JOBDATE,BE_NO ,BE_DATE ,BE_ASSESSABLE_VALUE ,BE_DUTY ,IGM_NO,IGM_DATE ,IGM_AIRLINENAME ,IGM_MAWB_MBL  ,IGM_HAWB_HBLNO ,INVOICE_NO  
,INVOICE_DATE ,INVOICE_CURRENCY ,SUPPLIER_NAME  ,OTHER_PURCHASE_ORDER ,ITEM_DESCRIPTION ,CTH_NO,ITEM_QTY  ,SCHEME_CODE ,JOB_DUP,FILE_REF_NO ,JOBNO_PS 
,left(IMPORTER_NAME ,18)+'...' as Imp_Name_Short
,BE_TYPE
,FILING_STATUS
,PORT_ORIGIN
from summary 
a inner join @temp_Job b on a.JOBNO =b.Jobno  

SET ROWCOUNT 0  SELECT @totalRows =23    end  else begin
SELECT JOBID  
,GEN.JOBNO  
,TRANSPORT_MODE  
,GEN.CUSTOMS_HOUSE  
,IMPORTER_NAME  
,Convert(varchar(11),JOBDATE, 103)JOBDATE  
,BE.BE_NO  
,(case when convert(varchar(10),BE.BE_DATE,103)='01/01/1900' then null else convert(varchar(10),BE.BE_DATE,103) end ) as BE_DATE  
,BE.BE_ASSESSABLE_VALUE  
,BE.BE_DUTY  
,IGM.IGM_NO  
,REPLACE(CONVERT(VARCHAR,igm.IGM_DATE,103),'01/01/1900','') 'IGM_DATE'  
,IGM.IGM_AIRLINENAME  
,igm.IGM_MAWB_MBL  
,IGM.IGM_HAWB_HBLNO  
,inv.INVOICE_NO  
,Convert(varchar(11),Inv.INVOICE_DATE, 103)INVOICE_DATE  
,inv.INVOICE_CURRENCY  
,INV.SUPPLIER_NAME  
,INV.OTHER_PURCHASE_ORDER   
,case when (LEN(INV.ITEM_DESCRIPTION)>40) then SUBSTRING(INV.ITEM_DESCRIPTION,0,40)+'...' else INV.ITEM_DESCRIPTION  end AS ITEM_DESCRIPTION
,INV.CTH_NO  
,INV.ITEM_QTY  
,INV.SCHEME_CODE  
,GEN.JOBNO as JOB_DUP 
,GEN.FILE_REF_NO as FILE_REF_NO 
, case when isnull(JOBNO_PS ,'')='' then cast ( GEN.JOBNO AS varchar(20)) else JOBNO_PS end JOBNO_PS
,left(IMPORTER_NAME ,18)+'...' as Imp_Name_Short
,GEN.BE_TYPE
,GEN.FILING_STATUS
,GEN.PORT_ORIGIN

FROM GENERAL_DETAILS GEN       
          left join BE_ENTRY BE on BE.BE_JOBNO=GEN.JOBNO and GEN.BRANCHCODE=BE.BRANCH_CODE        
          OUTER APPLY       
         (SELECT TOP 1 IGM.IGM_NO,igm.IGM_DATE,IGM.IGM_AIRLINENAME,igm.IGM_MAWB_MBL,IGM.IGM_HAWB_HBLNO      
          FROM IGM_DETAILS IGM      
          WHERE GEN.JOBNO=IGM.JOBNO and GEN.BRANCHCODE=IGM.IGM_BRANCH_CODE      
         ) AS IGM      
          OUTER APPLY       
      (SELECT TOP 1 inv.INVOICE_NO,Convert(varchar(11),Inv.INVOICE_DATE, 103)INVOICE_DATE,inv.INVOICE_CURRENCY,      
          INV.SUPPLIER_NAME,INV.OTHER_PURCHASE_ORDER,ITEM.ITEM_DESCRIPTION,ITEM.CTH_NO,ITEM.ITEM_QTY,ITEM.SCHEME_CODE      
       FROM INVOICE_DETAILS INV      
       INNER JOIN ITEM_PRODUCT_DETAILS ITEM  ON     
            INV.JOBNO=ITEM.JOBNO        
       WHERE GEN.JOBNO=INV.JOBNO  and GEN.BRANCHCODE=INV.BRANCH_CODE  and INV.BRANCH_CODE=ITEM.BRANCH_CODE     
              
      ) AS INV    
          
      WHERE GEN.JOBNO like @JOBNO+ '%' and  IMPORTER_NAME like @IMPORTER_NAME+'%' and TRANSPORT_MODE       
         like @TRANSPORT_MODE+'%' and CUSTOMS_HOUSE like @CUSTOMS_HOUSE+'%'  and  BRANCHCODE=@Working_Period and      
        -- JOBID >= @first_id ORDER BY JOBID  
         JOBNO >= @first_id  ORDER BY CAST(JOBNO as int) 
           
           SET ROWCOUNT 0      
            
      SELECT @totalRows = count(JOBID) FROM GENERAL_DETAILS       
       where JOBNO like @JOBNO+ '%' and  IMPORTER_NAME like @IMPORTER_NAME+'%' and TRANSPORT_MODE       
       like @TRANSPORT_MODE+'%' and CUSTOMS_HOUSE like @CUSTOMS_HOUSE+'%'  and  BRANCHCODE=@Working_Period     
                 
              end end  
else if(@name='select_Id') begin SELECT Convert(varchar(11),JOBDATE, 103)JOBDATE,Convert(varchar(11),EXBOND_INBOND_BE_DATE, 103)EXBOND_INBOND_BE_DATE,      
 Convert(varchar(11),EXBOND_BOND_DATE, 103)EXBOND_BOND_DATE,      
 BE.BE_NO
 --,Convert(varchar(11),BE.BE_DATE, 103)BE_DATE
  ,(case when convert(varchar(10),BE.BE_DATE,103)='01/01/1900' then null else convert(varchar(10),BE.BE_DATE,103) end ) as BE_DATE
 ,BE.BE_ASSESSABLE_VALUE,BE.BE_DUTY,*      
 FROM GENERAL_DETAILS  left join BE_ENTRY BE on BE.BE_JOBNO=JOBNO and BRANCHCODE=BE.BRANCH_CODE        
 where JOBID=@JOBID  and  BRANCHCODE=@Working_Period  ORDER BY JOBID  end else if(@name='select_Id_Submission') begin  select  JOB_STATUS  ,JOB_RELEASE ,USERID   FROM 
 GENERAL_DETAILS   where JOBNO=@JOBNO  and  BRANCHCODE=@Working_Period  end 
    
else if(@name='Exbond_select_Id')      
 begin      
 SELECT Convert(varchar(11),JOBDATE, 103)JOBDATE,Convert(varchar(11),EXBOND_INBOND_BE_DATE, 103)EXBOND_INBOND_BE_DATE,      
 Convert(varchar(11),EXBOND_BOND_DATE, 103)EXBOND_BOND_DATE,* FROM GENERAL_DETAILS       
 where JOBNO=@JOBID  and  BRANCHCODE=@Working_Period  ORDER BY JOBID       
end      
      
else if(@name='delete')      
 begin      
      
delete from BOND_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period      
delete from CERTIFICATE_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period      
delete from CONTAINER_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period      
delete from IGM_DETAILS where JOBNO=@JOBNO and IGM_BRANCH_CODE=@Working_Period      
delete from INVOICE_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period      
delete from ITEM_PRODUCT_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period      
delete from LICENSE_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period      
delete from MULTIPLE_INVOICE where MULTIPLE_JOBNO=@JOBNO and BRANCH_CODE=@Working_Period      
      
delete from RE_IMPORT_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period      
delete from SUPPLIER_DETAILS where JOBNO=@JOBNO and SUPPLIER_BRANCH_CODE=@Working_Period      
delete from SVB_DETAILS where JOBNO=@JOBNO and SVB_BRANCH_CODE=@Working_Period      
delete from BE_ENTRY where BE_JOBNO=@JOBNO and BRANCH_CODE=@Working_Period      
      
delete from GENERAL_DETAILS where JOBNO=@JOBNO and BRANCHCODE=@Working_Period  

delete FROM BE_ITEM_SW_INFO_TYPE where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period
delete FROM BE_ITEM_SW_CONST where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period
delete FROM BE_ITEM_SW_PROD where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period
delete FROM BE_ITEM_SW_CONTROL where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period
delete FROM IMP_SINGLE_WINDOW_STMT where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period
delete FROM BE_ITEM_SW_SUP_DOC where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period
    
 select @Mstatus=1      
end  

else if(@name='Select_JobNo_Exbond')      
 begin   
   select BE_ID,

	BE_INBOND_NO,
	Convert(varchar(11),BE_INBOND_DATE, 103)BE_INBOND_DATE,
	BE_WAREHOUSE_CUSTOMS,
	BE_WAREHOUSE_CUSTOMS_CODE
	,BE_NO
	,BE_JOBNO
	,Convert(varchar(11),BE_DATE, 103)BE_DATE from BE_ENTRY where BE_JOBNO like @JOBNO +'%'  and BRANCH_CODE=@Working_Period  AND BE_TYPE='Warehouse'
 end
 
 else if(@name='Select_BeNo_Exbond')      
 begin   
   select BE_ID,

	BE_INBOND_NO,
	Convert(varchar(11),BE_INBOND_DATE, 103)BE_INBOND_DATE,
	BE_WAREHOUSE_CUSTOMS,
	BE_WAREHOUSE_CUSTOMS_CODE
	,BE_NO
	,BE_JOBNO
	,Convert(varchar(11),BE_DATE, 103)BE_DATE from BE_ENTRY where  BE_NO like @JOBID +'%' and BRANCH_CODE=@Working_Period  AND BE_TYPE='Warehouse'
 end
 
 else if(@name='Select_JobNo_Beno_Exbond')      
 begin   
   select BE_ID,

	BE_INBOND_NO,
	Convert(varchar(11),BE_INBOND_DATE, 103)BE_INBOND_DATE,
	BE_WAREHOUSE_CUSTOMS,
	BE_WAREHOUSE_CUSTOMS_CODE
	,BE_NO
	,BE_JOBNO
	,Convert(varchar(11),BE_DATE, 103)BE_DATE from BE_ENTRY where BE_JOBNO like @JOBNO +'%' and BE_NO like @JOBID +'%' and BRANCH_CODE=@Working_Period  AND BE_TYPE='Warehouse'
 end
      
end      
      
else      
begin      
      
if(@IMPORTER_NAME ='' or @TRANSPORT_MODE ='' or @CUSTOMS_HOUSE ='' or @JOBNO ='')      
begin      
IF(@startRowIndex = 100000000)      
begin      
SELECT @startRowIndex = count(JOBID) FROM GENERAL_DETAILS       
--SET @startRowIndex = (@startRowIndex+1)      
if(@startRowIndex>=23)      
SET @startRowIndex = (@startRowIndex+1)-23      
else      
begin      
--SET @startRowIndex = 15-(@startRowIndex+1)      
set @maximumRows=@startRowIndex      
set @startRowIndex=1      
end      
end      
else if(@startRowIndex = 100000001)      
SET @startRowIndex = 1      
--SET @startRowIndex =  ((@startRowIndex+10) % 10)  * @maximumRows      
end      
else      
begin      
SET @startRowIndex =  (@startRowIndex - 1)  * @maximumRows      
      
IF @startRowIndex = 0      
SET @startRowIndex = 1      
end      
      
if(@name='select_con')      
 begin      
SET ROWCOUNT @startRowIndex   
/*   
SELECT @first_id = JOBID FROM GENERAL_DETAILS       
 where JOBNO like @JOBNO+ '%' and  IMPORTER_NAME like @IMPORTER_NAME+'%' and TRANSPORT_MODE       
 like @TRANSPORT_MODE+'%' and CUSTOMS_HOUSE like @CUSTOMS_HOUSE+'%'  ORDER BY JOBID 
 */
 
 SELECT @first_id = JOBNO FROM GENERAL_DETAILS       
 where JOBNO like @JOBNO+ '%' and  IMPORTER_NAME like @IMPORTER_NAME+'%' and TRANSPORT_MODE       
 like @TRANSPORT_MODE+'%' and CUSTOMS_HOUSE like @CUSTOMS_HOUSE+'%'  ORDER BY CAST(JOBNO as int) 
 
PRINT @first_id      
      
SET ROWCOUNT @maximumRows      
if(@SEARCH_CAT<>'' and  @SEARCH_ITEM <>''and @SEARCH_CAT<>'0')begin if(@SEARCH_CAT='JOB_NO') begin 
 --insert into @temp_Job select JOBNO From GENERAL_DETAILS where JOBNO=@SEARCH_ITEM   
  ;with summary as ( select jobno, case when ISNULL(JOBNO_PS,'')='' then cast (JOBNO as varchar(20)) else JOBNO_PS end  as JOBNO_PS 
  
  from GENERAL_DETAILS )insert into @temp_Job   select jobno from summary  where JOBNO_PS =@SEARCH_ITEM 
  set @JOBNO=''
 end else if(@SEARCH_CAT='INV_NO')  
 begin insert into @temp_Job  select JOBNO from INVOICE_DETAILS where INVOICE_NO =LTRIM(RTRIM(@SEARCH_ITEM)) end  else if(@SEARCH_CAT='CON_NO')  begin  
insert into @temp_Job  select JOBNO from CONTAINER_DETAILS where CONTAINER_NO=LTRIM(RTRIM(@SEARCH_ITEM))end  else if(@SEARCH_CAT='MAWB_NO')  begin  insert into @temp_Job  select JOBNO from IGM_DETAILS where IGM_MAWB_MBL =LTRIM(RTRIM(@SEARCH_ITEM))    end   else if(@SEARCH_CAT='HAWB_NO')  
begin insert into @temp_Job  select JOBNO from IGM_DETAILS where IGM_HAWB_HBLNO =LTRIM(RTRIM(@SEARCH_ITEM))end  else if(@SEARCH_CAT='BE_NO')   begin  insert into @temp_Job  select BE_JOBNO from BE_ENTRY where BE_NO= @SEARCH_ITEM   end        
 else if(@SEARCH_CAT='FILE_REF_NO')  begin  
insert into @temp_Job  select JOBNO from GENERAL_DETAILS where ISNULL(FILE_REF_NO ,' ')<>'' and FILE_REF_NO=LTRIM(RTRIM(@SEARCH_ITEM)) 
end  
else if(@SEARCH_CAT='S_NAME')  
begin  
      insert into @temp_Job  select distinct(JOBNO)  from INVOICE_DETAILS where SUPPLIER_NAME= LTRIM(RTRIM(@SEARCH_ITEM))
end 
else if(@SEARCH_CAT='ITEM_DESC')  begin insert into @temp_Job  select distinct(JOBNO) from item_product_details where ITEM_DESCRIPTION=LTRIM(RTRIM(@SEARCH_ITEM))
end 
else if(@SEARCH_CAT='BOND_NO')
begin 
    insert into @temp_Job select distinct (JOBNO) from BOND_DETAILS where BOND_NO=LTRIM(RTRIM(@SEARCH_ITEM)) 
end 
else if(@SEARCH_CAT='LICENSE_NO')
begin 
    insert into @temp_Job select distinct (JOBNO) from LICENSE_DETAILS where REGISTRATION_NO=LTRIM(RTRIM(@SEARCH_ITEM))
end

else if(@SEARCH_CAT='WH_To_Ex_Bond')begin

;with summary as (
select jobno ,case when ISNULL(JOBNO_PS,'')='' then cast (JOBNO as varchar(20)) else JOBNO_PS end  as JOBNO_PS from GENERAL_DETAILS 
where BE_TYPE='Warehouse')	
insert into @temp_Job   select jobno from summary  where JOBNO_PS =@SEARCH_ITEM
insert into @temp_Job   select  distinct(JOBNO) from ITEM_PRODUCT_DETAILS where isnull(WAREHOUSE_JOBNO,0) in( select Jobno from @temp_Job)
 
end 

;with summary_2  as( SELECT  JOBID,GEN.JOBNO,TRANSPORT_MODE,GEN.CUSTOMS_HOUSE,IMPORTER_NAME,  Convert(varchar(11),JOBDATE, 103)JOBDATE,BE.BE_NO,Convert(varchar(11),BE.BE_DATE, 103)BE_DATE,BE.BE_ASSESSABLE_VALUE,BE.BE_DUTY,      
IGM.IGM_NO,REPLACE(CONVERT(VARCHAR,igm.IGM_DATE,103),'01/01/1900','') IGM_DATE,IGM.IGM_AIRLINENAME,igm.IGM_MAWB_MBL,IGM.IGM_HAWB_HBLNO,      
inv.INVOICE_NO,Convert(varchar(11),Inv.INVOICE_DATE, 103)INVOICE_DATE,inv.INVOICE_CURRENCY, INV.SUPPLIER_NAME,INV.OTHER_PURCHASE_ORDER      
,case when (LEN(INV.ITEM_DESCRIPTION)>40) then SUBSTRING(INV.ITEM_DESCRIPTION,0,40)+'...' else INV.ITEM_DESCRIPTION  end AS ITEM_DESCRIPTION,INV.CTH_NO,INV.ITEM_QTY,INV.SCHEME_CODE ,GEN.JOBNO as JOB_DUP  ,GEN.FILE_REF_NO  as FILE_REF_NO
,case when isnull(JOBNO_PS ,'')='' then cast ( GEN.JOBNO AS varchar(20)) else JOBNO_PS end JOBNO_PS
,left(IMPORTER_NAME ,18)+'...' as Imp_Name_Short
,GEN.BE_TYPE ,GEN.FILING_STATUS,GEN.PORT_ORIGIN

FROM GENERAL_DETAILS GEN left join BE_ENTRY BE on BE.BE_JOBNO=JOBNO OUTER APPLY (SELECT TOP 1 IGM.IGM_NO,igm.IGM_DATE,IGM.IGM_AIRLINENAME,igm.IGM_MAWB_MBL,IGM.IGM_HAWB_HBLNO FROM 
IGM_DETAILS IGM WHERE GEN.JOBNO=IGM.JOBNO) AS IGM OUTER APPLY       
(SELECT TOP 1 inv.INVOICE_NO,Convert(varchar(11),Inv.INVOICE_DATE, 103)INVOICE_DATE,inv.INVOICE_CURRENCY,      
      INV.SUPPLIER_NAME,INV.OTHER_PURCHASE_ORDER,ITEM.ITEM_DESCRIPTION,ITEM.CTH_NO,ITEM.ITEM_QTY,ITEM.SCHEME_CODE      
        FROM       
        INVOICE_DETAILS INV      
         INNER JOIN ITEM_PRODUCT_DETAILS ITEM       
          ON INV.JOBNO=ITEM.JOBNO                       
        WHERE GEN.JOBNO=INV.JOBNO        
       ) AS INV      
                
       WHERE GEN.JOBNO like @JOBNO+ '%' and  IMPORTER_NAME like @IMPORTER_NAME+'%' and TRANSPORT_MODE       
       like @TRANSPORT_MODE+'%' and CUSTOMS_HOUSE like @CUSTOMS_HOUSE+'%'     
      )  
 select JOBID,a.JOBNO,TRANSPORT_MODE,CUSTOMS_HOUSE,IMPORTER_NAME,JOBDATE,BE_NO,BE_DATE,BE_ASSESSABLE_VALUE,BE_DUTY,IGM_NO,IGM_DATE,IGM_AIRLINENAME,IGM_MAWB_MBL  
,IGM_HAWB_HBLNO,INVOICE_NO,INVOICE_DATE,INVOICE_CURRENCY,SUPPLIER_NAME,OTHER_PURCHASE_ORDER,ITEM_DESCRIPTION,CTH_NO,ITEM_QTY,SCHEME_CODE,JOB_DUP,FILE_REF_NO,JOBNO_PS
,left(IMPORTER_NAME ,18)+'...' as Imp_Name_Short
,BE_TYPE
,FILING_STATUS
,PORT_ORIGIN

from summary_2 a inner join @temp_Job b  on a.JOBNO =b.Jobno  SELECT @totalRows =23      
    end  
              
            else  
             begin  
      SELECT  JOBID,GEN.JOBNO,TRANSPORT_MODE,GEN.CUSTOMS_HOUSE,IMPORTER_NAME,      
      Convert(varchar(11),JOBDATE, 103)JOBDATE,BE.BE_NO
      --,Convert(varchar(11),BE.BE_DATE, 103)BE_DATE
       ,(case when convert(varchar(10),BE.BE_DATE,103)='01/01/1900' then null else convert(varchar(10),BE.BE_DATE,103) end ) as BE_DATE
      ,BE.BE_ASSESSABLE_VALUE,BE.BE_DUTY,      
      IGM.IGM_NO,REPLACE(CONVERT(VARCHAR,igm.IGM_DATE,103),'01/01/1900','') 'IGM_DATE',IGM.IGM_AIRLINENAME,igm.IGM_MAWB_MBL,IGM.IGM_HAWB_HBLNO,      
      inv.INVOICE_NO,Convert(varchar(11),Inv.INVOICE_DATE, 103)INVOICE_DATE,inv.INVOICE_CURRENCY,      
      INV.SUPPLIER_NAME,INV.OTHER_PURCHASE_ORDER      
      ,case when (LEN(INV.ITEM_DESCRIPTION)>40) then SUBSTRING(INV.ITEM_DESCRIPTION,0,40)+'...' else INV.ITEM_DESCRIPTION  end 
      AS ITEM_DESCRIPTION,INV.CTH_NO,INV.ITEM_QTY,INV.SCHEME_CODE ,GEN.JOBNO as JOB_DUP ,FILE_REF_NO as FILE_REF_NO
      ,case when isnull(JOBNO_PS ,'')='' then cast ( GEN.JOBNO AS varchar(20)) else  JOBNO_PS end JOBNO_PS
      ,left(IMPORTER_NAME ,18)+'...' as Imp_Name_Short
	  ,GEN.BE_TYPE
	  ,GEN.FILING_STATUS
	  ,GEN.PORT_ORIGIN
      FROM GENERAL_DETAILS GEN       
      left join BE_ENTRY BE on BE.BE_JOBNO=JOBNO       
                
        OUTER APPLY       
       (SELECT TOP 1 IGM.IGM_NO,igm.IGM_DATE,IGM.IGM_AIRLINENAME,igm.IGM_MAWB_MBL,IGM.IGM_HAWB_HBLNO      
        FROM IGM_DETAILS IGM      
                              
        WHERE GEN.JOBNO=IGM.JOBNO       
        --ORDER BY m.creation_date      
       ) AS IGM      
              
      OUTER APPLY       
       (SELECT TOP 1 inv.INVOICE_NO,Convert(varchar(11),Inv.INVOICE_DATE, 103)INVOICE_DATE,inv.INVOICE_CURRENCY,      
      INV.SUPPLIER_NAME,INV.OTHER_PURCHASE_ORDER,ITEM.ITEM_DESCRIPTION,ITEM.CTH_NO,ITEM.ITEM_QTY,ITEM.SCHEME_CODE      
        FROM       
        INVOICE_DETAILS INV      
         INNER JOIN ITEM_PRODUCT_DETAILS ITEM       
          ON INV.JOBNO=ITEM.JOBNO        
                           
        WHERE GEN.JOBNO=INV.JOBNO       
        --ORDER BY m.creation_date      
       ) AS INV      
                
       WHERE GEN.JOBNO like @JOBNO+ '%' and  IMPORTER_NAME like @IMPORTER_NAME+'%' and TRANSPORT_MODE       
       like @TRANSPORT_MODE+'%' and CUSTOMS_HOUSE like @CUSTOMS_HOUSE+'%'   and      
             
       --JOBID >= @first_id   ORDER BY JOBID   
       JOBNO >= @first_id  ORDER BY CAST(JOBNO as int)     
         
       SET ROWCOUNT 0      
      
       -- GEt the total rows      
            
       SELECT @totalRows = count(JOBID) FROM GENERAL_DETAILS       
       where JOBNO like @JOBNO+ '%' and  IMPORTER_NAME like @IMPORTER_NAME+'%' and TRANSPORT_MODE       
       like @TRANSPORT_MODE+'%' and CUSTOMS_HOUSE like @CUSTOMS_HOUSE+'%'     
      end  
       
      
end      
      
      
      
else if(@name='select_Id')      
 begin      
 SELECT Convert(varchar(11),JOBDATE, 103)JOBDATE,Convert(varchar(11),EXBOND_INBOND_BE_DATE, 103)EXBOND_INBOND_BE_DATE,      
 Convert(varchar(11),EXBOND_BOND_DATE, 103)EXBOND_BOND_DATE,      
 BE.BE_NO
 --,Convert(varchar(11),BE.BE_DATE, 103)BE_DATE
  ,(case when convert(varchar(10),BE.BE_DATE,103)='01/01/1900' then null else convert(varchar(10),BE.BE_DATE,103) end ) as BE_DATE
 ,BE.BE_ASSESSABLE_VALUE,BE.BE_DUTY,*      
 FROM GENERAL_DETAILS  left join BE_ENTRY BE on BE.BE_JOBNO=JOBNO       
 where JOBID=@JOBID    ORDER BY JOBID       
end    
else if(@name='select_Id_Submission')      
 begin   
 select   
		 JOB_STATUS  
		 ,JOB_RELEASE
		 ,USERID   
		 FROM GENERAL_DETAILS        
		 where JOBNO=@JOBNO  
end 
  
else if(@name='Exbond_select_Id')      
 begin      
 SELECT Convert(varchar(11),JOBDATE, 103)JOBDATE,Convert(varchar(11),EXBOND_INBOND_BE_DATE, 103)EXBOND_INBOND_BE_DATE,      
 Convert(varchar(11),EXBOND_BOND_DATE, 103)EXBOND_BOND_DATE,* FROM GENERAL_DETAILS       
 where JOBNO=@JOBID   ORDER BY JOBID       
end      
      
else if(@name='delete')      
 begin      
      
delete from BOND_DETAILS where JOBNO=@JOBNO       
delete from CERTIFICATE_DETAILS where JOBNO=@JOBNO       
delete from CONTAINER_DETAILS where JOBNO=@JOBNO       
delete from IGM_DETAILS where JOBNO=@JOBNO       
delete from INVOICE_DETAILS where JOBNO=@JOBNO       
delete from ITEM_PRODUCT_DETAILS where JOBNO=@JOBNO       
delete from LICENSE_DETAILS where JOBNO=@JOBNO       
delete from MULTIPLE_INVOICE where MULTIPLE_JOBNO=@JOBNO       
      
delete from RE_IMPORT_DETAILS where JOBNO=@JOBNO       
delete from SUPPLIER_DETAILS where JOBNO=@JOBNO       
delete from SVB_DETAILS where JOBNO=@JOBNO       
delete from BE_ENTRY where BE_JOBNO=@JOBNO       
      
delete from GENERAL_DETAILS where JOBNO=@JOBNO  

delete FROM BE_ITEM_SW_INFO_TYPE where JOBNO=@JOBNO 
delete FROM BE_ITEM_SW_CONST where JOBNO=@JOBNO 
delete FROM BE_ITEM_SW_PROD where JOBNO=@JOBNO 
delete FROM BE_ITEM_SW_CONTROL where JOBNO=@JOBNO 
delete FROM IMP_SINGLE_WINDOW_STMT where JOBNO=@JOBNO 
delete FROM BE_ITEM_SW_SUP_DOC where JOBNO=@JOBNO 
     
 select @Mstatus=1      
end   

else if(@name='Select_JobNo_Exbond')      
 begin   
   select BE_ID,

	BE_INBOND_NO,
	Convert(varchar(11),BE_INBOND_DATE, 103)BE_INBOND_DATE,
	BE_WAREHOUSE_CUSTOMS,
	BE_WAREHOUSE_CUSTOMS_CODE
	,BE_NO
	,BE_JOBNO
	,Convert(varchar(11),BE_DATE, 103)BE_DATE from BE_ENTRY where BE_JOBNO like @JOBNO +'%' AND BE_TYPE='Warehouse'
 end
 
 else if(@name='Select_BeNo_Exbond')      
 begin   
   select BE_ID,

	BE_INBOND_NO,
	Convert(varchar(11),BE_INBOND_DATE, 103)BE_INBOND_DATE,
	BE_WAREHOUSE_CUSTOMS,
	BE_WAREHOUSE_CUSTOMS_CODE
	,BE_NO
	,BE_JOBNO
	,Convert(varchar(11),BE_DATE, 103)BE_DATE from BE_ENTRY where  BE_NO like @JOBID +'%'  AND BE_TYPE='Warehouse'
 end
 
 else if(@name='Select_JobNo_Beno_Exbond')      
 begin   
   select BE_ID,

