ALTER PROCEDURE [dbo].[SP_EXPORT_DRAWBACK_DETAILS]
	-- Add the parameters for the stored procedure here
	--@ANNEX_ID	varchar(35),
		@JOBNO   VARCHAR(40),
		@INVOICE_SLNO bigint,
		@ITEM_SLNO bigint,
		@SCHEME_CODE varchar(50),
		@RITC_NO varchar(8),
		@ITEM_DESCRIPTION varchar(300),
	@Working_Period varchar(30),
	@name 	varchar(300),

	@Mstatus  int output,
	@ErrorMsg nvarchar(max) output
AS
