ALTER PROCEDURE [dbo].[SP_EXPORT_JOBWISE_EXCEL_UPLOAD_SELECT]
	-- Add the parameters for the stored procedure here
	
	       --@JOBNO bigint, 
           --@INVOICE_SLNO bigint,    
           --@ITEM_SLNO bigint,
           --@RE_IMPORT_SLNO bigint,
	@IEC_NO varchar(50),
	@BRANCH_SLNO varchar(19),
	@Working_Period varchar(30),
	@name 	varchar(300),
	
	@Mstatus  int output,
	@ErrorMsg nvarchar(max) output
AS
begin try
	begin transaction
		set @ErrorMsg=''
		--declare @jobid as bigint


   IF(@name='Select_IEC_details')
   begin
		  select * from IMP_EXP_MASTER where IMP_EXP_IECNO=@IEC_NO and IMP_EXP_BRSLNO=@BRANCH_SLNO
		  set @Mstatus=1
   end
   
   if(@name='Gen_MAX_ID')
   begin
      select (isnull(max(isnull(JOBID,0)),0)+1 )MAXID from EXPORT_GENERAL_DETAILS
      set @Mstatus=1
   end
   if(@name='ANNEX_PKGS_ID')
   begin
      select (isnull(max(isnull(ANNEX_SEA_PACK_ID,0)),0)+1 )MAXID from EXPORT_ANNEXURE_C_SEA_PACKAGE
      set @Mstatus=1
   end
   if(@name='CONTAINER_MAX_ID')
   begin
      select (isnull(max(isnull(ANNEX_SEA_CON_ID,0)),0)+1 )MAXID from EXPORT_ANNEXURE_C_SEA_CONTAINER
      set @Mstatus=1
   end
   
      if(@name='INVOICE_MAX_ID')
