      select (isnull(max(isnull(INVOICE_ID,0)),0)+1 )MAXID from EXPORT_INVOICE_DETAILS
      set @Mstatus=1
   end
   
     if(@name='ITEM_MAX_ID')
   begin
      select (isnull(max(isnull(ITEM_ID,0)),0)+1 )MAXID from EXPORT_ITEM_DETAILS
      set @Mstatus=1
   end
   
     if(@name='AR4_MAX_ID')
   begin
      select (isnull(max(isnull(AR4_ID,0)),0)+1 )MAXID from EXPORT_AR4_TBL
      set @Mstatus=1
   end
   
        if(@name='DRAWBACK_MAX_ID')
   begin
      select (isnull(max(isnull(DRAWBACK_ID,0)),0)+1 )MAXID from EXPORT_DRAWBACK_DETAILS
      set @Mstatus=1
   end
   
   if(@name='LICENSE_MAX_ID')
   begin
      select (isnull(max(isnull(LICENSE_ID,0)),0)+1 )MAXID from EXPORT_LICENSE_DETAILS
      set @Mstatus=1
   end
   
   if(@name='LICENSE_IMP_EXP_MAX_ID')
   begin
      select (isnull(max(isnull(LICENSE_IMP_EXP_ID,0)),0)+1 )MAXID from EXPORT_LICENSE_IMP_EXP_DETAILS
      set @Mstatus=1
   end
   
      if(@name='EXP_SUPPORTING_DOCS_ID')
   begin
      select (isnull(max(isnull(SW_ID,0)),0)+1 )MAXID from EXP_SW_SUP_DOC
      set @Mstatus=1
   end
     
      if(@name='EXP_ANNEXURE_C1_ID')
   begin
      select (isnull(max(isnull(ANNEX_ID,0)),0)+1 )MAXID from ANNEXURE_C1_DETAILS
      set @Mstatus=1
   end
    
   if(@name ='EXPORT_Excel_Aval')
begin
        if(@Working_Period <>'')
        begin
			 select JOBNO from EXPORT_GENERAL_DETAILS where  JOBNO=@IEC_NO and BRANCHCODE=@Working_Period
        end
        else
        begin
             select JOBNO from EXPORT_GENERAL_DETAILS where  JOBNO=@IEC_NO 
        end
end

   if(@name ='Get_JOBID')
begin
        if(@Working_Period <>'')
        begin
			 select JOBID from EXPORT_GENERAL_DETAILS where  JOBNO=@IEC_NO and BRANCHCODE=@Working_Period
        end
        else
        begin
             select JOBID from EXPORT_GENERAL_DETAILS where  JOBNO=@IEC_NO 
        end
end

   IF(@name='Check_Avail_IEC_details')
   begin
	   if exists(select null from IMP_EXP_MASTER  where IMP_EXP_IECNO=@IEC_NO and IMP_EXP_BRSLNO=@BRANCH_SLNO)
	   begin
		  select * from IMP_EXP_MASTER where IMP_EXP_IECNO=@IEC_NO and IMP_EXP_BRSLNO=@BRANCH_SLNO
		  set @Mstatus=1
	   end
	   else
	   begin
	   
		   set @Mstatus=2
	   end
   end

   IF(@name='Check_Avail_CONSIGNEE_details')
   begin
	   if exists(select null from CONSIGNEE_MASTER  where REPLACE(CONSIGNEE_NAME,' ','')=REPLACE(@IEC_NO,' ','') and CONSIGNEE_BRANCHSLNO=@BRANCH_SLNO)
	   begin
	    select * from CONSIGNEE_MASTER where  REPLACE(CONSIGNEE_NAME,' ','')=REPLACE(@IEC_NO,' ','')
		  set @Mstatus=1
	   end
	   else
	   begin
		   set @Mstatus=2
	   end
   end
   
      IF(@name='Check_Avail_BUYER_details')
   begin
	   if exists(select null from BUYER_MASTER  where REPLACE(BUYER_NAME,' ','')=REPLACE(@IEC_NO,' ','') )
	   begin
	    select * from BUYER_MASTER where  REPLACE(BUYER_NAME,' ','')=REPLACE(@IEC_NO,' ','')
		  set @Mstatus=1
	   end
	   else
	   begin
		   set @Mstatus=2
	   end
   end
   
         IF(@name='Check_Avail_SUPPLIER_details')
   begin
	   if exists(select null from SUP_MASTER  where REPLACE(SUP_NAME,' ','')=REPLACE(@IEC_NO,' ','') )
	   begin
	    select * from SUP_MASTER where  REPLACE(SUP_NAME,' ','')=REPLACE(@IEC_NO,' ','')
		  set @Mstatus=1
	   end
	   else
	   begin
		   set @Mstatus=2
	   end
   end


else if(@name='Delete_Excel')
	begin	
	 if(@Working_Period <>'')
        begin
                
			delete from EXPORT_LICENSE_DETAILS where JOB_NO=@IEC_NO and BRANCH_CODE=@Working_Period
			delete from EXPORT_LICENSE_IMP_EXP_DETAILS where JOB_NO=@IEC_NO and BRANCH_CODE=@Working_Period
			delete from EXPORT_JOBBING where JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period

			delete from EXPORT_CESS_DETAILS where JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period

			delete from EXPORT_QUOTA_DETAILS where JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period

			delete from EXPORT_DRAWBACK_DETAILS where JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period
			delete from ANNEXURE_C1_DETAILS where ANNEX_JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period

			delete from EXPORT_AR4_TBL where AR4_JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period

			delete from EXPORT_ITEM_DETAILS where JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period
			delete from EXPORT_SB_ENTRY where SB_JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period
			delete from EXPORT_INVOICE_DETAILS where JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period

			delete from EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period
			delete from EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period
			delete from EXPORT_ANNEXURE_C_SEA_CONTAINER where ANNEX_SEA_CON_JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period
			delete from EXPORT_ANNEXURE_C_SEA_PACKAGE where ANNEX_SEA_PACK_JOBNO=@IEC_NO and BRANCH_CODE=@Working_Period
			delete from EXPORT_GENERAL_DETAILS where JOBNO=@IEC_NO and BRANCHCODE=@Working_Period
	select @Mstatus=1
         
		 select @Mstatus=1
		 end
		 else
		 begin
		       delete from EXPORT_LICENSE_DETAILS where JOB_NO=@IEC_NO
			delete from EXPORT_LICENSE_IMP_EXP_DETAILS where JOB_NO=@IEC_NO
			delete from EXPORT_JOBBING where JOBNO=@IEC_NO

			delete from EXPORT_CESS_DETAILS where JOBNO=@IEC_NO

			delete from EXPORT_QUOTA_DETAILS where JOBNO=@IEC_NO

			delete from EXPORT_DRAWBACK_DETAILS where JOBNO=@IEC_NO
			delete from ANNEXURE_C1_DETAILS where ANNEX_JOBNO=@IEC_NO

			delete from EXPORT_AR4_TBL where AR4_JOBNO=@IEC_NO

			delete from EXPORT_ITEM_DETAILS where JOBNO=@IEC_NO
			delete from EXPORT_SB_ENTRY where SB_JOBNO=@IEC_NO
			delete from EXPORT_INVOICE_DETAILS where JOBNO=@IEC_NO

			delete from EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO=@IEC_NO
			delete from EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO=@IEC_NO
			delete from EXPORT_ANNEXURE_C_SEA_CONTAINER where ANNEX_SEA_CON_JOBNO=@IEC_NO
			delete from EXPORT_ANNEXURE_C_SEA_PACKAGE where ANNEX_SEA_PACK_JOBNO=@IEC_NO
			delete from EXPORT_GENERAL_DETAILS where JOBNO=@IEC_NO 
			 
			select @Mstatus=1
		 end
end



commit
end try
begin catch
rollback transaction
	set @ErrorMsg=error_message()
	set @MStatus=0
end catch
/****** Object:  StoredProcedure [dbo].[WAREHOUSE_EXBOND_DETAILS_SELECT]    Script Date: 10/12/2018 15:54:55 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

ALTER PROCEDURE [dbo].[WAREHOUSE_EXBOND_DETAILS_SELECT]
	@JOBNO	varchar(35),
	@Working_Period varchar(30),
	@name 	varchar(300),
	@Mstatus  int output,
	@ErrorMsg nvarchar(max) output
AS
begin try
	begin transaction
		set @ErrorMsg=''
/*
declare @JOBNO	varchar(35),
	@Working_Period varchar(30),
	@name 	varchar(300),
	@Mstatus  int ,
	@ErrorMsg nvarchar(max)

	set @JOBNO=377
	set @Working_Period=''
	set @name='select_Details'
	*/


		declare @jobid as bigint, @product_value bigint
        declare @remain_qty as varchar(17)

if(@Working_Period<>'')
begin

if(@name='select_Warehouse_JobNo')
	begin
	select JOBNO,JOBNO_PS from GENERAL_DETAILS where BE_TYPE='Warehouse' and BRANCHCODE=@Working_Period order by JOBNO desc
end

else if(@name='select_Details')
	begin
	
	
select item1.ITEM_ID,item1.INVOICE_SLNO,item1.ITEM_SLNO,item1.ITEM_QTY
--isnull(sum(CONVERT(NUMERIC,item2.ITEM_QTY)),0) AS 'USED QTY',
--,isnull(convert (decimal(12,6), item1.ITEM_QTY ),0)-isnull(sum(CONVERT(decimal(12,6),item2.ITEM_QTY)),0) AS 'REMAINING_QTY'
,Convert(NUMERIC(25,6),CASE  WHEN ISNULL(item1.ITEM_QTY ,'') =''  THEN   '0' else ISNULL(item1.ITEM_QTY ,'0') end)-isnull(sum(CONVERT(decimal(12,6),item2.ITEM_QTY)),0) AS 'REMAINING_QTY'
,item1.ITEM_QTY_CODE,item1.ITEM_DESCRIPTION
   from ITEM_PRODUCT_DETAILS item1 LEFT join ITEM_PRODUCT_DETAILS item2 ON item1.JOBNO =item2.WAREHOUSE_JOBNO
AND item1.INVOICE_SLNO=item2.WAREHOUSE_INVOICE_SLNO AND item1.ITEM_SLNO =item2.WAREHOUSE_ITEM_SLNO 
and item1.BRANCH_CODE=item2.BRANCH_CODE
WHERE item1.JOBNO =@JOBNO and item1.BRANCH_CODE=@Working_Period
GROUP BY item1.ITEM_ID,item1.INVOICE_SLNO,item1.ITEM_SLNO,item1.WAREHOUSE_JOBNO,item1.WAREHOUSE_INVOICE_SLNO,item1.WAREHOUSE_ITEM_SLNO,item1.ITEM_DESCRIPTION,item1.ITEM_QTY,item1.ITEM_QTY_CODE
order by item1.INVOICE_SLNO ,item1.ITEM_SLNO asc

select BE_NO ,BE_JOBNO from BE_ENTRY where BE_JOBNO=@JOBNO and BRANCH_CODE=@Working_Period and BE_TYPE='Warehouse'

  set @MStatus=1
end

else if(@name='Select_JobNo_Beno')      
 begin   
   select BE_JOBNO,BE_NO from BE_ENTRY where BRANCH_CODE=@Working_Period  and BE_TYPE='Warehouse'
 end  
  else if(@name='Select_JobNo_Tr_mode')      
 begin   
	    select distinct TRANSPORT_MODE  from GENERAL_DETAILS where BE_TYPE='Warehouse' and JOBNO=@JOBNO and BRANCHCODE=@Working_Period 
 end 
    
 else if(@name='WH_select_Details')      
 begin   
 
	    select item1.ITEM_ID,item1.INVOICE_SLNO,item1.ITEM_SLNO,item1.ITEM_QTY
		--,isnull(convert (decimal(12,6), item1.ITEM_QTY ),0)-isnull(sum(CONVERT(decimal(12,6),item2.ITEM_QTY)),0) AS 'REMAINING_QTY'
		,Convert(NUMERIC(25,6),CASE  WHEN ISNULL(item1.ITEM_QTY ,'') =''  THEN   '0' else ISNULL(item1.ITEM_QTY ,'0') end)-isnull(sum(CONVERT(decimal(12,6),item2.ITEM_QTY)),0) AS 'REMAINING_QTY'
		,item1.ITEM_QTY_CODE,item1.ITEM_DESCRIPTION
		from ITEM_PRODUCT_DETAILS item1 LEFT join ITEM_PRODUCT_DETAILS item2 ON item1.JOBNO =item2.WAREHOUSE_JOBNO
		AND item1.INVOICE_SLNO=item2.WAREHOUSE_INVOICE_SLNO AND item1.ITEM_SLNO =item2.WAREHOUSE_ITEM_SLNO 
		and item1.BRANCH_CODE=item2.BRANCH_CODE
		WHERE 
		--item1.JOBNO =@JOBNO 
		item1.JOBNO = (select top 1 BE_JOBNO from  BE_ENTRY where BE_NO =@JOBNO and BRANCH_CODE=@Working_Period)
		
		and item1.BRANCH_CODE=@Working_Period
		GROUP BY item1.ITEM_ID,item1.INVOICE_SLNO,item1.ITEM_SLNO,item1.WAREHOUSE_JOBNO,item1.WAREHOUSE_INVOICE_SLNO
		,item1.WAREHOUSE_ITEM_SLNO,item1.ITEM_DESCRIPTION,item1.ITEM_QTY,item1.ITEM_QTY_CODE
		order by item1.INVOICE_SLNO asc
		
		select JOBNO from GENERAL_DETAILS where BE_TYPE='Warehouse' 
		and JOBNO =(select BE_JOBNO from BE_ENTRY where BRANCH_CODE=@Working_Period  and BE_TYPE='Warehouse' and BE_NO=@JOBNO)
		and BRANCHCODE=@Working_Period 
		
		
	   set @MStatus=1
 end    
  

end
else
begin

if(@name='select_Warehouse_JobNo')
	begin
	select JOBNO ,JOBNO_PS from GENERAL_DETAILS where BE_TYPE='Warehouse' order by JOBNO desc
end

else if(@name='select_Details')
	begin
	
select item1.ITEM_ID,item1.INVOICE_SLNO,item1.ITEM_SLNO,item1.ITEM_QTY
--isnull(sum(CONVERT(NUMERIC,item2.ITEM_QTY)),0) AS 'USED QTY',
--,isnull(convert (decimal(12,6), item1.ITEM_QTY ),0)-isnull(sum(CONVERT(decimal(12,6),item2.ITEM_QTY)),0) AS 'REMAINING_QTY'
,Convert(NUMERIC(25,6),CASE  WHEN ISNULL(item1.ITEM_QTY ,'') =''  THEN   '0' else ISNULL(item1.ITEM_QTY ,'0') end)-isnull(sum(CONVERT(decimal(12,6),item2.ITEM_QTY)),0) AS 'REMAINING_QTY'
,item1.ITEM_QTY_CODE,item1.ITEM_DESCRIPTION
   from ITEM_PRODUCT_DETAILS item1 LEFT join ITEM_PRODUCT_DETAILS item2 ON item1.JOBNO =item2.WAREHOUSE_JOBNO
AND item1.INVOICE_SLNO=item2.WAREHOUSE_INVOICE_SLNO AND item1.ITEM_SLNO =item2.WAREHOUSE_ITEM_SLNO
WHERE item1.JOBNO =@JOBNO
GROUP BY item1.ITEM_ID,item1.INVOICE_SLNO,item1.ITEM_SLNO,item1.WAREHOUSE_JOBNO,item1.WAREHOUSE_INVOICE_SLNO,item1.WAREHOUSE_ITEM_SLNO
,item1.ITEM_DESCRIPTION,item1.ITEM_QTY,item1.ITEM_QTY_CODE
order by item1.INVOICE_SLNO ,item1.ITEM_SLNO asc
select BE_NO ,BE_JOBNO from BE_ENTRY where BE_JOBNO=@JOBNO and BE_TYPE='Warehouse'
set @MStatus=1

end

else if(@name='Select_JobNo_Beno')      
 begin   
   select BE_JOBNO,BE_NO from BE_ENTRY where BE_TYPE='Warehouse'
 end    
 else if(@name='Select_JobNo_Tr_mode')      
 begin   
	             select distinct TRANSPORT_MODE  from GENERAL_DETAILS where BE_TYPE='Warehouse' and JOBNO=@JOBNO 
 end    
 else if(@name='WH_select_Details')      
 begin   
		select item1.ITEM_ID,item1.INVOICE_SLNO,item1.ITEM_SLNO,item1.ITEM_QTY
		--,isnull(convert (decimal(12,6), item1.ITEM_QTY ),0)-isnull(sum(CONVERT(decimal(12,6),item2.ITEM_QTY)),0) AS 'REMAINING_QTY'
		,Convert(NUMERIC(25,6),CASE  WHEN ISNULL(item1.ITEM_QTY ,'') =''  THEN   '0' else ISNULL(item1.ITEM_QTY ,'0') end)-isnull(sum(CONVERT(decimal(12,6),item2.ITEM_QTY)),0) AS 'REMAINING_QTY'
		,item1.ITEM_QTY_CODE,item1.ITEM_DESCRIPTION
		
	    from ITEM_PRODUCT_DETAILS item1 LEFT join ITEM_PRODUCT_DETAILS item2 ON item1.JOBNO =item2.WAREHOUSE_JOBNO
		AND item1.INVOICE_SLNO=item2.WAREHOUSE_INVOICE_SLNO AND item1.ITEM_SLNO =item2.WAREHOUSE_ITEM_SLNO
		WHERE 
		item1.JOBNO = (select top 1 BE_JOBNO from  BE_ENTRY where BE_NO =@JOBNO )
		GROUP BY item1.ITEM_ID,item1.INVOICE_SLNO,item1.ITEM_SLNO,item1.WAREHOUSE_JOBNO,item1.WAREHOUSE_INVOICE_SLNO,item1.WAREHOUSE_ITEM_SLNO,item1.ITEM_DESCRIPTION,item1.ITEM_QTY,item1.ITEM_QTY_CODE
		order by item1.INVOICE_SLNO asc
		
		select JOBNO from GENERAL_DETAILS where BE_TYPE='Warehouse' 
		and JOBNO =(select BE_JOBNO from BE_ENTRY where BRANCH_CODE=@Working_Period  and BE_TYPE='Warehouse' and BE_NO=@JOBNO)
		and BRANCHCODE=@Working_Period 
		
	   set @MStatus=1
 end
end




commit
end try
begin catch
rollback transaction
	set @ErrorMsg=error_message()
	set @MStatus=0
end catch




/****** Object:  StoredProcedure [dbo].[SP_AnnexureC_Report]    Script Date: 10/12/2018 15:55:35 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
ALTER PROCEDURE [dbo].[SP_AnnexureC_Report]  
(
	  @JOBNO varchar(35),  
	  @Working_Period varchar(30),  
	  @Branch varchar(50),  
	  @name  varchar(300),  
	   
	  @Mstatus  int output,  
	  @ErrorMsg nvarchar(max) output  
   )
AS  
begin try  
 begin transaction  
  set @ErrorMsg=''  
   declare @cnt int  
   declare @temp_FR_INS table(Id int identity(1,1) ,FREIGHT_CHARGES varchar(50),INSURANCE_CHARGES varchar(50))
   declare @temp_FR_INS_CUR table(Id int identity(1,1),FREIGHT_CURRENCY varchar(50),INSURANCE_CURRENCY varchar(50))
   declare @temp_FR_INS_F table(Id int identity(1,1),FREIGHT_CHARGES varchar(50),INSURANCE_CHARGES varchar(50),FREIGHT_CURRENCY varchar(50),INSURANCE_CURRENCY varchar(50))
  
if(@name='Get_Annex_C_Sea')  
begin  
    if(@Branch='' or @Branch=null )
     begin
			select * from EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO=@JOBNO
			select ANNEX_SEA_CON_CONTAINERNO,ANNEX_SEA_CON_SIZE,ANNEX_SEA_CON_TYPE,ANNEX_SEA_CON_EXCISE_SEALNO,CONVERT(varchar,ANNEX_SEA_CON_SEAL_DATE,103)ANNEX_SEA_CON_SEAL_DATE from EXPORT_ANNEXURE_C_SEA_CONTAINER where ANNEX_SEA_CON_JOBNO=@JOBNO 
			select AR4_NO,convert(varchar,AR4_DATE,103)AR4_DATE,AR4_COMMISSION_RATE,AR4_DIVISION,AR4_RANGE from EXPORT_AR4_TBL where AR4_JOBNO=@JOBNO 
			select SB_NO,convert(varchar,SB_DATE,103)SB_DATE from EXPORT_SB_ENTRY where SB_JOBNO=@JOBNO 
		
		     insert into @temp_FR_INS
			 select 
			 isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(FREIGHT_CHARGES,'') =''  THEN   '0' else ISNULL(FREIGHT_CHARGES,'0') end)),0) as FREIGHT_CHARGES
			 ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(INSURANCE_CHARGES,'') =''  THEN   '0' else ISNULL(INSURANCE_CHARGES,'0') end)),0)as INSURANCE_CHARGES
			 from EXPORT_INVOICE_DETAILS 
			 where JOBNO=@jobno 
     
             select @cnt= COUNT(FREIGHT_CURRENCY)from EXPORT_INVOICE_DETAILS where JOBNO=@jobno 
     
			 insert into @temp_FR_INS_CUR
			 select top 1  case when 1= @cnt then FREIGHT_CURRENCY else '' end as FREIGHT_CURRENCY  ,case when 1= @cnt then INSURANCE_CURRENCY else '' end as INSURANCE_CURRENCY
			 from EXPORT_INVOICE_DETAILS where JOBNO=@jobno 
		     
			 select  case when FREIGHT_CHARGES='0.00' then ' ' else FREIGHT_CHARGES end  as MIS_FREIGHT_CHARGES,FREIGHT_CURRENCY as MIS_FREIGHT_CURRENCY,case when	INSURANCE_CHARGES='0.00' then ' ' else INSURANCE_CHARGES end as MIS_INSURANCE_CHARGES,INSURANCE_CURRENCY as MIS_INSURANCE_CURRENCY from  @temp_FR_INS a  inner join  @temp_FR_INS_CUR b on a.Id=b.Id
			 
			 select ANNEX_SEA_PACK_PACKAGETYPE, ANNEX_SEA_PACK_FROM,ANNEX_SEA_PACK_TO from EXPORT_ANNEXURE_C_SEA_PACKAGE  where ANNEX_SEA_PACK_JOBNO=@JOBNO 
			   
     end
     

   if(@Branch<>'')
   begin
   
			select * from EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO=@JOBNO and BRANCH_CODE=@Branch  
			select ANNEX_SEA_CON_CONTAINERNO,ANNEX_SEA_CON_SIZE,ANNEX_SEA_CON_TYPE,ANNEX_SEA_CON_EXCISE_SEALNO,CONVERT(varchar,ANNEX_SEA_CON_SEAL_DATE,103)ANNEX_SEA_CON_SEAL_DATE from EXPORT_ANNEXURE_C_SEA_CONTAINER where ANNEX_SEA_CON_JOBNO=@JOBNO and BRANCH_CODE=@Branch  
			select AR4_NO,convert(varchar,AR4_DATE,103)AR4_DATE,AR4_COMMISSION_RATE,AR4_DIVISION,AR4_RANGE from EXPORT_AR4_TBL where AR4_JOBNO=@JOBNO and BRANCH_CODE=@Branch  
			select SB_NO,convert(varchar,SB_DATE,103)SB_DATE from EXPORT_SB_ENTRY where SB_JOBNO=@JOBNO and BRANCH_CODE=@Branch  
			 
			 
	 		insert into @temp_FR_INS
			select 
			isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(FREIGHT_CHARGES,'') =''  THEN   '0' else ISNULL(FREIGHT_CHARGES,'0') end)),0) as FREIGHT_CHARGES
			,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(INSURANCE_CHARGES,'') =''  THEN   '0' else ISNULL(INSURANCE_CHARGES,'0') end)),0)as INSURANCE_CHARGES
			from EXPORT_INVOICE_DETAILS 
			where JOBNO=@jobno and BRANCH_CODE=@Branch
		     
			select @cnt= COUNT(FREIGHT_CURRENCY)from EXPORT_INVOICE_DETAILS where JOBNO=@jobno and BRANCH_CODE=@Branch
		     
			insert into @temp_FR_INS_CUR
			select top 1  case when 1= @cnt then FREIGHT_CURRENCY else '' end as FREIGHT_CURRENCY  ,case when 1= @cnt then INSURANCE_CURRENCY else '' end as INSURANCE_CURRENCY
			from EXPORT_INVOICE_DETAILS where JOBNO=@jobno and BRANCH_CODE=@Branch
		     
			select  case when FREIGHT_CHARGES='0.00' then ' ' else FREIGHT_CHARGES end  as MIS_FREIGHT_CHARGES,FREIGHT_CURRENCY as MIS_FREIGHT_CURRENCY,	case when	INSURANCE_CHARGES='0.00' then ' ' else INSURANCE_CHARGES end as MIS_INSURANCE_CHARGES,INSURANCE_CURRENCY as MIS_INSURANCE_CURRENCY from  @temp_FR_INS a  inner join  @temp_FR_INS_CUR b on a.Id=b.Id
		    select ANNEX_SEA_PACK_PACKAGETYPE, ANNEX_SEA_PACK_FROM,ANNEX_SEA_PACK_TO from EXPORT_ANNEXURE_C_SEA_PACKAGE  where ANNEX_SEA_PACK_JOBNO=@JOBNO and BRANCH_CODE=@Branch	   
	   
   end



end  
----------------------------------------------------ram------start---------------------------------------- 
else if(@name='Get_Annex_C_Air')
begin
 
 if(@Branch='' or @Branch=null )
     begin
     select SB_No+' '+convert(varchar,SB_Date ,103)as [No_Date] from EXPORT_SB_ENTRY where SB_JOBNO=@jobno    
    
     insert into @temp_FR_INS
     select 
      isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(FREIGHT_CHARGES,'') =''  THEN   '0' else ISNULL(FREIGHT_CHARGES,'0') end)),0) as FREIGHT_CHARGES
     ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(INSURANCE_CHARGES,'') =''  THEN   '0' else ISNULL(INSURANCE_CHARGES,'0') end)),0)as INSURANCE_CHARGES
     from EXPORT_INVOICE_DETAILS 
     where JOBNO=@jobno 
     
     select @cnt= COUNT(FREIGHT_CURRENCY)from EXPORT_INVOICE_DETAILS where JOBNO=@jobno 
     
   insert into @temp_FR_INS_CUR
     select top 1  case when 1= @cnt then FREIGHT_CURRENCY else '' end as FREIGHT_CURRENCY  ,case when 1= @cnt then INSURANCE_CURRENCY else '' end as INSURANCE_CURRENCY
     from EXPORT_INVOICE_DETAILS where JOBNO=@jobno 

insert into @temp_FR_INS_F
select  FREIGHT_CHARGES,INSURANCE_CHARGES,FREIGHT_CURRENCY,INSURANCE_CURRENCY 
from @temp_FR_INS a inner join  @temp_FR_INS_CUR b on a.Id =b.id


select
		 ANNEX_AIR_MAWB_NO  as [Master_Airway_Bill_No]    
		,'' as [Airway_Bill_No]     
		, ANNEX_AIR_TOTAL_PACKAGES_MAWB as [Total_No_of_Pkgs_against_the_MAWB]  
		,'' as [No_of_Pkgs_against_the_airway_bill]  
		,ANNEX_AIR_HAWB_NO  as [House_Airway_Bill_No]    
		,ANNEX_AIR_TOTAL_PACKAGES   as [Total_No_of_Packages]    
		,ANNEX_AIR_UNIT_CODE   as [Type_of_pkgs]    
		,''  as [Number_marked_on_the_pkgs]    
		,ANNEX_AIR_GROSS_WEIGHT+' '+ANNEX_AIR_GR_UNIT_CODE as [Gross_weight_in_Kgs]    
		,ANNEX_AIR_NET_WEIGHT+' '+ANNEX_AIR_GR_UNIT_CODE  as [Net_Weight_in_Kgs]
		 
		/*,ANNEX_AIR_FREIGHT_AMT  as [Freight_Charges] 
		,'' as Fr_Currency  
		,ANNEX_AIR_INSURANCE_AMT  as [Insurance_Charges]    
		,'' as Ins_Currency  */
		,(select case when FREIGHT_CHARGES='0.00' then ' ' else FREIGHT_CHARGES  end  From @temp_FR_INS_F)as [Freight_Charges] 
		,(select FREIGHT_CURRENCY From @temp_FR_INS_F)as Fr_Currency
		,(select  case when INSURANCE_CHARGES ='0.00' then ' 'else INSURANCE_CHARGES end  From @temp_FR_INS_F)as [Insurance_Charges] 
		,(select INSURANCE_CURRENCY From @temp_FR_INS_F)as Ins_Currency
		,ANNEX_AIR_SEALNO  as [Seal_No_and_name_of_the_sealing_agency]  
		--,convert(varchar,ANNEX_AIR_ROTATION_DATE ,103)as [Date] 
		,(case when convert(varchar(10),ANNEX_AIR_ROTATION_DATE,103)='01/01/1900' then null else convert(varchar(10),ANNEX_AIR_ROTATION_DATE,103) end ) as [Date]
     from EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO=@jobno  
    
	 select     
		  AR4_NO     
		 ,convert(varchar,AR4_DATE ,103)as [AR4_DATE]    
		 ,AR4_COMMISSION_RATE    
		 ,AR4_DIVISION    
		 ,AR4_RANGE    
	 From EXPORT_AR4_TBL  where AR4_JOBNO =@jobno
	 
	  select ANNEX_SEA_PACK_PACKAGETYPE, ANNEX_SEA_PACK_FROM,ANNEX_SEA_PACK_TO from EXPORT_ANNEXURE_C_SEA_PACKAGE  where ANNEX_SEA_PACK_JOBNO=@JOBNO 
	      
     end
     
      if(@Branch<>'')
      begin
      select SB_No+' '+convert(varchar,SB_Date ,103)as [No_Date] from EXPORT_SB_ENTRY where SB_JOBNO=@jobno and BRANCH_CODE=@Branch    
     
      
      
		
  /* select
		 ANNEX_AIR_MAWB_NO  as [Master_Airway_Bill_No]    
		,'' as [Airway_Bill_No]     
		, ANNEX_AIR_TOTAL_PACKAGES_MAWB as [Total_No_of_Pkgs_against_the_MAWB]  
		,'' as [No_of_Pkgs_against_the_airway_bill]  
		,ANNEX_AIR_HAWB_NO  as [House_Airway_Bill_No]    
		,ANNEX_AIR_TOTAL_PACKAGES   as [Total_No_of_Packages]    
		,ANNEX_AIR_UNIT_CODE   as [Type_of_pkgs]    
		,ANNEX_AIR_MARKS_NOS  as [Number_marked_on_the_pkgs]    
		,ANNEX_AIR_GROSS_WEIGHT+' '+ANNEX_AIR_GR_UNIT_CODE as [Gross_weight_in_Kgs]    
		,ANNEX_AIR_NET_WEIGHT +' '+ANNEX_AIR_UNIT_CODE as [Net_Weight_in_Kgs] 
		,ANNEX_AIR_FREIGHT_AMT  as [Freight_Charges]    
		,'' as Fr_Currency    
		,ANNEX_AIR_INSURANCE_AMT  as [Insurance_Charges]    
		,'' as Ins_Currency    
		,ANNEX_AIR_SEALNO  as [Seal_No_and_name_of_the_sealing_agency]  
		,convert(varchar,ANNEX_AIR_ROTATION_DATE ,103)as [Date] 
		      
     from EXPORT_ANNEXURE_C_AIR  where ANNEX_AIR_JOBNO=@jobno  and BRANCH_CODE=@Branch */
     
   
     
     insert into @temp_FR_INS
     select 
      isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(FREIGHT_CHARGES,'') =''  THEN   '0' else ISNULL(FREIGHT_CHARGES,'0') end)),0) as FREIGHT_CHARGES
     ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(INSURANCE_CHARGES,'') =''  THEN   '0' else ISNULL(INSURANCE_CHARGES,'0') end)),0)as INSURANCE_CHARGES
     from EXPORT_INVOICE_DETAILS 
     where JOBNO=@jobno and BRANCH_CODE=@Branch
     
     select @cnt= COUNT(FREIGHT_CURRENCY)from EXPORT_INVOICE_DETAILS where JOBNO=@jobno and BRANCH_CODE=@Branch
     
   insert into @temp_FR_INS_CUR
     select top 1  case when 1= @cnt then FREIGHT_CURRENCY else '' end as FREIGHT_CURRENCY  ,case when 1= @cnt then INSURANCE_CURRENCY else '' end as INSURANCE_CURRENCY
     from EXPORT_INVOICE_DETAILS where JOBNO=@jobno and BRANCH_CODE=@Branch

insert into @temp_FR_INS_F
select  FREIGHT_CHARGES,INSURANCE_CHARGES,FREIGHT_CURRENCY,INSURANCE_CURRENCY 
from @temp_FR_INS a inner join  @temp_FR_INS_CUR b on a.Id =b.id


select
		 ANNEX_AIR_MAWB_NO  as [Master_Airway_Bill_No]    
		,'' as [Airway_Bill_No]     
		, ANNEX_AIR_TOTAL_PACKAGES_MAWB as [Total_No_of_Pkgs_against_the_MAWB]  
		,'' as [No_of_Pkgs_against_the_airway_bill]  
		,ANNEX_AIR_HAWB_NO  as [House_Airway_Bill_No]    
		,ANNEX_AIR_TOTAL_PACKAGES   as [Total_No_of_Packages]    
		,ANNEX_AIR_UNIT_CODE   as [Type_of_pkgs]    
		,''  as [Number_marked_on_the_pkgs]    
		,ANNEX_AIR_GROSS_WEIGHT+' '+ANNEX_AIR_GR_UNIT_CODE as [Gross_weight_in_Kgs]    
		,ANNEX_AIR_NET_WEIGHT+' '+ANNEX_AIR_GR_UNIT_CODE  as [Net_Weight_in_Kgs]
		 
		/*,ANNEX_AIR_FREIGHT_AMT  as [Freight_Charges] 
		,'' as Fr_Currency  
		,ANNEX_AIR_INSURANCE_AMT  as [Insurance_Charges]    
		,'' as Ins_Currency  */
		,(select case when FREIGHT_CHARGES='0.00' then ' ' else FREIGHT_CHARGES  end From @temp_FR_INS_F)as [Freight_Charges] 
		,(select FREIGHT_CURRENCY From @temp_FR_INS_F)as Fr_Currency
		,(select case when INSURANCE_CHARGES ='0.00' then ' 'else INSURANCE_CHARGES end From @temp_FR_INS_F)as [Insurance_Charges] 
		,(select INSURANCE_CURRENCY From @temp_FR_INS_F)as Ins_Currency
		,ANNEX_AIR_SEALNO  as [Seal_No_and_name_of_the_sealing_agency]  
		--,convert(varchar,ANNEX_AIR_ROTATION_DATE ,103)as [Date] 
		,(case when convert(varchar(10),ANNEX_AIR_ROTATION_DATE,103)='01/01/1900' then null else convert(varchar(10),ANNEX_AIR_ROTATION_DATE,103) end ) as [Date]
     from EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO=@jobno  and BRANCH_CODE=@Branch 
    
    
	 select     
		  AR4_NO     
		 ,convert(varchar,AR4_DATE ,103)as [AR4_DATE]    
		 ,AR4_COMMISSION_RATE    
		 ,AR4_DIVISION    
		 ,AR4_RANGE    
	 From EXPORT_AR4_TBL  where AR4_JOBNO =@jobno  and BRANCH_CODE=@Branch 
	 
	  select ANNEX_SEA_PACK_PACKAGETYPE, ANNEX_SEA_PACK_FROM,ANNEX_SEA_PACK_TO from EXPORT_ANNEXURE_C_SEA_PACKAGE  where ANNEX_SEA_PACK_JOBNO=@JOBNO and BRANCH_CODE=@Branch
	  
     end

end
  
  
  
commit  
end try  
begin catch  
rollback transaction  
 set @ErrorMsg=error_message()  
 set @MStatus=0  
end catch

/****** Object:  StoredProcedure [dbo].[EXP_ITEM_SINGLEWINDOW_SELECT]    Script Date: 10/12/2018 15:56:48 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


ALTER procedure [dbo].[EXP_ITEM_SINGLEWINDOW_SELECT]  
  (    
      @JOBNO varchar(10),@INVOICE_SLNO varchar(Max),@ITEM_SLNO varchar(max),@DELETE_ID varchar(10)
	 ,@BRANCH_COMMON varchar(30),@Mflag varchar(100),@ErrorMsg nvarchar(max) output ,@Mstatus  int output 
   )    
 AS    
begin try    
 begin transaction    
  set @ErrorMsg=''   
  
  declare @cnt int ,@Stmt_cnt int
  declare @i int ,@a int ,@b int ,@c int
  set @i=1
  
  declare @temp_Inv table (Id int identity(1,1), Inv_Slno int, Item_Slno int)
----------------------------------------------------------------------------------------------------------------------------------------------------
if(@Mflag='Bulk_select')    
begin
             ;with summary as( select item from dbo.fnSplit(@INVOICE_SLNO, ','))
             insert into @temp_Inv  SELECT PARSENAME(REPLACE(item,'-','.'),2) as Inv_slno, PARSENAME(REPLACE(item,'-','.'),1) as Item_slno  from summary
             select @cnt =COUNT(*) from @temp_Inv
             
             if( @BRANCH_COMMON<>'')
             begin
				 if(@cnt >0)
				 begin
						select SW_INFO_TYPE_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,SLNO,INFO_TYPE,INFO_QUALIFIER ,INFO_CODE,INFO_TEXT,INFO_MSR,INFO_UQC ,DEPARTMENT from EXP_SW_INFO_TYPE 
						where  JOBNO=@JOBNO AND INVOICE_SLNO=(select Inv_Slno From @temp_Inv where id=1 )
						AND ITEM_SLNO =(select Item_Slno From @temp_Inv where id=1 ) AND BRANCH_CODE=@BRANCH_COMMON order by SW_INFO_TYPE_ID asc	
				 end
				 else
				 begin
					   select SW_INFO_TYPE_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,SLNO,INFO_TYPE,INFO_QUALIFIER ,INFO_CODE,INFO_TEXT,INFO_MSR,INFO_UQC ,DEPARTMENT from EXP_SW_INFO_TYPE 
					   where  1=0
				 end
             end
             else
             begin
              if(@cnt >0)
				 begin
						select SW_INFO_TYPE_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,SLNO,INFO_TYPE,INFO_QUALIFIER ,INFO_CODE,INFO_TEXT,INFO_MSR,INFO_UQC ,DEPARTMENT from EXP_SW_INFO_TYPE 
						where  JOBNO=@JOBNO AND INVOICE_SLNO=(select Inv_Slno From @temp_Inv where id=1 ) AND ITEM_SLNO =(select Item_Slno From @temp_Inv where id=1 ) 
				 end
				 else
				 begin
					   select SW_INFO_TYPE_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,INFO_TYPE,INFO_QUALIFIER ,INFO_CODE,INFO_TEXT,INFO_MSR,INFO_UQC ,DEPARTMENT from EXP_SW_INFO_TYPE 
					   where  1=0
				 end
             
             end
end   
else if(@Mflag='Normal_Select')    
begin
		if( @BRANCH_COMMON<>'')
        begin
				  select SW_INFO_TYPE_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,SLNO,INFO_TYPE,INFO_QUALIFIER ,INFO_CODE,INFO_TEXT,INFO_MSR,INFO_UQC ,DEPARTMENT from EXP_SW_INFO_TYPE 
				  where  JOBNO=@JOBNO AND INVOICE_SLNO=@INVOICE_SLNO AND ITEM_SLNO =@ITEM_SLNO AND BRANCH_CODE=@BRANCH_COMMON order by SW_INFO_TYPE_ID asc	
        end else   begin
                  select SW_INFO_TYPE_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,SLNO,INFO_TYPE,INFO_QUALIFIER ,INFO_CODE,INFO_TEXT,INFO_MSR,INFO_UQC ,DEPARTMENT from EXP_SW_INFO_TYPE 
				  where  JOBNO=@JOBNO AND INVOICE_SLNO=@INVOICE_SLNO
				  AND ITEM_SLNO =@ITEM_SLNO order by SW_INFO_TYPE_ID asc
        end
end   
else if(@Mflag='CONSTITUENT_Select')    
begin
		if( @BRANCH_COMMON<>'')
        begin
				select SW_CONST_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,CONSTITUENT_SRNO,CONSTITUENT_ELEMENT_NAME,CONSTITUENT_ELEMENT_CODE,CONSTITUENT_PERCENTAGE
			    ,CONSTITUENT_YIELD_PERCENTAGE,ACTIVE_INGREDIENT from EXP_SW_CONST
			    where  JOBNO=@JOBNO AND INVOICE_SLNO=@INVOICE_SLNO AND ITEM_SLNO =@ITEM_SLNO AND BRANCH_CODE=@BRANCH_COMMON order by SW_CONST_ID asc 
        end else   begin
                 select SW_CONST_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,CONSTITUENT_SRNO,CONSTITUENT_ELEMENT_NAME,CONSTITUENT_ELEMENT_CODE,CONSTITUENT_PERCENTAGE
			    ,CONSTITUENT_YIELD_PERCENTAGE,ACTIVE_INGREDIENT from EXP_SW_CONST
			    where  JOBNO=@JOBNO AND INVOICE_SLNO=@INVOICE_SLNO AND ITEM_SLNO =@ITEM_SLNO order by SW_CONST_ID asc 
        end
end
else if(@Mflag='CONSTITUENT_BULK_Select')    
begin
        ;with summary as( select item from dbo.fnSplit(@INVOICE_SLNO, ','))
             insert into @temp_Inv  SELECT PARSENAME(REPLACE(item,'-','.'),2) as Inv_slno, PARSENAME(REPLACE(item,'-','.'),1) as Item_slno  from summary
             select @cnt =COUNT(*) from @temp_Inv
             
             if( @BRANCH_COMMON<>'')
             begin
				 if(@cnt >0)
				 begin
					select SW_CONST_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,CONSTITUENT_SRNO,CONSTITUENT_ELEMENT_NAME,CONSTITUENT_ELEMENT_CODE,CONSTITUENT_PERCENTAGE
			         ,CONSTITUENT_YIELD_PERCENTAGE,ACTIVE_INGREDIENT from EXP_SW_CONST
						where  JOBNO=@JOBNO AND INVOICE_SLNO=(select Inv_Slno From @temp_Inv where id=1 )
						AND ITEM_SLNO =(select Item_Slno From @temp_Inv where id=1 ) AND BRANCH_CODE=@BRANCH_COMMON order by SW_CONST_ID asc	
				 end
				 else
				 begin
					  	select SW_CONST_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,CONSTITUENT_SRNO,CONSTITUENT_ELEMENT_NAME,CONSTITUENT_ELEMENT_CODE,CONSTITUENT_PERCENTAGE
			         ,CONSTITUENT_YIELD_PERCENTAGE,ACTIVE_INGREDIENT from EXP_SW_CONST where  1=0
				 end
             end
             else
             begin
