 if(@Mflag='IMP_SingleWindow_STMT_Select')    
 begin
         ----------------------------------------------------------------
         declare @temp_Stmt table (Id int identity(1,1),Item_slno int )  
		 declare @temp_1 table (Id int identity(1,1),D_Count int)
		 declare @aa int ,@a_cnt int ,@aaa int ,@bbb int,@ccc int
         ----------------------------------------------------------------
       
       insert into @temp_Stmt select item from dbo.fnSplit(@ITEM_SLNO, ',')
       select @Stmt_cnt =count(*) from @temp_Stmt
       
       --select * from @temp_Stmt
       
       if(@BRANCH_COMMON <>'')
        begin
              if(@Stmt_cnt=0)
              begin
                    select  SW_ID  ,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO ,SLNO ,STMT_TYPE,STMT_CODE ,STMT_TEXT from EXP_SW_STMT  where 1=0
              end
              else if(@Stmt_cnt=1)
              begin
                    select  SW_ID  ,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO,SLNO  ,STMT_TYPE,STMT_CODE ,STMT_TEXT from EXP_SW_STMT  where JOBNO=@JOBNO AND INVOICE_SLNO=@INVOICE_SLNO 
			        AND ITEM_SLNO =(select Item_slno from @temp_Stmt where id=1) AND BRANCH_CODE=@BRANCH_COMMON  order by SW_ID desc 
              end
              else
              begin
                    
                      set @aa=1
                      
                      while(@aa <= @Stmt_cnt)
                      begin
                              insert into @temp_1 select COUNT(SW_ID) from EXP_SW_STMT where JOBNO=@JOBNO and INVOICE_SLNO=@INVOICE_SLNO 
                              AND ITEM_SLNO = (select Item_slno from @temp_Stmt where Id=@aa)  and BRANCH_CODE=@BRANCH_COMMON
                             
                            set @aa=@aa +1; 
                      end
                     select @aaa= COUNT(distinct(D_Count)) from @temp_1 
                     
                     
                     ;with summary as
					  (
						   select distinct STMT_TYPE,STMT_CODE ,STMT_TEXT from EXP_SW_STMT 
						   where  JOBNO=@JOBNO AND INVOICE_SLNO=@INVOICE_SLNO and ITEM_SLNO in (select Item_slno from @temp_Stmt)
						   AND BRANCH_CODE=@BRANCH_COMMON 
					  )
					 select @bbb=count(*) from summary
					 select @ccc=D_Count from @temp_1 where id=1
                      
                     if(@aaa=1  and  @bbb=@ccc )
					 begin
							select SW_ID  ,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO  ,STMT_TYPE,STMT_CODE ,STMT_TEXT from EXP_SW_STMT 
							where  JOBNO=@JOBNO AND INVOICE_SLNO=@INVOICE_SLNO and ITEM_SLNO = (select top 1 Item_slno from @temp_Stmt) AND BRANCH_CODE=@BRANCH_COMMON 
							order by SW_ID asc	
					end
					   else
							begin
									  select SW_ID  ,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO  ,STMT_TYPE,STMT_CODE ,STMT_TEXT from EXP_SW_STMT where 1=0
							end 
                         
                      
              end
         
         select @Mstatus=1  
        end
        else
        begin
			  if(@Stmt_cnt=0)
              begin
                    select  SW_ID  ,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO ,SLNO ,STMT_TYPE,STMT_CODE ,STMT_TEXT from EXP_SW_STMT  where 1=0
              end
              else if(@Stmt_cnt=1)
              begin
                    select  SW_ID  ,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO ,SLNO ,STMT_TYPE,STMT_CODE ,STMT_TEXT from EXP_SW_STMT  where JOBNO=@JOBNO AND INVOICE_SLNO=@INVOICE_SLNO 
			        AND ITEM_SLNO =(select Item_slno from @temp_Stmt where id=1)order by SW_ID desc 
              end
              else
              begin
                      set @aa=1
                      
                      while(@aa <= @Stmt_cnt)
                      begin
                              insert into @temp_1 select COUNT(SW_ID) from EXP_SW_STMT where JOBNO=@JOBNO and INVOICE_SLNO=@INVOICE_SLNO 
                              AND ITEM_SLNO = (select Item_slno from @temp_Stmt where Id=@aa)  
                             
                            set @aa=@aa +1; 
                      end
                     select @aaa= COUNT(distinct(D_Count)) from @temp_1 
                     
                     
                     ;with summary as
					  (
						   select distinct STMT_TYPE,STMT_CODE ,STMT_TEXT from EXP_SW_STMT 
						   where  JOBNO=@JOBNO AND INVOICE_SLNO=@INVOICE_SLNO and ITEM_SLNO in (select Item_slno from @temp_Stmt)
					  )
					 select @bbb=count(*) from summary
					 select @ccc=D_Count from @temp_1 where id=1
                      
                     if(@aaa=1  and  @bbb=@ccc )
					 begin
							select SW_ID  ,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO,SLNO  ,STMT_TYPE,STMT_CODE ,STMT_TEXT from EXP_SW_STMT 
							where  JOBNO=@JOBNO AND INVOICE_SLNO=@INVOICE_SLNO and ITEM_SLNO = (select top 1 Item_slno from @temp_Stmt) 
							order by SW_ID asc	
					end
					   else
							begin
									  select SW_ID  ,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO ,SLNO ,STMT_TYPE,STMT_CODE ,STMT_TEXT from EXP_SW_STMT where 1=0
							end 
                         
                      
              end
			 
				select @Mstatus=1  
        end
  end
