				 else
				 begin
					   select SW_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,SLNO,UNIQUE_DOC_NUMBER,DOC_TYPE_CODE,DOC_ISSUING_PARTY_CODE,DOC_ISSUING_PARTY_NAME_ADD1,DOC_ISSUING_PARTY_NAME_ADD2
			,DOC_ISSUING_PARTY_CITY,DOC_ISSUING_PARTY_PIN,DOC_REF_NUMBER,PLACE_OF_ISSUE,DOC_ISSUE_DATE,DOC_EXPIRY_DATE,BENEFICIARY_PARTY_CODE,BENEFICIARY_PARTY_ADDRESS1
			,BENEFICIARY_PARTY_ADDRESS2,BENEFICIARY_PARTY_CITY,BENEFICIARY_PARTY_PIN,FILE_TYPE ,DOC_ISSUING_PARTY_NAME,BENEFICIARY_PARTY_NAME from EXP_SW_SUP_DOC where  1=0
				 end
             
             end
end

----------------------------------------------------------------------------------------------------------------------------------------------------      

commit    
end try    
begin catch    
rollback transaction    
 set @ErrorMsg=error_message()    
 --set @MStatus=0    
end catch





