ALTER Procedure [dbo].[IMP_GEN_EXCEL_UPLOAD]

(
  @Jobno varchar(30) ,@Supplier_name varchar(200) ,@Imp_Name varchar(200) 
 ,@All_XL_details VARCHAR(MAX) ,@SAPTA_Rate VARCHAR(MAX) ,@LEVY VARCHAR(MAX) ,@Ex_Rate VARCHAR(MAX),@Scheme_Code VARCHAR(MAX)
 ,@Branch_Code varchar(50) ,@Branch_Common  varchar(50) ,@WORKING_PERIOD varchar(50) ,@COMPANYID varchar(20) ,@User_Id varchar(50) ,@flag varchar(150)
 ,@ErrorMsg nvarchar(max) output  )  
AS          
begin try                  
begin transaction                  
set @ErrorMsg=''
------------------------------------------------------------------------------------------------------------------------------------------------------------
if(@flag='Inv_No_Chk')
begin
         if(@Branch_Common <>'')   
         begin
                select INVOICE_SLNO from INVOICE_DETAILS where JOBNO=@Jobno and BRANCH_CODE=@Branch_Common
         end
         else
         begin
                select INVOICE_SLNO from INVOICE_DETAILS where JOBNO=@Jobno 
         end
