		 ,IGST_LEVY_EXCEPTION_CC_NOTN ,IGST_LEVY_EXCEMPTION_CC_SLNO ,LEVY_EXCEMPTION_NOTN_TYPE ,LEVY_EXCEPTION_CC_NOTN_TYPE ,SOCIAL_WELFARE_NOTN ,SOCIAL_WELFARE_NOTN_SLNO
		 
		  FROM OPENXML (@xmlHandle_XL_All_det, '/NewDataSet/SampleDataTable',1)WITH (
		  INVOICE_SLNO nvarchar(15) '@INVOICE_SLNO',INVOICE_NO nvarchar(17) '@INVOICE_NO',INVOICE_DATE nvarchar(20) '@INVOICE_DATE',TERMS nvarchar(3) '@TERMS' ,INVOICE_CURRENCY nvarchar(3) '@INVOICE_CURRENCY'
		 ,ITEM_SLNO int '@ITEM_SLNO' ,ITEM_QTY nvarchar(23) '@ITEM_QTY' ,ITEM_QTY_CODE nvarchar(3) '@ITEM_QTY_CODE' ,ITEM_UNIT_PRICE nvarchar(23) '@ITEM_UNIT_PRICE'
		 ,ITEM_DESCRIPTION nvarchar(500) '@ITEM_DESCRIPTION' ,MIS_FREIGHT_CHARGES nvarchar(19) '@MIS_FREIGHT_CHARGES' ,MIS_FREIGHT_CURRENCY nvarchar(3) '@MIS_FREIGHT_CURRENCY'
		 ,MIS_INSURANCE_CHARGES nvarchar(19) '@MIS_INSURANCE_CHARGES' ,MIS_INSURANCE_CURRENCY nvarchar(3) '@MIS_INSURANCE_CURRENCY' ,MIS_CHARGES nvarchar(19) '@MIS_CHARGES'
		 ,MIS_CURRENCY nvarchar(3) '@MIS_CURRENCY' ,CTH_NO nvarchar(50) '@CTH_NO' ,RITC_NO nvarchar(50) '@RITC_NO' ,BCD_NOTN nvarchar(8) '@BCD_NOTN' ,BCD_NOTN_SLNO nvarchar(10) '@BCD_NOTN_SLNO'
		 ,CETH_NO nvarchar(30) '@CETH_NO' ,CVD_NOTN nvarchar(8) '@CVD_NOTN'
		 ,CVD_NOTN_SLNO nvarchar(10) '@CVD_NOTN_SLNO' ,GENEARL_DESCRIPTION nvarchar(60) '@GENEARL_DESCRIPTION' ,MANUFACTURER nvarchar(50) '@MANUFACTURER' ,BRAND nvarchar(20) '@BRAND'
		 ,MODEL nvarchar(20) '@MODEL' ,END_USE_OF_ITEM nvarchar(20) '@END_USE_OF_ITEM' ,COUNTRY_OF_ORIGIN nvarchar(50) '@COUNTRY_OF_ORIGIN' ,SCHEME_CODE nvarchar(50) '@SCHEME_CODE'
		 ,SCHEME_NOTN nvarchar(8) '@SCHEME_NOTN' ,SCHEME_NOTN_SLNO nvarchar(10) '@SCHEME_NOTN_SLNO' ,LICENSE_NO nvarchar(50) '@LICENSE_NO' ,LICENSE_DATE nvarchar(20) '@LICENSE_DATE'
		 
		 ,EXCEMPTION nvarchar(1) '@EXCEMPTION' ,LICENSE_SLNO nvarchar(8) '@LICENSE_SLNO' ,PORT_OF_LICENSE nvarchar(6) '@PORT_OF_LICENSE' 
		 ,SAPTA_NOTN nvarchar(8) '@SAPTA_NOTN' ,SAPTA_NOTN_SLNO nvarchar(10) '@SAPTA_NOTN_SLNO' 
		 
		 ,AGGREGATE_NOTN nvarchar(8) '@AGGREGATE_NOTN'
		 ,AGGREGATE_NOTN_SLNO nvarchar(10) '@AGGREGATE_NOTN_SLNO' ,SAFEGUARD_NOTN nvarchar(8) '@SAFEGUARD_NOTN' ,SAFEGUARD_NOTN_SLNO nvarchar(10) '@SAFEGUARD_NOTN_SLNO'
		 ,IGST_LEVY_NOTN nvarchar(8) '@IGST_LEVY_NOTN'  ,IGST_LEVY_SLNO nvarchar(8) '@IGST_LEVY_SLNO' ,IGST_LEVY_EXCEMPTION_NOTN nvarchar(8) '@IGST_LEVY_EXCEMPTION_NOTN'
		 ,IGST_LEVY_EXCEMPTION_SLNO nvarchar(10) '@IGST_LEVY_EXCEMPTION_SLNO' ,IGST_LEVY_COMPENSATION_CESS_NOTN nvarchar(8) '@IGST_LEVY_COMPENSATION_CESS_NOTN'
		 ,IGST_LEVY_COMPENSATION_CESS_SLNO nvarchar(10) '@IGST_LEVY_COMPENSATION_CESS_SLNO' ,IGST_LEVY_EXCEPTION_CC_NOTN nvarchar(8) '@IGST_LEVY_EXCEPTION_CC_NOTN'
		 
		 ,IGST_LEVY_EXCEMPTION_CC_SLNO nvarchar(8) '@IGST_LEVY_EXCEMPTION_CC_SLNO' ,LEVY_EXCEMPTION_NOTN_TYPE nvarchar(1) '@LEVY_EXCEMPTION_NOTN_TYPE'
		 ,LEVY_EXCEPTION_CC_NOTN_TYPE nvarchar(1) '@LEVY_EXCEPTION_CC_NOTN_TYPE' ,SOCIAL_WELFARE_NOTN nvarchar(8) '@SOCIAL_WELFARE_NOTN' ,SOCIAL_WELFARE_NOTN_SLNO nvarchar(10) '@SOCIAL_WELFARE_NOTN_SLNO'
		)
		EXEC sp_xml_removedocument @xmlHandle_XL_All_det
	end
end

