begin
         delete from INVOICE_DETAILS where JOBNO=@Jobno and BRANCH_CODE=@Branch_Common
         delete from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno and BRANCH_CODE=@Branch_Common
         delete from LICENSE_DETAILS where JOBNO=@Jobno and BRANCH_CODE=@Branch_Common
         delete from IMP_SINGLE_WINDOW_STMT where JOBNO=@Jobno and BRANCH_CODE=@Branch_Common
end
else
begin
         delete from INVOICE_DETAILS  where JOBNO=@Jobno 
         delete from ITEM_PRODUCT_DETAILS  where JOBNO=@Jobno
         delete from LICENSE_DETAILS  where JOBNO=@Jobno
         delete from IMP_SINGLE_WINDOW_STMT where JOBNO=@Jobno 
end
