declare @Inv_id int,@Item_id int ,@LICENSE_ID int

select @Inv_id=(isnull(max(isnull(INVOICE_ID,0)),0)+1 ) from INVOICE_DETAILS  

 declare @SVB_RELATION  varchar(20),@SVB_REF_NO varchar(30),@SVB_REF_DATE varchar(30),@SVB_CUSTOM_HOUSE varchar(30),@SVB_LOADING_ON varchar(40),@SVB_ASSESABLE_RATE varchar(30)
 ,@SVB_DUTY_RATE varchar(30),@SVB_ASSESABLE_STATUS varchar(30),@SVB_DUTY_STATUS varchar(30),@BOND_NO varchar(30),@BOND_LOCATION varchar(30),@BOND_TYPE varchar(30)
 
 SELECT @SVB_RELATION =SVB_RELATION ,@SVB_REF_NO=SVB_REF_NO ,@SVB_REF_DATE=convert(varchar(15),SVB_REF_DATE,101) ,@SVB_CUSTOM_HOUSE=SVB_CUSTOM_HOUSE
 ,@SVB_LOADING_ON=SVB_LOADING_ON ,@SVB_ASSESABLE_RATE=SVB_ASSESABLE_RATE ,@SVB_DUTY_RATE=SVB_DUTY_RATE ,@SVB_ASSESABLE_STATUS=SVB_ASSESABLE_STATUS
 ,@SVB_DUTY_STATUS=SVB_DUTY_STATUS ,@BOND_NO=BOND_NO ,@BOND_LOCATION=BOND_LOCATION ,@BOND_TYPE=BOND_TYPE     FROM SVB_RELATION_MASTER 
 where IMP_NAME = @Imp_Name and  SUPPLIER_NAME = @Supplier_name and SVB_RELATION='Y'
 

;With Summary as( select  distinct 
 INVOICE_SLNO,INVOICE_NO 
 ,INVOICE_DATE
 ,TERMS,INVOICE_CURRENCY,MIS_CHARGES,MIS_CURRENCY,MIS_FREIGHT_CHARGES,MIS_INSURANCE_CHARGES
,MIS_FREIGHT_CURRENCY
,MIS_INSURANCE_CURRENCY
,@Supplier_name as Supplier_name
from @temp_Gen )
 
 
 insert into INVOICE_DETAILS(
INVOICE_ID ,JOBNO,INVOICE_SLNO,INVOICE_NO ,INVOICE_DATE,TERMS,INVOICE_CURRENCY,INVOICE_EXRATE
,SUPPLIER_NAME,SUPPLIER_ADDRESS,SUPPLIER_ADDRESS1,SUPPLIER_ADDRESS2,SUPPLIER_COUNTRY_NAME,SUPPLIER_COUNTRY_CODE
,SUPPLIER_COUNTRY_PINCODE

,MIS_CHARGES
,MIS_CURRENCY 
,MIS_EXRATE
	
,MIS_AGENCY_RATE
,MIS_AGENCY_CURRENCY
,MIS_AGENCY_EXRATE
,MIS_DISCOUNT_RATE
,MIS_DISCOUNT_CURRENCY 
,MIS_DISCOUNT_EXRATE
,MIS_HIGHSEASALE_RATE
,MIS_HIGHSEASALE_CURRENCY
,MIS_HIGHSEASALE_EXRATE
,MIS_SINGLE_OR_MULITIPLE
	
,SVB_RELATION
,SVB_REF_NO
,SVB_REF_DATE
,SVB_CUSTOM_HOUSE
,SVB_LOADING_ON
,SVB_ASSESABLE_RATE
,SVB_DUTY_RATE
,SVB_ASSESABLE_STATUS
,SVB_DUTY_STATUS
	 
,MIS_FREIGHT_CHARGES
,MIS_INSURANCE_CHARGES
	
,MIS_FREIGHT_CURRENCY 
,MIS_INSURANCE_CURRENCY 

,MIS_FREIGHT_EXRATE
,MIS_INSURANCE_EXRATE 
    
,MIS_FREIGHT_RATE
,MIS_INSURANCE_RATE
    
,OTHER_PURCHASE_ORDER_DATE
,OTHER_CONTRACT_DATE
,OTHER_LOC_DATE
,OTHER_NATURE_OF_TRANSACTION
,OTHER_TERMS_OF_PAYMENT
,OTHER_VALUATION_METHOD
,SHIP_DATE
,NON_STD_EFFECT_DT_IMP
,NON_STD_CERTIFICATE_DATE
,USER_ID
,DATE_TIME
,BRANCH_CODE 
,WORKING_PERIOD
)
 select 
	  ROW_NUMBER() OVER (ORDER BY @JOBNO)+ @Inv_id as INVOICE_ID
	  ,@Jobno
	, INVOICE_SLNO
	,INVOICE_NO 
	,INVOICE_DATE
	,TERMS
	,INVOICE_CURRENCY
	,b.EX_Rate
	,c.SUP_NAME
	,SUP_ADD1
	,SUP_ADD2
	,SUP_ADD3
	,SUP_COUNTRY_NAME
	,SUP_COUNTRY_CODE
	,SUP_PIN_CODE
	
	,MIS_CHARGES
	,MIS_CURRENCY 
	,case when ISNULL(MIS_CURRENCY,'')='' then  b.EX_Rate  else e.EX_Rate  end MIS_EXRATE
	
	,'0.00' as MIS_AGENCY_RATE
	,INVOICE_CURRENCY as MIS_AGENCY_CURRENCY
	,b.EX_Rate as MIS_AGENCY_EXRATE
	,'0.00' as MIS_DISCOUNT_RATE
	,INVOICE_CURRENCY as MIS_DISCOUNT_CURRENCY 
	,b.EX_Rate as MIS_DISCOUNT_EXRATE
	
	,'0.00' as MIS_HIGHSEASALE_RATE
	,'INR' as MIS_HIGHSEASALE_CURRENCY
	,'1.00' as MIS_HIGHSEASALE_EXRATE
	,'S' as MIS_SINGLE_OR_MULITIPLE
	
	,@SVB_RELATION
	,@SVB_REF_NO
	,isnull(@SVB_REF_DATE,'01/01/1900')
	,@SVB_CUSTOM_HOUSE
	,@SVB_LOADING_ON
	,@SVB_ASSESABLE_RATE
	,@SVB_DUTY_RATE
    ,@SVB_ASSESABLE_STATUS
    ,@SVB_DUTY_STATUS
	 
	,MIS_FREIGHT_CHARGES
	,MIS_INSURANCE_CHARGES
	
    ,MIS_FREIGHT_CURRENCY 
    ,MIS_INSURANCE_CURRENCY 
    
    /*,f.EX_Rate MIS_FREIGHT_EXRATE
    ,g.EX_Rate MIS_INSURANCE_EXRATE
    ,'' as MIS_FREIGHT_RATE
    ,'' as MIS_INSURANCE_RATE*/
    
    /*,case when TERMS='CIF' or  TERMS='CF' then '' else cast(f.EX_Rate as varchar(20)) end MIS_FREIGHT_EXRATE
    ,case when TERMS='CIF' or TERMS='CI'  then '' else cast(g.EX_Rate as varchar(20)) end MIS_INSURANCE_EXRATE
    ,case when TERMS='CIF' or  TERMS='CF' then '0' else '' end MIS_FREIGHT_RATE
    ,case when TERMS='CIF' or TERMS='CI' then '0' else '' end MIS_INSURANCE_RATE*/
    
    ,'' MIS_FREIGHT_EXRATE
    ,'' MIS_INSURANCE_EXRATE
    ,'0' MIS_FREIGHT_RATE
    ,'0' MIS_INSURANCE_RATE
    
    ,'01/01/1900' as OTHER_PURCHASE_ORDER_DATE
    ,'01/01/1900' as OTHER_CONTRACT_DATE
    ,'01/01/1900' as OTHER_LOC_DATE
    
    ,'S  Sale' as  OTHER_NATURE_OF_TRANSACTION
    ,'OTH  Others' as OTHER_TERMS_OF_PAYMENT
    ,'Rule 4 - Transaction Value' as OTHER_VALUATION_METHOD
    ,'01/01/1900' as SHIP_DATE
    ,'01/01/1900' as NON_STD_EFFECT_DT_IMP
    ,'01/01/1900' as NON_STD_CERTIFICATE_DATE
    ,@User_Id as USER_ID
    ,GETDATE() as DATE_TIME
    ,@Branch_Code as BRANCH_CODE 
    ,@WORKING_PERIOD as WORKING_PERIOD
    
     
  from Summary a  left outer join @temp_Ex_Rate b
  on a.INVOICE_CURRENCY=b.Cur_Code 
  left outer join 
  ( select SUP_NAME,SUP_ADD1,SUP_ADD2,SUP_ADD3,SUP_COUNTRY_NAME,SUP_COUNTRY_CODE,SUP_PIN_CODE FROM SUP_MASTER where SUP_NAME=@Supplier_name  )
  c on a.Supplier_name= c.SUP_NAME
  left outer join @temp_Ex_Rate e on a.MIS_CURRENCY=e.Cur_Code
  order by cast(INVOICE_SLNO as int) asc
  
  --left outer join @temp_Ex_Rate f on a.MIS_FREIGHT_CURRENCY=f.Cur_Code
  --left outer join @temp_Ex_Rate g on a.MIS_INSURANCE_CURRENCY=g.Cur_Code

