select @Item_id=(isnull(max(isnull(ITEM_ID,0)),0)+1 ) from ITEM_PRODUCT_DETAILS  

insert into ITEM_PRODUCT_DETAILS( 
ITEM_ID,JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,ITEM_DESCRIPTION,ITEM_QTY,ITEM_QTY_CODE,ITEM_UNIT_PRICE,ITEM_UNIT_CODE
,ITEM_TOTAL_AMOUNT,ITEM_AMOUNT_CODE,CTH_NO,SCHEME_CODE ,SCHEME_NOTN ,SCHEME_NOTN_SLNO ,GENEARL_DESCRIPTION,MANUFACTURER,BRAND,MODEL
,END_USE_OF_ITEM,COUNTRY_OF_ORIGIN,PREVIOUS_BE_DATE,PRODUCT_RITC,PRODUCT_CTH  
,PRODUCT_BCD_NOTN,PRODUCT_BCD_SLNO

,PRODUCT_AGGREGATE_DUTY_NOTN 
,PRODUCT_AGGREGATE_DUTY_NOTN_SL 
,PRODUCT_AGGREGATE_DUTY_NOTN_RATE

,PRODUCT_SAFEGUARD_NOTN  
,PRODUCT_SAFEGUARD_SLNO
,PRODUCT_SAFEGUARD_RATE 

,PRODUCT_SAPTA_NOTN
,PRODUCT_SAPTA_SLNO
,PRODUCT_SAPTA_RATE
,PRODUCT_CETH
,PRODUCT_MRP_YN
,PRODUCT_MRP_ABT_RATE
,PRODUCT_CVD_NOTN
,PRODUCT_CVD_SLNO
,WAREHOUSE_JOBNO 
,WAREHOUSE_INVOICE_SLNO
,WAREHOUSE_ITEM_SLNO
,USER_ID
,DATE_TIME
,BRANCH_CODE
,WORKING_PERIOD
,RSP_APPLICABLE

,IGST_LEVY_NOTN
,IGST_LEVY_SLNO
,IGST_LEVY_RATE

,IGST_LEVY_EXCEPTION_NOTN
,IGST_LEVY_EXCEPTION_SLNO
,IGST_LEVY_EXCEPTION_RATE

,IGST_LEVY_COMPENSATION_CESS_NOTN
,IGST_LEVY_COMPENSATION_CESS_SLNO
,IGST_LEVY_COMPENSATION_CESS_RATE

,IGST_LEVY_EXCEPTION_CC_NOTN
,IGST_LEVY_EXCEPTION_CC_SLNO
,IGST_LEVY_EXCEPTION_CC_RATE

,LEVY_EXCEMPTION_NOTN_TYPE
,LEVY_EXCEPTION_CC_NOTN_TYPE 

,SOCIAL_WELFARE_NOTN
,SOCIAL_WELFARE_NOTN_SLNO
,SOCIAL_WELFARE_RATE

,Year
)
select 
 ROW_NUMBER() OVER (ORDER BY @JOBNO)+ @Item_id as ITEM_ID
,@Jobno as JOBNO
,INVOICE_SLNO
,INVOICE_NO
,ITEM_SLNO
,ITEM_DESCRIPTION
,ITEM_QTY
,ITEM_QTY_CODE
,ITEM_UNIT_PRICE
,INVOICE_CURRENCY as ITEM_UNIT_CODE --10
--,(ITEM_QTY * ITEM_UNIT_PRICE) as ITEM_TOTAL_AMOUNT
,(Convert(NUMERIC(25,6),CASE  WHEN ISNULL(ITEM_QTY,'') =''  THEN   '0' else ISNULL(ITEM_QTY,'0') end)*
Convert(NUMERIC(25,6),CASE  WHEN ISNULL(ITEM_UNIT_PRICE,'') =''  THEN   '0' else ISNULL(ITEM_UNIT_PRICE,'0') end)
)as ITEM_TOTAL_AMOUNT

,INVOICE_CURRENCY as ITEM_AMOUNT_CODE
,CTH_NO
,case when  isnull(b.SCHEME_CODE,'')='' then '00 - DUTIABLE' else b.SCHEME_CODE end SCHEME_CODE 
,case when  isnull(b.SCHEME_CODE,'')='' and  isnull(SCHEME_NOTN,'')=''   then '' else SCHEME_NOTN end SCHEME_NOTN 
,case when  isnull(b.SCHEME_CODE,'')='' and  isnull(SCHEME_NOTN,'')=''   then '' else SCHEME_NOTN_SLNO end SCHEME_NOTN_SLNO 
,GENEARL_DESCRIPTION
,MANUFACTURER
,BRAND
,MODEL

,END_USE_OF_ITEM
,COUNTRY_OF_ORIGIN
,'01/01/1900' as PREVIOUS_BE_DATE
,RITC_NO as PRODUCT_RITC
,CETH_NO as PRODUCT_CTH  
,BCD_NOTN as PRODUCT_BCD_NOTN
,BCD_NOTN_SLNO as PRODUCT_BCD_SLNO



,AGGREGATE_NOTN as PRODUCT_AGGREGATE_DUTY_NOTN 
,AGGREGATE_NOTN_SLNO as PRODUCT_AGGREGATE_DUTY_NOTN_SL 
,C.RATE as PRODUCT_AGGREGATE_DUTY_NOTN_RATE

,SAFEGUARD_NOTN as PRODUCT_SAFEGUARD_NOTN  
,SAFEGUARD_NOTN_SLNO as PRODUCT_SAFEGUARD_SLNO
,D.RATE as PRODUCT_SAFEGUARD_RATE 

,SAPTA_NOTN as PRODUCT_SAPTA_NOTN
,SAPTA_NOTN_SLNO as PRODUCT_SAPTA_SLNO
,E.RATE as PRODUCT_SAPTA_RATE

,CETH_NO as PRODUCT_CETH
,'N' PRODUCT_MRP_YN
,'' PRODUCT_MRP_ABT_RATE
,CVD_NOTN as PRODUCT_CVD_NOTN
,CVD_NOTN_SLNO as PRODUCT_CVD_SLNO
,'0' WAREHOUSE_JOBNO 
,'0' as WAREHOUSE_INVOICE_SLNO
,'0' as WAREHOUSE_ITEM_SLNO
,@User_Id as USER_ID
,GETDATE() as DATE_TIME
,@Branch_Code as BRANCH_CODE
,@WORKING_PERIOD as WORKING_PERIOD
,'N' as RSP_APPLICABLE
,IGST_LEVY_NOTN as IGST_LEVY_NOTN
,IGST_LEVY_SLNO as IGST_LEVY_SLNO
,F.RATE as IGST_LEVY_RATE
,IGST_LEVY_EXCEMPTION_NOTN as IGST_LEVY_EXCEPTION_NOTN
,IGST_LEVY_EXCEMPTION_SLNO as IGST_LEVY_EXCEPTION_SLNO
,G.RATE as IGST_LEVY_EXCEPTION_RATE

,IGST_LEVY_COMPENSATION_CESS_NOTN as IGST_LEVY_COMPENSATION_CESS_NOTN
,IGST_LEVY_COMPENSATION_CESS_SLNO as IGST_LEVY_COMPENSATION_CESS_SLNO
,H.RATE as IGST_LEVY_COMPENSATION_CESS_RATE

,IGST_LEVY_EXCEPTION_CC_NOTN as IGST_LEVY_EXCEPTION_CC_NOTN
,IGST_LEVY_EXCEMPTION_CC_SLNO as IGST_LEVY_EXCEPTION_CC_SLNO
,I.RATE as IGST_LEVY_EXCEPTION_CC_RATE

,LEVY_EXCEMPTION_NOTN_TYPE as LEVY_EXCEMPTION_NOTN_TYPE
,LEVY_EXCEPTION_CC_NOTN_TYPE as LEVY_EXCEPTION_CC_NOTN_TYPE 

,isnull(SOCIAL_WELFARE_NOTN,'')
,isnull(SOCIAL_WELFARE_NOTN_SLNO,'')
,''

,YEAR(getdate())

 from @temp_Gen a  left outer join  @temp_Scheme_Code b
on a.SCHEME_CODE=left(b.SCHEME_CODE,2) 
left outer join @temp_SAPTA_Rate C 
on a.AGGREGATE_NOTN=C.NOTN_No and a.AGGREGATE_NOTN_SLNO =C.NOTN_SLNo
left outer join @temp_SAPTA_Rate D 
on a.SAFEGUARD_NOTN=D.NOTN_No and a.SAFEGUARD_NOTN_SLNO =D.NOTN_SLNo
left outer join @temp_SAPTA_Rate E 
on a.SAPTA_NOTN=E.NOTN_No and a.SAPTA_NOTN_SLNO =E.NOTN_SLNo 

left outer join @temp_LEVY_NOTN F
on a.IGST_LEVY_NOTN= F.NOTN_No and a.IGST_LEVY_SLNO = F.NOTN_SLNo  and F.RATE='1E'
left outer join @temp_LEVY_NOTN G
on a.IGST_LEVY_EXCEMPTION_NOTN= G.NOTN_No and a.IGST_LEVY_EXCEMPTION_SLNO = G.NOTN_SLNo  and G.RATE='1L'

left outer join @temp_LEVY_NOTN H
on a.IGST_LEVY_COMPENSATION_CESS_NOTN= H.NOTN_No and a.IGST_LEVY_COMPENSATION_CESS_SLNO = H.NOTN_SLNo  and H.RATE='2E'
left outer join @temp_LEVY_NOTN I
on a.IGST_LEVY_EXCEPTION_CC_NOTN= I.NOTN_No and a.IGST_LEVY_EXCEMPTION_CC_SLNO = I.NOTN_SLNo  and I.RATE='2L'
