,@F_CURRENCY varchar(10)
,@I_CURRENCY varchar(10)
,@F_EXRATE  varchar(10)
,@I_EXRATE  varchar(10)
----------------------------------------------------------------------------------------------------------------------------------------------------------------


set @i=1

If(@Branch_Common <>'')
begin 
           insert into @temp_Inv_det 
           select INVOICE_SLNO, INVOICE_CURRENCY, TERMS, MIS_FREIGHT_CURRENCY ,MIS_FREIGHT_EXRATE ,MIS_FREIGHT_RATE ,MIS_FREIGHT_CHARGES ,MIS_INSURANCE_CURRENCY
		  ,MIS_INSURANCE_EXRATE,MIS_INSURANCE_RATE,MIS_INSURANCE_CHARGES from INVOICE_DETAILS where JOBNO=@Jobno and BRANCH_CODE=@Branch_Common 
          
          insert into @temp_Item_det
          select INVOICE_SLNO,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ITEM_TOTAL_AMOUNT,'') =''  THEN   '0' else ISNULL(ITEM_TOTAL_AMOUNT,'0') end)),0) from ITEM_PRODUCT_DETAILS 
          where JOBNO=@Jobno and BRANCH_CODE=@Branch_Common   group by INVOICE_SLNO
  
end
else
begin
            insert into @temp_Inv_det 
           select INVOICE_SLNO, INVOICE_CURRENCY, TERMS, MIS_FREIGHT_CURRENCY ,MIS_FREIGHT_EXRATE ,MIS_FREIGHT_RATE ,MIS_FREIGHT_CHARGES ,MIS_INSURANCE_CURRENCY
		  ,MIS_INSURANCE_EXRATE,MIS_INSURANCE_RATE,MIS_INSURANCE_CHARGES from INVOICE_DETAILS where JOBNO=@Jobno 
          
          insert into @temp_Item_det
          select INVOICE_SLNO,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ITEM_TOTAL_AMOUNT,'') =''  THEN   '0' else ISNULL(ITEM_TOTAL_AMOUNT,'0') end)),0) from ITEM_PRODUCT_DETAILS 
          where JOBNO=@Jobno   group by INVOICE_SLNO
  
end

select @cnt=COUNT(Id)  from @temp_Inv_det 
          
while (@i<=@cnt)
begin
                 select @Inv_Slno=INVOICE_SLNO,@TERMS=TERMS
                      ,@INVOICE_CURRENCY=INVOICE_CURRENCY
                      ,@MIS_FREIGHT_CURRENCY=MIS_FREIGHT_CURRENCY 
					 -- ,@MIS_FREIGHT_EXRATE=MIS_FREIGHT_EXRATE 
					  --,@MIS_FREIGHT_RATE=MIS_FREIGHT_RATE 
					  ,@MIS_FREIGHT_CHARGES=MIS_FREIGHT_CHARGES

					  ,@MIS_INSURANCE_CURRENCY =MIS_INSURANCE_CURRENCY
					  --,@MIS_INSURANCE_EXRATE=MIS_INSURANCE_EXRATE
					  --,@MIS_INSURANCE_RATE=MIS_INSURANCE_RATE
					  ,@MIS_INSURANCE_CHARGES=MIS_INSURANCE_CHARGES
                 
                 from @temp_Inv_det where Id=@i
                 select @Inv_Value=INV_VALUE from @temp_Item_det where INVOICE_SLNO=@Inv_Slno
                
                -----------------------------------------------------------------------------------
                if(@MIS_FREIGHT_CHARGES ='' or @MIS_INSURANCE_CHARGES='')
                begin
							 if(@TERMS='FOB')
							 begin
							         --------@MIS_FREIGHT_CHARGES  
									 if(@MIS_FREIGHT_CHARGES='')--Y
									 begin
									        set @MIS_FREIGHT_RATE ='20.0000'
									        select @MIS_FREIGHT_CHARGES =cast(Round(@Inv_Value*0.2,2)as decimal(18,2))
									        
									        if(@MIS_FREIGHT_CURRENCY<>'')
									        begin
													/*
									                ,@F_CURRENCY varchar(10)
													,@I_CURRENCY varchar(10)
													,@F_EXRATE  varchar(10)
													,@I_EXRATE  varchar(10)
													 */
									              select @F_CURRENCY=Cur_Code ,@F_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@MIS_FREIGHT_CURRENCY
									        end
									        else
									        begin
									              select @F_CURRENCY=Cur_Code ,@F_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@INVOICE_CURRENCY
									        end
									 end
									 else --N
									 begin
									        set @MIS_FREIGHT_CHARGES=@MIS_FREIGHT_CHARGES
									        set @MIS_FREIGHT_RATE =''
									        
									        if(@MIS_FREIGHT_CURRENCY<>'')
									        begin
									              select @F_CURRENCY=Cur_Code ,@F_EXRATE =EX_Rate from @temp_Ex_Rate   where Cur_Code=@MIS_FREIGHT_CURRENCY
									        end
									        else
									        begin
									              select @F_CURRENCY=Cur_Code ,@F_EXRATE =EX_Rate from @temp_Ex_Rate  where Cur_Code=@INVOICE_CURRENCY
									        end
									 end 
									 
							   --------@MIS_INSURANCE_CHARGES
							   
							      if(@MIS_INSURANCE_CHARGES='')--Y
									 begin
									        set @MIS_INSURANCE_RATE ='1.1250'
									        select @MIS_INSURANCE_CHARGES =cast(Round(@Inv_Value*0.01125,2)as decimal(18,2))
									        
									        if(@MIS_INSURANCE_CURRENCY<>'')
									        begin
													/*
									                ,@F_CURRENCY varchar(10)
													,@I_CURRENCY varchar(10)
													,@F_EXRATE  varchar(10)
													,@I_EXRATE  varchar(10)
													 */
									              select @I_CURRENCY=Cur_Code ,@I_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@MIS_INSURANCE_CURRENCY
									        end
									        else
									        begin
									              select @I_CURRENCY=Cur_Code ,@I_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@INVOICE_CURRENCY
									        end
									 end
									 else --N
									 begin
									        set @MIS_INSURANCE_CHARGES=@MIS_INSURANCE_CHARGES
									        set @MIS_INSURANCE_RATE =''
									        
									        if(@MIS_INSURANCE_CURRENCY<>'')
									        begin
									              select @I_CURRENCY=Cur_Code ,@I_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@MIS_INSURANCE_CURRENCY
									        end
									        else
									        begin
									              select @I_CURRENCY=Cur_Code ,@I_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@INVOICE_CURRENCY
									        end
									 end 
									 	  
										  
										  
							 end
							 
							 else if(@TERMS='CI')
							 begin
							         --------@MIS_FREIGHT_CHARGES  
									 if(@MIS_FREIGHT_CHARGES='')--Y
									 begin
									        set @MIS_FREIGHT_RATE ='20.0000'
									        select @MIS_FREIGHT_CHARGES =cast(Round(@Inv_Value*0.2,2)as decimal(18,2))
									        
									        if(@MIS_FREIGHT_CURRENCY<>'')
									        begin
									              select @F_CURRENCY=Cur_Code ,@F_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@MIS_FREIGHT_CURRENCY
									        end
									        else
									        begin
									              select @F_CURRENCY=Cur_Code ,@F_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@INVOICE_CURRENCY
									        end
									 end
									 else --N
									 begin
									        set @MIS_FREIGHT_CHARGES=@MIS_FREIGHT_CHARGES
									        set @MIS_FREIGHT_RATE =''
									        
									        if(@MIS_FREIGHT_CURRENCY<>'')
									        begin
									              select @F_CURRENCY=Cur_Code ,@F_EXRATE =EX_Rate from @temp_Ex_Rate   where Cur_Code=@MIS_FREIGHT_CURRENCY
									        end
									        else
									        begin
									              select @F_CURRENCY=Cur_Code ,@F_EXRATE =EX_Rate from @temp_Ex_Rate  where Cur_Code=@INVOICE_CURRENCY
									        end
									 end 
									 --------@MIS_INSURANCE_CHARGES
									        set @MIS_INSURANCE_RATE ='0'
									        set @MIS_INSURANCE_CHARGES='0'
									        set @I_CURRENCY=''
									        set @I_EXRATE=''
							 end
							 
							 else if(@TERMS='CF')
							 begin
							         --------@MIS_FREIGHT_CHARGES 
							        set @MIS_FREIGHT_RATE ='0'
									set @MIS_FREIGHT_CHARGES ='0'
									set @F_CURRENCY=''
									set @F_EXRATE=''
							         --------@MIS_INSURANCE_CHARGES
							   
							      if(@MIS_INSURANCE_CHARGES='')--Y
									 begin
									        set @MIS_INSURANCE_RATE ='1.1250'
									        select @MIS_INSURANCE_CHARGES =cast(Round(@Inv_Value*0.01125,2)as decimal(18,2))
									        
									        if(@MIS_INSURANCE_CURRENCY<>'')
									        begin
									              select @I_CURRENCY=Cur_Code ,@I_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@MIS_INSURANCE_CURRENCY
									        end
									        else
									        begin
									              select @I_CURRENCY=Cur_Code ,@I_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@INVOICE_CURRENCY
									        end
									 end
									 else --N
									 begin
									        set @MIS_INSURANCE_CHARGES=@MIS_INSURANCE_CHARGES
									        set @MIS_INSURANCE_RATE =''
									        
									        if(@MIS_INSURANCE_CURRENCY<>'')
									        begin
									              select @I_CURRENCY=Cur_Code ,@I_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@MIS_INSURANCE_CURRENCY
									        end
									        else
									        begin
									              select @I_CURRENCY=Cur_Code ,@I_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@INVOICE_CURRENCY
									        end
									 end 
							 
							 end
							  else if(@TERMS='CIF')
							   begin
							    --------@MIS_FREIGHT_CHARGES 
							        set @MIS_FREIGHT_RATE ='0'
									set @MIS_FREIGHT_CHARGES ='0'
									set @F_CURRENCY=''
									set @F_EXRATE=''
							         --------@MIS_INSURANCE_CHARGES
							        set @MIS_INSURANCE_RATE ='0'
									set @MIS_INSURANCE_CHARGES='0'
									set @I_CURRENCY=''
									set @I_EXRATE=''
							   end
							 ---------CF-----------
							 
                end
                else
                begin
                        --------@MIS_FREIGHT_CHARGES 
                         set @MIS_FREIGHT_CHARGES =@MIS_FREIGHT_CHARGES
                         set @MIS_FREIGHT_RATE =''
                         
                         if(isnull(@MIS_FREIGHT_CURRENCY,'') <>'')
                         begin
                                select @F_CURRENCY=Cur_Code ,@F_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@MIS_FREIGHT_CURRENCY
                         end
                         else
                         begin
                                select @F_CURRENCY=Cur_Code ,@F_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@INVOICE_CURRENCY
                         end
                        --------@MIS_INSURANCE_CHARGES 
                         set @MIS_INSURANCE_CHARGES =@MIS_INSURANCE_CHARGES
                         set @MIS_INSURANCE_RATE =''
                         
                         if(isnull(@MIS_INSURANCE_CURRENCY,'') <>'')
                         begin
                                select @I_CURRENCY=Cur_Code ,@I_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@MIS_INSURANCE_CURRENCY
                         end
                         else
                         begin
                                select @I_CURRENCY=Cur_Code ,@I_EXRATE =EX_Rate from @temp_Ex_Rate where Cur_Code=@INVOICE_CURRENCY
                         end
                         
                         
                end
                ------------------------------------------------------------------------------------------------
                if(@Branch_Common <>'')
                begin
					update INVOICE_DETAILS set INVOICE_VALUE=@Inv_Value          
					,MIS_FREIGHT_CHARGES=@MIS_FREIGHT_CHARGES ,MIS_FREIGHT_RATE=@MIS_FREIGHT_RATE,MIS_FREIGHT_CURRENCY=@F_CURRENCY,MIS_FREIGHT_EXRATE=@F_EXRATE
					,MIS_INSURANCE_CHARGES=@MIS_INSURANCE_CHARGES,MIS_INSURANCE_RATE=@MIS_INSURANCE_RATE,MIS_INSURANCE_CURRENCY=@I_CURRENCY,MIS_INSURANCE_EXRATE=@I_EXRATE
					where JOBNO=@Jobno and INVOICE_SLNO =@Inv_Slno and BRANCH_CODE=@Branch_Common
                end
                else
                begin
                     update INVOICE_DETAILS set INVOICE_VALUE=@Inv_Value          
					,MIS_FREIGHT_CHARGES=@MIS_FREIGHT_CHARGES ,MIS_FREIGHT_RATE=@MIS_FREIGHT_RATE,MIS_FREIGHT_CURRENCY=@F_CURRENCY,MIS_FREIGHT_EXRATE=@F_EXRATE
					,MIS_INSURANCE_CHARGES=@MIS_INSURANCE_CHARGES,MIS_INSURANCE_RATE=@MIS_INSURANCE_RATE,MIS_INSURANCE_CURRENCY=@I_CURRENCY,MIS_INSURANCE_EXRATE=@I_EXRATE
					where JOBNO=@Jobno and INVOICE_SLNO =@Inv_Slno 
                end
                  
                  set @i=@i+1;
                  
                  set @Inv_Value =0
				  set @Inv_Slno =''
				  set @TERMS =''
				 
				  set @MIS_FREIGHT_CHARGES=''
                  set @MIS_FREIGHT_RATE=''
                  set @F_CURRENCY=''
				  set @F_EXRATE=''
                
                  set @MIS_INSURANCE_CHARGES=''
                  set @MIS_INSURANCE_RATE=''
                  set @I_CURRENCY=''
                  set @I_EXRATE=''
          end

----------------------------------------------------------------------------------------------------------------------------------------------------------------------
if(isnull(@BOND_NO,'') <>'' and isnull(@BOND_LOCATION,'') <>'' and isnull(@BOND_TYPE,'')<>'')
begin
       if(@Branch_Common <>'')
       begin
			   if not exists(SELECT BOND_NO  FROM BOND_DETAILS where JOBNO=@JOBNO and BOND_NO=@BOND_NO and BRANCH_CODE=@Branch_Common)	
			   begin
				   INSERT INTO BOND_DETAILS(JOBNO,BOND_NO,BOND_TYPE,BOND_LOCATION,USER_ID,DATE_TIME,BRANCH_CODE,YEAR,WORKING_PERIOD)VALUES(
					@JOBNO,@BOND_NO,@BOND_TYPE,@BOND_LOCATION,@USER_ID,GETDATE(),@BRANCH_CODE,year(GETDATE()),@WORKING_PERIOD)
			   end
	   end	
	   else
	   begin
	           if not exists(SELECT BOND_NO  FROM BOND_DETAILS where JOBNO=@JOBNO and BOND_NO=@BOND_NO)	
			   begin
				   INSERT INTO BOND_DETAILS(JOBNO,BOND_NO,BOND_TYPE,BOND_LOCATION,USER_ID,DATE_TIME,BRANCH_CODE,YEAR,WORKING_PERIOD)VALUES(
					@JOBNO,@BOND_NO,@BOND_TYPE,@BOND_LOCATION,@USER_ID,GETDATE(),@BRANCH_CODE,year(GETDATE()),@WORKING_PERIOD)
			   end
	   end
end
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
select @LICENSE_ID=(isnull(max(isnull(LICENSE_ID,0)),0)+1 ) from LICENSE_DETAILS

insert into LICENSE_DETAILS( LICENSE_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO 
,SCHEME_CODE,LICENSE_SLNO,REGISTRATION_NO,REGISTRATION_DATE,EXCEMPTION
,DEBIT_QTY,UNIT_QTY,LICENSE_NO,LICENSE_ITEM_NO,PORT_OF_LICENSE,LICENSE_DATE ,USER_ID
,DATE_TIME,BRANCH_CODE,WORKING_PERIOD,YEAR)

select ROW_NUMBER() OVER (ORDER BY @jobno) as LICENSE_ID,@Jobno,INVOICE_SLNO
,ITEM_SLNO ,case when  isnull(b.SCHEME_CODE,'')='' then '00 - DUTIABLE' else b.SCHEME_CODE end SCHEME_CODE 
,LICENSE_SLNO,LICENSE_NO as REGISTRATION_NO
, LICENSE_DATE as REGISTRATION_DATE
,EXCEMPTION
 ,Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ITEM_QTY,'') =''  THEN   '0' else ISNULL(ITEM_QTY,'0') end)as DEBIT_QTY 
,ITEM_QTY_CODE as UNIT_QTY
,a.LICENSE_NO
,LICENSE_SLNO as LICENSE_ITEM_NO
,PORT_OF_LICENSE

,LICENSE_DATE as INVOICE_DATE

,@User_Id,GETDATE(),@Branch_Code,@WORKING_PERIOD,YEAR(GETDATE())
From @temp_Gen a left outer join  @temp_Scheme_Code b 
on a.SCHEME_CODE=left(b.SCHEME_CODE,2) where isnull(a.LICENSE_NO,'') <>'' 

exec [dbo].[IMP_XL_UPLOAD_DECLARATION_BULK_ENTRY] @Jobno,@Branch_Common,@Branch_Code,@WORKING_PERIOD,@User_Id,''  
  
if(@Branch_Common <>'')  
begin  
       select JOBNO from INVOICE_DETAILS where JOBNO =@Jobno and INVOICE_SLNO=1 and BRANCH_CODE=@Branch_Common  
end  
else  
begin  
      select JOBNO from INVOICE_DETAILS where JOBNO =@Jobno and INVOICE_SLNO=1  
end  
------------------------------------------------------------------------------------------------------------------------------------------------------------
end
----------------------------------------------------------------------------------------------------------------------------------------------------------------------
------****************************---------------------------
commit                    
 End try                     
                       
begin catch                      
rollback transaction              
 set @ErrorMsg=error_message()                      
end catch



/****** Object:  StoredProcedure [dbo].[SP_AUTOCOMPLETE_SEARCH_EROYAL_MASTER]    Script Date: 10/12/2018 15:58:48 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

ALTER PROCEDURE [dbo].[SP_AUTOCOMPLETE_SEARCH_EROYAL_MASTER]

	-- Add the parameters for the stored procedure here
	@Name_Search varchar(100),
	@name 	varchar(300),
	@NSearch varchar(300),
	@Mstatus  int output,
	@ErrorMsg nvarchar(max) output
AS
begin try
	begin transaction
		set @ErrorMsg=''
/*
declare @Name_Search varchar(100),
	@name 	varchar(300),
	@NSearch varchar(300),
	@Mstatus  int ,
	@ErrorMsg nvarchar(max) 
	
	set @name='COVERING_YOUR_REFNO_BIND'
	set @Name_Search='t'
	set @NSearch='Export'
	set @NSearch='import'
	*/
	
		

if(@name='IMP_EXP_MASTER')
	begin
	select distinct(IMP_EXP_NAME) IMP_EXP_NAME from IMP_EXP_MASTER where IMP_EXP_NAME like @Name_Search+'%' order by IMP_EXP_NAME asc
	--select * from IMP_EXP_MASTER where IMP_EXP_NAME like 'R%' order by IMP_EXP_NAME asc
	end
	
	else if(@name='IMP_EXP_MASTER_Slno')
	begin
	select  convert(varchar(20),IMP_EXP_BRSLNO )+'--'+ IMP_EXP_NAME as IMP_EXP_NAME_SLNO from IMP_EXP_MASTER  
	where IMP_EXP_NAME like @Name_Search+'%' order by IMP_EXP_NAME,IMP_EXP_BRSLNO asc
	end
	
	else if(@name='IMP_EXP_MASTER_IMPORTER_SEARCH')
	begin
	select top 1 IMP_EXP_NAME,IMP_EXP_ADD1,IMP_EXP_ADD2,IMP_EXP_ADD3,IMP_EXP_ADD4,IMP_EXP_BRSLNO,IMP_EXP_IECNO,IMP_EXP_PIN_CODE,IMP_EXP_TYPE from IMP_EXP_MASTER where IMP_EXP_NAME=@Name_Search order by IMP_EXP_NAME asc
	end
	
	else if(@name='IMP_EXP_MASTER_IMPORTER_SEARCH_Slno')
	begin
		select  IMP_EXP_NAME,IMP_EXP_ADD1,IMP_EXP_ADD2,IMP_EXP_ADD3,IMP_EXP_ADD4,IMP_EXP_BRSLNO,IMP_EXP_IECNO,IMP_EXP_PIN_CODE,IMP_EXP_TYPE from IMP_EXP_MASTER where IMP_EXP_NAME=@Name_Search and IMP_EXP_BRSLNO=@NSearch order by IMP_EXP_NAME asc
	end
	
	else if(@name='IMP_EXP_MASTER_IMPORTER_SEARCH_ADCODE')
	begin
	select top 1 IMP_EXP_NAME,IMP_EXP_ADD1,IMP_EXP_ADD2,IMP_EXP_ADD3,IMP_EXP_ADD4,IMP_EXP_BRSLNO,IMP_EXP_IECNO,
	IMP_EXP_PIN_CODE,IMP_EXP_TYPE,IMP_EXP_DRAWBACK_AC_NO,GSTN_TYPE,GSTN_ID from IMP_EXP_MASTER where IMP_EXP_NAME=@Name_Search order by IMP_EXP_NAME asc
	--ADCODE SEARCH
	select top 1 ADCODE_IEC_ADCODE,ADCODE_BANK_ACCOUNT_NO from ADCODE_MASTER 
	where ADCODE_IEC_CODE=(select top 1 IMP_EXP_IECNO from IMP_EXP_MASTER where IMP_EXP_NAME=@Name_Search order by IMP_EXP_IECNO asc)
	 order by ADCODE_IEC_ADCODE asc
	--ADCODE SEARCH
		
	end
	else if(@name='IMP_EXP_MASTER_IMPORTER_BRANCH_WISE_ADCODE')
	begin
	select IMP_EXP_NAME,IMP_EXP_ADD1,IMP_EXP_ADD2,IMP_EXP_ADD3,IMP_EXP_ADD4,
	IMP_EXP_BRSLNO,IMP_EXP_IECNO,IMP_EXP_PIN_CODE,IMP_EXP_TYPE,IMP_EXP_DRAWBACK_AC_NO from IMP_EXP_MASTER 
	where IMP_EXP_BRSLNO = @Name_Search and IMP_EXP_IECNO=@NSearch 
	--ADCODE SEARCH
	select top 1 ADCODE_IEC_ADCODE,ADCODE_BANK_ACCOUNT_NO from ADCODE_MASTER 
	where ADCODE_IEC_CODE=(select top 1 IMP_EXP_IECNO from IMP_EXP_MASTER where IMP_EXP_IECNO=@NSearch order by IMP_EXP_IECNO asc)
	 order by ADCODE_IEC_ADCODE asc
	--ADCODE SEARCH
	end
	
	else if(@name='IMP_EXP_MASTER_IMPORTER_BRANCH_WISE')
	begin
	select IMP_EXP_NAME,IMP_EXP_ADD1,IMP_EXP_ADD2,IMP_EXP_ADD3,IMP_EXP_ADD4,IMP_EXP_BRSLNO,IMP_EXP_IECNO,IMP_EXP_PIN_CODE,IMP_EXP_TYPE from IMP_EXP_MASTER where IMP_EXP_BRSLNO = @Name_Search and IMP_EXP_IECNO=@NSearch 
	end
	else if(@name='IMP_EXP_MASTER_IMPORTER_IECCODE_SEARCH_WISE')
	begin
	select IMP_EXP_NAME,IMP_EXP_ADD1,IMP_EXP_ADD2,IMP_EXP_ADD3,IMP_EXP_ADD4,IMP_EXP_BRSLNO,IMP_EXP_IECNO,IMP_EXP_PIN_CODE 
	from IMP_EXP_MASTER where IMP_EXP_IECNO=@Name_Search 
	end
	
	else if(@name='IMP_EXP_MASTER_BRANCH')
	begin
	select IMP_EXP_BRSLNO from IMP_EXP_MASTER where IMP_EXP_BRSLNO like @Name_Search+'%' and IMP_EXP_IECNO=@NSearch order by IMP_EXP_BRSLNO asc
	end
	else if(@name='IMP_EXP_MASTER_IMPORTER_IECCODE_SEARCH')
	begin
	select distinct(IMP_EXP_IECNO) from IMP_EXP_MASTER where IMP_EXP_IECNO like @Name_Search+'%' order by IMP_EXP_IECNO asc
	end
	else if(@name='IMP_EXP_MASTER_IMPORTER_IECCODE_WISE')
	begin
	select distinct(IMP_EXP_NAME) from IMP_EXP_MASTER where IMP_EXP_IECNO = @Name_Search order by IMP_EXP_NAME asc
	end
	else if(@name='EXCHANGE_MASTER')
	begin
	select distinct(EXCHANGE_CUR_CODE) from EXCHANGE_MASTER where EXCHANGE_CUR_CODE like @Name_Search+'%' order by EXCHANGE_CUR_CODE asc
	end
	else if(@name='EXCHANGE_MASTER_RATE_WISE')
	begin
	select distinct(EXCHANGE_RATE_IMPORT) from EXCHANGE_MASTER where EXCHANGE_CUR_CODE = @Name_Search order by EXCHANGE_RATE_IMPORT asc
	end
	else if(@name='SUPPLIER_MASTER')
	begin
	select distinct(SUP_NAME) from SUP_MASTER where SUP_NAME like @Name_Search+'%' order by SUP_NAME asc
	end
	else if(@name='SUPPLIER_MASTER_SEARCH')
	begin
	select top 1 SUP_NAME,SUP_ADD1,SUP_ADD2,SUP_ADD3,SUP_COUNTRY_NAME,SUP_COUNTRY_CODE,SUP_PIN_CODE from SUP_MASTER where SUP_NAME=@Name_Search order by SUP_NAME asc
	end
	else if(@name='ADCODE_MASTER')
	begin
	select distinct(ADCODE_IEC_ADCODE) from ADCODE_MASTER where ADCODE_IEC_ADCODE like @Name_Search+'%' and ADCODE_IEC_CODE=@NSearch order by ADCODE_IEC_ADCODE asc

	end
	else if(@name='ADCODE_MASTER_SEARCH')
	begin
	select ADCODE_IEC_ADCODE,ADCODE_BANK_ACCOUNT_NO,IMPORT_ADCODE from ADCODE_MASTER where ADCODE_IEC_ADCODE like @Name_Search+'%' and ADCODE_IEC_CODE=@NSearch order by ADCODE_IEC_ADCODE asc
	end
	
	else if(@name='ADCODE_MASTER_SEARCH_branch_slno_wise')
	begin
	select ADCODE_IEC_ADCODE,ADCODE_BANK_ACCOUNT_NO,IMPORT_ADCODE from ADCODE_MASTER where ADCODE_BRANCH_SLNO like @Name_Search+'%' and ADCODE_IEC_CODE=@NSearch order by ADCODE_IEC_ADCODE asc
	end
	
	else if(@name='CONSIGNEE_MASTER')
	begin
	select distinct(CONSIGNEE_NAME) from CONSIGNEE_MASTER where CONSIGNEE_NAME like @Name_Search+'%' order by CONSIGNEE_NAME asc
	end
	else if(@name='CONSIGNEE_MASTER_SEARCH')
	begin
	select top 1 CONSIGNEE_NAME,CONSIGNEE_ADD1,CONSIGNEE_ADD2,CONSIGNEE_ADD3,CONSIGNEE_ADD4,CONSIGNEE_COUNTRY_NAME,CONSIGNEE_PIN_CODE,CONSIGNEE_BRANCHSLNO from CONSIGNEE_MASTER where CONSIGNEE_NAME=@Name_Search order by CONSIGNEE_NAME asc
	end
	else if(@name='BUYER_MASTER')
	begin
	select distinct(BUYER_NAME) from BUYER_MASTER where BUYER_NAME like @Name_Search+'%' order by BUYER_NAME asc
	end
	else if(@name='BUYER_MASTER_SEARCH')
	begin
	select top 1 BUYER_NAME,BUYER_ADD1,BUYER_ADD2,BUYER_ADD3,BUYER_COUNTRY_NAME,BUYER_PIN_CODE from BUYER_MASTER where BUYER_NAME=@Name_Search order by BUYER_NAME asc
	end
	else if(@name='IMP_ITEM_DESC')
	begin
	select distinct ITEM_DESCRIPTION,CTH_NO from ITEM_PRODUCT_DETAILS where ITEM_DESCRIPTION like @Name_Search+'%' order by ITEM_DESCRIPTION asc
	end
	
	else if(@name='IMP_ITEM_DESC_MASTER')
	begin
	     select PRODUCT_CTH+'--'+ PRODUCT_DESCRIPTION as  ITEM_DESCRIPTION ,PRODUCT_CTH as CTH_NO  from PRODUCT_IMPORT_MASTER  
	                    where PRODUCT_DESCRIPTION like @Name_Search+'%' order by PRODUCT_DESCRIPTION asc
	end
	
	else if(@name='IMP_ITEM_DESC_SEARCH')
	begin
	select top 1 ITEM_DESCRIPTION,CTH_NO from ITEM_PRODUCT_DETAILS where ITEM_DESCRIPTION=@Name_Search order by ITEM_DESCRIPTION asc
	end
	else if(@name='EXP_ITEM_DESC')
	begin
	select distinct(ITEM_DESCRIPTION) from EXPORT_ITEM_DETAILS where ITEM_DESCRIPTION like @Name_Search+'%' order by ITEM_DESCRIPTION asc
	end
	else if(@name='EXP_ITEM_DESC_SEARCH')
	begin
	select top 1 ITEM_DESCRIPTION,RITCNO from EXPORT_ITEM_DETAILS 
	where ITEM_DESCRIPTION=@Name_Search order by ITEM_DESCRIPTION asc
	end
	else if(@name='USER_CREATION_USER_SEARCH')
	begin
	select USER_NAME from USER_CREATION	
	where USER_NAME like @Name_Search+'%' order by USER_NAME asc
	end
	else if(@name='LICENSE_MASTER')
	begin
	select distinct(LICENSE_NO) from LICENSE_MASTER 
	where LICENSE_NO like @Name_Search+'%' and LICENSE_REG_TYPE=@NSearch order by LICENSE_NO asc
	end
	else if(@name='LICENSE_MASTER_SEARCH')
	begin
	select top 1 Convert(varchar(11),LICENSE_DATE, 103)LICENSE_DATE,Convert(varchar(11),LICENSE_REG_DATE, 103)LICENSE_REG_DATE,* from LICENSE_MASTER 
	where LICENSE_NO =@Name_Search order by LICENSE_NO asc
	end
	
	else if(@name='NON_STD_CUR_MASTER')
	begin
	select distinct(NON_STD_CUR_CODE) from NON_STANDARD_CUR_MASTER where NON_STD_CUR_CODE like @Name_Search+'%' order by NON_STD_CUR_CODE asc
	end
	else if(@name='NON_STD_CUR_RATE_IMPORTWISE')
	begin
	select NON_STD_RATE_IMPORT,Convert(varchar(11),NON_STD_EFFECT_DT_IMP, 103)NON_STD_EFFECT_DT_IMP,
	NON_STD_BANKNAME,Convert(varchar(11),NON_STD_CERTIFICATE_DATE, 103)NON_STD_CERTIFICATE_DATE,NON_STD_CERTIFICATE_NO
	 from NON_STANDARD_CUR_MASTER where NON_STD_CUR_CODE = @Name_Search 
	end
	else if(@name='NON_STD_CUR_RATE_EXPORTWISE')
	begin
	select NON_STD_RATE_EXPORT,Convert(varchar(11),NON_STD_EFFECT_DT_EXP, 103)NON_STD_EFFECT_DT_EXP,
	NON_STD_BANKNAME,Convert(varchar(11),NON_STD_CERTIFICATE_DATE, 103)NON_STD_CERTIFICATE_DATE,NON_STD_CERTIFICATE_NO
	 from NON_STANDARD_CUR_MASTER where NON_STD_CUR_CODE = @Name_Search 
	end
	
	/*********** PRODUCT EXPORT MASTER ****************/
	
	else if(@name='EXPORT_PRODUCT_DESC_SEARCH')
	begin
	select PRODUCT_DESCRIPTION,PRODUCT_RITC from PRODUCT_EXPORT_MASTER 
	where PRODUCT_DESCRIPTION like @Name_Search+'%' order by PRODUCT_DESCRIPTION asc
	end
	
	else if(@name='EXPORT_PRODUCT_RITCNo_SEARCH')
	begin
	select PRODUCT_DESCRIPTION,PRODUCT_RITC from PRODUCT_EXPORT_MASTER 
	where PRODUCT_RITC like @Name_Search+'%' order by PRODUCT_RITC asc
	end
	
	else if(@name='EXPORT_PRODUCT_DESC_SEARCH_ALL')
	begin
	select PRODUCT_DESCRIPTION,PRODUCT_RITC,REWARD_YES_NO,STR_YES_NO,STR_CODE,DBK_SL_NO from PRODUCT_EXPORT_MASTER 
	where PRODUCT_DESCRIPTION like @Name_Search+'%' order by PRODUCT_DESCRIPTION asc
	end
	
	else if(@name='EXP_ITEM_DESC_PRODUCT')
	begin
	select distinct(PRODUCT_DESCRIPTION) from PRODUCT_EXPORT_MASTER where PRODUCT_DESCRIPTION like @Name_Search+'%' order by PRODUCT_DESCRIPTION asc
	end
	
	else if(@name='IMP_ITEM_DESC_RITCNo_MASTER')
	begin
	     select 
	                  
				PRODUCT_DESCRIPTION
			   ,PRODUCT_RITC
			   ,PRODUCT_GENERAL_DESC
		       
			   ,PRODUCT_CTH
			   ,PRODUCT_CETH
		       
			   --Basic Duty / Notn 
			   ,PRODUCT_BCD_NOTN
			   ,PRODUCT_BCD_SLNO
			   ,PRODUCT_BCD_RATE
			   ,PRODUCT_BCD_SPL
			   ,PRODUCT_BCD_UNIT
		       
			   --Addl Duty 
			   ,PRODUCT_ADDL_DUTY_NOTN
			   ,PRODUCT_ADDL_DUTY_NOTN_SL
		       
			   --Education Cess 
			   ,PRODUCT_EDU_CESS_NOTN
			   ,PRODUCT_EDU_CESS_NOTN_SL
			   ,PRODUCT_EDU_CESS_RATE
		       
				--Sec & Higher Edu. Cess
			   ,PRODUCT_SEC_EDU_CESS_NOTN
			   ,PRODUCT_SEC_EDU_CESS_NOTN_SL
			   ,PRODUCT_SEC_EDU_CESS_RATE
		       
			   --NCD
			   ,PRODUCT_NCD_NOTN
			   ,PRODUCT_NCD_SLNO
			   ,PRODUCT_NCD_RATE
			   ,PRODUCT_NCD_SPL
			   ,PRODUCT_NCD_UNIT
		       
			   --Aggregate Duty 
			   ,PRODUCT_AGGREGATE_DUTY_NOTN
			   ,PRODUCT_AGGREGATE_DUTY_NOTN_SL
			   ,PRODUCT_AGGREGATE_DUTY_NOTN_RATE
		       
			   --Safeguard Duty 
			   ,PRODUCT_SAFEGUARD_NOTN
			   ,PRODUCT_SAFEGUARD_SLNO
			   ,PRODUCT_SAFEGUARD_RATE
			   ,PRODUCT_SAFEGUARD_SPL
			   ,PRODUCT_SAFEGUARD_UNIT
		       
			   --SAPTA Notn 
			   ,PRODUCT_SAPTA_NOTN
			   ,PRODUCT_SAPTA_SLNO
			   ,PRODUCT_SAPTA_RATE
		       
		       
			   --Tariff Value
			   ,PRODUCT_TARIFF_NOTN
			   ,PRODUCT_TARIFF_SLNO
			   ,PRODUCT_TARIFF_QTY
			   ,PRODUCT_TARIFF_AMOUNT
			   ,PRODUCT_TARIFF_AMOUNT_UNIT
		       
			   --CETH No 
			   --CVD
			   ,PRODUCT_CVD_NOTN
			   ,PRODUCT_CVD_SLNO
			   ,PRODUCT_CVD_RATE
			   ,PRODUCT_CVD_SPL
			   ,PRODUCT_CVD_UNIT
		       
			  --Sec&Hig.Edu Cess
			   ,PRODUCT_CVD_SEC_EDU_CESS_NOTN
			   ,PRODUCT_CVD_SEC_EDU_CESS_NOTN_SL
			   ,PRODUCT_CETH_CVD_SEC_EDU_CESS_RATE
		       
			   --Addl. Duty (Sub-Section)
			   ,PRODUCT_ADDL5_SIA_NOTN
			   ,PRODUCT_ADDL5_SIA_NOTN_SL
			   ,PRODUCT_ADDL5_SIA_RATE
		       
			   --Addl Duty of Exice(GSI) 
			   ,PRODUCT_ADDL_GSI_NOTN
			   ,PRODUCT_ADDL_GSI_SLNO
			   ,PRODUCT_ADDL_GSI_RATE
			   ,PRODUCT_ADDL_GSI_SPL
			   ,PRODUCT_ADDL_GSI_UNIT
		       
			   --Spl. Exice Duty (Sched-11)
			   ,PRODUCT_ADDL_SHEII_NOTN
			   ,PRODUCT_ADDL_SHEII_SLNO
			   ,PRODUCT_ADDL_SHEII_RATE
			   ,PRODUCT_ADDL_SHEII_SPL
			   ,PRODUCT_ADDL_SHEII_UNIT
		       
			   --Addl Duty of Excise (TTA)
			   ,PRODUCT_ADDL_TTA_NOTN
			   ,PRODUCT_ADDL_TTA_SLNO
			   ,PRODUCT_ADDL_TTA_RATE
			   ,PRODUCT_ADDL_TTA_SPL
			   ,PRODUCT_ADDL_TTA_UNIT
		       
			   --Health Cess 
			   ,PRODUCT_ADDL_HEALTH_CESS_NOTN
			   ,PRODUCT_ADDL_HEALTH_CESS_SLNO
			   ,PRODUCT_ADDL_HEALTH_CESS_RATE
			   ,PRODUCT_ADDL_HEALTH_CESS_SPL
			   ,PRODUCT_ADDL_HEALTH_CESS_UNIT
		       
			   --Cess & Notification
				,PRODUCT_CESS_NOTN
				,PRODUCT_CESS_SLNO
				,PRODUCT_CESS_RATE
				,PRODUCT_CESS_SPL
				,PRODUCT_CESS_UNIT
		        
				--MRP Duty 
				,PRODUCT_MRP_SL_NO
				,PRODUCT_MRP_AMOUNT
				,PRODUCT_MRP_ABT_RATE
		        
				--RSP Notn No 
				,PRODUCT_RSP_NOTN_NO
				,PRODUCT_RSP_NOTN_SL_NO
		        
				--Generic Desc 
				,PRODUCT_GENERAL_DESC
				,PRODUCT_MANUFACTURER
				,PRODUCT_BRAND
				,PRODUCT_MODEL
		        
				--End Use 
				,PRODUCT_END_USE
				,PRODUCT_COUNTRY_ORIGIN
				,PRODUCT_ACCESSORIES
				,PRODUCT_REMARKS
				   from PRODUCT_IMPORT_MASTER 
	                                        where PRODUCT_RITC=@Name_Search and PRODUCT_DESCRIPTION=@NSearch
	end
	/*********** PRODUCT EXPORT MASTER END****************/
	
	/*******BILLING START*****/
	
	else if(@name='BL_CHARGE_MASTER_SELECT')
	begin
	select distinct(CHARGE_NAME),CHARGE_CODE from BL_CHARGE_MASTER where CHARGE_NAME like @Name_Search+'%' order by CHARGE_NAME asc
	end
	
	
	else if(@name='BL_QUOTATION_MASTER_SELECT')
	begin
	select distinct(CHARGE_NAME) from BL_QUOTATION_MASTER where CHARGE_NAME like @Name_Search+'%' order by CHARGE_NAME asc
	end
	
	else if(@name='BL_CHARGECODE_SEARCH_SELECT')
	begin
	select distinct(CHARGE_CODE) from BL_CHARGE_MASTER where CHARGE_CODE like @Name_Search+'%' order by CHARGE_CODE asc
	end
	
	else if(@name='BL_QUOTATION_CLIENTNAME_SELECT')
	begin
	select distinct(CLIENT_NAME) from BL_QUOTATION_MASTER where CLIENT_NAME like @Name_Search+'%' order by CLIENT_NAME asc
	end

	
	/*******BILLING END*****/
	
	/* **************************** BL GENERATION NAME SEARCH**************** */
	
	else if(@name='BL_REPORT_CLIENTNAME_SELECT')
	begin
	--select distinct(CLIENT_NAME) from REPORT_CLIENT_MASTER where CLIENT_NAME like @Name_Search+'%' and CLIENT_TYPE like @NSearch+'%' order by CLIENT_NAME asc
	
	select  convert(varchar(20),CLIENT_BRSLNO )+'--'+ CLIENT_NAME as CLIENT_NAME from REPORT_CLIENT_MASTER  
	where CLIENT_NAME like @Name_Search+'%' and CLIENT_TYPE like @NSearch+'%' order by CLIENT_NAME asc
	
	end
	
	else if(@name='BL_REPORT_OCEANVESSEL_SELECT')
	begin
	select distinct(OCEANVESSEL) from REPORT_AGENT_VESSEL_MASTER where OCEANVESSEL like @Name_Search+'%' and AGENT_TYPE like @NSearch+'%' order by OCEANVESSEL asc
	end
	
	
    ELSE if(@name='IMPORT_LICENSE_REGN_NO')      
       begin      
        select distinct(REGISTRATION_NO) From IMPORT_LICENSE_MASTER where REGISTRATION_NO like @Name_Search+'%'
        AND LICENSE_TYPE like @NSearch+'%' order by REGISTRATION_NO asc       
       end 
       
       else if(@name='CONSIGNEE_MASTER_SEARCH_with_BRANCH_SLNO')
	begin
	select top 1 CONSIGNEE_NAME,CONSIGNEE_ADD1,CONSIGNEE_ADD2,CONSIGNEE_ADD3,CONSIGNEE_ADD4,CONSIGNEE_COUNTRY_NAME,CONSIGNEE_PIN_CODE,CONSIGNEE_BRANCHSLNO 
	from CONSIGNEE_MASTER where CONSIGNEE_NAME=@Name_Search  AND CONSIGNEE_BRANCHSLNO LIKE @NSearch+'%' order by CONSIGNEE_NAME,CONSIGNEE_BRANCHSLNO asc
	end  
	
	else if(@name='CONSIGNEE_NAME_with_BRANCH_SLNO')
	begin
	  SELECT ISNULL(CONSIGNEE_BRANCHSLNO,'')CONSIGNEE_BRANCHSLNO FROM CONSIGNEE_MASTER WHERE CONSIGNEE_BRANCHSLNO=@Name_Search AND CONSIGNEE_NAME=@NSearch order by CONSIGNEE_BRANCHSLNO
	end
	
	--else if(@name='PORT_MASTER_USER_WISE_LIST')
	--begin
	--select distinct PORT_NAME+'-'+PORT_CODE AS PORT_NAME from PORT_MASTER_USERWISE_MASTER where PORT_NAME LIKE @Name_Search+'%' 
	--end
	
	else if(@name='PORT_MASTER_USER_WISE_LIST_AIR')
	begin
		select distinct(PORT_NAME +'-'+ PORT_CODE) as PORT_NAME from PORT_MASTER_USERWISE_MASTER where PORT_NAME +'-'+ PORT_CODE like @Name_Search+'%' and len(PORT_CODE)=3 order by PORT_NAME asc
	end
	else if(@name='PORT_MASTER_USER_WISE_LIST_SEA_LAND')
	begin
		select distinct(PORT_NAME +'-'+ PORT_CODE) as PORT_NAME from PORT_MASTER_USERWISE_MASTER where PORT_NAME +'-'+ PORT_CODE like @Name_Search+'%' and len(PORT_CODE)=5 order by PORT_NAME asc
	end
	
	else if(@name='PORT_MASTER_USER_WISE_LIST_AIR_general')
	begin
		select distinct(PORT_NAME +'-'+ PORT_CODE) as PORT_NAME from PORT_MASTER_USERWISE_MASTER where PORT_NAME +'-'+ PORT_CODE = @Name_Search and len(PORT_CODE)=3 order by PORT_NAME asc
	end
	else if(@name='PORT_MASTER_USER_WISE_LIST_SEA_LAND_general')
	begin
		select distinct(PORT_NAME +'-'+ PORT_CODE) as PORT_NAME from PORT_MASTER_USERWISE_MASTER where PORT_NAME +'-'+ PORT_CODE = @Name_Search and len(PORT_CODE)=5 order by PORT_NAME asc
	end
	else if(@name='Get_Warehouse_Beno')
	begin
	      if(@NSearch <>'')
	      begin 
		       --select BE_NO from BE_ENTRY where BE_TYPE='Warehouse'and BRANCH_CODE=@NSearch  and BE_NO like @Name_Search+'%' order by BE_NO asc
		       select BE_NO ,BE_JOBNO from BE_ENTRY where BE_TYPE='Warehouse'and BRANCH_CODE=@NSearch  order by BE_NO asc
		  end
		  else
		  begin
		          ---select BE_NO from BE_ENTRY where BE_TYPE='Warehouse' and BE_NO like @Name_Search+'%' order by BE_NO asc
		          select BE_NO ,BE_JOBNO from BE_ENTRY where BE_TYPE='Warehouse'  order by BE_NO asc
		  end
	end
	
	else if(@name='WAREHOUSE_MASTER_USERWISE_SEARCH')
	begin
		--select distinct(WAREHOUSE_NAME +'-'+ WAREHOUSE_CODE) as WAREHOUSE_NAME from WAREHOUSE_MASTER_USERWISE_MASTER where WAREHOUSE_NAME +'-'+ WAREHOUSE_CODE  like '%'+@Name_Search+'%' order by WAREHOUSE_NAME asc
		select distinct(WAREHOUSE_CODE +'--'+ WAREHOUSE_NAME ) as WAREHOUSE_NAME from WAREHOUSE_MASTER_USERWISE_MASTER where WAREHOUSE_NAME +'-'+ WAREHOUSE_CODE  like '%'+@Name_Search+'%' order by WAREHOUSE_NAME asc
	end
	
	else if(@name='EXP_THIRDPARTY_MASTER')
	begin
	select distinct(THIRDPARTY_NAME) from EXP_THIRDPARTY_MASTER where THIRDPARTY_NAME like @Name_Search+'%' order by THIRDPARTY_NAME asc
	end
	else if(@name='EXP_THIRDPARTY_MASTER_SEARCH')
	begin
	select top 1 THIRDPARTY_NAME,THIRDPARTY_ADD1,THIRDPARTY_ADD2,THIRDPARTY_CITY,THIRDPARTY_COUNTRY_SUBDIVISION,THIRDPARTY_COUNTRY_CODE,
			TERMS_PLACE,AEO_CODE,AEO_COUNTRY,AEO_ROLE,THIRDPARTY_PIN from EXP_THIRDPARTY_MASTER where THIRDPARTY_NAME=@Name_Search order by THIRDPARTY_NAME asc
	end
	
	else if(@name='GST_IMPORT_BILLING_IMPORTER_SEARCH')
	begin
	select distinct(IMPORTER_NAME) from GST_BILL_IMPORT_JOB where IMPORTER_NAME like @Name_Search+'%' order by IMPORTER_NAME asc
	end
	
	
	
	
	else if(@name='GST_EXPORT_BILLING_EXPORTER_SEARCH')
	begin
	select distinct(EXPORTER_NAME) from GST_BILL_EXPORT_JOB where EXPORTER_NAME like @Name_Search+'%' order by EXPORTER_NAME asc
	end
	
	
	
	
	
	else if(@name='IMP_THIRDPARTY_MASTER')
	begin
	select distinct(THIRDPARTY_NAME) from IMP_THIRDPARTY_MASTER where THIRDPARTY_NAME like @Name_Search+'%' order by THIRDPARTY_NAME asc
	end
	else if(@name='IMP_THIRDPARTY_MASTER_SEARCH')
	begin
	select top 1 THIRDPARTY_NAME,THIRDPARTY_ADD1,THIRDPARTY_ADD2,THIRDPARTY_CITY,THIRDPARTY_COUNTRY_SUBDIVISION,THIRDPARTY_COUNTRY_CODE,
			TERMS_PLACE,AEO_CODE,AEO_COUNTRY,AEO_ROLE,THIRDPARTY_PIN,BUYER_RELATED_Y_N from IMP_THIRDPARTY_MASTER where THIRDPARTY_NAME=@Name_Search order by THIRDPARTY_NAME asc
	end
	
	else if(@name='EXPORT_DUPLICATE_INVOICENO')
	begin

	 select
   distinct  
    stuff((
        select ',' + cast(u.JOBNO as varchar)
        from EXPORT_INVOICE_DETAILS u 
        where u.INVOICE_NO = @Name_Search
        order by u.JOBNO
        for xml path('')
    ),1,1,'') as INVOICE_NO
from EXPORT_INVOICE_DETAILS
	
	end
	
	else if(@name='Vessel_Liner_Master')
	begin
	select distinct(NAME) from EGM_LINER_VESSEL_MASTER where NAME like @Name_Search+'%' and EGM_TYPE=@NSearch order by NAME asc
	end
	
	else if(@name='Liner_Master')
	begin
	select distinct(LINERNAME) from EGM_LINER_MASTER where LINERNAME like @Name_Search+'%' order by LINERNAME asc
	end
	
	else if(@name='Vessel_Master')
	begin
	select distinct(NAME) from EGM_VESSEL_MASTER where NAME like @Name_Search+'%'  order by NAME asc
	end
	
	--else if(@name='Get_Vessel_IMO_Code')
	--begin
	--select CODE from EGM_LINER_VESSEL_MASTER where NAME like @Name_Search+'%' and EGM_TYPE=@NSearch order by NAME asc
	--end
	
	else if(@name='Get_Vessel_IMO_Code')
	begin
	select IMO_CODE as CODE from EGM_VESSEL_MASTER where NAME like @Name_Search+'%' order by NAME asc
	end
	
	--else if(@name='Get_Liner_eMailID')
	--begin
	--select EMAIL_ID from EGM_LINER_VESSEL_MASTER where NAME like @Name_Search+'%' and EGM_TYPE=@NSearch order by NAME asc
	--end
	
	else if(@name='Get_Liner_eMailID')
	begin
	select EMAIL_ID from EGM_LINER_MASTER where LINERNAME like @Name_Search+'%'  order by LINERNAME asc
	end
	
	 if(@name='EXPORT_JOBNO')      
       begin      
         select distinct(JOBNO)JOBNO from EXPORT_GENERAL_DETAILS where JOBNO like @Name_Search+'%' and BRANCHCODE like @NSearch+'%' order by JOBNO DESC    
       end  
       if(@name='EXPORT_SB_NO')      
       begin      
         select distinct(SB_NO)SB_NO from EXPORT_SB_ENTRY where SB_NO like @Name_Search+'%' and BRANCH_CODE like @NSearch+'%' order by SB_NO DESC    
       end 
       
     if(@name='COVERING_NO_BIND')      
       begin  
          select  distinct(COVERING_PS)COVERING_NO from GST_BILL_COVERING_LETTER_DETAILS where COVERING_NO like @Name_Search+'%' and TYPE like @NSearch+'%'     
       end  
       
       if(@name='COVERING_YOUR_REFNO_BIND')      
       begin  
        declare @Your_Ref nvarchar(max)
		declare @x int
		declare @cnt int
		set @x=1;
		declare @tbl table(id int identity(1,1), YourRef varchar(max))
		declare @final table(YOUR_REF_NO VARCHAR(300))
           
				insert into @tbl 
					select distinct(BILL_REMARKS) from GST_BILL_COVERING_LETTER_DETAILS where TYPE=@NSearch and isnull(BILL_REMARKS,'')<>''
					--select * from @tbl
					set @cnt=(select COUNT(id) from @tbl )
					--select @cnt

					while(@cnt>=@x)
					begin
					  set @Your_Ref=(select replace(YourRef,'&nbsp;','') from @tbl where id=@x)
					--SELECT @Your_Ref
					INSERT INTO @final
					select distinct(Splitcolumn) from dbo.Split(@Your_Ref, '^') where Splitcolumn like @Name_Search+'%' 
					SET @x=@x+1;

					end 
					select distinct(YOUR_REF_NO) from @final order by YOUR_REF_NO
     
       end  
       
        if(@name='COVERING_NO_BIND_PEGASUS')      
       begin  
		   IF(@NSearch='Import')
		   BEGIN
			  select  distinct(YOUR_REF)YOUR_REF_NO from GST_BILL_IMPORT_JOB where YOUR_REF like @Name_Search+'%'     
		   end
		   else
		   begin
			 select  distinct(YOUR_REF)YOUR_REF_NO from GST_BILL_EXPORT_JOB where YOUR_REF like @Name_Search+'%'     
		   end
		end
       
       
        if(@name='COVERING_BIND_container_Details_PEGASUS')      
       begin  

		   IF(@NSearch='Import')
		   BEGIN
			  select  'Sub: Clearance of Import/Export '+CONTAINER_SIZE + ' CONT '+ NO_OF_PKG + ' OF '+ COMMODITY +' Per '+VESSEL 
			  +' vide '+MBL_NO +'/ '+ case when CONVERT(varchar(15), MBL_NO_DATE ,103)='01/01/1900' then '' else CONVERT(varchar(15), MBL_NO_DATE ,103) end as CONTAINER
			  from GST_BILL_IMPORT_JOB where YOUR_REF like @Name_Search+'%'     
		   end
		   else
		   begin
			  select  'Sub: Clearance of Import/Export '+CONTAINER_SIZE + ' CONT '+ NO_OF_PKG + ' OF '+ COMMODITY +' Per '+VESSEL 
			  +' vide '+MAWB_NO +'/ '+ case when CONVERT(varchar(15), MAWB_DATE ,103)='01/01/1900' then '' else CONVERT(varchar(15), MAWB_DATE ,103) end as CONTAINER
			  from GST_BILL_EXPORT_JOB where YOUR_REF like @Name_Search+'%'  
		   end
       END
       
       
 
commit
end try
begin catch
rollback transaction
	set @ErrorMsg=error_message()
	set @MStatus=0
end catch

/****** Object:  StoredProcedure [dbo].[IMP_CHECKLIST_SELECT_HTMLVIEW]    Script Date: 10/12/2018 16:03:49 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

ALTER procedure [dbo].[IMP_CHECKLIST_SELECT_HTMLVIEW]
  (    
       @Jobno varchar(50)
      ,@Inv_Slno  varchar(20)
      ,@Branch_Common varchar(150)
      ,@COMPANY_LICENSE varchar(20) 
      ,@flag varchar(50) 
      --,@CountryData  Tbl_Country_UDT  readonly      
      ,@ErrorMsg nvarchar(max) output    
   )    
 AS    
begin try    
 begin transaction    
  set @ErrorMsg=''  
  SET NOCOUNT OFF; 
--
 if(@flag='Jobno')
  begin
          if(@Branch_Common <>'')
          begin
                SELECT distinct(JOBNO)JOBNO , JOBNO_PS FROM GENERAL_DETAILS where  BRANCHCODE=@Branch_Common order by JOBNO desc
          end
          else
          begin
                SELECT distinct(JOBNO)JOBNO , JOBNO_PS FROM GENERAL_DETAILS order by JOBNO desc        
          end 
  end
 else if(@flag='EmptyChklistStr')
   begin
	select
	'Inv_Slno' Inv_Slno, 'Item_Slno' Item_Slno,  'ASSESSABLE_VALUE' ASSESSABLE_VALUE,  'DUTY_VALUE' DUTY_VALUE,  'CIF_VALUE' CIF_VALUE,  'CVD_VALUE' CVD_VALUE,  'BASIC_VALUE' BASIC_VALUE,  'CEC_VALUE' CEC_VALUE,  'CHEC_VALUE' CHEC_VALUE, 
	'ADD_DUTY_VALUE' ADD_DUTY_VALUE,  
	'INDIVITUAL_FREIGHT_AMOUNT' INDIVITUAL_FREIGHT_AMOUNT, 'INDIVITUAL_INSURANCE_AMOUNT' INDIVITUAL_INSURANCE_AMOUNT,  'INDIVITUAL_MISC_AMOUNT' INDIVITUAL_MISC_AMOUNT,  'INDIVITUAL_EDU_CESS_AMT' INDIVITUAL_EDU_CESS_AMT,  'INDIVITUAL_SEC_HIGHER_CESS_AMT' INDIVITUAL_SEC_HIGHER_CESS_AMT,  'INDIVITUAL_LANDING_CHARGE' INDIVITUAL_LANDING_CHARGE,  
	'CHECKLIST_BCD_RATE' CHECKLIST_BCD_RATE,  'CHECKLIST_CVD_RATE' CHECKLIST_CVD_RATE,  'CHECKLIST_ADDL_DUTY_RATE' CHECKLIST_ADDL_DUTY_RATE,  'MERIT_DUTY_VALUE' MERIT_DUTY_VALUE,  'PRODUCT_BCD_RATE' PRODUCT_BCD_RATE,  'PRODUCT_CVD_RATE' PRODUCT_CVD_RATE,  'MERIT_BASIC_VALUE' MERIT_BASIC_VALUE,  
	'MERIT_CVD_VALUE' MERIT_CVD_VALUE,'MERIT_CEC_VALUE' MERIT_CEC_VALUE,  'MERIT_CHEC_VALUE' MERIT_CHEC_VALUE,  'MERIT_ADD_DUTY_VALUE' MERIT_ADD_DUTY_VALUE,  'MERIT_NOTN_BASIC_VALUE' MERIT_NOTN_BASIC_VALUE,  'MERIT_NOTN_CVD_VALUE' MERIT_NOTN_CVD_VALUE,  'MERIT_NOTN_CEC_VALUE' MERIT_NOTN_CEC_VALUE,  
	'MERIT_NOTN_CHEC_VALUE' MERIT_NOTN_CHEC_VALUE, 'MERIT_NOTN_ADD_DUTY_VALUE' MERIT_NOTN_ADD_DUTY_VALUE,  'MERIT_NOTN_CESS_VALUE' MERIT_NOTN_CESS_VALUE,  'MERIT_NOTN_NCD_VALUE' MERIT_NOTN_NCD_VALUE,  'INDIVITUAL_HSS_AMOUNT' INDIVITUAL_HSS_AMOUNT,  'CHECKLIST_IGST_LEVY_AMOUNT' CHECKLIST_IGST_LEVY_AMOUNT,  
	'CHECKLIST_COMPENSATION_CC_AMOUNT' CHECKLIST_COMPENSATION_CC_AMOUNT,  'IGST_LEVY_RATE' IGST_LEVY_RATE,  'IGST_LEVY_COMPENSATION_CESS_RATE' IGST_LEVY_COMPENSATION_CESS_RATE,  'CHECKLIST_SOCIAL_WELFARE_AMT' CHECKLIST_SOCIAL_WELFARE_AMT  
	where 1=2 ;
	
	select 'NOTN_NO' NOTN_NO, 'NOTN_SLNO' NOTN_SLNO, 'INVOICE_SLNO' INVOICE_SLNO ,'ITEM_SLNO' ITEM_SLNO where 1=2

   end
  else if(@flag='ConvNumberToWord')
	begin
		--select dbo.NumberToWords(@Jobno)
		select dbo.IndianCurrencyInWords(@Jobno)
	end
  else if(@flag='Jobno_Item_Cnt')
  begin
          if(@Branch_Common <>'')
          begin
                select COUNT(JOBNO)as Item_Cnt  from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno  and BRANCH_CODE=@Branch_Common
          end
          else
          begin
                select COUNT(JOBNO)as Item_Cnt  from ITEM_PRODUCT_DETAILS where JOBNO=@Jobno     
          end 
  end
  
 else if(@flag='General')
  begin
        declare @IMP_EXP_PAN_NO varchar(150)
        declare @ADCODE_FULL varchar(50)
        
        if(@Branch_Common <>'')
        begin
                select @IMP_EXP_PAN_NO=IMP_EXP_PAN_NO from IMP_EXP_MASTER where IMP_EXP_NAME=(select IMPORTER_NAME From GENERAL_DETAILS where JOBNO=@Jobno and BRANCHCODE=@Branch_Common )
				and IMP_EXP_BRSLNO =(select BRANCH_NO From GENERAL_DETAILS where JOBNO=@Jobno and BRANCHCODE=@Branch_Common) 
				
                SELECT Convert(varchar(11),JOBDATE, 103)JOBDATE, TRANSPORT_MODE,BE_TYPE,
                case when BE_TYPE='HOME' then BE_TYPE +' '+'Consumption'  when BE_TYPE='WAREHOUSE' then BE_TYPE +', W.Code : '+WAREHOUSE_CODE else BE_TYPE end  as  BE_TYPE_New,
                
                CUSTOMS_HOUSE,CUSTOMS_HOUSE_NAME,FILING_STATUS,SECTION46,FIRSTCHECK,GREEN_CHANNEL
                ,case when isnull(KACHHA_BE,'')='Y' then '(KACHHA BE)' else '' end KACHHA_BE
                ,SECTION48,IMPORTER_NAME,ADDRESS1,ADDRESS2,ADDRESS3,ADDRESS4,ADDRESS5,IEC_NO,BRANCH_NO,PORT_ORIGIN,PORT_SHIPMENT,COUNTRY_ORIGIN,COUNTRY_SHIPMENT,COMMERCIAL_DETAILS_STATUS,
				COMMERCIAL_TAX_STATECODE ,COMMERCIAL_TAX_TYPE ,COMMERCIAL_TAX_REGISTRATION_NO,EXBOND_INBOND_BE_NO,
				case when convert(NVARCHAR, EXBOND_INBOND_BE_DATE, 103)='01/01/1900' then '' else  convert(NVARCHAR, EXBOND_INBOND_BE_DATE, 103) end  as EXBOND_INBOND_BE_DATE,			
				EXBOND_BOND_NO ,				
				case when convert(NVARCHAR, EXBOND_BOND_DATE, 103)='01/01/1900' then '' else  convert(NVARCHAR, EXBOND_BOND_DATE, 103) end  as EXBOND_BOND_DATE,
				EXBOND_WAREHOUSE_CUSTOMS ,EXBOND_WAREHOUSE_CUSTOMS_CODE ,EXBOND_NOOFPACKAGE ,
				EXBOND_NOOFPACKAGE_UNITCODE ,EXBOND_GROSS_WEIGHT ,EXBOND_GROSS_WEIGHT_UNITCODE ,EXBOND_DIRECT_EXBONDING,IMP_EXP_TYPE 
				,JOBNO,SECTION46_DESC,FIRSTCHECK_DESC,GREEN_CHANNEL_DESC,KACHHA_BE_DESC,SECTION48_DESC,HIGH_SEA_SALE,HIGH_SEA_SALE_NAME,HIGH_SEA_IEC,HIGH_SEA_BRANCH_SL_NO
				,HSS_ADD1,HSS_ADD2,HSS_ADD3,HSS_ADD4,HSS_ADD5,WAREHOUSE_NAME,WAREHOUSE_CODE,COMMERCIAL_TAX_STATENAME,REMARKS,CONTAINER_TYPE,JOB_STATUS,JOB_RELEASE,JOB_FILED_STATUS
				,JOB_PREFIX,JOB_SUFFIX,JOBNO_PS,COMPLETED_DATE,ADCODE,UCR_NO,UCR_TYPE,PAYMENT_METHOD_CODE,PRECEDING_LEVEL,DOC_RECEIVED_DATE,AGENT_NAME,EXBOND_ADDL_LOAD_HSS,EXBOND_MISC_LOAD_RATE
				,GSTN_TYPE,GSTN_ID,PARTY_REF_NO 
				,isnull((select SVB_ASSESABLE_STATUS From INVOICE_DETAILS where JOBNO=@Jobno and BRANCH_CODE=@Branch_Common and INVOICE_SLNO=1),'')SVB_ASSESABLE_STATUS
				,@IMP_EXP_PAN_NO as IMP_EXP_PAN_NO ,FILE_REF_NO
				,case when BE_TYPE ='Home' then 'HOME CONSUMPTION' else Upper(BE_TYPE) end BE_TYPE_Desc , convert(varchar(10),GETDATE(),103) printdate, 
				substring(TRANSPORT_MODE,1,1) TRANSPORT_MODENEW,substring(FILING_STATUS,1,1) FILING_STATUS_NEW,				
				(select COUNT(JOBNO) from GENERAL_DETAILS where JOBNO=@Jobno and BRANCHCODE=@Branch_Common 
				and FILING_STATUS in ('Prior','Advanced') and TRANSPORT_MODE='Air' and @COMPANY_LICENSE in (247,4)) cnt
				FROM GENERAL_DETAILS where JOBNO=@Jobno and BRANCHCODE=@Branch_Common

				select BE_NO +'  '+(case when convert(varchar(10),BE_DATE,105)='01/01/1900' then '' else convert(varchar(12),BE_DATE,105) end ) as BE_NO_DATE
				,Convert(varchar(11),GETDATE(), 103) printdate
				from BE_ENTRY  where BE_JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common order by BE_JOBNO
                 
				---IGM
				SELECT IGM_NO, 
				case when convert(varchar(10),IGM_JOBDATE,105)='01/01/1900' then '' else convert(varchar(12),IGM_JOBDATE,105) end as IGM_JOBDATE,
				case when convert(varchar(10),IGM_DATE,105)='01/01/1900' then '' else convert(varchar(12),IGM_DATE,105) end as IGM_DATE,                  
				case when convert(varchar(10),IGM_FLIGHT_VESSELDATE,105)='01/01/1900' then '' else convert(varchar(12),IGM_FLIGHT_VESSELDATE,105) end as IGM_FLIGHT_VESSELDATE  ,               
				IGM_MAWB_MBL,IGM_HAWB_HBLNO,
				case when convert(varchar(10),IGM_MAWB_MBLDATE,103)='01/01/1900' then '' else convert(varchar(12),IGM_MAWB_MBLDATE,103) end as IGM_MAWB_MBLDATE,
				case when convert(varchar(10),IGM_HAWB_HBLDATE,103)='01/01/1900' then '' else convert(varchar(12),IGM_HAWB_HBLDATE,103) end as IGM_HAWB_HBLDATE,
				IGM_TRANSPORTMODE,
				IGM_NOOFPACKAGE,IGM_PACKAGETYPE,IGM_GROSSWEIGHT,IGM_TYPEOFWEIGHT,IGM_MARKSNOS,IGM_GATEWAY_IGM_NO,
				case when convert(varchar(10),IGM_GATEWAY_IGM_DATE,105)='01/01/1900' then '' else convert(varchar(12),IGM_GATEWAY_IGM_DATE,105) end as IGM_GATEWAY_IGM_DATE,
				upper(IGM_MAWB_MBL)IGM_MAWB_MBL ,upper(IGM_HAWB_HBLNO)IGM_HAWB_HBLNO,IGM_GATEWAY_PORT_CODE 
				, case when convert(varchar(10),Igm_DATE,105)='01/01/1900' then '' else substring(convert(varchar(12),Igm_DATE,105),7,4) end as IGM_YEAR 
				FROM IGM_DETAILS where JOBNO=@JOBNO and IGM_BRANCH_CODE=@Branch_Common order by JOBNO,IGM_SLNO 
                  
                
        end
        else
        begin
              select @IMP_EXP_PAN_NO=IMP_EXP_PAN_NO from IMP_EXP_MASTER where IMP_EXP_NAME=(select IMPORTER_NAME From GENERAL_DETAILS where JOBNO=@Jobno )
				and IMP_EXP_BRSLNO =(select BRANCH_NO From GENERAL_DETAILS where JOBNO=@Jobno ) 
				
                SELECT Convert(varchar(11),JOBDATE, 103)JOBDATE, TRANSPORT_MODE, BE_TYPE,
                case when BE_TYPE='HOME' then BE_TYPE +' '+'Consumption'  when BE_TYPE='WAREHOUSE' then BE_TYPE +', W.Code : '+WAREHOUSE_CODE else BE_TYPE end  as  BE_TYPE_New,
                CUSTOMS_HOUSE,CUSTOMS_HOUSE_NAME,FILING_STATUS,SECTION46,FIRSTCHECK,GREEN_CHANNEL
               ,case when isnull(KACHHA_BE,'')='Y' then '(KACHHA BE)' else '' end KACHHA_BE
               ,SECTION48,IMPORTER_NAME,ADDRESS1,ADDRESS2,ADDRESS3,ADDRESS4,ADDRESS5,IEC_NO,BRANCH_NO,PORT_ORIGIN,PORT_SHIPMENT,COUNTRY_ORIGIN,COUNTRY_SHIPMENT,COMMERCIAL_DETAILS_STATUS,
				COMMERCIAL_TAX_STATECODE ,COMMERCIAL_TAX_TYPE ,COMMERCIAL_TAX_REGISTRATION_NO,EXBOND_INBOND_BE_NO,
				case when convert(NVARCHAR, EXBOND_INBOND_BE_DATE, 103)='01/01/1900' then '' else  convert(NVARCHAR, EXBOND_INBOND_BE_DATE, 103) end  as EXBOND_INBOND_BE_DATE,
				EXBOND_BOND_NO ,
				 
				case when convert(NVARCHAR, EXBOND_BOND_DATE, 103)='01/01/1900' then '' else  convert(NVARCHAR, EXBOND_BOND_DATE, 103) end  as EXBOND_BOND_DATE,
				EXBOND_WAREHOUSE_CUSTOMS ,EXBOND_WAREHOUSE_CUSTOMS_CODE ,EXBOND_NOOFPACKAGE ,
				EXBOND_NOOFPACKAGE_UNITCODE ,EXBOND_GROSS_WEIGHT ,EXBOND_GROSS_WEIGHT_UNITCODE ,EXBOND_DIRECT_EXBONDING,IMP_EXP_TYPE 
				,JOBNO,SECTION46_DESC,FIRSTCHECK_DESC,GREEN_CHANNEL_DESC,KACHHA_BE_DESC,SECTION48_DESC,HIGH_SEA_SALE,HIGH_SEA_SALE_NAME,HIGH_SEA_IEC,HIGH_SEA_BRANCH_SL_NO
				,HSS_ADD1,HSS_ADD2,HSS_ADD3,HSS_ADD4,HSS_ADD5,WAREHOUSE_NAME,WAREHOUSE_CODE,COMMERCIAL_TAX_STATENAME,REMARKS,CONTAINER_TYPE,JOB_STATUS,JOB_RELEASE,JOB_FILED_STATUS
				,JOB_PREFIX,JOB_SUFFIX,JOBNO_PS,COMPLETED_DATE,ADCODE
				,UCR_NO,UCR_TYPE,PAYMENT_METHOD_CODE,PRECEDING_LEVEL,DOC_RECEIVED_DATE,AGENT_NAME,EXBOND_ADDL_LOAD_HSS,EXBOND_MISC_LOAD_RATE
				,GSTN_TYPE,GSTN_ID,PARTY_REF_NO 
				,isnull((select SVB_ASSESABLE_STATUS From INVOICE_DETAILS where JOBNO=@Jobno and INVOICE_SLNO=1),'')SVB_ASSESABLE_STATUS
				,@IMP_EXP_PAN_NO as IMP_EXP_PAN_NO ,FILE_REF_NO
				,case when BE_TYPE ='Home' then 'HOME CONSUMPTION' else Upper(BE_TYPE) end BE_TYPE_Desc , convert(varchar(10),GETDATE(),103) printdate
				, substring(TRANSPORT_MODE,1,1) TRANSPORT_MODENEW ,substring(FILING_STATUS,1,1) FILING_STATUS_NEW				
				,(select COUNT(JOBNO) from GENERAL_DETAILS where JOBNO=@Jobno and FILING_STATUS in ('Prior','Advanced') and TRANSPORT_MODE='Air' and @COMPANY_LICENSE in (247,4)) cnt
				
				 FROM GENERAL_DETAILS where JOBNO=@Jobno 
				 
				 select BE_NO +'  '+(case when convert(varchar(10),BE_DATE,105)='01/01/1900' then '' else convert(varchar(12),BE_DATE,105) end ) as BE_NO_DATE
                 from BE_ENTRY  where BE_JOBNO=@JOBNO order by BE_JOBNO
                 
               ---IGM
				SELECT IGM_NO, 
				case when convert(varchar(10),IGM_JOBDATE,105)='01/01/1900' then '' else convert(varchar(12),IGM_JOBDATE,105) end as IGM_JOBDATE,
				case when convert(varchar(10),IGM_DATE,105)='01/01/1900' then '' else convert(varchar(12),IGM_DATE,105) end as IGM_DATE,                  
				case when convert(varchar(10),IGM_FLIGHT_VESSELDATE,105)='01/01/1900' then '' else convert(varchar(12),IGM_FLIGHT_VESSELDATE,105) end as IGM_FLIGHT_VESSELDATE  ,               
				IGM_MAWB_MBL,IGM_HAWB_HBLNO,
				case when convert(varchar(10),IGM_MAWB_MBLDATE,103)='01/01/1900' then '' else convert(varchar(12),IGM_MAWB_MBLDATE,103) end as IGM_MAWB_MBLDATE,
				case when convert(varchar(10),IGM_HAWB_HBLDATE,103)='01/01/1900' then '' else convert(varchar(12),IGM_HAWB_HBLDATE,103) end as IGM_HAWB_HBLDATE,
				IGM_TRANSPORTMODE,
				IGM_NOOFPACKAGE,IGM_PACKAGETYPE,IGM_GROSSWEIGHT,IGM_TYPEOFWEIGHT,IGM_MARKSNOS,IGM_GATEWAY_IGM_NO,
				case when convert(varchar(10),IGM_GATEWAY_IGM_DATE,105)='01/01/1900' then '' else convert(varchar(12),IGM_GATEWAY_IGM_DATE,105) end as IGM_GATEWAY_IGM_DATE,
				upper(IGM_MAWB_MBL)IGM_MAWB_MBL ,upper(IGM_HAWB_HBLNO)IGM_HAWB_HBLNO,IGM_GATEWAY_PORT_CODE 
				, case when convert(varchar(10),Igm_DATE,105)='01/01/1900' then '' else substring(convert(varchar(12),Igm_DATE,105),7,4) end as IGM_YEAR 
				FROM IGM_DETAILS  where JOBNO=@JOBNO order by JOBNO,IGM_SLNO 
        end
  end

else if(@flag='INVOICE_LICENSE_RE_IMP')
begin
       if(@Branch_Common <>'')
        begin
            SELECT INVOICE_ID,JOBNO,INVOICE_SLNO,INVOICE_NO,Convert(varchar(11),INVOICE_DATE, 103)INVOICE_DATE,TERMS,INVOICE_CURRENCY,INVOICE_EXRATE,INVOICE_VALUE,
			SUPPLIER_NAME,SUPPLIER_ADDRESS,SUPPLIER_ADDRESS1,SUPPLIER_ADDRESS2,SUPPLIER_COUNTRY_NAME,SUPPLIER_COUNTRY_CODE,SUPPLIER_COUNTRY_PINCODE,MIS_CHARGES,MIS_RATE,
			MIS_CURRENCY,MIS_EXRATE,MIS_AGENCY_CHARGES,MIS_AGENCY_RATE,MIS_AGENCY_CURRENCY,MIS_AGENCY_EXRATE,MIS_DISCOUNT_CHARGES,MIS_DISCOUNT_RATE,MIS_DISCOUNT_CURRENCY,MIS_DISCOUNT_EXRATE,
			MIS_DISCOUNT_REASON,MIS_LOADING_CHARGES,MIS_LOADING_RATE,MIS_LOADING_CURRENCY,MIS_LOADING_EXRATE,MIS_FREIGHT_CHARGES,MIS_FREIGHT_RATE,MIS_FREIGHT_CURRENCY,MIS_FREIGHT_EXRATE,
			MIS_INSURANCE_CHARGES,MIS_INSURANCE_RATE,MIS_INSURANCE_CURRENCY,MIS_INSURANCE_EXRATE,MIS_HIGHSEASALE_CHARGES,MIS_HIGHSEASALE_RATE,MIS_HIGHSEASALE_CURRENCY,MIS_HIGHSEASALE_EXRATE,
			MIS_SINGLE_OR_MULITIPLE,SVB_RELATION,SVB_REF_NO,Convert(varchar(11),SVB_REF_DATE, 103)SVB_REF_DATE,SVB_CUSTOM_HOUSE,SVB_LOADING_ON,SVB_ASSESABLE_RATE,SVB_DUTY_RATE,
			SVB_ASSESABLE_STATUS,SVB_DUTY_STATUS,BRANCH_CODE,REVENUEDEPOSIT_RATE,REVENUEDEPOSIT_ON,TERMS_PLACE,THIRDPARTY_NAME,THIRDPARTY_ADD1,THIRDPARTY_ADD2,THIRDPARTY_CITY,
			T_PARTY_COUNTRY_SUB_DIV,T_PARTY_COUNTRY_CODE,T_PARTY_PIN,AUTHORIZED_ECONOMIC_OPERATOR_CODE,A_E_O_COUNTRY,AUTHORIZED_ECONOMIC_OPERATOR,WHETHER_BUYER_SELLER_RELATED,
			A_AMOUNT,B_AMOUNT,C_AMOUNT,D_AMOUNT,E_AMOUNT,F_AMOUNT,G_AMOUNT,H_AMOUNT,I_AMOUNT,J_AMOUNT,K_AMOUNT,L_AMOUNT,M_AMOUNT,N_AMOUNT FROM INVOICE_DETAILS where JOBNO=@JOBNO 
			and BRANCH_CODE=@Branch_Common order by INVOICE_SLNO   
			
			SELECT LICENSE_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,SCHEME_CODE,LICENSE_SLNO,REGISTRATION_NO,REGISTRATION_DATE,EXCEMPTION,DEBIT_AMT,DEBIT_QTY,UNIT_QTY,
			LICENSE_ITEM_NO,PORT_OF_LICENSE,BRANCH_CODE,DEBIT_DUTY,LICENSE_NO,LICENSE_DATE,TOTAL_CIF_VALUE,TOTAL_DEBIT_DUTY,ENTRY_DEBIT_DUTY
			FROM LICENSE_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common order by JOBNO 
			
			SELECT Convert(varchar(11),SB_DATE, 103)SB_DATE,RE_IMPORT_SLNO,JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,SB_NO,SB_DATE,PORT_EXPORT,SB_INVOICE_NO,SB_INVOICE__ITEM_NO,
			NOTN_NO,NOTN_SLNO,EXPORT_FREIGHT,EXPORT_INSURANCE,CUSTOMS_DUTY,EXCISE_DUTY,BRANCH_CODE  FROM RE_IMPORT_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common order by JOBNO 
			
			
			
        end
        else begin
            SELECT INVOICE_ID,JOBNO,INVOICE_SLNO,INVOICE_NO,Convert(varchar(11),INVOICE_DATE, 103)INVOICE_DATE,TERMS,INVOICE_CURRENCY,INVOICE_EXRATE,INVOICE_VALUE,
			SUPPLIER_NAME,SUPPLIER_ADDRESS,SUPPLIER_ADDRESS1,SUPPLIER_ADDRESS2,SUPPLIER_COUNTRY_NAME,SUPPLIER_COUNTRY_CODE,SUPPLIER_COUNTRY_PINCODE,MIS_CHARGES,MIS_RATE,
			MIS_CURRENCY,MIS_EXRATE,MIS_AGENCY_CHARGES,MIS_AGENCY_RATE,MIS_AGENCY_CURRENCY,MIS_AGENCY_EXRATE,MIS_DISCOUNT_CHARGES,MIS_DISCOUNT_RATE,MIS_DISCOUNT_CURRENCY,MIS_DISCOUNT_EXRATE,
			MIS_DISCOUNT_REASON,MIS_LOADING_CHARGES,MIS_LOADING_RATE,MIS_LOADING_CURRENCY,MIS_LOADING_EXRATE,MIS_FREIGHT_CHARGES,MIS_FREIGHT_RATE,MIS_FREIGHT_CURRENCY,MIS_FREIGHT_EXRATE,
			MIS_INSURANCE_CHARGES,MIS_INSURANCE_RATE,MIS_INSURANCE_CURRENCY,MIS_INSURANCE_EXRATE,MIS_HIGHSEASALE_CHARGES,MIS_HIGHSEASALE_RATE,MIS_HIGHSEASALE_CURRENCY,MIS_HIGHSEASALE_EXRATE,
			MIS_SINGLE_OR_MULITIPLE,SVB_RELATION,SVB_REF_NO,Convert(varchar(11),SVB_REF_DATE, 103)SVB_REF_DATE,SVB_CUSTOM_HOUSE,SVB_LOADING_ON,SVB_ASSESABLE_RATE,SVB_DUTY_RATE,
			SVB_ASSESABLE_STATUS,SVB_DUTY_STATUS,BRANCH_CODE,REVENUEDEPOSIT_RATE,REVENUEDEPOSIT_ON,TERMS_PLACE,THIRDPARTY_NAME,THIRDPARTY_ADD1,THIRDPARTY_ADD2,THIRDPARTY_CITY,
			T_PARTY_COUNTRY_SUB_DIV,T_PARTY_COUNTRY_CODE,T_PARTY_PIN,AUTHORIZED_ECONOMIC_OPERATOR_CODE,A_E_O_COUNTRY,AUTHORIZED_ECONOMIC_OPERATOR,WHETHER_BUYER_SELLER_RELATED,
			A_AMOUNT,B_AMOUNT,C_AMOUNT,D_AMOUNT,E_AMOUNT,F_AMOUNT,G_AMOUNT,H_AMOUNT,I_AMOUNT,J_AMOUNT,K_AMOUNT,L_AMOUNT,M_AMOUNT,N_AMOUNT FROM INVOICE_DETAILS where JOBNO=@JOBNO 
			order by INVOICE_SLNO   
			
			SELECT LICENSE_ID,JOBNO,INVOICE_SLNO,ITEM_SLNO,SCHEME_CODE,LICENSE_SLNO,REGISTRATION_NO,REGISTRATION_DATE,EXCEMPTION,DEBIT_AMT,DEBIT_QTY,UNIT_QTY,
			LICENSE_ITEM_NO,PORT_OF_LICENSE,BRANCH_CODE,DEBIT_DUTY,LICENSE_NO,LICENSE_DATE,TOTAL_CIF_VALUE,TOTAL_DEBIT_DUTY,ENTRY_DEBIT_DUTY
			FROM LICENSE_DETAILS where JOBNO=@JOBNO order by JOBNO 
			
			SELECT Convert(varchar(11),SB_DATE, 103)SB_DATE,RE_IMPORT_SLNO,JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,SB_NO,SB_DATE,PORT_EXPORT,SB_INVOICE_NO,SB_INVOICE__ITEM_NO,
			NOTN_NO,NOTN_SLNO,EXPORT_FREIGHT,EXPORT_INSURANCE,CUSTOMS_DUTY,EXCISE_DUTY,BRANCH_CODE  FROM RE_IMPORT_DETAILS where JOBNO=@JOBNO order by JOBNO 
            
            
        end
end
