else if(@flag='commondetails')
begin
    if(@Branch_Common <>'')
    begin
		 
		-- RSP
		SELECT  JOBNO,INVOICE_SLNO,INVOICE_NO, ITEM_SLNO,				ITEM_DESCRIPTION,
		ITEM_QTY,RSP_DUTY_STATUS,				PRODUCT_MRP_YN,				CTH_NO,				PRODUCT_MRP_SL_NO,
		RSP_DESC,		RSP_QTY,		PRODUCT_MRP_AMOUNT,		RSP_NOTN_NO,		RSP_NOTN_SL_NO,		PRODUCT_MRP_ABT_RATE,
		RSP_APPLICABLE 	FROM ITEM_PRODUCT_DETAILS where JOBNO=@JOBNO and RSP_APPLICABLE='S' and BRANCH_CODE=@Branch_Common order by JOBNO 

		--Bond
		SELECT BOND_TYPE,BOND_NO,BOND_LOCATION FROM BOND_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common order by JOBNO   

		--certificate
		SELECT Convert(varchar(11),CERTIFICATE_DATE, 103)CERTIFICATE_DATE,CERTIFICATE_TYPE,CERTIFICATE_NO FROM CERTIFICATE_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common order by JOBNO        
		--container
		SELECT ROW_NUMBER() OVER (ORDER BY CONTAINER_DETAILS.CONTAINER_IGM_SLNO ASC) as CONTAINER_IGM_SLNO
		,CONTAINERID,CONTAINER_IGM_SLNO,CONTAINER_NO,SEAL_NO,FCL_OR_LCL,TYPE,TRUCK_NO
		FROM CONTAINER_DETAILS where JOBNO=@JOBNO  and BRANCH_CODE=@Branch_Common order by CONTAINERID	
		
		----- GSTIN Details  
		
		SELECT  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ASSESSABLE_VALUE,'') =''  THEN   '0' else ISNULL(ASSESSABLE_VALUE,'0') end)),0)
		+isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(MERIT_BASIC_VALUE,'') =''  THEN   '0' else ISNULL(MERIT_BASIC_VALUE,'0') end)),0)
		+isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CHECKLIST_SOCIAL_WELFARE_AMT,'') =''  THEN   '0' else ISNULL(CHECKLIST_SOCIAL_WELFARE_AMT,'0') end)),0) AS IGST_ASSESSABLE_VALUE
		,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CHECKLIST_IGST_LEVY_AMOUNT,'') =''  THEN   '0' else ISNULL(CHECKLIST_IGST_LEVY_AMOUNT,'0') end)),0)IGST_IGST_LEVY_AMOUNT
		,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CHECKLIST_COMPENSATION_CC_AMOUNT,'') =''  THEN   '0' else ISNULL(CHECKLIST_COMPENSATION_CC_AMOUNT,'0') end)),0)IGST_COMPENSATION_CC_AMOUNT,
		COMMERCIAL_TAX_STATECODE , COMMERCIAL_TAX_STATECODE+'/'+COMMERCIAL_TAX_STATENAME  as COMMERCIAL_TAX_STATECODE_NEW  ,B.COMMERCIAL_TAX_TYPE ,B.COMMERCIAL_TAX_REGISTRATION_NO,B.COMMERCIAL_DETAILS_STATUS
		FROM   ITEM_PRODUCT_DETAILS a 
		left JOIN GENERAL_DETAILS B 
		ON a.JOBNO = B.JOBNO and a.BRANCH_CODE=B.BRANCHCODE where a.JOBNO=@JOBNO AND BRANCH_CODE=@Branch_Common  
		GROUP  BY COMMERCIAL_TAX_STATECODE,COMMERCIAL_TAX_STATECODE+'/'+COMMERCIAL_TAX_STATENAME,COMMERCIAL_TAX_TYPE,COMMERCIAL_TAX_REGISTRATION_NO,COMMERCIAL_DETAILS_STATUS    
		
		--Reimport
		SELECT Convert(varchar(11),SB_DATE, 103)SB_DATE,RE_IMPORT_SLNO,JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,SB_NO,SB_DATE,PORT_EXPORT,SB_INVOICE_NO,SB_INVOICE__ITEM_NO,
		NOTN_NO,NOTN_SLNO,EXPORT_FREIGHT,EXPORT_INSURANCE,CUSTOMS_DUTY,EXCISE_DUTY,BRANCH_CODE  FROM RE_IMPORT_DETAILS where JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common order by RE_IMPORT_ID 
			
		-- manufacturer info
		select ITEM_SLNO, INVOICE_NO, INVOICE_SLNO, MANUFACTURER, 
		M_P_GROWER_ADD1 +' '+ M_P_GROWER_ADD2 +' '+ M_P_GROWER_CITY +' '+M_P_GROWER_PIN +' '+ M_P_GROWER_COUNTRY 'ManufactAddress', SOURCE_COUNTRY, TRANSIT_COUNTRY
		from ITEM_PRODUCT_DETAILS where len(M_P_GROWER_ADD1 +' '+ M_P_GROWER_ADD2 +' '+ M_P_GROWER_CITY +' '+M_P_GROWER_PIN +' '+ M_P_GROWER_COUNTRY)>0
		and JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common  order by ITEM_SLNO
		
		-- start of End use info
		create table #tempenduse(ID int,	END_USE_CODE varchar(30),END_USE_DESCRIPTION varchar(200))
		insert into #tempenduse values(1,'DCA100','For Veterinary Medical Use as a Non-Food Product under Controlled Distribution (Trading)')
		insert into #tempenduse values(2,'DCH100','For Human Medical Use as a Non-Food Product under Controlled Distribution (Trading) ')
		insert into #tempenduse values(3,'DCH300','For Human Medical Use as a Transplanted Organ, Tissue, or Fluid ')
		insert into #tempenduse values(4,'DCH400','For Human Medical Use as a Non-Food Product under Controlled Distribution ')
		insert into #tempenduse values(5,'DCH800','For Research use a human medicine ')
		insert into #tempenduse values(6,'DCX200','For manufacture/processing as a human or veterinary medicine (Manufacture/Actual Use) ')
		insert into #tempenduse values(7,'DCX900','Drugs and Cosmetics -For  personal consumption ')
		insert into #tempenduse values(8,'FSA100','For Animal Food or Feed (Trading/ commercial distribution) ')
		insert into #tempenduse values(9,'FSA200','For manufacture/processing as a Animal Food/Feed (Manufacture/Actual Use) ')
		insert into #tempenduse values(10,'FSA800','For use research use as animal Food ')
		insert into #tempenduse values(11,'FSA900','Foods and Supplements -For Personal use  ')
		insert into #tempenduse values(12,'FSH100','Food - For Consumer use under commercial distribution (Trading)- Retail or wholsale ')
		insert into #tempenduse values(13,'FSH200','Food - For manufacture/ commercial Processing (Manufacture/Actual Use) ')
		insert into #tempenduse values(14,'FSH700','Food -For Internal use in Hotels-Restaurant ')
		insert into #tempenduse values(15,'FSH700','Food -For Public Display or Exhibition ')
		insert into #tempenduse values(16,'FSH750','Food -For use in International Sports Events ')
		insert into #tempenduse values(17,'FSH800','Food -For Research Use ')
		insert into #tempenduse values(18,'FSH900','Food - For personal consumption ')
		insert into #tempenduse values(19,'FSH910','Food - For distribution in a natural disaster (if received gratis) ')
		insert into #tempenduse values(20,'FSH920','Food -For Charitable Use ')
		insert into #tempenduse values(21,'FSH930','Food -For use in a Diplomatic Establishment ')
		insert into #tempenduse values(22,'GNX100','Generic -For Consumer use under commercial distribution (for Trading - wholesale or retail) ')
