			--Bond - table 1
			 SELECT BOND_TYPE,BOND_NO,BOND_LOCATION FROM BOND_DETAILS where JOBNO=@JOBNO order by JOBNO  
			 
			 --certificate - table 2
			SELECT Convert(varchar(11),CERTIFICATE_DATE, 103)CERTIFICATE_DATE,CERTIFICATE_TYPE,CERTIFICATE_NO FROM CERTIFICATE_DETAILS where JOBNO=@JOBNO  order by JOBNO        
			--container - table 3
			SELECT ROW_NUMBER() OVER (ORDER BY CONTAINER_DETAILS.CONTAINER_IGM_SLNO ASC) as CONTAINER_IGM_SLNO
			,CONTAINERID,CONTAINER_IGM_SLNO,CONTAINER_NO,SEAL_NO,FCL_OR_LCL,TYPE,TRUCK_NO  FROM CONTAINER_DETAILS where JOBNO=@JOBNO order by CONTAINERID
			
