			--Reimport - table 5
			SELECT Convert(varchar(11),SB_DATE, 103)SB_DATE,RE_IMPORT_SLNO,JOBNO,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,SB_NO,SB_DATE,PORT_EXPORT,SB_INVOICE_NO,SB_INVOICE__ITEM_NO,
			NOTN_NO,NOTN_SLNO,EXPORT_FREIGHT,EXPORT_INSURANCE,CUSTOMS_DUTY,EXCISE_DUTY,BRANCH_CODE  FROM RE_IMPORT_DETAILS where JOBNO=@JOBNO  order by RE_IMPORT_ID
			
