		insert into #tempenduseBrn values(21,'FSH930','Food -For use in a Diplomatic Establishment ')
		insert into #tempenduseBrn values(22,'GNX100','Generic -For Consumer use under commercial distribution (for Trading - wholesale or retail) ')
		insert into #tempenduseBrn values(23,'GNX200','Generic -For Commercial Assembly or processing (For Manufacture/Actual use) ')
		insert into #tempenduseBrn values(24,'GNX300','Generic -For use as Fertilizers or soil promoters ')
