else if(@flag='SINGLE_WINDOW')
begin
      if(@Branch_Common <>'')
       begin 
			 SELECT INVOICE_SLNO,ITEM_SLNO,INFO_TYPE,INFO_QUALIFIER,INFO_CODE,INFO_TEXT,INFO_MSR,INFO_UQC
		     FROM BE_ITEM_SW_INFO_TYPE WHERE  JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common order by JOBNO,INVOICE_SLNO,ITEM_SLNO
		     
		     SELECT INVOICE_SLNO,ITEM_SLNO,CONSTITUENT_SRNO,CONSTITUENT_ELEMENT_NAME,CONSTITUENT_ELEMENT_CODE,CONSTITUENT_PERCENTAGE,CONSTITUENT_YIELD_PERCENTAGE,ACTIVE_INGREDIENT
		     FROM BE_ITEM_SW_CONST WHERE  JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common order by JOBNO,INVOICE_SLNO,ITEM_SLNO
		     
		     SELECT JOBNO,INVOICE_SLNO,ITEM_SLNO,PRODUCTION_BATCH_IDENTIFIER,PRODUCTION_BATCH_QUANTITY,UNIT_QTY_CODE,
			 convert(varchar, case when DATE_OF_MANUFACTURING ='1900-01-01 00:00:00.000' then null else DATE_OF_MANUFACTURING end,103) as DATE_OF_MANUFACTURING,
			 convert(varchar, case when DATE_OF_EXPIRY ='1900-01-01 00:00:00.000' then null else DATE_OF_EXPIRY end,103) as DATE_OF_EXPIRY,
			 convert(varchar, case when BEST_BEFORE ='1900-01-01 00:00:00.000' then null else BEST_BEFORE end,103) as BEST_BEFORE 
			 FROM BE_ITEM_SW_PROD WHERE  JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common order by JOBNO,INVOICE_SLNO,ITEM_SLNO
			 
			 SELECT JOBNO,INVOICE_SLNO,ITEM_SLNO,CONTROL_TYPE_CODE,CONTROL_LOCATION,CONTROL_RESULT_CODE,CONTROL_RESULT_TEXT,
			 convert(varchar, case when CONTROL_START_DATE ='1900-01-01 00:00:00.000' then null else CONTROL_START_DATE end,103) as CONTROL_START_DATE,
			 convert(varchar, case when CONTROL_END_DATE ='1900-01-01 00:00:00.000' then null else CONTROL_END_DATE end,103) as CONTROL_END_DATE
			 FROM BE_ITEM_SW_CONTROL WHERE  JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common order by JOBNO,INVOICE_SLNO,ITEM_SLNO
			 
			 SELECT JOBNO,INVOICE_SLNO,ITEM_SLNO,STMT_DECLARATION_TYPE,STMT_DECLARATION_NUMBER,STMT_TYPE,STMT_CODE,STMT_TEXT,
			 convert(varchar, case when STMT_DECLARATION_DATE ='1900-01-01 00:00:00.000' then null else STMT_DECLARATION_DATE end,103) as STMT_DECLARATION_DATE
			 FROM IMP_SINGLE_WINDOW_STMT WHERE  JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common order by JOBNO,INVOICE_SLNO,ITEM_SLNO
			 
		     select  convert(varchar, case when DOC_ISSUE_DATE ='1900-01-01 00:00:00.000' then null else DOC_ISSUE_DATE end,103) as DOC_ISSUE_DATE,
			 convert(varchar, case when DOC_EXPIRY_DATE ='1900-01-01 00:00:00.000' then null else DOC_EXPIRY_DATE end,103) as DOC_EXPIRY_DATE,JOBNO,
			 --INVOICE_SLNO,ITEM_SLNO,
			 
			 case when SELECT_TYPE='Item' then '1' when  SELECT_TYPE='job' then '0' when SELECT_TYPE='invoice' then '1' 
			 else INVOICE_SLNO end as INVOICE_SLNO ,
			 case when SELECT_TYPE='Item' then '1' when  SELECT_TYPE='job' then '0' when SELECT_TYPE='invoice' then '0' 
			 else ITEM_SLNO end as ITEM_SLNO,
			 
			 DECLARATION_TYPE,IMAGE_REF_NUMBER,
			 DOC_TYPE_CODE,DOC_ISSUING_PARTY_CODE,DOC_ISSUING_PARTY_NAME ,DOC_ISSUING_PARTY_NAME_ADD1,DOC_ISSUING_PARTY_NAME_ADD2,DOC_ISSUING_PARTY_CITY,DOC_ISSUING_PARTY_PIN,DOC_REF_NUMBER,PLACE_OF_ISSUE,BENEFICIARY_PARTY_CODE,BENEFICIARY_PARTY_NAME
			,BENEFICIARY_PARTY_ADDRESS1,BENEFICIARY_PARTY_ADDRESS2,BENEFICIARY_PARTY_CITY,BENEFICIARY_PARTY_PIN,FILE_TYPE,
			 UPPER(LEFT(SELECT_TYPE,1))+LOWER(SUBSTRING(SELECT_TYPE,2,LEN(SELECT_TYPE))) +' Level' SELECT_TYPE from BE_ITEM_SW_SUP_DOC  where JOBNO=@JOBNO and BRANCH_CODE=@Branch_Common  order by JOBNO,INVOICE_SLNO,ITEM_SLNO
		     
       end
       else begin
             SELECT INVOICE_SLNO,ITEM_SLNO,INFO_TYPE,INFO_QUALIFIER,INFO_CODE,INFO_TEXT,INFO_MSR,INFO_UQC
		     FROM BE_ITEM_SW_INFO_TYPE WHERE  JOBNO=@JOBNO order by JOBNO,INVOICE_SLNO,ITEM_SLNO
		     
		     SELECT INVOICE_SLNO,ITEM_SLNO,CONSTITUENT_SRNO,CONSTITUENT_ELEMENT_NAME,CONSTITUENT_ELEMENT_CODE,CONSTITUENT_PERCENTAGE,CONSTITUENT_YIELD_PERCENTAGE,ACTIVE_INGREDIENT
		     FROM BE_ITEM_SW_CONST WHERE  JOBNO=@JOBNO  order by JOBNO,INVOICE_SLNO,ITEM_SLNO
		     
		     SELECT JOBNO,INVOICE_SLNO,ITEM_SLNO,PRODUCTION_BATCH_IDENTIFIER,PRODUCTION_BATCH_QUANTITY,UNIT_QTY_CODE,
			 convert(varchar, case when DATE_OF_MANUFACTURING ='1900-01-01 00:00:00.000' then null else DATE_OF_MANUFACTURING end,103) as DATE_OF_MANUFACTURING,
			 convert(varchar, case when DATE_OF_EXPIRY ='1900-01-01 00:00:00.000' then null else DATE_OF_EXPIRY end,103) as DATE_OF_EXPIRY,
			 convert(varchar, case when BEST_BEFORE ='1900-01-01 00:00:00.000' then null else BEST_BEFORE end,103) as BEST_BEFORE 
			 FROM BE_ITEM_SW_PROD WHERE  JOBNO=@JOBNO  order by JOBNO,INVOICE_SLNO,ITEM_SLNO
			 
			 SELECT JOBNO,INVOICE_SLNO,ITEM_SLNO,CONTROL_TYPE_CODE,CONTROL_LOCATION,CONTROL_RESULT_CODE,CONTROL_RESULT_TEXT,
			 convert(varchar, case when CONTROL_START_DATE ='1900-01-01 00:00:00.000' then null else CONTROL_START_DATE end,103) as CONTROL_START_DATE,
			 convert(varchar, case when CONTROL_END_DATE ='1900-01-01 00:00:00.000' then null else CONTROL_END_DATE end,103) as CONTROL_END_DATE
			 FROM BE_ITEM_SW_CONTROL WHERE  JOBNO=@JOBNO  order by JOBNO,INVOICE_SLNO,ITEM_SLNO
			 
			 SELECT JOBNO,INVOICE_SLNO,ITEM_SLNO,STMT_DECLARATION_TYPE,STMT_DECLARATION_NUMBER,STMT_TYPE,STMT_CODE,STMT_TEXT,
			 convert(varchar, case when STMT_DECLARATION_DATE ='1900-01-01 00:00:00.000' then null else STMT_DECLARATION_DATE end,103) as STMT_DECLARATION_DATE
			 FROM IMP_SINGLE_WINDOW_STMT WHERE  JOBNO=@JOBNO  order by JOBNO,INVOICE_SLNO,ITEM_SLNO
			 
		     select  convert(varchar, case when DOC_ISSUE_DATE ='1900-01-01 00:00:00.000' then null else DOC_ISSUE_DATE end,103) as DOC_ISSUE_DATE,
			 convert(varchar, case when DOC_EXPIRY_DATE ='1900-01-01 00:00:00.000' then null else DOC_EXPIRY_DATE end,103) as DOC_EXPIRY_DATE,JOBNO,
			 --INVOICE_SLNO,ITEM_SLNO,
			 case when SELECT_TYPE='Item' then '1' when  SELECT_TYPE='job' then '0' when SELECT_TYPE='invoice' then '1' 
			 else INVOICE_SLNO end as INVOICE_SLNO ,
			 case when SELECT_TYPE='Item' then '1' when  SELECT_TYPE='job' then '0' when SELECT_TYPE='invoice' then '0' 
			 else ITEM_SLNO end as ITEM_SLNO,
			 
			 DECLARATION_TYPE,IMAGE_REF_NUMBER,DOC_TYPE_CODE,DOC_ISSUING_PARTY_CODE,DOC_ISSUING_PARTY_NAME ,DOC_ISSUING_PARTY_NAME_ADD1,
			 DOC_ISSUING_PARTY_NAME_ADD2,DOC_ISSUING_PARTY_CITY,DOC_ISSUING_PARTY_PIN,DOC_REF_NUMBER,PLACE_OF_ISSUE,BENEFICIARY_PARTY_CODE,BENEFICIARY_PARTY_NAME
			,BENEFICIARY_PARTY_ADDRESS1,BENEFICIARY_PARTY_ADDRESS2,BENEFICIARY_PARTY_CITY,BENEFICIARY_PARTY_PIN,FILE_TYPE,
			 UPPER(LEFT(SELECT_TYPE,1))+LOWER(SUBSTRING(SELECT_TYPE,2,LEN(SELECT_TYPE))) +' Level' SELECT_TYPE from BE_ITEM_SW_SUP_DOC  where JOBNO=@JOBNO order by JOBNO,INVOICE_SLNO,ITEM_SLNO
		     
       end
End


else if(@flag='IGST_DETAILS')
begin
        if(@Branch_Common <>'')
        begin 
			SELECT  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ASSESSABLE_VALUE,'') =''  THEN   '0' else ISNULL(ASSESSABLE_VALUE,'0') end)),0)
+isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(MERIT_BASIC_VALUE,'') =''  THEN   '0' else ISNULL(MERIT_BASIC_VALUE,'0') end)),0)
+isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CHECKLIST_SOCIAL_WELFARE_AMT,'') =''  THEN   '0' else ISNULL(CHECKLIST_SOCIAL_WELFARE_AMT,'0') end)),0) AS IGST_ASSESSABLE_VALUE
,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CHECKLIST_IGST_LEVY_AMOUNT,'') =''  THEN   '0' else ISNULL(CHECKLIST_IGST_LEVY_AMOUNT,'0') end)),0)IGST_IGST_LEVY_AMOUNT
,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CHECKLIST_COMPENSATION_CC_AMOUNT,'') =''  THEN   '0' else ISNULL(CHECKLIST_COMPENSATION_CC_AMOUNT,'0') end)),0)IGST_COMPENSATION_CC_AMOUNT,
COMMERCIAL_TAX_STATECODE ,B.COMMERCIAL_TAX_TYPE ,B.COMMERCIAL_TAX_REGISTRATION_NO,B.COMMERCIAL_DETAILS_STATUS
FROM   ITEM_PRODUCT_DETAILS a 
       left JOIN GENERAL_DETAILS B 
         ON a.JOBNO = B.JOBNO and a.BRANCH_CODE=B.BRANCHCODE where a.JOBNO=@JOBNO AND BRANCH_CODE=@Branch_Common  GROUP  BY COMMERCIAL_TAX_STATECODE,COMMERCIAL_TAX_TYPE,COMMERCIAL_TAX_REGISTRATION_NO,COMMERCIAL_DETAILS_STATUS    

		end
		else
		begin
		       SELECT  isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ASSESSABLE_VALUE,'') =''  THEN   '0' else ISNULL(ASSESSABLE_VALUE,'0') end)),0)
+isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(MERIT_BASIC_VALUE,'') =''  THEN   '0' else ISNULL(MERIT_BASIC_VALUE,'0') end)),0)
+isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CHECKLIST_SOCIAL_WELFARE_AMT,'') =''  THEN   '0' else ISNULL(CHECKLIST_SOCIAL_WELFARE_AMT,'0') end)),0) AS IGST_ASSESSABLE_VALUE
,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CHECKLIST_IGST_LEVY_AMOUNT,'') =''  THEN   '0' else ISNULL(CHECKLIST_IGST_LEVY_AMOUNT,'0') end)),0)IGST_IGST_LEVY_AMOUNT
,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CHECKLIST_COMPENSATION_CC_AMOUNT,'') =''  THEN   '0' else ISNULL(CHECKLIST_COMPENSATION_CC_AMOUNT,'0') end)),0)IGST_COMPENSATION_CC_AMOUNT,
COMMERCIAL_TAX_STATECODE ,B.COMMERCIAL_TAX_TYPE ,B.COMMERCIAL_TAX_REGISTRATION_NO,B.COMMERCIAL_DETAILS_STATUS
FROM   ITEM_PRODUCT_DETAILS a 
       left JOIN GENERAL_DETAILS B 
         ON a.JOBNO = B.JOBNO where a.JOBNO=@JOBNO GROUP  BY COMMERCIAL_TAX_STATECODE,COMMERCIAL_TAX_TYPE,COMMERCIAL_TAX_REGISTRATION_NO,COMMERCIAL_DETAILS_STATUS 

		end
end

--
SET NOCOUNT ON; 
commit    
end try    
begin catch    
rollback transaction    
 set @ErrorMsg=error_message()    
end catch



