ALTER PROCEDURE [dbo].[Export_Docket_SP]

@ExpDocID BIGINT,@JobNo BIGINT,@TypeofSB varchar(20),@Transport varchar(20),@ExporterName varchar(200),@Cnee varchar(100),
@SLineAgent varchar(50),@Commission varchar(20),@SbillNo varchar(50),
@SDt varchar(20),@Volume varchar(30),@NetWeight varchar(50),@GrossWeight varchar(50),@POD varchar(50),
@InvNo varchar(20),@InvDt varchar(20),@Term varchar(10),
@InvValue varchar(20),@Containing varchar(100),@Termvalue varchar(20),@DrawBack varchar(20),
@ExchangeRate varchar(10),@GoodsArrived varchar(20),
@CartingDt varchar(20),@CustomeClearDt varchar(20),@CFS varchar(10),@EntDate varchar(20),@OfsCoordinator varchar(50),
@CFSClerkName varchar(50),@CFSName varchar(50),@ShipBillno varchar(20),@ShipBillDt varchar(20),@TruckNo varchar(50),
@NoofTyres varchar(50),	@TransComp varchar(50),@TransCartDt varchar(20),@LEODt varchar(20),
@TotPacks varchar(20),@TotUnits varchar(20),
@NonRecExp1 varchar(200),@NonRecExp2 varchar(200),@NonRecExp3 varchar(200),@NonRecExp4 varchar(200),@NonRecExp5 varchar(200),
@RecExp1 varchar(200),@RecExp2 varchar(200),@RecExp3 varchar(200),@RecExp4 varchar(200),@RecExp5 varchar(200),
@BranchCode varchar(100),@Year varchar(20), @WORKINGPERIOD varchaR(50),
@USERID VARCHAR(50),@Ename varchar(50),  @BRANCH_COMMON varchar(20)

   
     
AS    
begin try    
 begin transaction    
  
 --------------------------------------------------------------------------------------------------------------------------------------------------------------  
    
 if (@Ename='Save')  
  begin 
	SET @ExpDocID =(SELECT isnull(max(isnull(ExpDocID,0)),0)+1  FROM ExportDocket );
	
	insert into ExportDocket (ExpDocID,JobNo,TypeofSB,Transport,ExporterName,Consignee,SLineAgent,Commission,SbillNo,
	SDt,Volume,POD,TotPacks,TotUnits ,NetWeight,GrossWeight,InvNo,InvDt,Term,InvValue,Containing,Termvalue,DrawBack,ExchangeRate,GoodsArrived,
	CartingDt,CustomeClearDt,CFS,EntDate,OfsCoordinator,CFSClerkName,CFSName,ShipBillno,ShipBillDt,TruckNo,NoofTyres,
	TransComp,TransCartDt,LEODt,NonRecExp1,NonRecExp2,NonRecExp3,NonRecExp4,NonRecExp5,
	RecExp1,RecExp2,RecExp3,RecExp4,RecExp5,BranchCode,Year,WorkingPeriod,userID,EntryDt) 
	values(@ExpDocID,@JobNo,@TypeofSB,@Transport,@ExporterName,@Cnee,@SLineAgent,@Commission,@SbillNo,
	@SDt,@Volume,@POD,@TotPacks, @TotUnits, @NetWeight,@GrossWeight,@InvNo,@InvDt,@Term,@InvValue,@Containing,@Termvalue,@DrawBack,@ExchangeRate,
	@GoodsArrived,@CartingDt,@CustomeClearDt,@CFS,@EntDate,@OfsCoordinator,@CFSClerkName,@CFSName,@ShipBillno,@ShipBillDt,
	@TruckNo,@NoofTyres,@TransComp,@TransCartDt,@LEODt,@NonRecExp1,@NonRecExp2,@NonRecExp3,@NonRecExp4,@NonRecExp5,
	@RecExp1,@RecExp2,@RecExp3,@RecExp4,@RecExp5,@BranchCode,@Year , @WORKINGPERIOD,@USERID,GETDATE() );
	
	select 1 'status'

  end 
  
 else  if (@Ename='Update')  
  begin 
	if (@BRANCH_COMMON <>'') 
	 begin
		update ExportDocket set TypeofSB=@TypeofSB,Transport=@Transport,ExporterName=@ExporterName,Consignee=@Cnee,
		SLineAgent=@SLineAgent,Commission=@Commission,SbillNo=@SbillNo,
		SDt=@SDt,Volume=@Volume,NetWeight=@NetWeight,GrossWeight=@GrossWeight,POD=@POD,
		TotPacks=@TotPacks,TotUnits=@TotUnits,InvNo=@InvNo,InvDt=@InvDt,
		Term=@Term,InvValue=@InvValue,Containing=@Containing,Termvalue=@Termvalue,DrawBack=@DrawBack,ExchangeRate=@ExchangeRate,
		GoodsArrived=@GoodsArrived,
		CartingDt=@CartingDt,CustomeClearDt=@CustomeClearDt,CFS=@CFS,EntDate=@EntDate,OfsCoordinator=@OfsCoordinator,CFSClerkName=@CFSClerkName,
		CFSName=@CFSName,ShipBillno=@ShipBillno,ShipBillDt=@ShipBillDt,TruckNo=@TruckNo,NoofTyres=@NoofTyres,
		TransComp=@TransComp,TransCartDt=@TransCartDt,LEODt=@LEODt,
		NonRecExp1=@NonRecExp1,NonRecExp2=@NonRecExp2,NonRecExp3=@NonRecExp3,NonRecExp4=@NonRecExp4,NonRecExp5=@NonRecExp5,
		RecExp1=@RecExp1,RecExp2=@RecExp2,RecExp3=@RecExp3,RecExp4=@RecExp4,RecExp5=@RecExp5,		
		BranchCode=@BranchCode,Year=@Year,WorkingPeriod=@WORKINGPERIOD	where jobno=@JOBNO ;
		
		select 2 'status'
	 end	 
		
	else
	 begin
		update ExportDocket set TypeofSB=@TypeofSB,Transport=@Transport,ExporterName=@ExporterName,Consignee=@Cnee,
		SLineAgent=@SLineAgent,Commission=@Commission,SbillNo=@SbillNo,
		SDt=@SDt,Volume=@Volume,NetWeight=@NetWeight,GrossWeight=@GrossWeight,POD=@POD,
		TotPacks=@TotPacks,TotUnits=@TotUnits,InvNo=@InvNo,InvDt=@InvDt,
		Term=@Term,InvValue=@InvValue,Containing=@Containing,Termvalue=@Termvalue,DrawBack=@DrawBack,ExchangeRate=@ExchangeRate,
		GoodsArrived=@GoodsArrived,
		CartingDt=@CartingDt,CustomeClearDt=@CustomeClearDt,CFS=@CFS,EntDate=@EntDate,OfsCoordinator=@OfsCoordinator,CFSClerkName=@CFSClerkName,
		CFSName=@CFSName,ShipBillno=@ShipBillno,ShipBillDt=@ShipBillDt,TruckNo=@TruckNo,NoofTyres=@NoofTyres,
		TransComp=@TransComp,TransCartDt=@TransCartDt,LEODt=@LEODt,
		NonRecExp1=@NonRecExp1,NonRecExp2=@NonRecExp2,NonRecExp3=@NonRecExp3,NonRecExp4=@NonRecExp4,NonRecExp5=@NonRecExp5,
		RecExp1=@RecExp1,RecExp2=@RecExp2,RecExp3=@RecExp3,RecExp4=@RecExp4,RecExp5=@RecExp5,		
		BranchCode=@BranchCode,Year=@Year,WorkingPeriod=@WORKINGPERIOD	where jobno=@JOBNO and BranchCode=@BranchCode;
		
		select 2 'status'
	 end	

  end  
  
 else  if (@Ename='Delete')  
  begin 
	if (@BRANCH_COMMON <>'')  
		begin
			delete from ExportDocket  where jobno=@JOBNO  and BranchCode=@BranchCode;
			select 3 'status'
		end
	else
		begin
			delete from ExportDocket  where jobno=@JOBNO ;
			select 3 'status'
		end
	
  end
  
 else  if (@Ename='Get_ExpDocketData')  
  begin 
	 
	if   exists(select * from ExportDocket  where JobNo=@JOBNO  and BranchCode=@BranchCode)
		begin
		  if (@BRANCH_COMMON <>'') 
			begin
			select top 1 ExpDocID,Ex.JobNo,TypeofSB,Transport,ExporterName,Consignee,SLineAgent,Commission,SbillNo,
			case when convert(NVARCHAR, SDt, 103)='01/01/1900' then '' else convert(NVARCHAR, SDt, 103) end  as sdt,
 			Volume,POD,TotPacks,TotUnits, NetWeight,GrossWeight,InvNo,
 			case when convert(NVARCHAR, invdt, 103)='01/01/1900' then '' else convert(NVARCHAR, invdt, 103) end  as InvDt,
			Term,InvValue,Containing,Termvalue,DrawBack,ExchangeRate,GoodsArrived,
			case when convert(NVARCHAR, CartingDt, 103)='01/01/1900' then '' else convert(NVARCHAR, CartingDt, 103) end  as CartingDt,
			case when convert(NVARCHAR, CustomeClearDt, 103)='01/01/1900' then '' else convert(NVARCHAR, CustomeClearDt, 103) end  as CustomeClearDt,CFS,
			case when convert(NVARCHAR, EntDate, 103)='01/01/1900' then '' else convert(NVARCHAR, EntDate, 103) end  as EntDate,
			OfsCoordinator,CFSClerkName,CFSName,ShipBillno,
			case when convert(NVARCHAR, ShipBillDt, 103)='01/01/1900' then '' else convert(NVARCHAR, ShipBillDt, 103) end  as ShipBillDt,			 
			TruckNo,NoofTyres,TransComp,
			case when convert(NVARCHAR, TransCartDt, 103)='01/01/1900' then '' else convert(NVARCHAR, TransCartDt, 103) end  as TransCartDt,
			case when convert(NVARCHAR, LEODt, 103)='01/01/1900' then '' else convert(NVARCHAR, LEODt, 103) end  as  LEODt,
			NonRecExp1,NonRecExp2,NonRecExp3,NonRecExp4,NonRecExp5,	RecExp1,RecExp2,RecExp3,RecExp4,RecExp5,			
			'Docket-Table' Datafrom	
			, a.ADDRESS1 +' '+ a.ADDRESS2+' '+ a.ADDRESS3+' '+ a.ADDRESS4+' '+ a.ADDRESS5 'ExporterAddr',
			a.CONSIGNEE_NAME , a.CONSIGNEE_ADD1+' '+ a.CONSIGNEE_ADD2+' '+ a.CONSIGNEE_ADD3+' '+ a.CONSIGNEE_ADD4+' '+ CONSIGNEE_ADD5 'ConsAddr'
			,(select top 1 item_description from export_item_details where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE)'GoodContain'
			,(select sum(isnull(CAST(FOB_VALUE AS DECIMAL(18, 2) ),0)) from EXPORT_ITEM_DETAILS where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE and len(FOB_VALUE) >0 )'FOBVALUE'
			,(select sum(isnull(CAST(DRAWBACK_VALUE AS DECIMAL(18, 2) ),0)) from EXPORT_ITEM_DETAILS where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE and len(DRAWBACK_VALUE) >0 )'DRAWBACKVALUE'
			, a.PORT_FINAL_DEST 'POD' , file_ref_no  		
			from ExportDocket Ex left outer join EXPORT_GENERAL_DETAILS a  on Ex.JobNo=a.JOBNO 
			where Ex.jobno=@JOBNO  and a.BranchCode=@BranchCode
			
			
			
			end
		  ELSE
			begin
			select top 1 ExpDocID,Ex.JobNo,TypeofSB,Transport,ExporterName,Consignee,SLineAgent,Commission,SbillNo,
			case when convert(NVARCHAR, SDt, 103)='01/01/1900' then '' else convert(NVARCHAR, SDt, 103) end  as sdt,
 			Volume,POD,TotPacks,TotUnits,NetWeight,GrossWeight,InvNo,
 			case when convert(NVARCHAR, invdt, 103)='01/01/1900' then '' else convert(NVARCHAR, invdt, 103) end  as InvDt,
			Term,InvValue,Containing,Termvalue,DrawBack,ExchangeRate,GoodsArrived,
			case when convert(NVARCHAR, CartingDt, 103)='01/01/1900' then '' else convert(NVARCHAR, CartingDt, 103) end  as CartingDt,
			case when convert(NVARCHAR, CustomeClearDt, 103)='01/01/1900' then '' else convert(NVARCHAR, CustomeClearDt, 103) end  as CustomeClearDt,CFS,
			case when convert(NVARCHAR, EntDate, 103)='01/01/1900' then '' else convert(NVARCHAR, EntDate, 103) end  as EntDate,
			OfsCoordinator,CFSClerkName,CFSName,ShipBillno,
			case when convert(NVARCHAR, ShipBillDt, 103)='01/01/1900' then '' else convert(NVARCHAR, ShipBillDt, 103) end  as ShipBillDt,			 
			TruckNo,NoofTyres,TransComp,
			case when convert(NVARCHAR, TransCartDt, 103)='01/01/1900' then '' else convert(NVARCHAR, TransCartDt, 103) end  as TransCartDt,
			case when convert(NVARCHAR, LEODt, 103)='01/01/1900' then '' else convert(NVARCHAR, LEODt, 103) end  as  LEODt,
			NonRecExp1,NonRecExp2,NonRecExp3,NonRecExp4,NonRecExp5,	RecExp1,RecExp2,RecExp3,RecExp4,RecExp5,
			'Docket-Table' Datafrom	 
			, a.ADDRESS1 +' '+ a.ADDRESS2+' '+ a.ADDRESS3+' '+ a.ADDRESS4+' '+ a.ADDRESS5 'ExporterAddr',
			a.CONSIGNEE_NAME , a.CONSIGNEE_ADD1+' '+ a.CONSIGNEE_ADD2+' '+ a.CONSIGNEE_ADD3+' '+ a.CONSIGNEE_ADD4+' '+ CONSIGNEE_ADD5 'ConsAddr'
			,(select top 1 item_description from export_item_details where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE)'GoodContain'
			,(select sum(isnull(CAST(FOB_VALUE AS DECIMAL(18, 2) ),0)) from EXPORT_ITEM_DETAILS where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE and len(FOB_VALUE) >0)'FOBVALUE'
			,(select sum(isnull(CAST(DRAWBACK_VALUE AS DECIMAL(18, 2) ),0)) from EXPORT_ITEM_DETAILS where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE and len(DRAWBACK_VALUE) >0 )'DRAWBACKVALUE'
			, a.PORT_FINAL_DEST 'POD'	, file_ref_no
			from ExportDocket Ex left outer join EXPORT_GENERAL_DETAILS a  on Ex.JobNo=a.JOBNO 
			where Ex.jobno=@JOBNO  
			
			 
					
			end
		end
	else
		begin
		 if (@BRANCH_COMMON <>'')
			begin
			declare @trmode varchar(10);
			 select a.JOBNO,a.EXPORTER_NAME,a.BRANCHCODE, c.INVOICE_NO,			 
			case when convert(NVARCHAR, c.INVOICE_DATE, 103)='01/01/1900' then '' else convert(NVARCHAR, c.INVOICE_DATE, 103) end  as INVOICE_DATE,
			a.TRANSPORT_MODE ,c.invoice_value, c.terms,c.exchange_rate,c.commission_charges,c.FOB_charges, 'Invoice-Table' Datafrom		
			
			,(select top 1 item_description from export_item_details where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE)'GoodContain'
			,(select sum(isnull(CAST(FOB_VALUE AS DECIMAL(18, 2) ),0)) from EXPORT_ITEM_DETAILS where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE and len(FOB_VALUE) >0 )'FOBVALUE'
			,(select sum(isnull(CAST(DRAWBACK_VALUE AS DECIMAL(18, 2) ),0)) from EXPORT_ITEM_DETAILS where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE and len(DRAWBACK_VALUE) >0 )'DRAWBACKVALUE'
			, a.PORT_FINAL_DEST 'POD'
			,a.CONSIGNEE_NAME 	, file_ref_no
			from EXPORT_GENERAL_DETAILS a 
			left outer join EXPORT_INVOICE_DETAILS c on a.JOBNO=c.JOBNO and c.BRANCH_CODE=@BranchCode
			where a.JOBNO=@JOBNO and a.BRANCHCODE=@BranchCode  
			
			set @trmode=(select  upper(TRANSPORT_MODE)  from EXPORT_GENERAL_DETAILS where  JOBNO=@JOBNO and BRANCHCODE=@BranchCode )
			
			if(@trmode='AIR' or @trmode='A') --TotPacks,TotUnits, NetWeight,GrossWeight
				begin
					select top 1 ANNEX_AIR_TOTAL_PACKAGES 'TotPacks',ANNEX_AIR_UNIT_CODE 'TotUnits',ANNEX_AIR_GROSS_WEIGHT 'NetWeight',ANNEX_AIR_NET_WEIGHT 'GrossWeight' from 
					EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO=@JOBNO and  BRANCH_CODE=@BranchCode
				end
			else if(@trmode='SEA' or @trmode='S')
				begin
					select top 1 ANNEX_SEA_TOTAL_PACKAGES 'TotPacks',(select top 1 ANNEX_SEA_PACK_PACKAGETYPE  from 
					EXPORT_ANNEXURE_C_SEA_PACKAGE where ANNEX_SEA_PACK_JOBNO=@JOBNO and  BRANCH_CODE=@BranchCode ) 'TotUnits',ANNEX_SEA_GROSS_WEIGHT 'NetWeight',ANNEX_SEA_NET_WEIGHT 'GrossWeight' from 
					EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO=@JOBNO and  BRANCH_CODE=@BranchCode
				end
			else
				select 	'' TotPacks,'' TotUnits, '' NetWeight,'' GrossWeight where 1=2
		 end	
			/*select a.JOBNO,a.EXPORTER_NAME,a.BRANCHCODE, c.INVOICE_NO,			 
			case when convert(NVARCHAR, c.INVOICE_DATE, 103)='01/01/1900' then '' else convert(NVARCHAR, c.INVOICE_DATE, 103) end  as INVOICE_DATE,
			a.TRANSPORT_MODE ,c.invoice_value, c.terms,c.exchange_rate,c.commission_charges,c.FOB_charges, 'Invoice-Table' Datafrom		
			, a.ADDRESS1 +' '+ a.ADDRESS2+' '+ a.ADDRESS3+' '+ a.ADDRESS4+' '+ a.ADDRESS5 'Exp-Address',
			a.CONSIGNEE_NAME , a.CONSIGNEE_ADD1+' '+ a.CONSIGNEE_ADD2+' '+ a.CONSIGNEE_ADD3+' '+ a.CONSIGNEE_ADD4+' '+ CONSIGNEE_ADD5 'Cons-Address',
			(select top 1 item_description from export_item_details where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE)'GoodContain'
			from EXPORT_GENERAL_DETAILS a 
			left outer join EXPORT_INVOICE_DETAILS c on a.JOBNO=c.JOBNO and c.BRANCH_CODE=@BranchCode
			where a.JOBNO=@JOBNO and a.BRANCHCODE=@BranchCode */

		 ELSE
			begin
				select a.JOBNO,a.EXPORTER_NAME,a.BRANCHCODE, c.INVOICE_NO,			 
				case when convert(NVARCHAR, c.INVOICE_DATE, 103)='01/01/1900' then '' else convert(NVARCHAR, c.INVOICE_DATE, 103) end  as INVOICE_DATE,
				a.TRANSPORT_MODE ,c.invoice_value, c.terms,c.exchange_rate,c.commission_charges,c.FOB_charges, 'Invoice-Table' Datafrom		
				
				,(select top 1 item_description from export_item_details where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE)'GoodContain'
				,(select sum(isnull(CAST(FOB_VALUE AS DECIMAL(18, 2) ),0)) from EXPORT_ITEM_DETAILS where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE and len(FOB_VALUE) >0 )'FOBVALUE'
				,(select sum(isnull(CAST(DRAWBACK_VALUE AS DECIMAL(18, 2) ),0)) from EXPORT_ITEM_DETAILS where JOBNO=a.JOBNO and BRANCH_CODE=a.BRANCHCODE and len(DRAWBACK_VALUE) >0 )'DRAWBACKVALUE'
				, a.PORT_FINAL_DEST 'POD'
				,a.CONSIGNEE_NAME 	,file_ref_no
				from EXPORT_GENERAL_DETAILS a  
				left outer join EXPORT_INVOICE_DETAILS c on a.JOBNO=c.JOBNO and c.BRANCH_CODE=@BranchCode
				where a.JOBNO=@JOBNO  
				
				 set @trmode=(select  upper(TRANSPORT_MODE)  from EXPORT_GENERAL_DETAILS where  JOBNO=@JOBNO and BRANCHCODE=@BranchCode )
			
			if(@trmode='AIR' or @trmode='A') --TotPacks,TotUnits, NetWeight,GrossWeight
				begin
					select top 1 ANNEX_AIR_TOTAL_PACKAGES 'TotPacks',ANNEX_AIR_UNIT_CODE 'TotUnits',ANNEX_AIR_GROSS_WEIGHT 'NetWeight',ANNEX_AIR_NET_WEIGHT 'GrossWeight' from 
					EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO=@JOBNO  
				end
			else if(@trmode='SEA' or @trmode='S')
				begin
					select top 1 ANNEX_SEA_TOTAL_PACKAGES 'TotPacks',(select top 1 ANNEX_SEA_PACK_PACKAGETYPE  from 
					EXPORT_ANNEXURE_C_SEA_PACKAGE where ANNEX_SEA_PACK_JOBNO=@JOBNO) 'TotUnits',ANNEX_SEA_GROSS_WEIGHT 'NetWeight',ANNEX_SEA_NET_WEIGHT 'GrossWeight' from 
					EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO=@JOBNO  
				end
			else
				select 	'' TotPacks,'' TotUnits, '' NetWeight,'' GrossWeight where 1=2
			end
		end
  end
 
 --------------------------------------------------------------------------------------------------------------------------------------------------------------  
             
 commit                    
 End try                     
                       
begin catch                
rollback transaction                      
                      
 select 0 'status'                     
end catch



/****** Object:  StoredProcedure [dbo].[GENERATE_IMPORT_DUPLICATE_JOB]    Script Date: 10/12/2018 16:08:00 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

ALTER  PROCEDURE [dbo].[GENERATE_IMPORT_DUPLICATE_JOB]
	@OLD_JOBNO varchar(35),@CURRENT_JOBNO varchar(35),@BRANCHCODE varchar(20),@Working_Period varchar(30),@USERID varchar(30),@name varchar(300),@DB_Name varchar(30),
	@Current_Working_Period varchar(30),@Mstatus  int output,@ErrorMsg nvarchar(max) output
AS

begin try
	begin transaction
		set @ErrorMsg=''		
		declare @jobid as bigint declare @igmid as bigint declare @containerid as bigint declare @certificateid as bigint declare @bondid as bigint declare @invoiceid as bigint
		declare @itemid as bigint declare @reimportid as bigint	declare @licenseid as bigint declare @single_multiple varchar(10) declare @multiple_invoiceid as bigint
		declare @TransportMode as varchar(30)  declare @i as int
		
		--======================================
		
		declare @SW_INFO_TYPE_ID as bigint
		declare @SW_CONST_ID as bigint
		declare @SW_PROD_ID as bigint
		declare @SW_CONTROL_ID as bigint
		declare @SW_STMT_ID as bigint
		declare @SW_SUP_DOC_ID as bigint
		
		--======================================
		declare @j int
		declare @cnt int
		declare @inv_slno int
		declare @temp table( Id int identity(1,1),Inv_slno int, Jobno varchar(25))
		--=======================================

set @jobid=(SELECT isnull(max(isnull(JOBID,0)),0)+1  FROM dbo.GENERAL_DETAILS )
--select @SWid= isnull(max(isnull(SW_ID,0)),0)+1  from IMP_SINGLE_WINDOW_DETAILS

select @SW_INFO_TYPE_ID= isnull(max(isnull(SW_INFO_TYPE_ID,0)),0)+1  from BE_ITEM_SW_INFO_TYPE -- SW_INFO_TYPE_ID
select @SW_CONST_ID= isnull(max(isnull(SW_CONST_ID,0)),0)+1  from BE_ITEM_SW_CONST --SW_CONST_ID
select @SW_PROD_ID= isnull(max(isnull(SW_PROD_ID,0)),0)+1  from BE_ITEM_SW_PROD --SW_PROD_ID
select @SW_CONTROL_ID= isnull(max(isnull(SW_CONTROL_ID,0)),0)+1  from BE_ITEM_SW_CONTROL--SW_CONTROL_ID
select @SW_STMT_ID= isnull(max(isnull(SW_ID,0)),0)+1   from IMP_SINGLE_WINDOW_STMT --SW_ID
select @SW_SUP_DOC_ID= isnull(max(isnull(SW_ID,0)),0)+1   from BE_ITEM_SW_SUP_DOC --SW_ID


set @igmid=(SELECT isnull(max(isnull(IGM_ID,0)),0)+1  FROM dbo.IGM_DETAILS )
set @containerid=(SELECT isnull(max(isnull(CONTAINERID,0)),0)  FROM dbo.CONTAINER_DETAILS )
set @certificateid=(SELECT isnull(max(isnull(CERTIFICATEID,0)),0)  FROM dbo.CERTIFICATE_DETAILS )
set @bondid=(SELECT isnull(max(isnull(BONDID,0)),0)  FROM dbo.BOND_DETAILS )
declare @job_P varchar(30),@job_s varchar(30),@jobps varchar(150) ,@Z int 

------------CONTAINER Continue Auto No-------------
    dbcc checkident(CONTAINER_DETAILS,reseed,@containerid)
------------------------------------------
------------BOND Continue Auto No-------------
	dbcc checkident(BOND_DETAILS,reseed,@bondid)
------------------------------------------
------------CERTIFICATE Continue Auto No-------------	
    dbcc checkident(CERTIFICATE_DETAILS,reseed,@certificateid)
------------------------------------------

set @invoiceid=(SELECT isnull(max(isnull(INVOICE_ID,0)),0)+1  FROM dbo.INVOICE_DETAILS )
set @multiple_invoiceid=(SELECT isnull(max(isnull(MUITIPLE_ID,0)),0)+1  FROM dbo.MULTIPLE_INVOICE )
set @itemid=(SELECT isnull(max(isnull(ITEM_ID,0)),0)+1  FROM dbo.ITEM_PRODUCT_DETAILS )
set @reimportid=(SELECT isnull(max(isnull(RE_IMPORT_ID,0)),0)+1  FROM dbo.RE_IMPORT_DETAILS )
set @licenseid=(SELECT isnull(max(isnull(LICENSE_ID,0)),0)+1  FROM dbo.LICENSE_DETAILS )

if(@Working_Period<>'')
begin


set @single_multiple=(SELECT top 1 MIS_SINGLE_OR_MULITIPLE  FROM dbo.INVOICE_DETAILS where JOBNO=@OLD_JOBNO and BRANCH_CODE=@Working_Period)
set @TransportMode=(SELECT TRANSPORT_MODE  FROM dbo.GENERAL_DETAILS where JOBNO=@OLD_JOBNO  and BRANCHCODE=@Working_Period)

if(@name='Duplicate_Job')
begin
if not exists(SELECT JOBNO  FROM dbo.GENERAL_DETAILS where JOBNO=@CURRENT_JOBNO  and BRANCHCODE=@Working_Period)
begin
 
