ALTER PROCEDURE [dbo].[GENERATE_IMPORT_DUPLICATE_JOB_WORK_PERIOD]  

(  
 @OLD_JOBNO varchar(35),@CURRENT_JOBNO varchar(35),@BRANCHCODE varchar(20),@Working_Period varchar(30),@USERID varchar(30),@name  varchar(300),@DB_Name varchar(300),  
 @Current_Working_Period varchar(100),@Mstatus  int output,@ErrorMsg nvarchar(max) output )  
AS  
  
begin try  
 begin transaction  
  set @ErrorMsg=''    
  declare @jobid as bigint declare @igmid as bigint declare @containerid as bigint declare @certificateid as bigint declare @bondid as bigint declare @invoiceid as bigint  
  declare @itemid as bigint declare @reimportid as bigint declare @licenseid as bigint declare @single_multiple varchar(10)declare @multiple_invoiceid as bigint  
  declare @TransportMode as varchar(30)declare @i as int  
 set @jobid=(SELECT isnull(max(isnull(JOBID,0)),0)+1  FROM dbo.GENERAL_DETAILS ) set @igmid=(SELECT isnull(max(isnull(IGM_ID,0)),0)+1  FROM dbo.IGM_DETAILS )  
 set @containerid=(SELECT isnull(max(isnull(CONTAINERID,0)),0)  FROM dbo.CONTAINER_DETAILS )set @certificateid=(SELECT isnull(max(isnull(CERTIFICATEID,0)),0)  FROM dbo.CERTIFICATE_DETAILS )  
 set @bondid=(SELECT isnull(max(isnull(BONDID,0)),0)  FROM dbo.BOND_DETAILS ) 
 declare @job_P varchar(30),@job_s varchar(30),@jobps varchar(150) ,@Z int  
 dbcc checkident(CONTAINER_DETAILS,reseed,@containerid)  
 dbcc checkident(BOND_DETAILS,reseed,@bondid)  
 dbcc checkident(CERTIFICATE_DETAILS,reseed,@certificateid)  
 
 --======================================
		
		declare @SW_INFO_TYPE_ID as  varchar(50)
		declare @SW_CONST_ID as  varchar(50)
		declare @SW_PROD_ID as  varchar(50)
		declare @SW_CONTROL_ID as  varchar(50)
		declare @SW_STMT_ID as  varchar(50)
		declare @SW_SUP_DOC_ID as bigint
		
select @SW_INFO_TYPE_ID= isnull(max(isnull(SW_INFO_TYPE_ID,0)),0)+1  from BE_ITEM_SW_INFO_TYPE -- SW_INFO_TYPE_ID
select @SW_CONST_ID= isnull(max(isnull(SW_CONST_ID,0)),0)+1  from BE_ITEM_SW_CONST --SW_CONST_ID
select @SW_PROD_ID= isnull(max(isnull(SW_PROD_ID,0)),0)+1  from BE_ITEM_SW_PROD --SW_PROD_ID
select @SW_CONTROL_ID= isnull(max(isnull(SW_CONTROL_ID,0)),0)+1  from BE_ITEM_SW_CONTROL--SW_CONTROL_ID
select @SW_STMT_ID= isnull(max(isnull(SW_ID,0)),0)+1   from IMP_SINGLE_WINDOW_STMT --SW_ID
select @SW_SUP_DOC_ID= isnull(max(isnull(SW_ID,0)),0)+1   from BE_ITEM_SW_SUP_DOC --SW_ID

declare @output_SW_INFO_TYPE nvarchar(Max)
declare @output_SW_CONST nvarchar(Max)
declare @output_SW_PROD nvarchar(Max)
declare @output_CONTROL nvarchar(Max)
declare @output_SW_STMT nvarchar(Max)
declare @output_SW_SUP_DOC nvarchar(Max)

