if(@Working_Period<>'')  
begin  
set @output_S_or_M ='SELECT top 1 MIS_SINGLE_OR_MULITIPLE  FROM '+@DB_Name+'.dbo.INVOICE_DETAILS where JOBNO='+@OLD_JOBNO+' and BRANCH_CODE='''+@Working_Period+''''
insert into @temp_1 exec sp_executesql @output_S_or_M
select @cnt_1=COUNT(*) from @temp_1
if(@cnt_1>0)
begin
         select  @single_multiple= S_or_M  from @temp_1
end

set @Tr_M='SELECT TRANSPORT_MODE  FROM '+@DB_Name+'.dbo.GENERAL_DETAILS where JOBNO='+@OLD_JOBNO+'  and BRANCHCODE='''+@Working_Period+''''
insert into @temp_2 exec sp_executesql @Tr_M

select @cnt_2=COUNT(*) from @temp_2

if(@cnt_2>0)
begin
         select  @TransportMode= Tr_mode  from @temp_2
end


  
