begin set @jobps= @CURRENT_JOBNO end else if(@job_P<>'' and  @job_s='') begin set @jobps= @job_P+'/'+ @CURRENT_JOBNO end else if(@job_P='' and  @job_s<>'') begin
set @jobps=  @CURRENT_JOBNO +'/'+@job_s end else if(@job_P<>'' and  @job_s<>'')begin set @jobps= @job_P+'/'+ @CURRENT_JOBNO +'/'+@job_s end end  else begin set @jobps =@CURRENT_JOBNO
