ALTER PROCEDURE [dbo].[IMP_JOB_DUPLICATE_BRANCH_TO_BRANCH](
 @JOBNO_Old varchar(20),@JOBNO_New varchar(20),@Branch_Old varchar(50),@Branch_New varchar(50),@USER_ID varchar(50)
