,@To_Tr_Mode varchar(20),@CUSTOMS_HOUSE varchar(20),@flag varchar(150),@PORT_ORIGIN varchar(50),@PORT_SHIPMENT varchar(50)
,@Mstatus  int output ,@ErrorMsg nvarchar(max) output
)  
