GO
SET QUOTED_IDENTIFIER ON
GO

ALTER PROCEDURE [dbo].[IMP_JOB_DUPLICATE_BRANCH_TO_BRANCH_COMMON]
				(
                    @JOBNO_Old varchar(20),@JOBNO_New varchar(20),@Branch_Old varchar(50),@Branch_New varchar(50),@USER_ID varchar(50)
                   ,@WORKING_PERIOD varchar(50),@JOB_PREFIX varchar(30) ,@JOB_SUFFIX varchar(30),@JOBNO_PS varchar(50),@PORT_ORIGIN varchar(50),@PORT_SHIPMENT varchar(50)
                   ,@To_Tr_Mode varchar(20),@CUSTOMS_HOUSE varchar(20),@flag varchar(150),@Mstatus  int output ,@ErrorMsg nvarchar(max) output                
			    )  
AS          
begin try                  
begin transaction                  
set @ErrorMsg='' 
 
 if(@flag='IMP_Job_Duplicate_Generate')
 begin
   if not exists(select JOBNO from GENERAL_DETAILS where JOBNO=@JOBNO_New)     
      begin 
           
           insert into  GENERAL_DETAILS select [dbo].IMP_EXP_MAX_ID('GENERAL_DETAILS')+ ROW_NUMBER() OVER(ORDER BY JOBNO DESC)-1,@JOBNO_New
           ,cast(convert (varchar(20), getdate(),102)  as datetime)
           --,TRANSPORT_MODE
           ,@To_Tr_Mode,BE_TYPE,@CUSTOMS_HOUSE,'',IMPORTER_NAME,ADDRESS1,ADDRESS2,ADDRESS3,ADDRESS4,ADDRESS5,IEC_NO,BRANCH_NO,COUNTRY_ORIGIN,@PORT_ORIGIN,@PORT_SHIPMENT,COUNTRY_SHIPMENT,FILING_STATUS,SECTION46
		  ,SECTION46_DESC,FIRSTCHECK,FIRSTCHECK_DESC,GREEN_CHANNEL,GREEN_CHANNEL_DESC,KACHHA_BE,KACHHA_BE_DESC,SECTION48,SECTION48_DESC,HIGH_SEA_SALE,HIGH_SEA_SALE_NAME
		  ,HIGH_SEA_IEC,HIGH_SEA_BRANCH_SL_NO,HSS_ADD1,HSS_ADD2,HSS_ADD3,HSS_ADD4,HSS_ADD5,WAREHOUSE_NAME,WAREHOUSE_CODE,IMP_EXP_TYPE,COMMERCIAL_DETAILS_STATUS
		  ,COMMERCIAL_TAX_STATENAME,COMMERCIAL_TAX_STATECODE,COMMERCIAL_TAX_TYPE,COMMERCIAL_TAX_REGISTRATION_NO,EXBOND_INBOND_BE_NO,EXBOND_INBOND_BE_DATE,EXBOND_BOND_NO
		  ,EXBOND_BOND_DATE,EXBOND_WAREHOUSE_CUSTOMS,EXBOND_WAREHOUSE_CUSTOMS_CODE,EXBOND_NOOFPACKAGE,EXBOND_NOOFPACKAGE_UNITCODE,EXBOND_GROSS_WEIGHT,EXBOND_GROSS_WEIGHT_UNITCODE
		  ,EXBOND_DIRECT_EXBONDING,REMARKS,@USER_ID,getdate(),'N',BRANCHCODE,@WORKING_PERIOD,FILE_REF_NO,CONTAINER_TYPE,JOB_STATUS,JOB_RELEASE,JOB_FILED_STATUS,@USER_ID,getdate()
		  ,@JOB_PREFIX,@JOB_SUFFIX,@JOBNO_PS ,'' ,ADCODE,UCR_NO,UCR_TYPE,PAYMENT_METHOD_CODE,PRECEDING_LEVEL,DOC_RECEIVED_DATE,AGENT_NAME,EXBOND_ADDL_LOAD_HSS
		  ,EXBOND_MISC_LOAD_RATE ,GSTN_TYPE,GSTN_ID,PARTY_REF_NO,ETA from GENERAL_DETAILS where JOBNO=@JOBNO_Old 
           
           insert into BOND_DETAILS select  @JOBNO_New,BOND_NO,BOND_TYPE,BOND_LOCATION,@USER_ID,GETDATE(),'N'
		  ,BRANCH_CODE,year(GETDATE()),@WORKING_PERIOD,@USER_ID,getdate() from BOND_DETAILS where JOBNO =@JOBNO_Old 
           insert into CERTIFICATE_DETAILS select @JOBNO_New ,CERTIFICATE_NO,CERTIFICATE_DATE,CERTIFICATE_TYPE
		  ,@USER_ID,GETDATE(),'N',BRANCH_CODE,year(GETDATE()),@WORKING_PERIOD,@USER_ID,getdate() from CERTIFICATE_DETAILS where JOBNO =@JOBNO_Old 
         
           declare @from_mode varchar(50)
           select @from_mode =TRANSPORT_MODE from GENERAL_DETAILS where JOBNO =@JOBNO_Old 
           if(@from_mode<> @To_Tr_Mode)
           begin
                   if(@from_mode='Air' and @To_Tr_Mode ='Sea')
				   begin
				          insert into IGM_DETAILS select [dbo].IMP_EXP_MAX_ID('IGM_DETAILS')+ ROW_NUMBER() OVER(ORDER BY JOBNO DESC)-1,IGM_SLNO,@JOBNO_New,IGM_JOBDATE,IGM_AIRLINECODE,IGM_AIRLINENAME,IGM_FLIGHTNO_VESSELNO
	 					  ,IGM_FLIGHT_VESSELDATE,IGM_NO,IGM_DATE,IGM_MAWB_MBL,IGM_MAWB_MBLDATE,IGM_HAWB_HBLNO,IGM_HAWB_HBLDATE,IGM_NOOFPACKAGE,IGM_PACKAGETYPE,IGM_GROSSWEIGHT
						  ,IGM_TYPEOFWEIGHT,IGM_NETWEIGHT,IGM_NETWEIGHTTYPE ,@To_Tr_Mode --,IGM_TRANSPORTMODE 
						  ,IGM_MARKSNOS,IGM_GATEWAY_IGM_NO,IGM_GATEWAY_IGM_DATE,IGM_GATEWAY_PORT_CODE,@USER_ID
						  ,GETDATE(),'N',@Branch_New,year(GETDATE()),@WORKING_PERIOD,@USER_ID,getdate() ,IGM_LINE_NUMBER,IGM_SHIPPING_LINE_NUMBER,IGM_VOYAGE,IGM_CHARGEABLE_WGT,ROTATION_NO,ROTATION_DATE from IGM_DETAILS 
						  where JOBNO =@JOBNO_Old 
				          
				           /* insert into CONTAINER_DETAILS select CONTAINER_IGM_SLNO,CONTAINER_IGM_NO,CONTAINER_IGM_DATE,@JOBNO_New
		                   ,CONTAINER_NO,SEAL_NO,FCL_OR_LCL,@USER_ID,GETDATE(),'N',@Branch_New,year(GETDATE()),@WORKING_PERIOD,TYPE,TRUCK_NO,@USER_ID
		                   ,getdate() from CONTAINER_DETAILS  where JOBNO =@JOBNO_Old */
				   end
				   else if(@from_mode='Air' and @To_Tr_Mode ='Land')
				   begin
				          insert into IGM_DETAILS select [dbo].IMP_EXP_MAX_ID('IGM_DETAILS')+ ROW_NUMBER() OVER(ORDER BY JOBNO DESC)-1,IGM_SLNO,@JOBNO_New,IGM_JOBDATE,IGM_AIRLINECODE,IGM_AIRLINENAME,IGM_FLIGHTNO_VESSELNO
	 					  ,IGM_FLIGHT_VESSELDATE,IGM_NO,IGM_DATE,IGM_MAWB_MBL,IGM_MAWB_MBLDATE,IGM_HAWB_HBLNO,IGM_HAWB_HBLDATE,IGM_NOOFPACKAGE,IGM_PACKAGETYPE,IGM_GROSSWEIGHT
