,@JOBNO_New,INVOICE_SLNO,ITEM_SLNO,PRODUCTION_BATCH_IDENTIFIER,PRODUCTION_BATCH_QUANTITY,UNIT_QTY_CODE,DATE_OF_MANUFACTURING,DATE_OF_EXPIRY,BEST_BEFORE,RESIDUAL_SHELF_LIFE_DAYS
,TOTAL_SHELF_LIFE_DAYS,RESIDUAL_SHELF_PERCENT,@USER_ID,GETDATE(),'N',BRANCH_CODE,YEAR,WORKING_PERIOD,null,null from BE_ITEM_SW_PROD where JOBNO=@JOBNO_Old 
insert into dbo.BE_ITEM_SW_CONTROL select [dbo].IMP_EXP_MAX_ID('BE_ITEM_SW_CONTROL')+ ROW_NUMBER() OVER(ORDER BY JOBNO DESC)-1,@JOBNO_New,INVOICE_SLNO,ITEM_SLNO
,CONTROL_TYPE_CODE,CONTROL_LOCATION,CONTROL_START_DATE,CONTROL_END_DATE,CONTROL_RESULT_CODE,CONTROL_RESULT_TEXT,@USER_ID,GETDATE(),'N',BRANCH_CODE,YEAR,WORKING_PERIOD
,null,null from BE_ITEM_SW_CONTROL  where JOBNO=@JOBNO_Old  insert into dbo.IMP_SINGLE_WINDOW_STMT select [dbo].IMP_EXP_MAX_ID('IMP_SINGLE_WINDOW_STMT')+ ROW_NUMBER() OVER(ORDER BY JOBNO DESC)-1
,@JOBNO_New,INVOICE_SLNO,ITEM_SLNO,STMT_DECLARATION_TYPE,STMT_DECLARATION_NUMBER,STMT_DECLARATION_DATE,STMT_TYPE,STMT_CODE,STMT_TEXT,BRANCH_CODE,WORKING_PERIOD
,GETDATE(),@USER_ID,null,null from IMP_SINGLE_WINDOW_STMT where JOBNO=@JOBNO_Old 
 insert into RE_IMPORT_DETAILS  select [dbo].IMP_EXP_MAX_ID('RE_IMPORT_DETAILS')+ ROW_NUMBER() OVER(ORDER BY JOBNO DESC)-1,RE_IMPORT_SLNO,@JOBNO_New,INVOICE_SLNO,INVOICE_NO,ITEM_SLNO,SB_NO
		  ,SB_DATE,PORT_EXPORT,SB_INVOICE_NO,SB_INVOICE__ITEM_NO,NOTN_NO,NOTN_SLNO,EXPORT_FREIGHT,EXPORT_INSURANCE,CUSTOMS_DUTY,EXCISE_DUTY,@USER_ID,getdate(),'N'
		  ,BRANCH_CODE,YEAR(getdate()),@WORKING_PERIOD,@USER_ID,getdate() from RE_IMPORT_DETAILS where JOBNO=@JOBNO_Old 
		  
		  insert into dbo.BE_ITEM_SW_SUP_DOC select 
@JOBNO_New,INVOICE_SLNO,ITEM_SLNO,DECLARATION_TYPE,IMAGE_REF_NUMBER,DOC_TYPE_CODE,DOC_ISSUING_PARTY_CODE,DOC_ISSUING_PARTY_NAME,DOC_ISSUING_PARTY_NAME_ADD1,
DOC_ISSUING_PARTY_NAME_ADD2,DOC_ISSUING_PARTY_CITY,DOC_ISSUING_PARTY_PIN,DOC_REF_NUMBER,PLACE_OF_ISSUE,DOC_ISSUE_DATE,DOC_EXPIRY_DATE,BENEFICIARY_PARTY_CODE,
BENEFICIARY_PARTY_NAME,BENEFICIARY_PARTY_ADDRESS1,BENEFICIARY_PARTY_ADDRESS2,BENEFICIARY_PARTY_CITY,BENEFICIARY_PARTY_PIN,FILE_TYPE,USER_ID,DATE_TIME,
BRANCH_CODE,WORKING_PERIOD,GETDATE(),@USER_ID,null,null,SELECT_TYPE from BE_ITEM_SW_SUP_DOC where JOBNO=@JOBNO_Old 
   
             set @Mstatus=1
       end
          else
              begin
                     set @Mstatus=2
              end
       
end


commit                    
 End try                     
                       
begin catch                      
rollback transaction              
 set @ErrorMsg=error_message()                      
end catch

