ALTER  PROCEDURE [dbo].[IMPORT_WAREHOUSE_EXBOND_DETAILS_DUPLICATE_JOB]
@OLD_JOBNO varchar(35),@CURRENT_JOBNO varchar(35),@ITEM_ID bigint,@INVOICE_SLNO bigint,@ITEM_SLNO bigint,@ITEM_DESCRIPTION varchar(120),@ITEM_QTY varchar(17),@ITEM_QTY_CODE varchar(3),
@BRANCHCODE varchar(20),@Working_Period varchar(30),@USERID varchar(30),@name varchar(300),@Port_Orgin varchar(150),@Port_Shipment varchar(150),@Cus_House varchar(50),
@Tr_Mode varchar(20),@Mstatus  int output,@ErrorMsg nvarchar(max) output ,@JOBNO_PS varchar(50),@JOB_PREFIX varchar(30), @JOB_SUFFIX  varchar(30),@Company_Id varchar(20)
AS begin try begin transaction
set @ErrorMsg=''declare @jobid as bigint declare @igmid as bigint declare @containerid as bigint declare @certificateid as bigint declare @bondid as bigint	declare @invoiceid as bigint
declare @itemid as bigint declare @reimportid as bigint	declare @licenseid as bigint declare @single_multiple varchar(10)declare @multiple_invoiceid as bigint
,@SWID as bigint ,@a_cnt int, @b_cnt int
 
declare @TransportMode as varchar(30) declare @i as int set @jobid=(SELECT isnull(max(isnull(JOBID,0)),0)+1  FROM dbo.GENERAL_DETAILS )set @igmid=(SELECT isnull(max(isnull(IGM_ID,0)),0)+1  FROM dbo.IGM_DETAILS )
set @containerid=(SELECT isnull(max(isnull(CONTAINERID,0)),0)  FROM dbo.CONTAINER_DETAILS )set @certificateid=(SELECT isnull(max(isnull(CERTIFICATEID,0)),0)  FROM dbo.CERTIFICATE_DETAILS )
set @bondid=(SELECT isnull(max(isnull(BONDID,0)),0)  FROM dbo.BOND_DETAILS )


declare @Item_SL int
--CONTAINER Continue Auto No-------------
dbcc checkident(CONTAINER_DETAILS,reseed,@containerid)
--BOND Continue Auto No-------------
dbcc checkident(BOND_DETAILS,reseed,@bondid)
--CERTIFICATE Continue Auto No-------------	
dbcc checkident(CERTIFICATE_DETAILS,reseed,@certificateid)
set @invoiceid=(SELECT isnull(max(isnull(INVOICE_ID,0)),0)+1  FROM dbo.INVOICE_DETAILS )set @multiple_invoiceid=(SELECT isnull(max(isnull(MUITIPLE_ID,0)),0)+1  FROM dbo.MULTIPLE_INVOICE )
set @itemid=(SELECT isnull(max(isnull(ITEM_ID,0)),0)+1  FROM dbo.ITEM_PRODUCT_DETAILS )set @reimportid=(SELECT isnull(max(isnull(RE_IMPORT_ID,0)),0)+1  FROM dbo.RE_IMPORT_DETAILS )
set @licenseid=(SELECT isnull(max(isnull(LICENSE_ID,0)),0)+1  FROM dbo.LICENSE_DETAILS )
declare @Fno varchar(50),@Fileno varchar(30)

if(@Working_Period<>'')
begin 
 set @single_multiple=(SELECT top 1 MIS_SINGLE_OR_MULITIPLE  FROM dbo.INVOICE_DETAILS where JOBNO=@CURRENT_JOBNO and BRANCH_CODE=@Working_Period)
set @TransportMode=(SELECT TRANSPORT_MODE  FROM dbo.GENERAL_DETAILS where JOBNO=@OLD_JOBNO  and BRANCHCODE=@Working_Period)
if(@name='Duplicate_Job')begin
if not exists(SELECT JOBNO  FROM dbo.GENERAL_DETAILS where JOBNO=@CURRENT_JOBNO  and BRANCHCODE=@Working_Period)begin
if(@Company_Id='268' or @Company_Id='479')
begin
	  select @Fno=FILE_REF_NO from GENERAL_DETAILS where JOBNO=@OLD_JOBNO and BE_TYPE ='Warehouse' and isnull(FILE_REF_NO,'')<>'' and BRANCHCODE=@Working_Period
   	  if(isnull(@Fno,'') <>'')
	  begin
	  	    select @Fileno =@Fno +'-'+CAST( COUNT(distinct jobno)+1 as varchar(50)) from ITEM_PRODUCT_DETAILS where isnull(WAREHOUSE_JOBNO,'')<>'' and WAREHOUSE_JOBNO=@OLD_JOBNO and BRANCH_CODE =@Working_Period
	  end
end

insert into dbo.GENERAL_DETAILS select @jobid,cast(@CURRENT_JOBNO as bigint),cast(convert (varchar(20), getdate(),102)  as datetime),TRANSPORT_MODE,'Ex-Bond',CUSTOMS_HOUSE,CUSTOMS_HOUSE_NAME,IMPORTER_NAME,ADDRESS1,ADDRESS2,ADDRESS3,
ADDRESS4,ADDRESS5,IEC_NO,BRANCH_NO,COUNTRY_ORIGIN,PORT_ORIGIN,PORT_SHIPMENT,COUNTRY_SHIPMENT,'Normal',SECTION46,SECTION46_DESC,FIRSTCHECK,FIRSTCHECK_DESC,GREEN_CHANNEL,
GREEN_CHANNEL_DESC,KACHHA_BE,KACHHA_BE_DESC,SECTION48,SECTION48_DESC,HIGH_SEA_SALE,HIGH_SEA_SALE_NAME,HIGH_SEA_IEC,HIGH_SEA_BRANCH_SL_NO,HSS_ADD1,HSS_ADD2,HSS_ADD3,
HSS_ADD4,HSS_ADD5,'Yes',WAREHOUSE_CODE,IMP_EXP_TYPE,COMMERCIAL_DETAILS_STATUS,COMMERCIAL_TAX_STATENAME,COMMERCIAL_TAX_STATECODE,COMMERCIAL_TAX_TYPE,COMMERCIAL_TAX_REGISTRATION_NO,
EXBOND_INBOND_BE_NO,EXBOND_INBOND_BE_DATE,EXBOND_BOND_NO,EXBOND_BOND_DATE,EXBOND_WAREHOUSE_CUSTOMS,EXBOND_WAREHOUSE_CUSTOMS_CODE,EXBOND_NOOFPACKAGE,EXBOND_NOOFPACKAGE_UNITCODE,
