,CONTAINER_TYPE,JOB_STATUS,JOB_RELEASE,'Created',@USERID,GETDATE(),@JOB_PREFIX,@JOB_SUFFIX,@JOBNO_PS,'' ,ADCODE,UCR_NO,UCR_TYPE,PAYMENT_METHOD_CODE,PRECEDING_LEVEL,DOC_RECEIVED_DATE,AGENT_NAME,EXBOND_ADDL_LOAD_HSS
,EXBOND_MISC_LOAD_RATE ,GSTN_TYPE,GSTN_ID,PARTY_REF_NO,ETA from dbo.GENERAL_DETAILS where JOBNO=@OLD_JOBNO and BRANCHCODE=@Working_Period 

end

