			,INDIVITUAL_HSS_AMOUNT
			,IGST_LEVY_NOTN,IGST_LEVY_SLNO,IGST_LEVY_RATE,IGST_LEVY_SPL,IGST_LEVY_UNIT,IGST_LEVY_SPL_TYPE,IGST_LEVY_EXCEPTION_NOTN,IGST_LEVY_EXCEPTION_SLNO,IGST_LEVY_EXCEPTION_RATE
			,IGST_LEVY_COMPENSATION_CESS_NOTN,IGST_LEVY_COMPENSATION_CESS_SLNO,IGST_LEVY_COMPENSATION_CESS_RATE,IGST_LEVY_COMPENSATION_CESS_SPL,IGST_LEVY_COMPENSATION_CESS_UNIT
			,IGST_LEVY_COMPENSATION_CESS_SPL_TYPE,IGST_LEVY_EXCEPTION_CC_NOTN,IGST_LEVY_EXCEPTION_CC_SLNO,IGST_LEVY_EXCEPTION_CC_RATE
			,LEVY_EXCEMPTION_NOTN_TYPE,LEVY_EXCEPTION_CC_NOTN_TYPE,CHECKLIST_IGST_LEVY_AMOUNT,CHECKLIST_COMPENSATION_CC_AMOUNT
			,SOCIAL_WELFARE_NOTN,SOCIAL_WELFARE_NOTN_SLNO,SOCIAL_WELFARE_RATE,CHECKLIST_SOCIAL_WELFARE_AMT
			  from ITEM_PRODUCT_DETAILS where JOBNO=@OLD_JOBNO and ITEM_ID=@ITEM_ID end
			select @Item_SL =ITEM_SLNO from ITEM_PRODUCT_DETAILS where JOBNO=@OLD_JOBNO and ITEM_ID=@ITEM_ID 
			if not exists(SELECT JOBNO  FROM dbo.RE_IMPORT_DETAILS where JOBNO=@CURRENT_JOBNO  AND INVOICE_SLNO=@INVOICE_SLNO AND ITEM_SLNO=@ITEM_SLNO )begin insert into dbo.RE_IMPORT_DETAILS select @reimportid,RE_IMPORT_SLNO,@CURRENT_JOBNO,INVOICE_SLNO,INVOICE_NO,
			ITEM_SLNO,SB_NO,SB_DATE,PORT_EXPORT,SB_INVOICE_NO,SB_INVOICE__ITEM_NO,NOTN_NO,NOTN_SLNO,EXPORT_FREIGHT,EXPORT_INSURANCE,CUSTOMS_DUTY,EXCISE_DUTY,@USERID,GETDATE(),
			'N',@BRANCHCODE,YEAR,WORKING_PERIOD,@USERID,GETDATE() from dbo.RE_IMPORT_DETAILS where JOBNO=@OLD_JOBNO  AND INVOICE_SLNO=@INVOICE_SLNO AND ITEM_SLNO=@ITEM_SLNO end
			if not exists(SELECT JOBNO  FROM dbo.LICENSE_DETAILS where JOBNO=@CURRENT_JOBNO AND INVOICE_SLNO=@INVOICE_SLNO AND ITEM_SLNO=@ITEM_SLNO)begin  insert into dbo.LICENSE_DETAILS select @licenseid,@CURRENT_JOBNO,INVOICE_SLNO,
			ITEM_SLNO,SCHEME_CODE,LICENSE_SLNO,REGISTRATION_NO,REGISTRATION_DATE,EXCEMPTION,DEBIT_AMT,DEBIT_QTY,UNIT_QTY,LICENSE_ITEM_NO,PORT_OF_LICENSE,@USERID,GETDATE(),'N',
			@BRANCHCODE,YEAR,WORKING_PERIOD,DEBIT_DUTY,LICENSE_NO,LICENSE_DATE,@USERID,GETDATE(),TOTAL_CIF_VALUE,TOTAL_DEBIT_DUTY,ENTRY_DEBIT_DUTY,LIC_DESC,LICENSE_CURRENCY, EX_RATE
			from dbo.LICENSE_DETAILS where JOBNO=@OLD_JOBNO AND INVOICE_SLNO=@INVOICE_SLNO AND ITEM_SLNO=@ITEM_SLNO end 


			if not exists(SELECT JOBNO  FROM dbo.BE_ITEM_SW_SUP_DOC where JOBNO=@CURRENT_JOBNO  AND INVOICE_SLNO=@INVOICE_SLNO AND ITEM_SLNO=@ITEM_SLNO)
			begin 
			insert into dbo.BE_ITEM_SW_SUP_DOC select @CURRENT_JOBNO,INVOICE_SLNO,ITEM_SLNO,
			DECLARATION_TYPE,IMAGE_REF_NUMBER,DOC_TYPE_CODE,DOC_ISSUING_PARTY_CODE,DOC_ISSUING_PARTY_NAME,DOC_ISSUING_PARTY_NAME_ADD1,
			DOC_ISSUING_PARTY_NAME_ADD2,DOC_ISSUING_PARTY_CITY,DOC_ISSUING_PARTY_PIN,DOC_REF_NUMBER,PLACE_OF_ISSUE,DOC_ISSUE_DATE,DOC_EXPIRY_DATE,BENEFICIARY_PARTY_CODE,
			BENEFICIARY_PARTY_NAME,BENEFICIARY_PARTY_ADDRESS1,BENEFICIARY_PARTY_ADDRESS2,BENEFICIARY_PARTY_CITY,BENEFICIARY_PARTY_PIN,FILE_TYPE,USER_ID,DATE_TIME,
			BRANCH_CODE,WORKING_PERIOD,GETDATE(),@USERID,null,null,SELECT_TYPE from dbo.BE_ITEM_SW_SUP_DOC where JOBNO=@OLD_JOBNO  AND INVOICE_SLNO=@INVOICE_SLNO AND ITEM_SLNO=@ITEM_SLNO  end 
			
----------------------------------------------------------------------------------------------
select @a_cnt=COUNT(INVOICE_SLNO)  from INVOICE_DETAILS where JOBNO =@CURRENT_JOBNO 
select @b_cnt=min(ITEM_SLNO) from ITEM_PRODUCT_DETAILS where JOBNO =@CURRENT_JOBNO and INVOICE_SLNO=@INVOICE_SLNO 
if(@a_cnt=1 and  @ITEM_SLNO=@b_cnt)
begin
		 SELECT @SWID=isnull(max(isnull(SW_ID,0)),0)+1  FROM IMP_SINGLE_WINDOW_STMT   
         INSERT INTO IMP_SINGLE_WINDOW_STMT (SW_ID,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO ,STMT_TYPE,STMT_CODE,STMT_TEXT
         ,BRANCH_CODE  ,WORKING_PERIOD  ,CREATEDON  ,CREATEDBY )VALUES (  @SWID  ,@CURRENT_JOBNO  ,@INVOICE_SLNO ,@ITEM_SLNO  
         ,'DEC','CUG00','I/We declare that the contents of this Bill of Entry for goods imported against above mentioned Bill of Lading/ Airway Bill /Lorry Receipt/Railway Receipt numbers are in accordance with the above mentioned invoice(s) No(s)and other documents presented herewith.'	,@BRANCHCODE  ,@WORKING_PERIOD  ,getdate()  ,@USERID 	 ) 
          
         SELECT @SWID=isnull(max(isnull(SW_ID,0)),0)+1  FROM IMP_SINGLE_WINDOW_STMT   
         INSERT INTO IMP_SINGLE_WINDOW_STMT (SW_ID,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO ,STMT_TYPE,STMT_CODE,STMT_TEXT
         ,BRANCH_CODE  ,WORKING_PERIOD  ,CREATEDON  ,CREATEDBY )VALUES (  @SWID  ,@CURRENT_JOBNO  ,@INVOICE_SLNO ,@ITEM_SLNO  
         ,'DEC','CUG01','I/We declare that the contents of the above mentioned invoice(s) and documents are true and correct in every respect.I/We have not received and do not know of any other documents or information showing a different description, quantity, price, value, of the said goods and that if at any time hereafter I/We discover any document / information showing different facts, I/We will immediately make the same known to the Commissioner of Customs.'	,@BRANCHCODE  ,@WORKING_PERIOD  ,getdate()  ,@USERID 	 )  
 
end
if(@ITEM_SLNO=@b_cnt)
begin
         SELECT @SWID=isnull(max(isnull(SW_ID,0)),0)+1  FROM IMP_SINGLE_WINDOW_STMT   
         INSERT INTO IMP_SINGLE_WINDOW_STMT (SW_ID,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO ,STMT_TYPE,STMT_CODE,STMT_TEXT
         ,BRANCH_CODE  ,WORKING_PERIOD  ,CREATEDON  ,CREATEDBY )VALUES (  @SWID  ,@CURRENT_JOBNO  ,@INVOICE_SLNO ,@ITEM_SLNO  
         ,'DEC','CUV01','I/We declare that all conditions or restrictions, if any, imposed by the seller of any third party on the disposition or use of the imported goods [as per proviso to Rule 3(2)) of the Customs Valuation Rules, 2007] are specified above.'	,@BRANCHCODE  ,@WORKING_PERIOD  ,getdate()  ,@USERID 	 )  
         
         SELECT @SWID=isnull(max(isnull(SW_ID,0)),0)+1  FROM IMP_SINGLE_WINDOW_STMT   
         INSERT INTO IMP_SINGLE_WINDOW_STMT (SW_ID,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO ,STMT_TYPE,STMT_CODE,STMT_TEXT
         ,BRANCH_CODE  ,WORKING_PERIOD  ,CREATEDON  ,CREATEDBY )VALUES (  @SWID  ,@CURRENT_JOBNO  ,@INVOICE_SLNO ,@ITEM_SLNO  
         ,'DEC','CUV02','I/We declare that the price paid or payable by the importer is as per the details provided above, and any price paid or payable in addition to the above will be settled with the seller at the end of a defined period by means of debit note / credit note (post – import price adjustment), which are as per the contract attached as a supporting document.'	,@BRANCHCODE  ,@WORKING_PERIOD  ,getdate()  ,@USERID 	 )  
         
         SELECT @SWID=isnull(max(isnull(SW_ID,0)),0)+1  FROM IMP_SINGLE_WINDOW_STMT   
         INSERT INTO IMP_SINGLE_WINDOW_STMT (SW_ID,JOBNO  ,INVOICE_SLNO  ,ITEM_SLNO ,STMT_TYPE,STMT_CODE,STMT_TEXT
         ,BRANCH_CODE  ,WORKING_PERIOD  ,CREATEDON  ,CREATEDBY )VALUES (  @SWID  ,@CURRENT_JOBNO  ,@INVOICE_SLNO ,@ITEM_SLNO  
         ,'DEC','CUV03','I/We declare that there are no payments actually paid or payable for the imported goods by way of • cost and services [in terms of Rules 10(1)(a)(i), Rule 10(1)(a)(ii), Rule 10 (1) (a) (iii) and   Rule 10 (1) (b) of Customs Valuation Rules, 2007] • Royalty / Licence Fee / subsequent resale or use of goods /other payment as a condition of sale [(Please see Rule 10 (1) (c), (d) & (e) of Customs Valuation Rules, 2007] other than those declared in the invoice which are mentioned as miscellaneous charges in this Bill of Entry.'	,@BRANCHCODE  ,@WORKING_PERIOD  ,getdate()  ,@USERID 	 )  
end
----------------------------------------------------------------------------------------------

			select @Mstatus=1 end
			select @Mstatus=1 
end
commit
end try
begin catch
rollback transaction
	set @ErrorMsg=error_message()
	set @MStatus=0
end catch

/****** Object:  StoredProcedure [dbo].[IMPORT_WAREHOUSE_EXBOND_DETAILS_DUPLICATE_JOB_BRANCH_TO_BRANCH]    Script Date: 10/12/2018 16:13:45 ******/
