ALTER  PROCEDURE [dbo].[IMPORT_WAREHOUSE_EXBOND_DETAILS_DUPLICATE_JOB_BRANCH_TO_BRANCH]
@OLD_JOBNO varchar(35),	@CURRENT_JOBNO varchar(35),	@ITEM_ID bigint,@INVOICE_SLNO bigint,@ITEM_SLNO bigint,	@ITEM_DESCRIPTION varchar(120),	@ITEM_QTY varchar(17),
@ITEM_QTY_CODE varchar(3),@BRANCHCODE varchar(20),@Working_Period varchar(30),@USERID varchar(30),@name varchar(300),@Port_Orgin varchar(150),@Port_Shipment varchar(150),
@Cus_House varchar(50),@Tr_Mode varchar(20),@Mstatus  int output,@ErrorMsg nvarchar(max) output  ,@JOBNO_PS varchar(50),@JOB_PREFIX varchar(30), @JOB_SUFFIX  varchar(30),@Company_Id varchar(20)
AS
begin try
	begin transaction
set @ErrorMsg='' declare @Item_SL int  declare @jobid as bigint declare @igmid as bigint declare @containerid as bigint declare @certificateid as bigint declare @bondid as bigint
declare @invoiceid as bigint declare @itemid as bigint declare @reimportid as bigint declare @licenseid as bigint declare @single_multiple varchar(10)declare @multiple_invoiceid as bigint
declare @TransportMode as varchar(30)  declare @i as int set @jobid=(SELECT isnull(max(isnull(JOBID,0)),0)+1  FROM dbo.GENERAL_DETAILS )set @igmid=(SELECT isnull(max(isnull(IGM_ID,0)),0)+1  FROM dbo.IGM_DETAILS )
set @containerid=(SELECT isnull(max(isnull(CONTAINERID,0)),0)  FROM dbo.CONTAINER_DETAILS )set @certificateid=(SELECT isnull(max(isnull(CERTIFICATEID,0)),0)  FROM dbo.CERTIFICATE_DETAILS )
set @bondid=(SELECT isnull(max(isnull(BONDID,0)),0)  FROM dbo.BOND_DETAILS )


declare @SWID as bigint ,@a_cnt int, @b_cnt int

declare @SW_INFO_TYPE_ID bigint,@SW_CONST_ID bigint, @SW_PROD_ID bigint ,@SW_CONTROL_ID bigint ,@SW_STMT_ID bigint
select @SW_INFO_TYPE_ID= isnull(max(isnull(SW_INFO_TYPE_ID,0)),0)+1  from BE_ITEM_SW_INFO_TYPE -- SW_INFO_TYPE_ID
select @SW_CONST_ID= isnull(max(isnull(SW_CONST_ID,0)),0)+1  from BE_ITEM_SW_CONST --SW_CONST_ID
select @SW_PROD_ID= isnull(max(isnull(SW_PROD_ID,0)),0)+1  from BE_ITEM_SW_PROD --SW_PROD_ID
select @SW_CONTROL_ID= isnull(max(isnull(SW_CONTROL_ID,0)),0)+1  from BE_ITEM_SW_CONTROL--SW_CONTROL_ID
select @SW_STMT_ID= isnull(max(isnull(SW_ID,0)),0)+1   from IMP_SINGLE_WINDOW_STMT --SW_ID
dbcc checkident(CONTAINER_DETAILS,reseed,@containerid)
dbcc checkident(BOND_DETAILS,reseed,@bondid)
dbcc checkident(CERTIFICATE_DETAILS,reseed,@certificateid)
set @invoiceid=(SELECT isnull(max(isnull(INVOICE_ID,0)),0)+1  FROM dbo.INVOICE_DETAILS )set @multiple_invoiceid=(SELECT isnull(max(isnull(MUITIPLE_ID,0)),0)+1  FROM dbo.MULTIPLE_INVOICE )
set @itemid=(SELECT isnull(max(isnull(ITEM_ID,0)),0)+1  FROM dbo.ITEM_PRODUCT_DETAILS )set @reimportid=(SELECT isnull(max(isnull(RE_IMPORT_ID,0)),0)+1  FROM dbo.RE_IMPORT_DETAILS )
set @licenseid=(SELECT isnull(max(isnull(LICENSE_ID,0)),0)+1  FROM dbo.LICENSE_DETAILS ) declare @Fno varchar(50),@Fileno varchar(30)
if(@Working_Period<>'')begin   set @single_multiple=(SELECT top 1 MIS_SINGLE_OR_MULITIPLE  FROM dbo.INVOICE_DETAILS where JOBNO=@CURRENT_JOBNO and BRANCH_CODE=@BRANCHCODE)
set @TransportMode=(SELECT TRANSPORT_MODE  FROM dbo.GENERAL_DETAILS where JOBNO=@OLD_JOBNO  and BRANCHCODE=@BRANCHCODE) if(@name='Duplicate_Job_Branch_TO_Branch')
begin if not exists(SELECT JOBNO  FROM dbo.GENERAL_DETAILS where JOBNO=@CURRENT_JOBNO  and BRANCHCODE=@BRANCHCODE) begin
if(@Company_Id='268')
begin
	  select @Fno=FILE_REF_NO from GENERAL_DETAILS where JOBNO=@OLD_JOBNO and BE_TYPE ='Warehouse' and isnull(FILE_REF_NO,'')<>'' and BRANCHCODE=@Working_Period
   	  if(isnull(@Fno,'') <>'')
	  begin
	  	    select @Fileno =@Fno +'-'+CAST( COUNT(distinct jobno)+1 as varchar(50)) from ITEM_PRODUCT_DETAILS where isnull(WAREHOUSE_JOBNO,'')<>'' and WAREHOUSE_JOBNO=@OLD_JOBNO and BRANCH_CODE =@Working_Period
	  end
end
insert into dbo.GENERAL_DETAILS select @jobid,cast(@CURRENT_JOBNO as bigint)
,cast(convert (varchar(20), getdate(),102)  as datetime)
,@Tr_Mode,'Ex-Bond',@Cus_House,@BRANCHCODE,IMPORTER_NAME,ADDRESS1,ADDRESS2,ADDRESS3,
ADDRESS4,ADDRESS5,IEC_NO,BRANCH_NO,COUNTRY_ORIGIN,@Port_Orgin,@Port_Shipment,COUNTRY_SHIPMENT,'Normal',SECTION46,SECTION46_DESC,FIRSTCHECK,FIRSTCHECK_DESC,
GREEN_CHANNEL,GREEN_CHANNEL_DESC,KACHHA_BE,KACHHA_BE_DESC,SECTION48,SECTION48_DESC,HIGH_SEA_SALE,HIGH_SEA_SALE_NAME,HIGH_SEA_IEC,HIGH_SEA_BRANCH_SL_NO,HSS_ADD1,
HSS_ADD2,HSS_ADD3,HSS_ADD4,HSS_ADD5,'Yes',WAREHOUSE_CODE,IMP_EXP_TYPE,COMMERCIAL_DETAILS_STATUS,COMMERCIAL_TAX_STATENAME,COMMERCIAL_TAX_STATECODE,COMMERCIAL_TAX_TYPE,
COMMERCIAL_TAX_REGISTRATION_NO,EXBOND_INBOND_BE_NO,EXBOND_INBOND_BE_DATE,EXBOND_BOND_NO,EXBOND_BOND_DATE,EXBOND_WAREHOUSE_CUSTOMS,EXBOND_WAREHOUSE_CUSTOMS_CODE,
EXBOND_NOOFPACKAGE,EXBOND_NOOFPACKAGE_UNITCODE,EXBOND_GROSS_WEIGHT,EXBOND_GROSS_WEIGHT_UNITCODE,EXBOND_DIRECT_EXBONDING,REMARKS,@USERID,GETDATE(),'N',@BRANCHCODE,
WORKINGPERIOD,(case when isnull(@Fileno,'')<>'' then @Fileno else FILE_REF_NO end),CONTAINER_TYPE,JOB_STATUS,JOB_RELEASE,'Created',@USERID,GETDATE(),@JOB_PREFIX,@JOB_SUFFIX,@JOBNO_PS,'',ADCODE,UCR_NO,UCR_TYPE,PAYMENT_METHOD_CODE,PRECEDING_LEVEL,DOC_RECEIVED_DATE,AGENT_NAME,EXBOND_ADDL_LOAD_HSS
,EXBOND_MISC_LOAD_RATE ,GSTN_TYPE,GSTN_ID,PARTY_REF_NO,ETA  from dbo.GENERAL_DETAILS where JOBNO=@OLD_JOBNO and BRANCHCODE=@Working_Period end
if not exists(SELECT JOBNO  FROM dbo.IGM_DETAILS where JOBNO=@CURRENT_JOBNO  and IGM_BRANCH_CODE=@BRANCHCODE)begin insert into dbo.IGM_DETAILS select @igmid,
IGM_SLNO,@CURRENT_JOBNO,IGM_JOBDATE,IGM_AIRLINECODE,IGM_AIRLINENAME,IGM_FLIGHTNO_VESSELNO,IGM_FLIGHT_VESSELDATE,IGM_NO,IGM_DATE,IGM_MAWB_MBL,IGM_MAWB_MBLDATE,IGM_HAWB_HBLNO,
IGM_HAWB_HBLDATE,IGM_NOOFPACKAGE,IGM_PACKAGETYPE,IGM_GROSSWEIGHT,IGM_TYPEOFWEIGHT,IGM_NETWEIGHT,IGM_NETWEIGHTTYPE,@Tr_Mode,IGM_MARKSNOS,IGM_GATEWAY_IGM_NO,
IGM_GATEWAY_IGM_DATE,IGM_GATEWAY_PORT_CODE,@USERID,GETDATE(),'N',@BRANCHCODE,IGM_YEAR,IGM_WORKING_PERIOD,@USERID,GETDATE() ,IGM_LINE_NUMBER,IGM_SHIPPING_LINE_NUMBER,IGM_VOYAGE,IGM_CHARGEABLE_WGT,ROTATION_NO,ROTATION_DATE from dbo.IGM_DETAILS where JOBNO=@OLD_JOBNO and IGM_BRANCH_CODE=@Working_Period end
if not exists(SELECT JOBNO  FROM dbo.BOND_DETAILS where JOBNO=@CURRENT_JOBNO  and BRANCH_CODE=@BRANCHCODE)begin insert into dbo.BOND_DETAILS select @CURRENT_JOBNO,
BOND_NO,BOND_TYPE,BOND_LOCATION,@USERID,GETDATE(),'N',@BRANCHCODE,YEAR,WORKING_PERIOD,@USERID,GETDATE() from dbo.BOND_DETAILS where JOBNO=@OLD_JOBNO and BRANCH_CODE=@Working_Period end
if not exists(SELECT JOBNO  FROM dbo.CERTIFICATE_DETAILS where JOBNO=@CURRENT_JOBNO  and BRANCH_CODE=@BRANCHCODE)
begin insert into dbo.CERTIFICATE_DETAILS select @CURRENT_JOBNO,CERTIFICATE_NO,CERTIFICATE_DATE,CERTIFICATE_TYPE,@USERID,GETDATE(),'N',@BRANCHCODE,YEAR,WORKING_PERIOD,
@USERID,GETDATE() from dbo.CERTIFICATE_DETAILS where JOBNO=@OLD_JOBNO and BRANCH_CODE=@Working_Period  end
if not exists (select null  from dbo.INVOICE_DETAILS where JOBNO=@CURRENT_JOBNO and INVOICE_SLNO=@INVOICE_SLNO and BRANCH_CODE=@BRANCHCODE)
begin insert into dbo.INVOICE_DETAILS select @invoiceid,@CURRENT_JOBNO,INVOICE_SLNO,INVOICE_NO,INVOICE_DATE,TERMS,INVOICE_CURRENCY,INVOICE_EXRATE,INVOICE_VALUE,
SUPPLIER_NAME,SUPPLIER_ADDRESS,SUPPLIER_ADDRESS1,SUPPLIER_ADDRESS2,SUPPLIER_COUNTRY_NAME,SUPPLIER_COUNTRY_CODE,SUPPLIER_COUNTRY_PINCODE,SELLER_NAME,SELLER_ADDRESS,
SELLER_ADDRESS1,SELLER_ADDRESS2,SELLER_COUNTRY_NAME,SELLER_COUNTRY_CODE,SELLERCOUNTRY_PINCODE,BROKER_NAME,BROKER_ADDRESS,BROKER_ADDRESS1,BROKER_ADDRESS2,BROKER_COUNTRY_NAME,
BROKER_COUNTRY_CODE,BROKER_COUNTRY_PINCODE,MIS_CHARGES,MIS_RATE,MIS_CURRENCY,MIS_EXRATE,MIS_AGENCY_CHARGES,MIS_AGENCY_RATE,MIS_AGENCY_CURRENCY,MIS_AGENCY_EXRATE,
MIS_DISCOUNT_CHARGES,MIS_DISCOUNT_RATE,MIS_DISCOUNT_CURRENCY,MIS_DISCOUNT_EXRATE,MIS_DISCOUNT_REASON,MIS_LOADING_CHARGES,MIS_LOADING_RATE,MIS_LOADING_CURRENCY,
MIS_LOADING_EXRATE,MIS_FREIGHT_CHARGES,MIS_FREIGHT_RATE,MIS_FREIGHT_CURRENCY,MIS_FREIGHT_EXRATE,MIS_INSURANCE_CHARGES,MIS_INSURANCE_RATE,MIS_INSURANCE_CURRENCY,
MIS_INSURANCE_EXRATE,MIS_HIGHSEASALE_CHARGES,MIS_HIGHSEASALE_RATE,MIS_HIGHSEASALE_CURRENCY,MIS_HIGHSEASALE_EXRATE,MIS_SINGLE_OR_MULITIPLE,SVB_RELATION,SVB_REF_NO,
SVB_REF_DATE,SVB_CUSTOM_HOUSE,SVB_LOADING_ON,SVB_ASSESABLE_RATE,SVB_DUTY_RATE,SVB_ASSESABLE_STATUS,SVB_DUTY_STATUS,OTHER_PURCHASE_ORDER,OTHER_PURCHASE_ORDER_DATE,
OTHER_CONTRACT_NO,OTHER_CONTRACT_DATE,OTHER_LOC_NO,OTHER_LOC_DATE,OTHER_NATURE_OF_TRANSACTION,OTHER_TERMS_OF_PAYMENT,OTHER_CONDITIONS,OTHER_VALUATION_METHOD,@USERID,
GETDATE(),'N',@BRANCHCODE,YEAR,WORKING_PERIOD,NON_STD_EFFECT_DT_IMP,NON_STD_BANKNAME,NON_STD_CERTIFICATE_NO,NON_STD_CERTIFICATE_DATE,SAP_DELIEVERY_ID,SHIP_DATE,
INVOICE_LEVEL,COUNTRY_OF_DEPARTURE,REVENUEDEPOSIT_RATE,REVENUEDEPOSIT_ON,MI_FREIGHT,MI_INSURANCE,MI_MISC,MI_HSS,@USERID,GETDATE(),INDEV_INV_TYPE,TERMS_PLACE,
THIRDPARTY_NAME,THIRDPARTY_ADD1,THIRDPARTY_ADD2,THIRDPARTY_CITY,T_PARTY_COUNTRY_SUB_DIV,T_PARTY_COUNTRY_CODE,T_PARTY_PIN,AUTHORIZED_ECONOMIC_OPERATOR_CODE,
A_E_O_COUNTRY,AUTHORIZED_ECONOMIC_OPERATOR,WHETHER_BUYER_SELLER_RELATED
,A_AMOUNT,B_AMOUNT,C_AMOUNT,D_AMOUNT,E_AMOUNT,F_AMOUNT,G_AMOUNT,H_AMOUNT,I_AMOUNT,J_AMOUNT,K_AMOUNT,L_AMOUNT,M_AMOUNT,N_AMOUNT,TOTAL_OTHER_AMOUNT,DOC_RECD_DATE
 from dbo.INVOICE_DETAILS where JOBNO=@OLD_JOBNO and INVOICE_SLNO=@INVOICE_SLNO and BRANCH_CODE=@Working_Period
 end
 if(@single_multiple='M') begin if not exists(SELECT MULTIPLE_JOBNO  FROM dbo.MULTIPLE_INVOICE where MULTIPLE_JOBNO=@CURRENT_JOBNO  and BRANCH_CODE=@BRANCHCODE)
begin INSERT INTO dbo.MULTIPLE_INVOICE select @multiple_invoiceid ,@CURRENT_JOBNO,MULTIPLE_FRIEGHT_CURRENCY,MULTIPLE_FRIEGHT_EXCH_RATE,MULTIPLE_FRIEGHT_RATE,MULTIPLE_FRIEGHT_AMOUNT
,MULTIPLE_INSURANCE_CURRENCY,MULTIPLE_INSURANCE_EXCH_RATE,MULTIPLE_INSURANCE_RATE,MULTIPLE_INSURANCE_AMOUNT,USER_ID,DATE_TIME,STATUS,BRANCH_CODE,YEAR,WORKING_PERIOD
,MULTIPLE_MISC_AMT,MULTIPLE_HSS_AMT,@USERID,GETDATE() from dbo.MULTIPLE_INVOICE where MULTIPLE_JOBNO=@OLD_JOBNO and BRANCH_CODE=@Working_Period
end
     end
if not exists(SELECT JOBNO  FROM dbo.ITEM_PRODUCT_DETAILS where JOBNO=@CURRENT_JOBNO and  INVOICE_SLNO=@INVOICE_SLNO and ITEM_SLNO=@ITEM_SLNO and BRANCH_CODE=@BRANCHCODE)
