if(@BRANCH_COMMON<>'')  
begin  
				set @output_S_or_M ='SELECT top 1 MIS_SINGLE_OR_MULITIPLE  FROM '+@DB_Name+'.dbo.INVOICE_DETAILS where JOBNO='+@OLD_JOBNO+' and BRANCH_CODE='''+@BRANCH_COMMON+''''
				insert into @temp_1 exec sp_executesql @output_S_or_M
				select @cnt_1=COUNT(*) from @temp_1
				if(@cnt_1>0)
				begin
						 select  @single_multiple= S_or_M  from @temp_1
				end

				set @Tr_M='SELECT TRANSPORT_MODE  FROM '+@DB_Name+'.dbo.GENERAL_DETAILS where JOBNO='+@OLD_JOBNO+'  and BRANCHCODE='''+@BRANCH_COMMON+''''
				insert into @temp_2 exec sp_executesql @Tr_M

				select @cnt_2=COUNT(*) from @temp_2

				if(@cnt_2>0)
				begin
						 select  @TransportMode= Tr_mode  from @temp_2
				end

				-------------File_Refno-------------------------------------------
				select @Fno=FILE_REF_NO from GENERAL_DETAILS where JOBNO=@OLD_JOBNO and BE_TYPE ='Warehouse' and isnull(FILE_REF_NO,'')<>''
				and BRANCHCODE=@BRANCH_COMMON
   				if(isnull(@Fno,'') <>'')
				begin
					  insert into @temp_cnt select CAST( COUNT(distinct jobno) as varchar(50)) from ITEM_PRODUCT_DETAILS 
	  				  where isnull(WAREHOUSE_JOBNO,'')<>'' and WAREHOUSE_JOBNO=@OLD_JOBNO and BRANCH_CODE =@BRANCH_COMMON
	  				  
	  				  set @Old_wrk_Query='SELECT CAST( COUNT(distinct jobno) as varchar(50))  FROM '+@DB_Name+'.dbo.ITEM_PRODUCT_DETAILS 
	  				  where isnull(WAREHOUSE_JOBNO,'''')<>'''' and WAREHOUSE_JOBNO='+@OLD_JOBNO+'  and BRANCH_CODE='''+@BRANCH_COMMON+''''
	  				 
				      insert into @temp exec sp_executesql @Old_wrk_Query
	  				  select @Fileno =@Fno +'-'+CAST(SUM(Jobcnt)+1  as varchar(50)) from @temp_cnt
				 end
				--------------------------------------------------------

				  
				if(@Flag ='Duplicate_Job')  
				begin 
				 
				 if not exists(SELECT JOBNO  FROM dbo.GENERAL_DETAILS where JOBNO=@CURRENT_JOBNO  and BRANCHCODE=@BRANCH_COMMON)  begin   select @Z=COUNT(JOB_PREFIX) from IMPORT_JOB_INITIALIZATION where BRANCH_CODE=@BRANCH_COMMON
				if(@Z>0) begin select  @job_P =isnull(JOB_PREFIX,''),@job_s=isnull(JOB_SUFFIX,'') from IMPORT_JOB_INITIALIZATION where BRANCH_CODE=@BRANCH_COMMON if(@job_P='' and  @job_s='')
				begin set @jobps= @CURRENT_JOBNO end else if(@job_P<>'' and  @job_s='') begin set @jobps= @job_P+'/'+ @CURRENT_JOBNO end else if(@job_P='' and  @job_s<>'') begin
				set @jobps=  @CURRENT_JOBNO +'/'+@job_s end else if(@job_P<>'' and  @job_s<>'')begin set @jobps= @job_P+'/'+ @CURRENT_JOBNO +'/'+@job_s end end  else begin set @jobps =@CURRENT_JOBNO
				set @job_P=''set @job_s='' end  set @jobid_D= @jobid set @output_GEN='select '+@jobid_D+','+@CURRENT_JOBNO+',cast(convert (varchar(20), getdate(),102)  as datetime),  
				TRANSPORT_MODE, '''+ 'Ex-Bond'  +''' ,CUSTOMS_HOUSE,CUSTOMS_HOUSE_NAME,IMPORTER_NAME,ADDRESS1,ADDRESS2,ADDRESS3,ADDRESS4,ADDRESS5,IEC_NO,BRANCH_NO,COUNTRY_ORIGIN,PORT_ORIGIN,PORT_SHIPMENT,
				COUNTRY_SHIPMENT,FILING_STATUS,SECTION46,SECTION46_DESC,FIRSTCHECK,FIRSTCHECK_DESC,GREEN_CHANNEL,GREEN_CHANNEL_DESC,KACHHA_BE,KACHHA_BE_DESC,SECTION48,SECTION48_DESC,
				HIGH_SEA_SALE,HIGH_SEA_SALE_NAME,HIGH_SEA_IEC,HIGH_SEA_BRANCH_SL_NO,HSS_ADD1,HSS_ADD2,HSS_ADD3,HSS_ADD4,HSS_ADD5,WAREHOUSE_NAME,WAREHOUSE_CODE,IMP_EXP_TYPE,COMMERCIAL_DETAILS_STATUS,
				COMMERCIAL_TAX_STATENAME,COMMERCIAL_TAX_STATECODE,COMMERCIAL_TAX_TYPE,COMMERCIAL_TAX_REGISTRATION_NO,EXBOND_INBOND_BE_NO,EXBOND_INBOND_BE_DATE,EXBOND_BOND_NO,EXBOND_BOND_DATE,
				EXBOND_WAREHOUSE_CUSTOMS,EXBOND_WAREHOUSE_CUSTOMS_CODE,EXBOND_NOOFPACKAGE,EXBOND_NOOFPACKAGE_UNITCODE,EXBOND_GROSS_WEIGHT,EXBOND_GROSS_WEIGHT_UNITCODE,EXBOND_DIRECT_EXBONDING,
				REMARKS,'''+@USERID+''',GETDATE(),'''+ 'N' +''',BRANCHCODE,'''+@Current_Working_Period+'''
