ALTER procedure  [dbo].[EXP_CUSTOMIZATION_RPT_BRANCH]
 (   
   @jobno varchar(10),@from_date varchar(20),@to_date varchar(20),@Branch varchar(50),@Report_Name varchar(50),@Report_Name_id varchar(50)  
  ,@Orderby varchar(50),@Rpt_Type  varchar(50),@Exp_name varchar(200),@ErrorMsg nvarchar(max) output ,@Mstatus  int output             
  )                      
as                       
begin try                    
  begin transaction                      
  set @ErrorMsg='' 

/*
  DECLARE @jobno varchar(10)
  DECLARE @from_date varchar(20)
  DECLARE @to_date varchar(20)
  DECLARE @Branch varchar(50)
  DECLARE @Report_Name varchar(50)
  DECLARE @Report_Name_id varchar(50)
  DECLARE @Orderby varchar(50)
  DECLARE @Rpt_Type varchar(50)
  DECLARE @Exp_name varchar(200)
  DECLARE @ErrorMsg nvarchar(max)
  DECLARE @Mstatus  int
  
  set @ErrorMsg=''
  --SET @Rpt_Type ='Item's
  set @from_date=''
  set @to_date=''
  set @Exp_name=''
  
  SET @Rpt_Type ='Jobno'
  --SET @Rpt_Type ='Invoice'
  --SET @Rpt_Type ='Item'
  --set @Rpt_Type='Container'
  set @jobno=''
  set @Branch='ACC, Chennai'
  --set @Branch='CusHouse, Chennai'
  
  set @Report_Name='EKTA_EXPORT'
  set @Report_Name_id=21
  set @Orderby='Asc'
*/

declare @Tr_mode varchar(20)declare @REPORT_COLUMN_NAME nvarchar(max) declare @jobno_cond nvarchar(max)declare @jobdate_cond nvarchar(max)declare @Importername_Cond nvarchar(max)        
declare @Condition varchar(max)declare @mode_condition nvarchar(max)declare @output_Job nvarchar(max)declare @jobdate varchar(20)declare @Branch_Condition nvarchar(max)declare @Exp_name_cond nvarchar(max)  
select @Tr_mode=TR_MODE ,@REPORT_COLUMN_NAME=REPORT_COLUMN_NAME from TEMPLATE_TABLE where TEMPLATE_NAME=@Report_Name and T_ID=@Report_Name_id and ACTIVE='Yes'

if(@from_date <>'' or @to_date <>'') begin if(@from_date <>'' and @to_date <>'')          
  begin         
       set @jobdate_cond= ' cast(convert(varchar,JOBDATE,101)as datetime) between cast(''' + @from_date + ''' as datetime) and cast(''' + @to_date + ''' as datetime)'          
       set @jobdate=@from_date end else begin if(@from_date <>'')begin          
       set @jobdate_cond=' cast(convert(varchar,JOBDATE,101)as datetime) between cast(''' + @from_date + ''' as datetime) and getdate()'set @jobdate=@from_date end if(@to_date <>'') begin          
	   set @jobdate_cond=' cast(CONVERT(varchar,JOBDATE,101)as datetime)=cast(''' + @to_date + ''' as datetime)'          
       set @jobdate=@to_date end end          
  end          
if(@from_date ='' and @to_date ='')begin set @jobdate='' end if(@Branch<>'')begin set @Branch_Condition=' BRANCHCODE='''+@Branch+''''end if(@jobno<>'')begin set @jobno_cond=' jobno='''+@jobno+'''' end if(@Exp_name<>'')
begin
     set @Exp_name_cond=' EXPORTER_NAME='''+@Exp_name+''''    
end
if(@jobdate='' and @jobno='' and @Branch<>'' and @Exp_name='' ) begin set @Condition= ' where '+@Branch_Condition  end if(@jobdate='' and @jobno='' and @Branch<>'' and @Exp_name<>'' )    
begin    
      set @Condition= ' where '+@Branch_Condition +' and '+@Exp_name_cond end if(@jobdate='' and @jobno<>'' and @Branch<>'' and @Exp_name='' ) begin    
      set @Condition= ' where '+@Branch_Condition +' and '+@jobno_cond end if(@jobdate<>'' and @jobno='' and @Branch<>'' and @Exp_name='' ) begin    
      set @Condition= ' where '+@Branch_Condition +' and '+@jobdate_cond end if(@jobdate<>'' and @jobno<>'' and @Branch<>'' and @Exp_name='' ) begin    
      set @Condition= ' where '+@Branch_Condition +' and '+@jobdate_cond +' and '+@jobno_cond end if(@jobdate<>'' and @jobno='' and @Branch<>'' and @Exp_name<>'' ) begin    
      set @Condition= ' where '+@Branch_Condition +' and '+@jobdate_cond +' and '+@Exp_name_cond end if(@jobdate='' and @jobno<>'' and @Branch<>'' and @Exp_name<>'' )begin    
      set @Condition= ' where '+@Branch_Condition +' and '+@jobdate_cond +' and '+@Exp_name_cond +' and '+@jobno_cond end if(@jobdate<>'' and @jobno<>'' and @Branch<>'' and @Exp_name<>'' )begin    
      set @Condition= ' where '+@Branch_Condition +' and '+@jobdate_cond +' and '+@Exp_name_cond +' and '+@jobno_cond +' and '+@jobdate_cond end if(@Condition='') begin  set @Condition= '' 
      set @mode_condition= ' Where TRANSPORT_MODE='''+@Tr_mode+'''' end else begin set @mode_condition= ' and TRANSPORT_MODE='''+@Tr_mode+''''
end
declare @Query_Job nvarchar(max) set @Condition= @Condition + @mode_condition declare @temp_job table ( Id int identity(1,1), Jobno bigint, Branch_Code varchar(200))
set @Query_Job ='select jobno ,BRANCHCODE FROM EXPORT_GENERAL_DETAILS ' 
set @output_Job=@Query_Job+@Condition 


if(@Rpt_Type ='SBNO')
begin
