	  insert into @temp_job_SB exec sp_executesql @output_Job  
	  insert into @temp_job select SB_JOBNO,@Branch from EXPORT_SB_ENTRY where SB_JOBNO in(select Jobno from @temp_job_SB) and BRANCH_CODE=@Branch
end
