select @ANX_Air=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and   COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_ANNEXURE_C_AIR'	select 
