@ANX_S_PKG=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ','))and TABLE_NAME='EXPORT_ANNEXURE_C_SEA_PACKAGE' select 
@AR4=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_AR4_TBL' select 
@ITEM=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_ITEM_DETAILS' select 
@DRAWBACK=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_DRAWBACK_DETAILS'select 
@JOBBING=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_JOBBING'  select 
@LIC=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_LICENSE_DETAILS' select 
@ANX_C1=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='ANNEXURE_C1_DETAILS' select 
