,ANNEX_AIR_TOTAL_PACKAGES,ANNEX_AIR_UNIT_CODE,ANNEX_AIR_FREIGHT_AMT,ANNEX_AIR_INSURANCE_AMT,ANNEX_AIR_GROSS_WEIGHT,ANNEX_AIR_GR_UNIT_CODE,ANNEX_AIR_NET_WEIGHT
,ANNEX_AIR_MAWB_NO,ANNEX_AIR_HAWB_NO,ANNEX_AIR_TOTAL_PACKAGES_MAWB,ANNEX_AIR_ROTATION_NO,ANNEX_AIR_ROTATION_DATE,ANNEX_AIR_FOB_VALUE,BRANCH_CODE from EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO  in(select Jobno from @temp_job )and BRANCH_CODE=@Branch
