,b.ANNEX_SEA_CON_TYPE,b.ANNEX_SEA_CON_EXCISE_SEALNO,b.ANNEX_SEA_CON_SEAL_DATE,b.BRANCH_CODE from summary_SEA_CONTAINER a inner join EXPORT_ANNEXURE_C_SEA_CONTAINER b 
