end 
if(@Rpt_Type ='Jobno' OR @Rpt_Type ='Container' or @Rpt_Type ='SBNO') begin 

;with summary_INV as( select JOBNO ,MIN(INVOICE_SLNO)INVOICE_SLNO  from EXPORT_INVOICE_DETAILS where BRANCH_CODE=@Branch group by JOBNO)
insert into @temp_INV select  b.* from summary_INV a inner join   (select * from dbo.EXP_INV_DYNAMIC_RPT_BRANCH
((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') ),@Branch))b
on a.JOBNO =b.JOBNO and a.INVOICE_SLNO =b.INVOICE_SLNO  and a.JOBNO  in (select Jobno from @temp_job ) and b.BRANCH_CODE=@Branch  
						
 end
 
 else if(@Rpt_Type ='Invoice' or @Rpt_Type ='Item')
begin
     insert into @temp_INV select * from dbo.EXP_INV_DYNAMIC_RPT_BRANCH((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') ),@Branch)
end
	
