if(@AR4>0) begin ;with summary_AR4 as( select AR4_JOBNO ,MIN(AR4_INVOICE_SLNO)INVOICE_SLNO,MIN(AR4_ID) AR4_ID from EXPORT_AR4_TBL where BRANCH_CODE=@Branch  group by AR4_JOBNO)   
