insert into @temp_Item select b.* from summary_Item a inner join (select * from dbo.EXP_ITEM_DYNAMIC_RPT_BRANCH
((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') ),@Branch))b on a.JOBNO =b.JOBNO 
and a.ITEM_SLNO=b.ITEM_SLNO	 and a.JOBNO in (select Jobno from @temp_job) and  BRANCH_CODE=@Branch 

