((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') ),@Branch))b
on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO and a.ITEM_SLNO=b.ITEM_SLNO and a.JOBNO in (select Jobno from @temp_job ) and b.BRANCH_CODE=@Branch
declare @temp_sum_Item table (ID int identity(1,1) ,JOBNO bigint ,INVOICE_SLNO varchar(50),ITEM_QTY varchar(50),ITEM_UNIT_PRICE varchar(50),ITEM_AMOUNT varchar(50)
,PMV_VALUE varchar(50),FOB_VALUE varchar(50),DRAWBACK_VALUE varchar(50),BRANCH_CODE varchar(50)) insert into @temp_sum_Item select JOBNO ,INVOICE_SLNO ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ITEM_QTY,'') =''  
	                               THEN   '0' else ISNULL(ITEM_QTY,'0') end)),0)   ITEM_QTY  ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN 
	                               ISNULL(ITEM_UNIT_PRICE,'') =''  THEN   '0' else ISNULL(ITEM_UNIT_PRICE,'0') end)),0) ITEM_UNIT_PRICE ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ITEM_AMOUNT,'') =''  THEN   '0' else ISNULL(ITEM_AMOUNT,'0') end)),0) ITEM_TOTAL_AMOUNT         
									,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(PMV_VALUE,'') =''  THEN   '0' else ISNULL(PMV_VALUE,'0') end)),0)PMV_VALUE         
									 ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(FOB_VALUE,'') =''  THEN   '0' else ISNULL(FOB_VALUE,'0') end)),0)FOB_VALUE          
									  ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DRAWBACK_VALUE,'') =''  THEN   '0' else ISNULL(DRAWBACK_VALUE,'0') end)),0)  DRAWBACK_VALUE        
										,BRANCH_CODE
										 from EXPORT_ITEM_DETAILS where BRANCH_CODE =@Branch and JOBNO in (select Jobno from @temp_job)
										  group by JOBNO,INVOICE_SLNO,BRANCH_CODE order by JOBNO asc						             
						             
			  
 end

else if(@Rpt_Type ='Item')
 begin
      insert into @temp_Item select * from dbo.EXP_ITEM_DYNAMIC_RPT_BRANCH((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') ),@Branch)
 end
 end
