 insert into  @temp_Draw_back	select b.JOBNO,b.SCHEME_CODE,b.DRAWBACK_SLNO,b.DRAWBACK_QTY,b.DRAWBACK_UNIT,b.DRAWBACK_NOOFUNITS,b.DRAWBACK_RATE,b.DRAWBACK_CAPS
,b.DRAWBACK_DESC,b.BRANCH_CODE from summary_Drawback a inner join EXPORT_DRAWBACK_DETAILS b	 on a.JOBNO =b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO and a.ITEM_SLNO=b.ITEM_SLNO 
and a.JOBNO in (select Jobno from @temp_job) and  BRANCH_CODE=@Branch 	 
end					 
