and a.ITEM_SLNO=b.ITEM_SLNO and a.JOBBING_ID=b.JOBBING_ID and a.JOBNO in (select Jobno from @temp_job) and  BRANCH_CODE=@Branch 
 end
if(@LIC>0) begin ;with summary_Lic as (	select JOB_NO,MIN(INV_SL_NO)INV_SL_NO,MIN(ITEM_SL_NO) ITEM_SL_NO from EXPORT_LICENSE_DETAILS where JOB_NO in (select Jobno from @temp_job) and BRANCH_CODE=@Branch group by JOB_NO)
