on a.JOB_NO=b.JOB_NO and a.INV_SL_NO=b.INV_SL_NO and a.ITEM_SL_NO=b.ITEM_SL_NO and a.JOB_NO in(select Jobno from @temp_job)and  BRANCH_CODE=@Branch 
