,ANNEX_SUPER_DESIGN,ANNEX_COMMISSION_RATE,ANNEX_DIVISION,ANNEX_RANGE,ANNEX_VERIFIED_EXAM_OFFICER,ANNEX_SAMPLE_DRAWN,ANNEX_SEAL_NO,ANNEX_ADDRESS1,ANNEX_ADDRESS2
,ANNEX_ADDRESS3,ANNEX_ADDRESS4,BRANCH_CODE from ANNEXURE_C1_DETAILS  where ANNEX_JOBNO in (select Jobno from @temp_job)and  BRANCH_CODE=@Branch end	 
