 from @temp_Gen G	

LEFT JOIN @ANNEXURE_C_AIR A on G.JOBNO =A.ANNEX_AIR_JOBNO and G.BRANCHCODE = A.BRANCH_CODE
LEFT JOIN @ANNEXURE_C_SEA S on G.JOBNO=  S.ANNEX_SEA_JOBNO and G.BRANCHCODE = S.BRANCH_CODE
LEFT JOIN @temp_SEA_CONTAINER SC on  G.JOBNO=SC.ANNEX_SEA_CON_JOBNO and G.BRANCHCODE= SC.BRANCH_CODE
LEFT JOIN @temp_SEA_PACKAGE SP on G.JOBNO= SP.ANNEX_SEA_PACK_JOBNO and G.BRANCHCODE= SP.BRANCH_CODE
LEFT JOIN @temp_INV INV on  G.JOBNO=INV.JOBNO and G.BRANCHCODE= INV.BRANCH_CODE
LEFT JOIN @temp_AR4 AR4 on G.JOBNO =AR4.AR4_JOBNO and G.BRANCHCODE = AR4.BRANCH_CODE
LEFT JOIN @temp_Item Item on G.JOBNO =Item.JOBNO and G.BRANCHCODE =Item.BRANCH_CODE and INV.INVOICE_SLNO= ITEM.ITEM_INVOICE_SLNO 
LEFT JOIN @temp_Draw_back DB on G.JOBNO =DB.JOBNO and G.BRANCHCODE = DB.BRANCH_CODE
LEFT JOIN @temp_Jobbing JOB  on G.JOBNO =JOB.JOBNO and G.BRANCHCODE= JOB.BRANCH_CODE   
LEFT JOIN @temp_Lic LIC on G.JOBNO= LIC.JOB_NO and G.BRANCHCODE = LIC.BRANCH_CODE
LEFT JOIN @temp_ANX_C ANX_C on G.JOBNO =ANX_C.ANNEX_JOBNO and G.BRANCHCODE = ANX_C.BRANCH_CODE 
LEFT JOIN @temp_SB_ENTRY SB on G.JOBNO= SB.SB_JOBNO and G.BRANCHCODE= SB.BRANCH_CODE
order by cast(G.JOBNO as int),cast(INV.INVOICE_SLNO as Int) ,cast(Item.ITEM_SLNO as Int) asc 

