,CONSIGNEE_ADD3 varchar(150),CONSIGNEE_ADD4 varchar(150),CONSIGNEE_ADD5 varchar(150),COUNTRY_DISCHARGE varchar(50),PORT_DISCHARGE varchar(80),COUNTRY_FINAL_DEST varchar(180)
,PORT_FINAL_DEST varchar(200),STATE_OF_EXPORT varchar(150),NFEI varchar(150),NFEI_TYPE varchar(150)	,RBI_WAIVER_NO varchar(150),RBI_WAIVER_DATE datetime,MARKS_NO varchar(500),BRANCHCODE varchar(150)
,FILE_REF_NO varchar(150),CARTING_POINT VARCHAR(100) ,JOBNO_PS varchar(50))

