,ANNEX_AIR_TOTAL_PACKAGES varchar(50),ANNEX_AIR_UNIT_CODE varchar(50),ANNEX_AIR_FREIGHT_AMT varchar(50),ANNEX_AIR_INSURANCE_AMT varchar(50),ANNEX_AIR_GROSS_WEIGHT varchar(50)
,ANNEX_AIR_GR_UNIT_CODE varchar(50),ANNEX_AIR_NET_WEIGHT varchar(50),ANNEX_AIR_MAWB_NO varchar(50),ANNEX_AIR_HAWB_NO varchar(50),ANNEX_AIR_TOTAL_PACKAGES_MAWB varchar(50)
,ANNEX_AIR_ROTATION_NO varchar(50),ANNEX_AIR_ROTATION_DATE datetime,ANNEX_AIR_FOB_VALUE varchar(50),BRANCH_CODE varchar(50))declare @ANNEXURE_C_SEA table(
ANNEX_SEA_JOBNO bigint ,ANNEX_SEA_NATURE_OF_CARGO varchar(100)	,ANNEX_SEA_MARKS_NOS varchar(300)	,ANNEX_SEA_TOTAL_PACKAGES varchar(100),ANNEX_SEA_LOOSE_PACKETS varchar(100)
,ANNEX_SEA_NO_CONTAINERS varchar(100),ANNEX_SEA_GROSS_WEIGHT varchar(100),ANNEX_SEA_NET_WEIGHT varchar(100),ANNEX_SEA_UNIT_MEASUREMENT varchar(100),ANNEX_SEA_ROTATION_NO varchar(100)
,ANNEX_SEA_ROTATION_DATE varchar(100),ANNEX_SEA_FOB_VALUE varchar(100),BRANCH_CODE varchar(100),ANNEX_SEA_SEAL_TYPE varchar(100))declare @temp_SEA_CONTAINER table(
ANNEX_SEA_CON_JOBNO bigint	,ANNEX_SEA_CON_CONTAINERNO varchar(50),ANNEX_SEA_CON_SIZE varchar(50),ANNEX_SEA_CON_TYPE varchar(50),ANNEX_SEA_CON_EXCISE_SEALNO varchar(50)
,ANNEX_SEA_CON_SEAL_DATE datetime,BRANCH_CODE varchar(50))	declare @temp_SEA_PACKAGE table	( ANNEX_SEA_PACK_JOBNO bigint,ANNEX_SEA_PACK_GROUP varchar(50),ANNEX_SEA_PACK_FROM varchar(20),ANNEX_SEA_PACK_TO varchar(20),ANNEX_SEA_PACK_PACKAGETYPE varchar(20)
,BRANCH_CODE varchar(50),ANNEX_SEA_PACK_FROMDESC varchar(200),ANNEX_SEA_PACK_TODESC varchar(200))declare @temp_INV table(
JOBNO  bigint,JOBDATE datetime	,INVOICE_SLNO varchar(50),INVOICE_NO varchar(50),INVOICE_DATE datetime,PAYMENT_METHOD varchar(50),PERIOD_PAYMENT varchar(50)
,INVOICE_VALUE varchar(50),INVOICE_CURRENCY varchar(50)	,EXCHANGE_RATE varchar(50),CONTRACT_NO varchar(50),TERMS varchar(50),BUYER varchar(500),BUYER_NAME varchar(200)
,BUYER_ADDRESS varchar(150),BUYER_ADDRESS1 varchar(150)	,BUYER_ADDRESS2 varchar(150),BUYER_ADDRESS3 varchar(150),BUYER_ADDRESS4 varchar(150),COMMISSION_RATE varchar(50)
,COMMISSION_CHARGES varchar(50),COMMISSION_CURRENCY varchar(50)	,FOB_RATE varchar(50),FOB_CHARGES varchar(50),FOB_CURRENCY varchar(50),PACKMISC_RATE varchar(150)
,PACKMISC_CHARGES varchar(150),PACKMISC_CURRENCY varchar(150),OTHER_DEDUCTION_RATE varchar(150)	,OTHER_DEDUCTION_CHARGES varchar(150),OTHER_DEDUCTION_CURRENCY varchar(150)
,FREIGHT_RATE varchar(150),FREIGHT_CHARGES varchar(150)	,FREIGHT_CURRENCY varchar(150),FREIGHT_EXRATE varchar(150),INSURANCE_RATE varchar(150),INSURANCE_CHARGES varchar(150)
,INSURANCE_CURRENCY varchar(150),INSURANCE_EXRATE varchar(150),WHEATHER_UNIT_PRICE varchar(150),BRANCH_CODE varchar(150),NON_STD_EFFECT_DT_EXP varchar(150),NON_STD_BANKNAME varchar(150)
,NON_STD_CERTIFICATE_NO varchar(150),NON_STD_CERTIFICATE_DATE datetime,DOC_RECD_DATE VARCHAR(15)) declare @temp_AR4 table(AR4_JOBNO bigint ,AR4_NO varchar(50),AR4_DATE datetime	,AR4_COMMISSION_RATE varchar(50),AR4_DIVISION varchar(50),AR4_RANGE varchar(50)
,AR4_REMARKS varchar(300),BRANCH_CODE varchar(150))   declare @temp_Item table	(
JOBNO bigint ,ITEM_INVOICE_SLNO int,ITEM_SLNO int,ITEM_DESCRIPTION varchar(500),RITCNO varchar(50)	,ITEM_QTY varchar(50),ITEM_QTY_CODE varchar(50),ITEM_UNIT_PRICE varchar(50)
,ITEM_PER varchar(50),ITEM_AMOUNT varchar(50),ITEM_PMVVALUE varchar(50),ITEM_SCHEME_CODE varchar(50),ITEM_ACCESSORIES_DESC varchar(600)
,ITEM_AR4_NO varchar(50),ITEM_AR4_DATE datetime	,ITEM_COMMISSION_RATE varchar(50),ITEM_DIVISION varchar(50)	,ITEM_RANGE varchar(50)
,ITEM_REMARKS varchar(150),ITEM_IECCODE varchar(50)	,ITEM_EXPORTER_NAME varchar(200),BR_SLNO varchar(50),ADDRESS1 varchar(150),ADDRESS2 varchar(150)
,ADDRESS3 varchar(150),ADDRESS4 varchar(150),ADDRESS5 varchar(150),ITEM_STR_CODE varchar(50),REWARD_POINTS varchar(50),BRANCH_CODE varchar(50)
,PMV_VALUE varchar(50),FOB_VALUE varchar(50),DRAWBACK_VALUE varchar(50),STR_RATE	varchar(30),STR_AMOUNT	varchar(30))declare @temp_Draw_back table(
JOBNO  bigint ,SCHEME_CODE varchar(50),DRAWBACK_SLNO varchar(50),DRAWBACK_QTY varchar(30),DRAWBACK_UNIT varchar(50),DRAWBACK_NOOFUNITS varchar(100),DRAWBACK_RATE varchar(150)
,DRAWBACK_CAPS varchar(200),DRAWBACK_DESC varchar(500),BRANCH_CODE varchar(50))declare @temp_Jobbing table	( JOBNO bigint,SCHEME_CODE varchar(50),NOTIFICATION_NO  varchar(50),BE_NO varchar(50),BE_DATE varchar(50),BE_INV_SLNO varchar(50)
,BE_INV_NO varchar(50),BE_ITEM_NO varchar(50),BE_PORT_CODE varchar(50),QTY varchar(50),UNIT varchar(50),BRANCH_CODE varchar(50)	)declare @temp_Lic table
(JOB_NO bigint,SCHEME_CODE varchar(50),SCHEME varchar(50),LICENSE_R_SL_NO varchar(50),LICENSE_NO varchar(50),LICENSE_DATE datetime,BRANCH_CODE varchar(50))
 declare @temp_ANX_C table(ANNEX_JOBNO bigint ,ANNEX_EXPORTERNAME varchar(200),ANNEX_IECCODE varchar(100)	,ANNEX_BR_SLNO varchar(100),ANNEX_EXAM_DATE datetime,ANNEX_EXAM_OFFICER varchar(100)
,ANNEX_EXAM_DESIGN varchar(100)	,ANNEX_SUPER_NAME varchar(200),ANNEX_SUPER_DESIGN varchar(100),ANNEX_COMMISSION_RATE varchar(100),ANNEX_DIVISION  varchar(100)
,ANNEX_RANGE varchar(100),ANNEX_VERIFIED_EXAM_OFFICER varchar(200),ANNEX_SAMPLE_DRAWN varchar(100),ANNEX_SEAL_NO varchar(100),ANNEX_ADDRESS1 varchar(100)
,ANNEX_ADDRESS2 varchar(100),ANNEX_ADDRESS3 varchar(100),ANNEX_ADDRESS4 varchar(100),BRANCH_CODE varchar(100)) declare @temp_SB_ENTRY table (
SB_JOBNO bigint ,SB_JOBDATE datetime,SB_NO varchar(50),SB_DATE datetime,SB_PMV_VALUE varchar(50),SB_FOB_VALUE  varchar(50),SB_DRAWBACK_VALUE  varchar(50),BRANCH_CODE  varchar(50),EXPENSE_AMT	varchar(30))	
declare @temp_Min table (Id int identity(1,1),JOBNO bigint,INV_SLNO varchar(20) ,BRANCH_CODE varchar(20))declare @ANX_Air int ,@ANX_SEA int,@ANX_S_CON int,@ANX_S_PKG int,@AR4 int,@ITEM int,@DRAWBACK int,@JOBBING int,@LIC int,@ANX_C1 int,@SB_ENTRY int
select @ANX_Air=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and   COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_ANNEXURE_C_AIR'	select 
@ANX_SEA=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_ANNEXURE_C_SEA'select 
@ANX_S_CON=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ','))and TABLE_NAME='EXPORT_ANNEXURE_C_SEA_CONTAINER' select 
@ANX_S_PKG=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ','))and TABLE_NAME='EXPORT_ANNEXURE_C_SEA_PACKAGE' select 
@AR4=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_AR4_TBL' select 
@ITEM=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_ITEM_DETAILS' select 
@DRAWBACK=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_DRAWBACK_DETAILS'select 
@JOBBING=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_JOBBING'  select 
@LIC=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='EXPORT_LICENSE_DETAILS' select 
@ANX_C1=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) and TABLE_NAME='ANNEXURE_C1_DETAILS' select 
@SB_ENTRY=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Export' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ','))and TABLE_NAME='EXPORT_SB_ENTRY'        
insert into  @temp_Gen select JOBNO,JOBDATE,TRANSPORT_MODE,CUSTOMS_HOUSE,CUSTOMS_HOUSE_NAME,SB_TYPE,EXPORTER_NAME,BRANCH_NO,IEC_NO,ADDRESS1,ADDRESS2,ADDRESS3
,ADDRESS4,ADDRESS5,ADCODE,BANK_ACCOUNT,DRAWBACK_ACCOUNT,CONSIGNEE_NAME,CONSIGNEE_ADD1,CONSIGNEE_ADD2,CONSIGNEE_ADD3,CONSIGNEE_ADD4,CONSIGNEE_ADD5,COUNTRY_DISCHARGE
,PORT_DISCHARGE,COUNTRY_FINAL_DEST,PORT_FINAL_DEST,STATE_OF_EXPORT,NFEI,NFEI_TYPE,RBI_WAIVER_NO,RBI_WAIVER_DATE,MARKS_NO,BRANCHCODE,FILE_REF_NO
,CARTING_POINT ,JOBNO_PS  from EXPORT_GENERAL_DETAILS  where JOBNO in(select Jobno from @temp_job )
if(@ANX_Air>0)  begin   insert into @ANNEXURE_C_AIR	select 	ANNEX_AIR_JOBNO,ANNEX_AIR_SEALNO,ANNEX_AIR_SEAL_AGENCY,ANNEX_AIR_NATURE_OF_CARGO,ANNEX_AIR_MARKS_NOS
,ANNEX_AIR_TOTAL_PACKAGES,ANNEX_AIR_UNIT_CODE,ANNEX_AIR_FREIGHT_AMT,ANNEX_AIR_INSURANCE_AMT,ANNEX_AIR_GROSS_WEIGHT,ANNEX_AIR_GR_UNIT_CODE,ANNEX_AIR_NET_WEIGHT
,ANNEX_AIR_MAWB_NO,ANNEX_AIR_HAWB_NO,ANNEX_AIR_TOTAL_PACKAGES_MAWB,ANNEX_AIR_ROTATION_NO,ANNEX_AIR_ROTATION_DATE,ANNEX_AIR_FOB_VALUE,BRANCH_CODE from EXPORT_ANNEXURE_C_AIR where ANNEX_AIR_JOBNO  in(select Jobno from @temp_job )
end if(@ANX_SEA>0) begin  insert into @ANNEXURE_C_SEA  select ANNEX_SEA_JOBNO,case when  ANNEX_SEA_NATURE_OF_CARGO='C' then 'Containerized' when  ANNEX_SEA_NATURE_OF_CARGO='P'  then 'Packaged'when  ANNEX_SEA_NATURE_OF_CARGO='CP'  then 'Containerized'when  
ANNEX_SEA_NATURE_OF_CARGO='LB'  then 'Liquid and Bulk' when  ANNEX_SEA_NATURE_OF_CARGO='DB'  then 'Dry Bulk' end  ANNEX_SEA_NATURE_OF_CARGO
,ANNEX_SEA_MARKS_NOS,ANNEX_SEA_TOTAL_PACKAGES,ANNEX_SEA_LOOSE_PACKETS,ANNEX_SEA_NO_CONTAINERS,ANNEX_SEA_GROSS_WEIGHT,ANNEX_SEA_NET_WEIGHT,ANNEX_SEA_UNIT_MEASUREMENT
,ANNEX_SEA_ROTATION_NO,ANNEX_SEA_ROTATION_DATE,ANNEX_SEA_FOB_VALUE,BRANCH_CODE,ANNEX_SEA_SEAL_TYPE from EXPORT_ANNEXURE_C_SEA where ANNEX_SEA_JOBNO  in(select Jobno from @temp_job )
end if(@ANX_S_CON>0) begin ;with summary_SEA_CONTAINER as  (select ANNEX_SEA_CON_JOBNO ,MIN(ANNEX_SEA_CON_ID)ANNEX_SEA_CON_ID from EXPORT_ANNEXURE_C_SEA_CONTAINER   
group by ANNEX_SEA_CON_JOBNO  )insert into @temp_SEA_CONTAINER	select 	b.ANNEX_SEA_CON_JOBNO,b.ANNEX_SEA_CON_CONTAINERNO,b.ANNEX_SEA_CON_SIZE
,b.ANNEX_SEA_CON_TYPE,b.ANNEX_SEA_CON_EXCISE_SEALNO,b.ANNEX_SEA_CON_SEAL_DATE,b.BRANCH_CODE from summary_SEA_CONTAINER a inner join EXPORT_ANNEXURE_C_SEA_CONTAINER b 
on a.ANNEX_SEA_CON_JOBNO =b.ANNEX_SEA_CON_JOBNO and a.ANNEX_SEA_CON_ID = b.ANNEX_SEA_CON_ID and a.ANNEX_SEA_CON_JOBNO  in (select Jobno from @temp_job )  
end if(@ANX_S_PKG>0) begin ;with summary_SEA_PACKAGE as  ( select ANNEX_SEA_PACK_JOBNO,MIN(ANNEX_SEA_PACK_ID)ANNEX_SEA_PACK_ID from EXPORT_ANNEXURE_C_SEA_PACKAGE   
group by ANNEX_SEA_PACK_JOBNO  )insert into @temp_SEA_PACKAGE select b.ANNEX_SEA_PACK_JOBNO,b.ANNEX_SEA_PACK_GROUP,b.ANNEX_SEA_PACK_FROM
,b.ANNEX_SEA_PACK_TO,b.ANNEX_SEA_PACK_PACKAGETYPE,b.BRANCH_CODE,b.ANNEX_SEA_PACK_FROMDESC,b.ANNEX_SEA_PACK_TODESC from summary_SEA_PACKAGE a inner join  EXPORT_ANNEXURE_C_SEA_PACKAGE b
on a.ANNEX_SEA_PACK_JOBNO  =b.ANNEX_SEA_PACK_JOBNO and a.ANNEX_SEA_PACK_ID =b.ANNEX_SEA_PACK_ID and a.ANNEX_SEA_PACK_ID  in (select Jobno from @temp_job )  
end 
 if(@Rpt_Type ='Jobno' or @Rpt_Type ='SBNO') begin 

;with summary_INV as( select JOBNO ,MIN(INVOICE_SLNO)INVOICE_SLNO  from EXPORT_INVOICE_DETAILS  group by JOBNO)
insert into @temp_INV select  b.* from summary_INV a inner join   (select * from dbo.EXP_INV_DYNAMIC_RPT_COMMON
((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') )))b
on a.JOBNO =b.JOBNO and a.INVOICE_SLNO =b.INVOICE_SLNO  and a.JOBNO  in (select Jobno from @temp_job ) 
						
 end
 else if(@Rpt_Type ='Invoice' or @Rpt_Type ='Item')
begin
     insert into @temp_INV select * from dbo.EXP_INV_DYNAMIC_RPT_COMMON((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') ))
end
	
if(@AR4>0) begin ;with summary_AR4 as( select AR4_JOBNO ,MIN(AR4_INVOICE_SLNO)INVOICE_SLNO,MIN(AR4_ID) AR4_ID from EXPORT_AR4_TBL   group by AR4_JOBNO)   
insert into @temp_AR4 select b.AR4_JOBNO,b.AR4_NO,b.AR4_DATE,b.AR4_COMMISSION_RATE,b.AR4_DIVISION,b.AR4_RANGE,b.AR4_REMARKS,b.BRANCH_CODE from summary_AR4 a
inner join EXPORT_AR4_TBL b  on a.AR4_JOBNO =b.AR4_JOBNO and a.INVOICE_SLNO=b.AR4_INVOICE_SLNO and a.AR4_ID=b.AR4_ID and a.AR4_JOBNO in (select Jobno from @temp_job )
   end
 if(@ITEM>0)
    begin
 if(@Rpt_Type ='Jobno' or @Rpt_Type ='SBNO')
 begin
;with summary_Item as  (  select JOBNO,MIN(INVOICE_SLNO)INVOICE_SLNO,MIN(ITEM_SLNO)ITEM_SLNO From EXPORT_ITEM_DETAILS group by JOBNO )   
insert into @temp_Item select b.* from summary_Item a inner join (select * from dbo.EXP_ITEM_DYNAMIC_RPT_COMMON
((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') )))b on a.JOBNO =b.JOBNO 
and a.ITEM_SLNO=b.ITEM_SLNO	 and a.JOBNO in (select Jobno from @temp_job) 

end
 else if(@Rpt_Type ='Invoice')
 begin
     ;with summary_Item_2 as  (  select JOBNO,INVOICE_SLNO,MIN(ITEM_SLNO)ITEM_SLNO From EXPORT_ITEM_DETAILS   group by JOBNO ,INVOICE_SLNO ) 
insert into @temp_Item	 select b.* from summary_Item_2 a inner join (select * from dbo.EXP_ITEM_DYNAMIC_RPT_COMMON
((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') )))b
on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO and a.ITEM_SLNO=b.ITEM_SLNO and a.JOBNO in (select Jobno from @temp_job ) 
declare @temp_sum_Item table (ID int identity(1,1) ,JOBNO bigint ,INVOICE_SLNO varchar(50),ITEM_QTY varchar(50),ITEM_UNIT_PRICE varchar(50),ITEM_AMOUNT varchar(50)
,PMV_VALUE varchar(50),FOB_VALUE varchar(50),DRAWBACK_VALUE varchar(50),BRANCH_CODE varchar(50)) insert into @temp_sum_Item select JOBNO ,INVOICE_SLNO ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ITEM_QTY,'') =''  
	                               THEN   '0' else ISNULL(ITEM_QTY,'0') end)),0)   ITEM_QTY  ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN 
	                               ISNULL(ITEM_UNIT_PRICE,'') =''  THEN   '0' else ISNULL(ITEM_UNIT_PRICE,'0') end)),0) ITEM_UNIT_PRICE ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ITEM_AMOUNT,'') =''  THEN   '0' else ISNULL(ITEM_AMOUNT,'0') end)),0) ITEM_TOTAL_AMOUNT         
									,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(PMV_VALUE,'') =''  THEN   '0' else ISNULL(PMV_VALUE,'0') end)),0)PMV_VALUE         
									 ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(FOB_VALUE,'') =''  THEN   '0' else ISNULL(FOB_VALUE,'0') end)),0)FOB_VALUE          
									  ,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(DRAWBACK_VALUE,'') =''  THEN   '0' else ISNULL(DRAWBACK_VALUE,'0') end)),0)  DRAWBACK_VALUE        
										,BRANCH_CODE
										 from EXPORT_ITEM_DETAILS where JOBNO in (select Jobno from @temp_job)
										  group by JOBNO,INVOICE_SLNO,BRANCH_CODE order by JOBNO asc						             
						             
			  
 end

else if(@Rpt_Type ='Item')
 begin
      insert into @temp_Item select * from dbo.EXP_ITEM_DYNAMIC_RPT_COMMON((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') ))
 end
 end
if(@DRAWBACK>0)begin ;With summary_Drawback as ( select JOBNO,MIN(INVOICE_SLNO)INVOICE_SLNO,MIN(ITEM_SLNO)ITEM_SLNO from EXPORT_DRAWBACK_DETAILS group by JOBNO )
 insert into  @temp_Draw_back	select b.JOBNO,b.SCHEME_CODE,b.DRAWBACK_SLNO,b.DRAWBACK_QTY,b.DRAWBACK_UNIT,b.DRAWBACK_NOOFUNITS,b.DRAWBACK_RATE,b.DRAWBACK_CAPS
,b.DRAWBACK_DESC,b.BRANCH_CODE from summary_Drawback a inner join EXPORT_DRAWBACK_DETAILS b	 on a.JOBNO =b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO and a.ITEM_SLNO=b.ITEM_SLNO 
and a.JOBNO in (select Jobno from @temp_job) 	 
end					 
if(@JOBBING>0) begin ;with summary_Jobbing as ( select JOBNO,MIN(INVOICE_SLNO)INVOICE_SLNO,MIN(ITEM_SLNO)ITEM_SLNO , MIN(JOBBING_ID)JOBBING_ID from EXPORT_JOBBING group by JOBNO)
insert into @temp_Jobbing select b.JOBNO,b.SCHEME_CODE,b.NOTIFICATION_NO,b.BE_NO,b.BE_DATE,b.BE_INV_SLNO,b.BE_INV_NO,b.BE_ITEM_NO,b.BE_PORT_CODE,b.QTY,b.UNIT
,b.BRANCH_CODE from summary_Jobbing a  inner join EXPORT_JOBBING b on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO
and a.ITEM_SLNO=b.ITEM_SLNO and a.JOBBING_ID=b.JOBBING_ID and a.JOBNO in (select Jobno from @temp_job) 
 end
if(@LIC>0) begin ;with summary_Lic as (	select JOB_NO,MIN(INV_SL_NO)INV_SL_NO,MIN(ITEM_SL_NO) ITEM_SL_NO from EXPORT_LICENSE_DETAILS where JOB_NO in (select Jobno from @temp_job)  group by JOB_NO)
insert into  @temp_Lic select b.JOB_NO,b.SCHEME_CODE,b.SCHEME,b.LICENSE_R_SL_NO,b.LICENSE_NO,b.LICENSE_DATE,b.BRANCH_CODE from summary_Lic a inner join EXPORT_LICENSE_DETAILS b
on a.JOB_NO=b.JOB_NO and a.INV_SL_NO=b.INV_SL_NO and a.ITEM_SL_NO=b.ITEM_SL_NO and a.JOB_NO in(select Jobno from @temp_job)
end	 if(@ANX_C1>0)
begin insert into @temp_ANX_C select ANNEX_JOBNO,ANNEX_EXPORTERNAME,ANNEX_IECCODE,ANNEX_BR_SLNO,ANNEX_EXAM_DATE,ANNEX_EXAM_OFFICER,ANNEX_EXAM_DESIGN,ANNEX_SUPER_NAME
,ANNEX_SUPER_DESIGN,ANNEX_COMMISSION_RATE,ANNEX_DIVISION,ANNEX_RANGE,ANNEX_VERIFIED_EXAM_OFFICER,ANNEX_SAMPLE_DRAWN,ANNEX_SEAL_NO,ANNEX_ADDRESS1,ANNEX_ADDRESS2
,ANNEX_ADDRESS3,ANNEX_ADDRESS4,BRANCH_CODE from ANNEXURE_C1_DETAILS  where ANNEX_JOBNO in (select Jobno from @temp_job) end	 
if(@SB_ENTRY>0)   begin insert into @temp_SB_ENTRY select SB_JOBNO  ,SB_JOBDATE ,SB_NO ,SB_DATE ,SB_PMV_VALUE ,SB_FOB_VALUE  ,SB_DRAWBACK_VALUE  ,BRANCH_CODE,EXPENSE_AMT  from EXPORT_SB_ENTRY where SB_JOBNO in (select Jobno from @temp_job) order by SB_JOBNO asc
    end
create table #temp_Select_EXP (ID int identity(1,1),JOBNO  bigint,JOBDATE varchar(20),TRANSPORT_MODE varchar(50),CUSTOMS_HOUSE varchar(100),CUSTOMS_HOUSE_NAME varchar(100)
,SB_TYPE varchar(100),EXPORTER_NAME varchar(200),BRANCH_NO varchar(100),IEC_NO varchar(100),ADDRESS1 varchar(100),ADDRESS2 varchar(100),ADDRESS3 varchar(100)
,ADDRESS4 varchar(100),ADDRESS5 varchar(100),ADCODE varchar(100),BANK_ACCOUNT varchar(100),DRAWBACK_ACCOUNT varchar(100),CONSIGNEE_NAME varchar(200),CONSIGNEE_ADD1 varchar(100)
,CONSIGNEE_ADD2 varchar(100),CONSIGNEE_ADD3 varchar(100),CONSIGNEE_ADD4 varchar(100),CONSIGNEE_ADD5 varchar(100),COUNTRY_DISCHARGE varchar(200),PORT_DISCHARGE varchar(150)
,COUNTRY_FINAL_DEST varchar(150),PORT_FINAL_DEST varchar(150),STATE_OF_EXPORT varchar(100),NFEI varchar(100),NFEI_TYPE varchar(100),RBI_WAIVER_NO varchar(100)
,RBI_WAIVER_DATE varchar(20),MARKS_NO varchar(500),BRANCHCODE varchar(50),FILE_REF_NO varchar(150),ANNEX_AIR_SEALNO varchar(100),ANNEX_AIR_SEAL_AGENCY varchar(100)
,ANNEX_AIR_NATURE_OF_CARGO varchar(100),ANNEX_AIR_MARKS_NOS varchar(100),ANNEX_AIR_TOTAL_PACKAGES varchar(100),ANNEX_AIR_UNIT_CODE varchar(100),ANNEX_AIR_FREIGHT_AMT varchar(100)
,ANNEX_AIR_INSURANCE_AMT varchar(100),ANNEX_AIR_GROSS_WEIGHT varchar(100),ANNEX_AIR_GR_UNIT_CODE varchar(100),ANNEX_AIR_NET_WEIGHT varchar(100),ANNEX_AIR_MAWB_NO varchar(100)
