if(@Rpt_Type ='Jobno' or @Rpt_Type ='SBNO')
begin
		SET @output = 'SELECT '+@REPORT_COLUMN_NAME+' FROM #temp_Select_EXP order by JOBNO '+@Orderby+''  
end	
else if(@Rpt_Type ='Invoice')
 begin
					 declare @cnt int, @Z int,@Sno int
                     declare @ITEM_QTY varchar(50),@ITEM_UNIT_PRICE varchar(50),@Br_Code varchar(50),@J_No varchar(50),@INV_SLNo varchar(50)
                     
                     set @Z=1;
                     select @cnt=COUNT(*)from #temp_Select_EXP
                     
                     while(@Z<=@cnt)
                     begin
                            select @J_No=JOBNO,@INV_SLNo=INVOICE_SLNO,@Br_Code=BRANCHCODE  from #temp_Select_EXP where ID=@Z
                         
                            select 
                                   @ITEM_QTY=ITEM_QTY
                                  ,@ITEM_UNIT_PRICE=ITEM_UNIT_PRICE
                            from @temp_sum_Item  where JOBNO=@J_No 
												 and INVOICE_SLNO =@INV_SLNo 
												 and BRANCH_CODE=@Br_Code
                             
                        
							update  #temp_Select_EXP  set  ITEM_QTY=@ITEM_QTY,ITEM_UNIT_PRICE=@ITEM_UNIT_PRICE
													 where JOBNO=@J_No and INVOICE_SLNO =@INV_SLNo and BRANCHCODE=@Br_Code
								
                            set @ITEM_QTY=null;
                            set @ITEM_UNIT_PRICE=null;
                            set @Z=@Z+1;
                     end
                     
                      insert into @temp_Min 
									select JOBNO,MIN(isnull(INVOICE_SLNO,0))INVOICE_SLNO ,BRANCH_CODE From EXPORT_INVOICE_DETAILS 
									where  JOBNO in(select Jobno From @temp_job)
									group by JOBNO ,BRANCH_CODE
									
