ALTER procedure  [dbo].[IMP_CUSTOMIZATION_RPT_BRANCH]
( 
   @jobno varchar(10),@from_date varchar(20),@to_date varchar(20),@Branch varchar(50),@Report_Name varchar(50),@Report_Name_id varchar(50)
   ,@Orderby varchar(50),@BE_Type varchar(50),@Rpt_Type varchar(50),@Imp_Name varchar(200),@ErrorMsg nvarchar(max) output,@Mstatus  int output           
  )                    
as                     
begin try                  
  begin transaction                    
  set @ErrorMsg=''
  
  
