*/
 ------------------------------------------------------------------------------------------------------------------------------------------------------------------------- 
declare @Tr_mode varchar(20)declare @REPORT_COLUMN_NAME nvarchar(max)declare @jobno_cond nvarchar(max)declare @jobdate_cond nvarchar(max)
declare @Condition varchar(max),@BE_TYPE_Con varchar(max)        
declare @mode_condition nvarchar(max)declare @output_Job nvarchar(max)declare @jobdate varchar(20)declare @Branch_Condition nvarchar(max)declare @Imp_Name_cond nvarchar(max)  
select @Tr_mode=TR_MODE ,@REPORT_COLUMN_NAME=REPORT_COLUMN_NAME from TEMPLATE_TABLE where TEMPLATE_NAME=@Report_Name and T_ID=@Report_Name_id and ACTIVE='Yes'

if(@from_date <>'' or @to_date <>'')begin if(@from_date <>'' and @to_date <>'')          
begin         
       set @jobdate_cond= ' cast(convert(varchar,JOBDATE,101)as datetime) between cast(''' + @from_date + ''' as datetime) and cast(''' + @to_date + ''' as datetime)'          
       set @jobdate=@from_date end else begin if(@from_date <>'') begin          
       set @jobdate_cond=' cast(convert(varchar,JOBDATE,101)as datetime) between cast(''' + @from_date + ''' as datetime) and getdate()'          
	   set @jobdate=@from_date end if(@to_date <>'')begin          
	   set @jobdate_cond=' cast(CONVERT(varchar,JOBDATE,101)as datetime)=cast(''' + @to_date + ''' as datetime)'          
       set @jobdate=@to_date end end          
end          
       
if(@from_date ='' and @to_date ='')begin set @jobdate='' end    

if(@Branch<>'')
begin
set @Branch_Condition=' BRANCHCODE='''+@Branch+''''
end

if(@jobno<>'')
begin
set @jobno_cond=' jobno='''+@jobno+''''    
end
if(@Imp_Name<>'')
begin
set @Imp_Name_cond=' IMPORTER_NAME='''+@Imp_Name+''''    
end
if(@Tr_mode<>'')
begin
     set @mode_condition= ' TRANSPORT_MODE='''+@Tr_mode+''''  
end  
if(@BE_Type<>'')
begin
     set @BE_TYPE_Con= ' BE_Type='''+@BE_Type+''''  
end  

   
--------------------------------------------------------------------------------------
if(@jobdate<>'' and @jobno='' and @Imp_Name='' and @BE_Type ='')    
begin    
          set @Condition= ' where '+@jobdate_cond  +' and '+@Branch_Condition +' and '+@mode_condition   
end
else if(@jobdate='' and @jobno<>'' and @Imp_Name='' and @BE_Type ='')    
begin    
          set @Condition= ' where '+@jobno_cond   +' and '+@Branch_Condition +' and '+@mode_condition  
end
else if(@jobdate='' and @jobno='' and @Imp_Name<>'' and @BE_Type ='')    
begin    
          set @Condition= ' where '+@Imp_Name_cond  +' and '+@Branch_Condition +' and '+@mode_condition  
end
else if(@jobdate='' and @jobno='' and @Imp_Name='' and @BE_Type <>'')    
begin    
          set @Condition= ' where '+@BE_TYPE_Con  +' and '+@Branch_Condition +' and '+@mode_condition  
end
--------------------------------------------------------------------------------------
