else if(@jobdate<>'' and @jobno='' and @Imp_Name<>''and @BE_Type <>'')       
begin    
          set @Condition= ' where '+@Imp_Name_cond  +' and '+@Branch_Condition +' and '+@BE_TYPE_Con +' and '+@jobdate_cond  +' and '+@mode_condition  
end
else if(@jobdate='' and @jobno<>'' and @Imp_Name<>''and @BE_Type <>'')       
begin    
          set @Condition= ' where '+@Imp_Name_cond  +' and '+@Branch_Condition +' and '+@BE_TYPE_Con +' and '+@jobno_cond  +' and '+@mode_condition  
end
--------------------
else if(@jobdate='' and @jobno='' and @Imp_Name='' and @BE_Type ='')    
begin    
          set @Condition= ' where '+@Branch_Condition +' and '+@mode_condition 
end 
else if(@jobdate<>'' and @jobno<>'' and @Imp_Name<>'' and @BE_Type <>'')    
begin    
         set @Condition= ' where '+@Imp_Name_cond  +' and '+@Branch_Condition +' and '+@BE_TYPE_Con +' and '+@jobno_cond  +' and '+@mode_condition   +' and '+@jobdate_cond  
end 
