begin 
       
        ;with summary_3 as(
         select JOBNO,MIN(INVOICE_SLNO)INVOICE_SLNO,MIN(ITEM_SLNO)ITEM_SLNO From ITEM_PRODUCT_DETAILS where BRANCH_CODE=@Branch group by JOBNO 
