if(@RE_IMP>0) begin  
;with summary_Re_Imp as (  select JOBNO ,MIN(INVOICE_SLNO)INVOICE_SLNO,MIN(ITEM_SLNO)ITEM_SLNO,MIN(RE_IMPORT_SLNO)RE_IMPORT_SLNO from RE_IMPORT_DETAILS 
   where BRANCH_CODE=@Branch  group by JOBNO )
insert into #temp_Re_Imp select b.JOBNO ,b.PORT_EXPORT,b.SB_INVOICE_NO,b.SB_INVOICE__ITEM_NO,b.NOTN_NO,b.NOTN_SLNO,b.EXPORT_FREIGHT,b.EXPORT_INSURANCE,b.CUSTOMS_DUTY
,b.EXCISE_DUTY ,b.BRANCH_CODE from summary_Re_Imp a inner join  RE_IMPORT_DETAILS b on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO and 
a.ITEM_SLNO=b.ITEM_SLNO and a.RE_IMPORT_SLNO=b.RE_IMPORT_SLNO and a.JOBNO  in (select Jobno from @temp_job ) and b.BRANCH_CODE=@Branch
end
