if(@Bond>0)
begin
	 ;WITH cte AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY JOBNO ORDER BY JOBNO DESC) AS rn  FROM BOND_DETAILS where BRANCH_CODE=@Branch	)
	 insert into #temp_Bond SELECT   JOBNO,BOND_NO ,BOND_TYPE,BOND_LOCATION,BRANCH_CODE FROM cte WHERE rn = 1 and JOBNO  in (select Jobno from @temp_job ) and BRANCH_CODE=@Branch
end
----------------------------------------Certificate details---------------------------------------------------------------------------------------------------
if(@Cer>0)
begin
	;WITH cte_Cer AS(  SELECT *, ROW_NUMBER() OVER (PARTITION BY JOBNO ORDER BY JOBNO DESC) AS rn  FROM CERTIFICATE_DETAILS where  BRANCH_CODE =@Branch)
	insert into #temp_Cer SELECT JOBNO,CERTIFICATE_NO,CERTIFICATE_DATE,CERTIFICATE_TYPE	,BRANCH_CODE FROM cte_Cer WHERE rn = 1 and JOBNO in (select Jobno from @temp_job ) and BRANCH_CODE=@Branch
end
