,CHECKLIST_BCD_RATE	varchar(10),CHECKLIST_CVD_RATE	varchar(10),CHECKLIST_ADDL_DUTY_RATE	varchar(10),INDEV_RACK_TYPE	varchar(10),MERIT_DUTY_VALUE	varchar(30)
,RSP_APPLICABLE	varchar(10),CENTRAL_EXCISE_FLAG	varchar(10),MANUFACTURER_PRODUCER	varchar(150),M_P_GROWER_CODE	varchar(50),M_P_GROWER_ADD1	varchar(70),M_P_GROWER_ADD2	varchar(50)
,M_P_GROWER_CITY	varchar(50),M_P_GROWER_COUNTRY_SUBDIV varchar(50),M_P_GROWER_PIN	varchar(20),M_P_GROWER_COUNTRY	varchar(50),SOURCE_COUNTRY	varchar(50),TRANSIT_COUNTRY	varchar(50)
,ACCESSORY_STATUS	varchar(20),INFRA_CESS_NOTN	varchar(8),INFRA_CESS_NOTN_SL	varchar(10),INFRA_CESS_NOTN_RATE	varchar(10)
,MERIT_BASIC_VALUE varchar(30),MERIT_CVD_VALUE varchar(30),MERIT_CEC_VALUE varchar(30),MERIT_CHEC_VALUE varchar(30)
,IGST_LEVY_NOTN varchar(8),IGST_LEVY_SLNO varchar(10),IGST_LEVY_RATE varchar(10),IGST_LEVY_EXCEPTION_NOTN varchar(8)
,IGST_LEVY_EXCEPTION_SLNO varchar(10),IGST_LEVY_EXCEPTION_RATE varchar(10),LEVY_EXCEMPTION_NOTN_TYPE varchar(1),IGST_LEVY_COMPENSATION_CESS_NOTN varchar(8),IGST_LEVY_COMPENSATION_CESS_SLNO varchar(10)
,IGST_LEVY_COMPENSATION_CESS_RATE varchar(10),IGST_LEVY_EXCEPTION_CC_NOTN varchar(8),IGST_LEVY_EXCEPTION_CC_SLNO varchar(10),IGST_LEVY_EXCEPTION_CC_RATE varchar(10)
,LEVY_EXCEPTION_CC_NOTN_TYPE varchar(1),CHECKLIST_IGST_LEVY_AMOUNT varchar(15),CHECKLIST_COMPENSATION_CC_AMOUNT varchar(15)
,SOCIAL_WELFARE_NOTN varchar(8),SOCIAL_WELFARE_NOTN_SLNO varchar(10),SOCIAL_WELFARE_RATE varchar(10),CHECKLIST_SOCIAL_WELFARE_AMT varchar(15))
	
create table  #temp_Re_Imp (JOBNO bigint ,PORT_EXPORT varchar(50),SB_INVOICE_NO varchar(50),SB_INVOICE__ITEM_NO varchar(50),NOTN_NO varchar(50),NOTN_SLNO varchar(50)
,EXPORT_FREIGHT varchar(50),EXPORT_INSURANCE varchar(50),CUSTOMS_DUTY varchar(50),EXCISE_DUTY varchar(50),BRANCH_CODE varchar(50))
create table  #temp_Bond(JOBNO bigint,BOND_NO varchar(50),BOND_TYPE varchar(50),BOND_LOCATION varchar(50),BRANCH_CODE varchar(50))
create table  #temp_Cer(JOBNO bigint,CERTIFICATE_NO varchar(50),CERTIFICATE_DATE datetime,CERTIFICATE_TYPE varchar(50),BRANCH_CODE varchar(50))
create table #temp_Min  (Id int identity(1,1),JOBNO bigint,INV_SLNO varchar(20) )	
CREATE INDEX Gen_jobno ON #temp_Gen(JOBNO)CREATE INDEX BEjobno ON #temp_BE(BE_JOBNO)CREATE INDEX Igm_jobno ON #temp_IGM(JOBNO)CREATE INDEX con_jobno ON #temp_con(JOBNO)
CREATE INDEX con_c_jobno ON #temp_con_0(JOBNO)CREATE INDEX conCC_jobno ON #temp_con_1(JOBNO)CREATE INDEX Inv_jobno ON #temp_INV(JOBNO)CREATE INDEX Lic_jobno ON #temp_Lic(JOBNO)
CREATE INDEX Item_jobno ON #temp_Item(JOBNO)CREATE INDEX Reimp_jobno ON #temp_Re_Imp(JOBNO)CREATE INDEX Bond_jobno ON #temp_Bond(JOBNO)	CREATE INDEX Cer_jobno ON #temp_Cer(JOBNO)
CREATE INDEX Min_jobno ON #temp_Min(JOBNO)				
declare @BE int , @IGM int,@CON int,@Item int,@Bond int,@Cer int,@Lic int,@RE_IMP int
   
select @BE=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Import' and  COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) 
and TABLE_NAME='BE_ENTRY' select @IGM=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Import' and  COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) 
and TABLE_NAME='IGM_DETAILS' select @CON=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Import' and  COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) 
and TABLE_NAME='CONTAINER_DETAILS' select @Item=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Import' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) 
and TABLE_NAME='ITEM_PRODUCT_DETAILS' select @Bond=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Import' and  COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) 
and TABLE_NAME='BOND_DETAILS'  select @Cer=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Import' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) 
and TABLE_NAME='CERTIFICATE_DETAILS' select @Lic=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Import' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) 
and TABLE_NAME='LICENSE_DETAILS' select @RE_IMP=COUNT( distinct(TABLE_NAME)) From REPORT_TABLE_NAME where TYPE='Import' and COLUMN_NAME in(select item from dbo.fnSplit(@REPORT_COLUMN_NAME, ',')) 
and TABLE_NAME='RE_IMPORT_DETAILS'    
insert into #temp_Gen  select JOBNO ,JOBDATE,TRANSPORT_MODE,CUSTOMS_HOUSE,CUSTOMS_HOUSE_NAME,IMPORTER_NAME,ADDRESS1,ADDRESS2,ADDRESS3,ADDRESS4,ADDRESS5,IEC_NO
,BRANCH_NO,COUNTRY_ORIGIN,PORT_ORIGIN,PORT_SHIPMENT,COUNTRY_SHIPMENT,FILING_STATUS,SECTION46,SECTION46_DESC,FIRSTCHECK,FIRSTCHECK_DESC,GREEN_CHANNEL,GREEN_CHANNEL_DESC
,KACHHA_BE,KACHHA_BE_DESC,SECTION48,SECTION48_DESC,HIGH_SEA_SALE,HIGH_SEA_SALE_NAME,HIGH_SEA_IEC,HIGH_SEA_BRANCH_SL_NO,HSS_ADD1,HSS_ADD2,HSS_ADD3,HSS_ADD4,HSS_ADD5
,WAREHOUSE_NAME,WAREHOUSE_CODE,IMP_EXP_TYPE,COMMERCIAL_DETAILS_STATUS,COMMERCIAL_TAX_STATENAME,COMMERCIAL_TAX_STATECODE,COMMERCIAL_TAX_TYPE,COMMERCIAL_TAX_REGISTRATION_NO
,EXBOND_INBOND_BE_NO,EXBOND_INBOND_BE_DATE,EXBOND_BOND_NO,EXBOND_BOND_DATE,EXBOND_WAREHOUSE_CUSTOMS,EXBOND_WAREHOUSE_CUSTOMS_CODE,EXBOND_NOOFPACKAGE,EXBOND_NOOFPACKAGE_UNITCODE
,EXBOND_GROSS_WEIGHT,EXBOND_GROSS_WEIGHT_UNITCODE,EXBOND_DIRECT_EXBONDING,REMARKS,FILE_REF_NO,CONTAINER_TYPE,BRANCHCODE 
,ADCODE,PARTY_REF_NO,GSTN_TYPE,GSTN_ID,ETA , JOBNO_PS from GENERAL_DETAILS  where JOBNO in(select Jobno from @temp_job )

if(@BE>0) begin insert into #temp_BE select BE_JOBNO,BE_JOBDATE,BE_NO_OF_PACKAGES,BE_PACKAGE_CODE,BE_WEIGHT,BE_UNIT_CODE,BE_TRANSPORT_MODE,BE_TYPE,BE_NO,BE_DATE
,BE_ASSESSABLE_VALUE,BE_DUTY,BE_INBOND_NO,BE_INBOND_DATE,BE_WAREHOUSE_CUSTOMS,BE_WAREHOUSE_CUSTOMS_CODE,BRANCH_CODE,EXPENSE_AMT from BE_ENTRY  where BE_JOBNO in (select Jobno from @temp_job ) 
 end
if(@IGM>0) begin ;with summary as( select jobno ,MIN(IGM_SLNO)IGM_SLNO from IGM_DETAILS  group by jobno )
insert into #temp_IGM  select b.JOBNO,b.IGM_JOBDATE,b.IGM_AIRLINECODE,b.IGM_AIRLINENAME,b.IGM_FLIGHTNO_VESSELNO,b.IGM_FLIGHT_VESSELDATE,b.IGM_NO,b.IGM_DATE,b.IGM_MAWB_MBL
,b.IGM_MAWB_MBLDATE,b.IGM_HAWB_HBLNO,b.IGM_HAWB_HBLDATE,b.IGM_NOOFPACKAGE,b.IGM_PACKAGETYPE,b.IGM_GROSSWEIGHT,b.IGM_TYPEOFWEIGHT,b.IGM_NETWEIGHT,b.IGM_NETWEIGHTTYPE
,b.IGM_TRANSPORTMODE,b.IGM_MARKSNOS,b.IGM_GATEWAY_IGM_NO,b.IGM_GATEWAY_IGM_DATE,b.IGM_GATEWAY_PORT_CODE,b.IGM_BRANCH_CODE 
,b.IGM_LINE_NUMBER,b.IGM_SHIPPING_LINE_NUMBER,b.IGM_VOYAGE,b.ROTATION_NO,b.ROTATION_DATE
from summary   a inner join IGM_DETAILS  b
on a.JOBNO =b.JOBNO and a.IGM_SLNO =b.IGM_SLNO where b.JOBNO in (select Jobno from @temp_job )   end
if(@CON>0)begin ;with summary_Con as(select jobno ,MIN(IGM_SLNO)IGM_SLNO from IGM_DETAILS   group by jobno )
insert into #temp_con_0 select b.JOBNO,b.CONTAINERID From summary_Con a inner join CONTAINER_DETAILS b on a.JOBNO=b.JOBNO and a.IGM_SLNO =b.CONTAINER_IGM_SLNO      
where b.JOBNO in (select Jobno from @temp_job ) insert into  #temp_con_1 select JOBNO ,min(CONTAINERID) from  #temp_con_0 group by JOBNO                   
insert into #temp_con  select CONTAINERID,CONTAINER_IGM_NO,CONTAINER_IGM_DATE,JOBNO,CONTAINER_NO,SEAL_NO,FCL_OR_LCL,BRANCH_CODE,TYPE,TRUCK_NO From CONTAINER_DETAILS  where CONTAINERID in( select CONTAINERID from #temp_con_1)
insert into #temp_conID  select CONTAINERID,CONTAINER_IGM_NO,CONTAINER_IGM_DATE,JOBNO,CONTAINER_NO,SEAL_NO,FCL_OR_LCL,BRANCH_CODE,TYPE,TRUCK_NO From CONTAINER_DETAILS 
--select * from #temp_con

 end  if(@Rpt_Type ='Jobno' OR @Rpt_Type ='Container' or @Rpt_Type ='BENO')begin 
with summary_2 as( select jobno ,MIN(INVOICE_SLNO)INVOICE_SLNO from INVOICE_DETAILS   group by jobno   )

insert into #temp_INV select b.JOBNO,b.INVOICE_SLNO ,b.INVOICE_NO,b.INVOICE_DATE,b.TERMS,b.INVOICE_CURRENCY,b.INVOICE_EXRATE,b.INVOICE_VALUE,b.SUPPLIER_NAME,b.SUPPLIER_ADDRESS
,b.SUPPLIER_ADDRESS1,b.SUPPLIER_ADDRESS2,b.SUPPLIER_COUNTRY_NAME,b.SUPPLIER_COUNTRY_CODE,b.SUPPLIER_COUNTRY_PINCODE,b.SELLER_NAME,b.SELLER_ADDRESS,b.SELLER_ADDRESS1
,b.SELLER_ADDRESS2,b.SELLER_COUNTRY_NAME,b.SELLER_COUNTRY_CODE,b.SELLERCOUNTRY_PINCODE,b.BROKER_NAME,b.BROKER_ADDRESS,b.BROKER_ADDRESS1,b.BROKER_ADDRESS2,b.BROKER_COUNTRY_NAME
,b.BROKER_COUNTRY_CODE,b.BROKER_COUNTRY_PINCODE,b.MIS_CHARGES,b.MIS_RATE,b.MIS_CURRENCY,b.MIS_EXRATE,b.MIS_AGENCY_CHARGES,b.MIS_AGENCY_RATE,b.MIS_AGENCY_CURRENCY
,b.MIS_AGENCY_EXRATE,b.MIS_DISCOUNT_CHARGES,b.MIS_DISCOUNT_RATE,b.MIS_DISCOUNT_CURRENCY,b.MIS_DISCOUNT_EXRATE,b.MIS_DISCOUNT_REASON,b.MIS_LOADING_CHARGES,b.MIS_LOADING_RATE
,b.MIS_LOADING_CURRENCY,b.MIS_LOADING_EXRATE,b.MIS_FREIGHT_CHARGES,b.MIS_FREIGHT_RATE,b.MIS_FREIGHT_CURRENCY,b.MIS_FREIGHT_EXRATE,b.MIS_INSURANCE_CHARGES,b.MIS_INSURANCE_RATE
,b.MIS_INSURANCE_CURRENCY,b.MIS_INSURANCE_EXRATE,b.MIS_HIGHSEASALE_CHARGES,b.MIS_HIGHSEASALE_RATE,b.MIS_HIGHSEASALE_CURRENCY,b.MIS_HIGHSEASALE_EXRATE,b.MIS_SINGLE_OR_MULITIPLE
,b.SVB_RELATION,b.SVB_REF_NO,b.SVB_REF_DATE,b.SVB_CUSTOM_HOUSE,b.SVB_LOADING_ON,b.SVB_ASSESABLE_RATE,b.SVB_DUTY_RATE,b.SVB_ASSESABLE_STATUS,b.SVB_DUTY_STATUS
,b.OTHER_PURCHASE_ORDER,b.OTHER_PURCHASE_ORDER_DATE,b.OTHER_CONTRACT_NO,b.OTHER_CONTRACT_DATE,b.OTHER_LOC_NO,b.OTHER_LOC_DATE,b.OTHER_NATURE_OF_TRANSACTION
,b.OTHER_TERMS_OF_PAYMENT,b.OTHER_CONDITIONS,b.OTHER_VALUATION_METHOD,b.BRANCH_CODE,b.NON_STD_EFFECT_DT_IMP,b.NON_STD_BANKNAME,b.NON_STD_CERTIFICATE_NO,b.NON_STD_CERTIFICATE_DATE
,b.SAP_DELIEVERY_ID,b.SHIP_DATE,b.INVOICE_LEVEL,b.COUNTRY_OF_DEPARTURE,b.REVENUEDEPOSIT_RATE,b.REVENUEDEPOSIT_ON 
,b.TERMS_PLACE,b.THIRDPARTY_NAME,b.THIRDPARTY_ADD1,b.THIRDPARTY_ADD2,b.THIRDPARTY_CITY,b.T_PARTY_COUNTRY_SUB_DIV,b.T_PARTY_COUNTRY_CODE,b.T_PARTY_PIN
,b.A_E_O_COUNTRY,b.AUTHORIZED_ECONOMIC_OPERATOR,b.WHETHER_BUYER_SELLER_RELATED,b.DOC_RECD_DATE
From summary_2 a inner join INVOICE_DETAILS b
on a.JOBNO=b.JOBNO  and a.INVOICE_SLNO=b.INVOICE_SLNO and a.JOBNO in (select Jobno from @temp_job )  end
else if(@Rpt_Type ='Invoice' or @Rpt_Type ='Item') begin
 insert into #temp_INV  select JOBNO ,INVOICE_SLNO,INVOICE_NO,INVOICE_DATE,TERMS,INVOICE_CURRENCY,INVOICE_EXRATE
,INVOICE_VALUE,SUPPLIER_NAME,SUPPLIER_ADDRESS,SUPPLIER_ADDRESS1,SUPPLIER_ADDRESS2,SUPPLIER_COUNTRY_NAME,SUPPLIER_COUNTRY_CODE,SUPPLIER_COUNTRY_PINCODE,SELLER_NAME
,SELLER_ADDRESS,SELLER_ADDRESS1,SELLER_ADDRESS2,SELLER_COUNTRY_NAME,SELLER_COUNTRY_CODE,SELLERCOUNTRY_PINCODE,BROKER_NAME,BROKER_ADDRESS,BROKER_ADDRESS1,BROKER_ADDRESS2
,BROKER_COUNTRY_NAME,BROKER_COUNTRY_CODE,BROKER_COUNTRY_PINCODE,MIS_CHARGES,MIS_RATE,MIS_CURRENCY,MIS_EXRATE,MIS_AGENCY_CHARGES,MIS_AGENCY_RATE,MIS_AGENCY_CURRENCY
,MIS_AGENCY_EXRATE,MIS_DISCOUNT_CHARGES,MIS_DISCOUNT_RATE,MIS_DISCOUNT_CURRENCY,MIS_DISCOUNT_EXRATE,MIS_DISCOUNT_REASON,MIS_LOADING_CHARGES,MIS_LOADING_RATE,MIS_LOADING_CURRENCY
,MIS_LOADING_EXRATE,MIS_FREIGHT_CHARGES,MIS_FREIGHT_RATE,MIS_FREIGHT_CURRENCY,MIS_FREIGHT_EXRATE,MIS_INSURANCE_CHARGES,MIS_INSURANCE_RATE,MIS_INSURANCE_CURRENCY
,MIS_INSURANCE_EXRATE,MIS_HIGHSEASALE_CHARGES,MIS_HIGHSEASALE_RATE,MIS_HIGHSEASALE_CURRENCY,MIS_HIGHSEASALE_EXRATE,MIS_SINGLE_OR_MULITIPLE,SVB_RELATION,SVB_REF_NO
,SVB_REF_DATE,SVB_CUSTOM_HOUSE,SVB_LOADING_ON,SVB_ASSESABLE_RATE,SVB_DUTY_RATE,SVB_ASSESABLE_STATUS,SVB_DUTY_STATUS,OTHER_PURCHASE_ORDER,OTHER_PURCHASE_ORDER_DATE
,OTHER_CONTRACT_NO,OTHER_CONTRACT_DATE,OTHER_LOC_NO,OTHER_LOC_DATE,OTHER_NATURE_OF_TRANSACTION,OTHER_TERMS_OF_PAYMENT,OTHER_CONDITIONS,OTHER_VALUATION_METHOD,BRANCH_CODE
,NON_STD_EFFECT_DT_IMP,NON_STD_BANKNAME,NON_STD_CERTIFICATE_NO,NON_STD_CERTIFICATE_DATE,SAP_DELIEVERY_ID,SHIP_DATE,INVOICE_LEVEL,COUNTRY_OF_DEPARTURE,REVENUEDEPOSIT_RATE
,REVENUEDEPOSIT_ON ,TERMS_PLACE,THIRDPARTY_NAME,THIRDPARTY_ADD1,THIRDPARTY_ADD2,THIRDPARTY_CITY,T_PARTY_COUNTRY_SUB_DIV,T_PARTY_COUNTRY_CODE,T_PARTY_PIN
,A_E_O_COUNTRY,AUTHORIZED_ECONOMIC_OPERATOR,WHETHER_BUYER_SELLER_RELATED,DOC_RECD_DATE
From INVOICE_DETAILS where JOBNO in (select Jobno from @temp_job )  end

if(@Lic>0)
begin
;with summary_Lic as(select jobno ,MIN(INVOICE_SLNO)INVOICE_SLNO,MIN(ITEM_SLNO)ITEM_SLNO,MIN(LICENSE_SLNO) LICENSE_SLNO from LICENSE_DETAILS  group by jobno )
 insert into #temp_Lic  select b.JOBNO,b.SCHEME_CODE,b.REGISTRATION_NO,b.REGISTRATION_DATE,b.EXCEMPTION,b.DEBIT_AMT,b.DEBIT_QTY,b.UNIT_QTY,b.LICENSE_ITEM_NO
,b.PORT_OF_LICENSE,b.BRANCH_CODE,b.DEBIT_DUTY,b.LICENSE_NO,b.LICENSE_DATE From summary_Lic a inner join  LICENSE_DETAILS b on a.JOBNO =b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO and
a.LICENSE_SLNO=b.LICENSE_SLNO and a.JOBNO in (select Jobno from @temp_job ) 
end

if(@Item>0)   begin if(@Rpt_Type ='Jobno' OR @Rpt_Type ='Container' or @Rpt_Type ='BENO')
begin 
        ;with summary_3 as(
         select JOBNO,MIN(INVOICE_SLNO)INVOICE_SLNO,MIN(ITEM_SLNO)ITEM_SLNO From ITEM_PRODUCT_DETAILS  group by JOBNO 
         )
       insert into #temp_Item
   	    select b.* From summary_3 a inner join 
		(select * from dbo.IMP_ITEM_DYNAMIC_RPT_COMMON
        ((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') ))) b		
		 on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO and a.ITEM_SLNO=b.ITEM_SLNO
		 and a.JOBNO in (select Jobno from @temp_job ) 
 
        
  end		
else if(@Rpt_Type ='Invoice')begin 
	
;with summary_4 as	(select JOBNO,INVOICE_SLNO,MIN(ITEM_SLNO)ITEM_SLNO From ITEM_PRODUCT_DETAILS group by JOBNO ,INVOICE_SLNO)
insert into #temp_Item select b.* From summary_4 a inner join 
   (select * from dbo.IMP_ITEM_DYNAMIC_RPT_COMMON
((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') ))) b
on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO and a.ITEM_SLNO=b.ITEM_SLNO 
and a.JOBNO in (select Jobno from @temp_job ) 
			
declare @temp_sum_Item table( ID int identity(1,1),JOBNO bigint,INVOICE_SLNO varchar(50),ITEM_QTY varchar(50),ITEM_UNIT_PRICE varchar(50),ITEM_TOTAL_AMOUNT varchar(50)
,BASIC_VALUE varchar(50),CEC_VALUE varchar(50),CHEC_VALUE varchar(50),ADD_DUTY_VALUE varchar(50))
insert into @temp_sum_Item select JOBNO ,INVOICE_SLNO,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ITEM_QTY,'') =''  THEN   '0' else ISNULL(ITEM_QTY,'0') end)),0)   ITEM_QTY      
,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ITEM_UNIT_PRICE,'') =''  THEN   '0' else ISNULL(ITEM_UNIT_PRICE,'0') end)),0) ITEM_UNIT_PRICE         
,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ITEM_TOTAL_AMOUNT,'') =''  THEN   '0' else ISNULL(ITEM_TOTAL_AMOUNT,'0') end)),0) ITEM_TOTAL_AMOUNT         
,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(BASIC_VALUE,'') =''  THEN   '0' else ISNULL(BASIC_VALUE,'0') end)),0)BASIC_VALUE         
,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CEC_VALUE,'') =''  THEN   '0' else ISNULL(CEC_VALUE,'0') end)),0)CEC_VALUE          
,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(CHEC_VALUE,'') =''  THEN   '0' else ISNULL(CHEC_VALUE,'0') end)),0)  CHEC_VALUE        
,isnull(SUM(Convert(NUMERIC(25,2),CASE  WHEN ISNULL(ADD_DUTY_VALUE,'') =''  THEN   '0' else ISNULL(ADD_DUTY_VALUE,'0') end)),0) ADD_DUTY_VALUE        
 from ITEM_PRODUCT_DETAILS where JOBNO in(select Jobno from @temp_job) group by JOBNO,INVOICE_SLNO order by JOBNO asc

end	else if(@Rpt_Type ='Item')
 begin
      insert into #temp_Item						 
      select * from dbo.IMP_ITEM_DYNAMIC_RPT_COMMON((SELECT STUFF(( SELECT  ', ' + cast(E.jobno as varchar(20)) FROM @temp_job AS E FOR XML PATH('')) , 1, 2, '') ))
end 			
end
----------------------------------------Re-Import details---------------------------------------------------------------------------------------------------
if(@RE_IMP>0) begin  
;with summary_Re_Imp as (  select JOBNO ,MIN(INVOICE_SLNO)INVOICE_SLNO,MIN(ITEM_SLNO)ITEM_SLNO,MIN(RE_IMPORT_SLNO)RE_IMPORT_SLNO from RE_IMPORT_DETAILS 
 group by JOBNO )
insert into #temp_Re_Imp select b.JOBNO ,b.PORT_EXPORT,b.SB_INVOICE_NO,b.SB_INVOICE__ITEM_NO,b.NOTN_NO,b.NOTN_SLNO,b.EXPORT_FREIGHT,b.EXPORT_INSURANCE,b.CUSTOMS_DUTY
,b.EXCISE_DUTY ,b.BRANCH_CODE from summary_Re_Imp a inner join  RE_IMPORT_DETAILS b on a.JOBNO=b.JOBNO and a.INVOICE_SLNO=b.INVOICE_SLNO and 
a.ITEM_SLNO=b.ITEM_SLNO and a.RE_IMPORT_SLNO=b.RE_IMPORT_SLNO and a.JOBNO  in (select Jobno from @temp_job ) 
end
----------------------------------------Bond details---------------------------------------------------------------------------------------------------
if(@Bond>0)
begin
	 ;WITH cte AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY JOBNO ORDER BY JOBNO DESC) AS rn  FROM BOND_DETAILS 	)
	 insert into #temp_Bond SELECT   JOBNO,BOND_NO ,BOND_TYPE,BOND_LOCATION,BRANCH_CODE FROM cte WHERE rn = 1 and JOBNO  in (select Jobno from @temp_job ) 
end
----------------------------------------Certificate details---------------------------------------------------------------------------------------------------
if(@Cer>0)
begin
	;WITH cte_Cer AS(  SELECT *, ROW_NUMBER() OVER (PARTITION BY JOBNO ORDER BY JOBNO DESC) AS rn  FROM CERTIFICATE_DETAILS )
	insert into #temp_Cer SELECT JOBNO,CERTIFICATE_NO,CERTIFICATE_DATE,CERTIFICATE_TYPE	,BRANCH_CODE FROM cte_Cer WHERE rn = 1 and JOBNO in (select Jobno from @temp_job ) 
end
------------------------------------------------------------------END-----------------------------------------------------------------------------------------------------
create table #temp_Select 
			(
			 ID int identity(1,1), JOBNO bigint,JOBDATE varchar(20),TRANSPORT_MODE varchar(20), CUSTOMS_HOUSE varchar(150),CUSTOMS_HOUSE_NAME varchar(200)
			,IMPORTER_NAME  varchar(200) ,ADDRESS1 varchar(150),ADDRESS2 varchar(150) ,ADDRESS3 varchar(150),ADDRESS4 varchar(150),ADDRESS5 varchar(150)
			,IEC_NO varchar(150),BRANCH_NO varchar(150),COUNTRY_ORIGIN varchar(150),PORT_ORIGIN varchar(150),PORT_SHIPMENT varchar(150)
			,COUNTRY_SHIPMENT varchar(150),FILING_STATUS varchar(150),SECTION46 varchar(150),SECTION46_DESC varchar(150),FIRSTCHECK varchar(150)
			,FIRSTCHECK_DESC varchar(150),GREEN_CHANNEL varchar(150),GREEN_CHANNEL_DESC varchar(150),KACHHA_BE varchar(150),KACHHA_BE_DESC varchar(150)
