 -------------------------------  TO UPDATE WAREHOUSE NAME FROM ADMIN MASTER FOR EKTA SHIPPING START--------------------------------------------------------
 
 declare @wh_count int
 declare @wh int
 declare @wh_jobno1 int
 declare @wh_code1 varchar(100)
 
 create table #temp_wh_general ( id int identity(1,1),JOBNO bigint,Warehouse_cd varchar(100))
 insert into  #temp_wh_general 
 select JOBNO,WAREHOUSE_CODE from #temp_Select where isnull(WAREHOUSE_CODE,'')<>''
 --select * from #temp_wh_general

 
 set @wh_count=(select COUNT(WAREHOUSE_CODE) from #temp_Select where isnull(WAREHOUSE_CODE,'')<>'')
 set @wh=1;
 --select @wh_count
 declare @code_count int
 while(@wh_count>=@wh)
 begin
   set @wh_jobno1=(select JOBNO from #temp_wh_general where id=@wh)
   --set @wh_Branch1=(select BRANCHCODE from #temp_wh_general where id=@wh)
   set @wh_code1=(select Warehouse_cd from #temp_wh_general where id=@wh)
   --set @wh_code1='NSA1U039'
   --select @wh_jobno1,@wh_Branch1,@wh_code1
   
   set @code_count=(select count(WAREHOUSE_CODE) from WAREHOUSE_MASTER_USERWISE_MASTER where WAREHOUSE_CODE=@wh_code1)

   if(@code_count>0)
   begin
   update #temp_Select set WAREHOUSE_CODE=(select top 1 WAREHOUSE_CODE+'-'+WAREHOUSE_NAME from WAREHOUSE_MASTER_USERWISE_MASTER where WAREHOUSE_CODE=@wh_code1)
   where JOBNO=@wh_jobno1 
   end

   
   set @wh=@wh+1;
 end
 
 drop table #temp_wh_general
 
 
 -------------------------------  TO UPDATE WAREHOUSE NAME FROM ADMIN MASTER FOR EKTA SHIPPING END--------------------------------------------------------

 
 
