begin catch  
rollback transaction  
 set @ErrorMsg=error_message()  
 set @MStatus=0  
end catch


/****** Object:  StoredProcedure [dbo].[EXP_BL_GENERATION_SELECT]    Script Date: 10/12/2018 16:23:49 ******/
