ALTER procedure [dbo].[EXP_BL_GENERATION_SELECT]
		
		@BL_ID bigint,
	     @JOBNO varchar(50),
	     @ExporterName varchar(100),
		 @Working_Period Varchar(50),
		 @Ename varchar(50),
		 
		 @Mstatus  int output,
		 @ErrorMsg nvarchar(max) output
	AS
begin try
	begin transaction
		set @ErrorMsg=''

/*
declare @BL_ID bigint,
	     @JOBNO varchar(50),
	     @ExporterName varchar(100),
		 @Working_Period Varchar(50),
		 @Ename varchar(50),
		 
		 @Mstatus  int ,
		 @ErrorMsg nvarchar(max)
		 
		 set @BL_ID=''
		 set @JOBNO='4995'
		 set @ExporterName=''
		 set @Working_Period=''
		 set @Ename='Select_All_Details'
		 set @Mstatus=''
		 set @ErrorMsg=''
	*/	
		
	DECLARE @Tr_mode varchar(20)
	DECLARE @NewLineChar AS CHAR(2) = CHAR(13) + CHAR(10)
	declare @Roundamt varchar(200)
	declare @Currency varchar(50)
	
	 declare @temp table ( Id int, JOBNO bigint,ITEM_DESCRIPTION Varchar(200))
	 declare @temp_2 table(ID int,Mark_No varchar(100),no_pkg Varchar(500),gross_wgt Varchar(50),Net_Weight varchar(50),InWords varchar(500))
------------------------------------------------------------------------------------------------------------------------------------------------

if(@Ename='Select_All_Details')

 begin

	if(@Working_Period<>'')
	begin
	       
       If not exists(select JOBNO from EXPORT_BL_GENERATION where JOBNO=@JOBNO and BRANCHCODE=@Working_Period)
       begin
              select @Tr_mode=TRANSPORT_MODE From EXPORT_GENERAL_DETAILS where JOBNO=@JOBNO and BRANCHCODE=@Working_Period
              
              /* *************************************** table 1 ************************************************* */
              select 
               a.JOBNO
			  , a.EXPORTER_NAME  
			  ,a.ADDRESS1  
			  ,a.ADDRESS2  
			  ,a.ADDRESS3  
			  ,a.ADDRESS4  
			  ,a.ADDRESS5 
			  ,convert(varchar,a.JOBDATE,103)JOBDATE
			  ,a.IEC_NO
			  ,a.PORT_DISCHARGE
			  ,a.PORT_FINAL_DEST
			  ,a.COUNTRY_DISCHARGE
			  ,a.COUNTRY_FINAL_DEST
			  
			  ,a.CONSIGNEE_NAME  
			  ,a.CONSIGNEE_ADD1  
			  ,a.CONSIGNEE_ADD2  
			  ,a.CONSIGNEE_ADD3  
			  ,a.CONSIGNEE_ADD4 
			   
		      ,b.BUYER_NAME  
			  ,b.BUYER_ADDRESS  
			  ,b.BUYER_ADDRESS1  
			  ,b.BUYER_ADDRESS2  
			  ,b.BUYER_ADDRESS3 
			  ,b.INVOICE_NO 
			  ,convert(varchar,b.INVOICE_DATE,103)INVOICE_DATE
			   
			  ,'' as BL_NUMBER
			  ,'' as SHIP_REF_NO
			  ,'' as PLACE_OF_RECEIPT
			  ,'' as OCEAN_VESSEL
			  ,'' as PORT_OF_LOADING
			  ,'' as FREIGHT_PAYABLE
			  ,'' as PLACE_DATE
			  ,'' as DATE_OF_RECEIPT
			  ,'' as PLACE_OF_DELIVERY
			  
			  ,a.PORT_DISCHARGE 
			  
			  ,'' as NO_OF_ORGINAL_BL
			  ,'' as AGENTS_NAEE_REFNO
			  ,'' as FREIGHT_AMT
			  
			  ,c.SB_NO
			   ,convert(varchar,c.SB_DATE,103)SB_DATE
			  --,c.SB_DATE
			  ,@Tr_mode as TRANSPORT_MODE
			 
			   from EXPORT_GENERAL_DETAILS a left outer join EXPORT_INVOICE_DETAILS b on a.JOBNO=b.JOBNO 
			   left outer join EXPORT_SB_ENTRY c on a.JOBNO=c.SB_JOBNO			   
			   where a.JOBNO=@JOBNO and b.BRANCH_CODE=@Working_Period and a.BRANCHCODE=@Working_Period
			   and b.INVOICE_SLNO=(select  MIN(INVOICE_SLNO) from EXPORT_INVOICE_DETAILS where JOBNO=@JOBNO)
			   
			   
			   /* ***************************************** table 2 *********************************************** */
			    insert into @temp 
						   select top 1  
							          ROW_NUMBER() OVER(ORDER BY JOBNO DESC) 
									  ,JOBNO  
									  --,ITEM_DESCRIPTION
									  ,ITEM_ACCESSORIES_DESC
									   from EXPORT_ITEM_DETAILS  
									   where JOBNO=@JOBNO and BRANCH_CODE=@Working_Period
     
					if(@Tr_mode='Air')
					begin   
					     insert into @temp_2
								 select 
							         ROW_NUMBER() OVER(ORDER BY ANNEX_AIR_JOBNO DESC) 
									,ANNEX_AIR_MARKS_NOS
									,ANNEX_AIR_TOTAL_PACKAGES +  '/ ' + ANNEX_AIR_UNIT_CODE
									,ANNEX_AIR_GROSS_WEIGHT +' / ' + ANNEX_AIR_UNIT_CODE +@NewLineChar
									,+ANNEX_AIR_NET_WEIGHT
									,replace(Upper((select case when left(dbo.IndianCurrencyInWords(cast(ANNEX_AIR_TOTAL_PACKAGES as decimal(25,2))) , 4) =' and'          then  right( dbo.IndianCurrencyInWords(ANNEX_AIR_TOTAL_PACKAGES)  
              ,LEN( dbo.IndianCurrencyInWords(cast(ANNEX_AIR_TOTAL_PACKAGES as decimal(25,2)))) - 3)  else dbo.IndianCurrencyInWords(cast(ANNEX_AIR_TOTAL_PACKAGES as decimal(25,2))) end) ),'  ','') 

									
									 from EXPORT_ANNEXURE_C_AIR
									 WHERE ANNEX_AIR_JOBNO=@JOBNO
									 and BRANCH_CODE =@Working_Period
									
					end
					else if(@Tr_mode='Sea')
					begin
								insert into @temp_2
								 select 
							        ROW_NUMBER() OVER(ORDER BY ANNEX_SEA_JOBNO DESC) 
									,ANNEX_SEA_MARKS_NOS 
									,ANNEX_SEA_TOTAL_PACKAGES 
									
									,ANNEX_SEA_GROSS_WEIGHT +' / ' +ANNEX_SEA_UNIT_MEASUREMENT +@NewLineChar
									,+ ANNEX_SEA_NET_WEIGHT +'  / '+ANNEX_SEA_UNIT_MEASUREMENT
									,replace(Upper((select case when left(dbo.IndianCurrencyInWords(cast(ANNEX_SEA_TOTAL_PACKAGES as decimal(25,2))) , 4) =' and'          then  right( dbo.IndianCurrencyInWords(ANNEX_SEA_TOTAL_PACKAGES)  
              ,LEN( dbo.IndianCurrencyInWords(cast(ANNEX_SEA_TOTAL_PACKAGES as decimal(25,2)))) - 3)  else dbo.IndianCurrencyInWords(cast(ANNEX_SEA_TOTAL_PACKAGES as decimal(25,2))) end) ),'  ','') 
									
									
									 from EXPORT_ANNEXURE_C_SEA
									 WHERE ANNEX_SEA_JOBNO=@JOBNO
									 and BRANCH_CODE =@Working_Period
					end	   
					
					 select 
					        ROW_NUMBER() OVER(ORDER BY Mark_No DESC) as RowNumber
					      ,Mark_No as Mark_No
					       ,no_pkg
					       ,ITEM_DESCRIPTION as [desc]
					       ,gross_wgt + @NewLineChar  +'    '+ Net_Weight as gross_wgt
					       ,InWords
					       --,gross_wgt + @NewLineChar  +'  NET WT  '+ Net_Weight as gross_wgt
					       
					          from @temp a
					               left join @temp_2 b
					               on a.Id=b.ID
					               
					/* ************************************ table 3 **************************************************** */
					
					
					/* ************************************ table 4 **************************************************** */
					
			   
			   set @Mstatus=1
			   
			   
       end
       else 
       begin
				select 
						BL_ID
						,JOBNO
						,EXPORTER_NAME
						,ADDRESS1
						,ADDRESS2
						,ADDRESS3
						,ADDRESS4
						,ADDRESS5
						
						,CONSIGNEE_NAME
						,CONSIGNEE_ADD1
						,CONSIGNEE_ADD2
						,CONSIGNEE_ADD3
						,CONSIGNEE_ADD4
						
						,BUYER_NAME
						,BUYER_ADDRESS
						,BUYER_ADDRESS1
						,BUYER_ADDRESS2
						,BUYER_ADDRESS3
						,BUYER_ADDRESS4
						,INVOICE_NO
						
						,BL_NUMBER
						,SHIP_REF_NO
						,PLACE_OF_RECEIPT
						,OCEAN_VESSEL
						,PORT_OF_LOADING
						,FREIGHT_PAYABLE
						,PLACE_DATE
						,DATE_OF_RECEIPT
						,PLACE_OF_DELIVERY
						,PORT_DISCHARGE
						,NO_OF_ORGINAL_BL
						,AGENTS_NAEE_REFNO
						,FREIGHT_AMT
						
						,NOTIFY_1_1
						,NOTIFY_1_2
						,NOTIFY_1_3
						,NOTIFY_1_4
						,NOTIFY_1_5
						,INVOICE_NO
						,SB_NO
						,IEC_NO
						,HSS_CODE_NO
						,LC_NO
						,TOTALVOLUME
						,ORDER_NO
						,FREIGHT_PRE_COL
						,CONTAINER_Y_N
						,PENDING_Y_N
						,convert(varchar,JOB_DATE,103)as JOB_DATE
						,TOT_VOL_UNIT
						,COMMODITY
						,TOT_PKGS_UNIT

						----,Convert(varchar,JOB_DATE, 103)JOB_DATE
						--,convert(varchar(10),JOB_DATE,103) JOB_DATE

						
						from  EXPORT_BL_GENERATION where JOBNO=@JOBNO and BRANCHCODE=@Working_Period
						
				select 
						 ROW_NUMBER() OVER(ORDER BY JOBNO DESC) AS RowNumber
						 ,MARKS_NUMBERS as Mark_No
						 ,NO_OF_PKG as no_pkg
						 ,GOODS_DESC as [desc]
						 ,GROSS_WEIGHT as gross_wgt
				from EXPORT_BL_GENERATION_ITEMS where JOBNO=@JOBNO and BRANCHCODE=@Working_Period
				
				
				  set @Mstatus=2
       end
end
   else 
       begin
			  If not exists(select JOBNO from EXPORT_BL_GENERATION where JOBNO=@JOBNO)
       begin
       
        /* ************************************ table 1 **************************************************** */
              select @Tr_mode=TRANSPORT_MODE From EXPORT_GENERAL_DETAILS where JOBNO=@JOBNO 
              select  
              a.JOBNO
			  ,a.EXPORTER_NAME  
			  ,a.ADDRESS1  
			  ,a.ADDRESS2  
			  ,a.ADDRESS3  
			  ,a.ADDRESS4  
			  ,a.ADDRESS5 
			  ,convert(varchar,a.JOBDATE,103)JOBDATE
			   ,a.IEC_NO
			  ,a.PORT_DISCHARGE
			  ,a.PORT_FINAL_DEST
			  ,a.COUNTRY_DISCHARGE
			  ,a.COUNTRY_FINAL_DEST
			  
			  ,a.CONSIGNEE_NAME  
			  ,a.CONSIGNEE_ADD1  
			  ,a.CONSIGNEE_ADD2  
			  ,a.CONSIGNEE_ADD3  
			  ,a.CONSIGNEE_ADD4 
			   
		      ,b.BUYER_NAME  
			  ,b.BUYER_ADDRESS  
			  ,b.BUYER_ADDRESS1  
			  ,b.BUYER_ADDRESS2  
			  ,b.BUYER_ADDRESS3 
			  ,b.INVOICE_NO   
			    ,convert(varchar,b.INVOICE_DATE,103)INVOICE_DATE
			   
			  ,'' as BL_NUMBER
			  ,'' as SHIP_REF_NO
			  ,'' as PLACE_OF_RECEIPT
			  ,'' as OCEAN_VESSEL
			  ,'' as PORT_OF_LOADING
			  ,'' as FREIGHT_PAYABLE
			  ,'' as PLACE_DATE
			  ,'' as DATE_OF_RECEIPT
			  ,'' as PLACE_OF_DELIVERY
			  
			  ,a.PORT_DISCHARGE 
			  
			  ,'' as NO_OF_ORGINAL_BL
			  ,'' as AGENTS_NAEE_REFNO
			  ,'' as FREIGHT_AMT
			  
			   ,c.SB_NO
			   ,convert(varchar,c.SB_DATE,103)SB_DATE
			   ,@Tr_mode as TRANSPORT_MODE
			 
			   from EXPORT_GENERAL_DETAILS a left outer join EXPORT_INVOICE_DETAILS b on a.JOBNO=b.JOBNO
			   left outer join EXPORT_SB_ENTRY c on a.JOBNO=c.SB_JOBNO	  
			   where a.JOBNO=@JOBNO
			   and b.INVOICE_SLNO=(select  MIN(INVOICE_SLNO) from EXPORT_INVOICE_DETAILS where JOBNO=@JOBNO)		
			   
			   /* ************************************ table 2 **************************************************** */
			    insert into @temp 
						   select top 1  
							          ROW_NUMBER() OVER(ORDER BY JOBNO DESC) 
									  ,JOBNO  
									   --,ITEM_DESCRIPTION
									  ,ITEM_ACCESSORIES_DESC
									   from EXPORT_ITEM_DETAILS  
									   where JOBNO=@JOBNO 
			   
			    if(@Tr_mode='Air')
				begin
						 insert into @temp_2
								select 
							         ROW_NUMBER() OVER(ORDER BY ANNEX_AIR_JOBNO DESC) 
									,ANNEX_AIR_MARKS_NOS
									,ANNEX_AIR_TOTAL_PACKAGES +  '/ ' + ANNEX_AIR_UNIT_CODE
									,ANNEX_AIR_GROSS_WEIGHT +' / ' + ANNEX_AIR_UNIT_CODE +@NewLineChar
									,+ANNEX_AIR_NET_WEIGHT
									,replace(Upper((select case when left(dbo.IndianCurrencyInWords(cast(ANNEX_AIR_TOTAL_PACKAGES as decimal(25,2))) , 4) =' and'          then  right( dbo.IndianCurrencyInWords(ANNEX_AIR_TOTAL_PACKAGES)  
              ,LEN( dbo.IndianCurrencyInWords(cast(ANNEX_AIR_TOTAL_PACKAGES as decimal(25,2)))) - 3)  else dbo.IndianCurrencyInWords(cast(ANNEX_AIR_TOTAL_PACKAGES as decimal(25,2))) end) ),'  ','') 
									
									 from EXPORT_ANNEXURE_C_AIR
									 WHERE ANNEX_AIR_JOBNO=@JOBNO
				end
				else if(@Tr_mode='Sea')
				begin
						insert into @temp_2
								 select 
							        ROW_NUMBER() OVER(ORDER BY ANNEX_SEA_JOBNO DESC) 
									,ANNEX_SEA_MARKS_NOS 
									,ANNEX_SEA_TOTAL_PACKAGES 
									
									,ANNEX_SEA_GROSS_WEIGHT +' / ' +ANNEX_SEA_UNIT_MEASUREMENT +@NewLineChar
									,+ ANNEX_SEA_NET_WEIGHT +'  / '+ANNEX_SEA_UNIT_MEASUREMENT
									,replace(Upper((select case when left(dbo.IndianCurrencyInWords(cast(ANNEX_SEA_TOTAL_PACKAGES as decimal(25,2))) , 4) =' and'          then  right( dbo.IndianCurrencyInWords(ANNEX_SEA_TOTAL_PACKAGES)  
              ,LEN( dbo.IndianCurrencyInWords(cast(ANNEX_SEA_TOTAL_PACKAGES as decimal(25,2)))) - 3)  else dbo.IndianCurrencyInWords(cast(ANNEX_SEA_TOTAL_PACKAGES as decimal(25,2))) end) ),'  ','') 
									
									
									 from EXPORT_ANNEXURE_C_SEA
									 WHERE ANNEX_SEA_JOBNO=@JOBNO
									 
				end	
				     select 
					        ROW_NUMBER() OVER(ORDER BY Mark_No DESC) as RowNumber
					     ,Mark_No as Mark_No
					       ,no_pkg
					       ,ITEM_DESCRIPTION as [desc]
					       ,gross_wgt + ' - '+ ' '+ Net_Weight as gross_wgt
					       ,InWords
					       --,gross_wgt + ' - '+ '   NET WT  '+ Net_Weight as gross_wgt
					          from @temp a
					               left join @temp_2 b
					               on a.Id=b.ID
					               
			/* ************************************ table 3 **************************************************** */
				
					
		    /* ************************************ table 4 **************************************************** */
				
				set @Mstatus=1
       end
       else 
       begin
				select 
						BL_ID
						,JOBNO
						,EXPORTER_NAME
						,ADDRESS1
						,ADDRESS2
						,ADDRESS3
						,ADDRESS4
						,ADDRESS5
						
						,CONSIGNEE_NAME
						,CONSIGNEE_ADD1
						,CONSIGNEE_ADD2
						,CONSIGNEE_ADD3
						,CONSIGNEE_ADD4
						
						,BUYER_NAME
						,BUYER_ADDRESS
						,BUYER_ADDRESS1
						,BUYER_ADDRESS2
						,BUYER_ADDRESS3
						,BUYER_ADDRESS4
						,INVOICE_NO
						
						,BL_NUMBER
						,SHIP_REF_NO
						,PLACE_OF_RECEIPT
						,OCEAN_VESSEL
						,PORT_OF_LOADING
						,FREIGHT_PAYABLE
						,PLACE_DATE
						,DATE_OF_RECEIPT
						,PLACE_OF_DELIVERY
						,PORT_DISCHARGE
						,NO_OF_ORGINAL_BL
						,AGENTS_NAEE_REFNO
						,FREIGHT_AMT
						
						,NOTIFY_1_1
						,NOTIFY_1_2
						,NOTIFY_1_3
						,NOTIFY_1_4
						,NOTIFY_1_5
						,INVOICE_NO
						,SB_NO
						,IEC_NO
						,HSS_CODE_NO
						,LC_NO
						,TOTALVOLUME
						,ORDER_NO
						,FREIGHT_PRE_COL
						,CONTAINER_Y_N
						,PENDING_Y_N
						--,(case when convert(varchar(10),JOB_DATE,103)='01/01/1900' then null else convert(varchar(10),JOB_DATE,103) end ) as JOB_DATE
						,convert(varchar,JOB_DATE,103)as JOB_DATE
						,TOT_VOL_UNIT
						,COMMODITY
						,TOT_PKGS_UNIT
						
						from  EXPORT_BL_GENERATION where JOBNO=@JOBNO 
						
				select 
						 ROW_NUMBER() OVER(ORDER BY JOBNO DESC) AS RowNumber
						 ,MARKS_NUMBERS as Mark_No
						 ,NO_OF_PKG as no_pkg
						 ,GOODS_DESC as [desc]
						 ,GROSS_WEIGHT as gross_wgt
				from EXPORT_BL_GENERATION_ITEMS where JOBNO=@JOBNO 
				
				set @Mstatus=2
       end
       
       end
end

else if(@Ename='Check_JobNo')
begin

if(@Working_Period<>'')
begin
 if not exists(SELECT JOBNO  FROM EXPORT_BL_GENERATION where JOBNO=@JOBNO and BRANCHCODE=@Working_Period)
 begin
 
   set @Mstatus=1
 end
   else
   
  begin
      set @Mstatus=2
  end 
end

if(@Working_Period='')
begin
  if not exists(SELECT JOBNO  FROM EXPORT_BL_GENERATION where JOBNO=@JOBNO )
 begin
   set @Mstatus=1
 end
   else
   
  begin
      set @Mstatus=2
  end 
end

end




else if(@Ename='select_BL_Details_Grid')
begin
if(@Working_Period<>'')
begin

select (case when convert(varchar(10),JOB_DATE,103)='01/01/1900' then null else convert(varchar(10),JOB_DATE,103) end ) as JOB_DATE,
(case when convert(varchar(10),DBN_DATE,103)='01/01/1900' then null else convert(varchar(10),DBN_DATE,103) end ) as DBN_DATE,* from EXPORT_BL_GENERATION where BL_ID=@BL_ID and BRANCHCODE=@Working_Period

  select
  JOBNO ,
  BL_ID
  
		,EXPORTER_NAME
       ,IEC_NO
       ,CONSIGNEE_NAME
       ,BUYER_NAME
       ,PORT_OF_LOADING
       ,PORT_DISCHARGE
       ,PLACE_OF_DELIVERY
       ,INVOICE_NO 
       from EXPORT_BL_GENERATION where BRANCHCODE=@Working_Period order by JOBNO desc
       
       select 
						 ROW_NUMBER() OVER(ORDER BY JOBNO DESC) AS RowNumber
						 ,MARKS_NUMBERS as Mark_No
						 ,NO_OF_PKG as no_pkg
						 ,GOODS_DESC as [desc]
						 ,GROSS_WEIGHT as gross_wgt
				from EXPORT_BL_GENERATION_ITEMS where JOBNO=@JOBNO and BRANCHCODE=@Working_Period
       
       set @Mstatus=2
end

if(@Working_Period='')
begin

select (case when convert(varchar(10),JOB_DATE,103)='01/01/1900' then null else convert(varchar(10),JOB_DATE,103) end ) as JOB_DATE,
(case when convert(varchar(10),DBN_DATE,103)='01/01/1900' then null else convert(varchar(10),DBN_DATE,103) end ) as DBN_DATE,* from EXPORT_BL_GENERATION where BL_ID=@BL_ID 

select 
		JOBNO
		,BL_ID
		,EXPORTER_NAME
       ,IEC_NO
       ,CONSIGNEE_NAME
       ,BUYER_NAME
       ,PORT_OF_LOADING
       ,PORT_DISCHARGE
       ,PLACE_OF_DELIVERY
       ,INVOICE_NO 
       from EXPORT_BL_GENERATION  order by JOBNO desc
       
       select 
						 ROW_NUMBER() OVER(ORDER BY JOBNO DESC) AS RowNumber
						 ,MARKS_NUMBERS as Mark_No
						 ,NO_OF_PKG as no_pkg
						 ,GOODS_DESC as [desc]
						 ,GROSS_WEIGHT as gross_wgt
				from EXPORT_BL_GENERATION_ITEMS where JOBNO=@JOBNO 
       
       set @Mstatus=2
end
end



else if(@Ename='Get_Except_FileRefNo')
begin

      
if(@Working_Period<>'')
begin

select FILE_REF_NO from EXPORT_GENERAL_DETAILS where BRANCHCODE=@Working_Period and FILE_REF_NO<>'' and EXPORTER_NAME=@ExporterName

              except(select FILE_REF_NO from EXPORT_BL_GENERATION)
              except(
              select item from dbo.fnSplit(
												 (
											SELECT  STUFF(  
													   ( SELECT  ', ' +CAST( E.FILE_REF_NO as varchar(max))   
											                 
														FROM  EXPORT_MULTIPLE_BL_GENERATION AS E   where BRANCHCODE=@Working_Period
													   FOR XML PATH(''))  
														, 1, 2, '')    
														AS [Marks_No]
														 )
													  , ',') 
												)
 
select distinct(EXPORTER_NAME) from EXPORT_BL_GENERATION where BRANCHCODE=@Working_Period
 
 
 set @Mstatus=1
end

if(@Working_Period='')
begin

select FILE_REF_NO from EXPORT_GENERAL_DETAILS where   FILE_REF_NO<>'' and EXPORTER_NAME=@ExporterName
              except(select FILE_REF_NO from EXPORT_BL_GENERATION)
              except(
              select item from dbo.fnSplit(
												 (
											SELECT  STUFF(  
													   ( SELECT  ', ' +CAST( E.FILE_REF_NO as varchar(max))   
											                 
														FROM  EXPORT_MULTIPLE_BL_GENERATION AS E  
													   FOR XML PATH(''))  
														, 1, 2, '')    
														AS [Marks_No]
														 )
													  , ',') 
												)
              
select distinct(EXPORTER_NAME) from EXPORT_BL_GENERATION
 
 
 set @Mstatus=1
end

end




else if(@Ename='Get_Except_JobNo')
begin

      
if(@Working_Period<>'')
begin

     
SELECT JOBNO  FROM EXPORT_GENERAL_DETAILS
              where BRANCHCODE=@Working_Period 
              and JOBNO not in( select JOBNO from EXPORT_BL_GENERATION   where BRANCHCODE=@Working_Period )
              and JOBNO not in(
               select item from dbo.fnSplit(
												 (
											SELECT  STUFF(  
													   ( SELECT  ', ' +CAST( E.JOBNO as varchar(max))   
											                 
														FROM  EXPORT_MULTIPLE_BL_GENERATION AS E   where BRANCHCODE=@Working_Period
													   FOR XML PATH(''))  
														, 1, 2, '')    
														AS [Marks_No]
														 )
													  , ',') 
              )order by JOBNO desc
 
select distinct(EXPORTER_NAME) from EXPORT_BL_GENERATION where BRANCHCODE=@Working_Period
 
 
 set @Mstatus=1
end

if(@Working_Period='')
begin

 SELECT JOBNO  FROM EXPORT_GENERAL_DETAILS

              WHERE JOBNO not in( select JOBNO from EXPORT_BL_GENERATION  )
              and JOBNO not in(
               select item from dbo.fnSplit(
												 (
											SELECT  STUFF(  
													   ( SELECT  ', ' +CAST( E.JOBNO as varchar(max))   
											                 
														FROM  EXPORT_MULTIPLE_BL_GENERATION AS E 
													   FOR XML PATH(''))  
														, 1, 2, '')    
														AS [Marks_No]
														 )
													  , ',') 
              )order by JOBNO desc
              
select distinct(EXPORTER_NAME) from EXPORT_BL_GENERATION
 
 
 set @Mstatus=1
end

end

ELSE IF(@Ename='GET_JOBNO_from_FILE_REF_NO')
BEGIN
  if(@Working_Period<>'')
begin
   select JOBNO from EXPORT_GENERAL_DETAILS where FILE_REF_NO=@JOBNO and BRANCHCODE=@Working_Period
   set @Mstatus=1
end

if(@Working_Period='')
begin
   select JOBNO from EXPORT_GENERAL_DETAILS where FILE_REF_NO=@JOBNO
   set @Mstatus=1
end
   
END

else if(@Ename='Get_DbNo_ID')
begin

 if(@Working_Period<>'')
	begin

			WITH T(DBN_NO)
			 AS (SELECT 
						MAX(SUBSTRING(DBN_NO,15,5))
				 FROM   EXPORT_BL_GENERATION where BRANCHCODE=@Working_Period
				 GROUP  BY DBN_NO
				 UNION ALL
				 SELECT 
						MAX(SUBSTRING(DBN_NO,15,5))
				 FROM   EXPORT_MULTIPLE_BL_GENERATION where BRANCHCODE=@Working_Period
				 GROUP  BY DBN_NO)
		SELECT 
		       (isnull(max(isnull(DBN_NO,0)),0)+1 )AS DBN_SLNO
			   --MAX(DBN_NO)+1 AS DBN_SLNO
		FROM   T
			set @Mstatus=1
		end

	else
	begin
			WITH T(DBN_NO)
			 AS (SELECT 
						MAX(SUBSTRING(DBN_NO,15,5))
				 FROM   EXPORT_BL_GENERATION 
				 GROUP  BY DBN_NO
				 UNION ALL
				 SELECT 
						MAX(SUBSTRING(DBN_NO,15,5))
				 FROM   EXPORT_MULTIPLE_BL_GENERATION 
				 GROUP  BY DBN_NO)
		SELECT 
		      (isnull(max(isnull(DBN_NO,0)),0)+1 )AS DBN_SLNO
			   --MAX(DBN_NO)+1 AS DBN_SLNO
		FROM   T
			set @Mstatus=1
		end
end


else if(@Ename='Total_BillAmt_Num_to_Words')
begin
 
 
  if(@Working_Period<>'')
	begin
		SET  @Currency =( SELECT GRAND_TOTAL FROM EXPORT_BL_GENERATION WHERE JOBNO=@JOBNO and BRANCHCODE=@Working_Period)
		set @Roundamt= ROUND(isnull((Convert(NUMERIC(25,2),CASE  WHEN ISNULL(@Currency,'') =''  THEN   '0' else ISNULL(@Currency,'0') end)),0),0)
		select Upper((select case when left(dbo.IndianCurrencyInWords(cast(@Roundamt as decimal(25,2))) , 4) =' and'  then  right( dbo.IndianCurrencyInWords(@Roundamt),LEN( dbo.IndianCurrencyInWords(cast(@Roundamt as decimal(25,2)))) - 3)  else dbo.IndianCurrencyInWords(cast(@Roundamt as decimal(25,2))) end)+' ONLY.' ) WORDS
		--select dbo.[IndianCurrencyInWords](@Currency)as WORDS
		set @Mstatus=1 
    end
  else
  begin
    SET  @Currency =( SELECT GRAND_TOTAL FROM EXPORT_BL_GENERATION WHERE JOBNO=@JOBNO)
    set @Roundamt= ROUND(isnull((Convert(NUMERIC(25,2),CASE  WHEN ISNULL(@Currency,'') =''  THEN   '0' else ISNULL(@Currency,'0') end)),0),0)
		select Upper((select case when left(dbo.IndianCurrencyInWords(cast(@Roundamt as decimal(25,2))) , 4) =' and'  then  right( dbo.IndianCurrencyInWords(@Roundamt),LEN( dbo.IndianCurrencyInWords(cast(@Roundamt as decimal(25,2)))) - 3)  else dbo.IndianCurrencyInWords(cast(@Roundamt as decimal(25,2))) end)+' ONLY.' ) WORDS
    --select dbo.[IndianCurrencyInWords](@Currency) as WORDS
    set @Mstatus=1
  end
  
   
end


commit
end try
begin catch
rollback transaction
	set @ErrorMsg=error_message()
	set @MStatus=0
end catch

