											   BRANCHCODE,        
											   WORKINGPERIOD 
											       
											  )         
												(SELECT 
											  ROW_NUMBER() OVER (ORDER BY Mark_No)+ @ITEM_ID,
										      [Mark_No] ,        
											  [no_pkg],        
											  [desc],        
											  [gross_wgt],        
											  [JOBNO],        
											  [USERID], 
											  GETDATE(),       
											  [BRANCHCODE],        
											  [WORKINGPERIOD] 
											
											         
											  FROM @stagingTable)       
														                
						 EXEC sp_xml_removedocument @xmlHandle 
	
					SET @Mstatus=2							  
												  
end


else if(@flag='Check_JobNo')
begin

if(@BRANCHCODE<>'')
begin
 if not exists(SELECT JOBNO  FROM EXPORT_BL_GENERATION where JOBNO=@JOBNO and BRANCHCODE=@BRANCHCODE)
 begin
   set @Mstatus=1
 end
   else
   
  begin
      set @Mstatus=2
  end 
end

if(@BRANCHCODE='')
begin
  if not exists(SELECT JOBNO  FROM EXPORT_BL_GENERATION where JOBNO=@JOBNO )
 begin
   set @Mstatus=1
 end
   else
   
  begin
      set @Mstatus=2
  end 
end

end
                  
---------------------------------------------------------------------------------------------------------------------------------------------------    
commit                  
 End try                   
                     
begin catch                    
rollback transaction            
 set @ErrorMsg=error_message()                    
 --set @MStatus=0                    
end catch

