			,GROSS_WEIGHT  
         from EXPORT_BL_GENERATION_ITEMS where JOBNO=@jobno and BRANCHCODE=@Branch_Code  
         
         
         
     select 
ROW_NUMBER() OVER (ORDER BY ITEM_ID) as RowNumber,
CONTAINER_NO +' / '+SEAL_NO + @NewLineChar+
case when TOTAL_PKGS=''  then TOTAL_PKGS else TOTAL_PKGS+substring(UNIT_CODE,4,25) end 
+ '  '+GROSS_WEIGHT +' '+ WGT_UNIT_CODE + @NewLineChar
+'' +TYPE as CONTAINER_NO

,CONTAINER_NO as CONTAINER_NO_ONLY
,TYPE 

from EXPORT_BL_GENERATION_CONTAINER where JOBNO=@JOBNO and BRANCHCODE=@Branch_Code 
         
         SET @Mstatus=1
           
           
