    + ' ' + BUYER_ADDRESS2 + ' ' + BUYER_ADDRESS3  + @NewLineChar
    + ' ' + BUYER_ADDRESS4  as BUYER_ADDRESS
    
    ,BL_NUMBER  
    ,SHIP_REF_NO  
    ,PLACE_OF_RECEIPT  
    ,OCEAN_VESSEL  
    ,PORT_OF_LOADING  
    ,FREIGHT_PAYABLE  
    ,PLACE_DATE  
    ,DATE_OF_RECEIPT  
    ,PLACE_OF_DELIVERY  
    ,PORT_DISCHARGE  
    ,NO_OF_ORGINAL_BL  
    ,AGENTS_NAEE_REFNO  
    ,FREIGHT_AMT  
    
    ,NOTIFY_1_1
						,NOTIFY_1_2
						,NOTIFY_1_3
						,NOTIFY_1_4
						,NOTIFY_1_5
						,INVOICE_NO
						,SB_NO
						,IEC_NO
						,HSS_CODE_NO
						,LC_NO
						,TOTALVOLUME
						,ORDER_NO
						,FREIGHT_PRE_COL
						--,convert(varchar,JOB_DATE,103) JOB_DATE
						,(case when convert(varchar(10),JOB_DATE,103)='01/01/1900' then null else convert(varchar(10),JOB_DATE,103) end ) as JOB_DATE
						,TOT_VOL_UNIT
						,substring(TOT_PKGS_UNIT,5,20) as TOT_PKGS_UNIT
						,VOYAGE
						,CURRENCY
						,EX_RATE
						,NO_OF_CONTAINERS
						,PERCENTAGE
						--,TOTAL_BILLAMT
						,isnull((Convert(NUMERIC(25,2),CASE  WHEN ISNULL(TOTAL_BILLAMT,'') =''  THEN   '0' else ISNULL(TOTAL_BILLAMT,'0') end)),0) as TOTAL_BILLAMT
						,SHIPMENT_TYPE
						,DBN_NO
						,(case when convert(varchar(10),DBN_DATE,103)='01/01/1900' then null else convert(varchar(10),DBN_DATE,103) end ) as DBN_DATE
						--,convert(varchar,DBN_DATE,103) DBN_DATE
                    ,RPT_TYPE
                    ,FILE_REF_NO
                    ,TAX_LEDGER_1
                    ,TAX_LEDGER_2
                    ,TAX_LEDGER_3
                    ,LEDGER_1_TAX
                    ,isnull((Convert(NUMERIC(25,2),CASE  WHEN ISNULL(LEDGER_1_TAX_AMT,'') =''  THEN   '0' else ISNULL(LEDGER_1_TAX_AMT,'0') end)),0) as LEDGER_1_TAX_AMT
                    ,LEDGER_2_TAX
                    ,isnull((Convert(NUMERIC(25,2),CASE  WHEN ISNULL(LEDGER_2_TAX_AMT,'') =''  THEN   '0' else ISNULL(LEDGER_2_TAX_AMT,'0') end)),0) as LEDGER_2_TAX_AMT
					,LEDGER_3_TAX
					,isnull((Convert(NUMERIC(25,2),CASE  WHEN ISNULL(LEDGER_3_TAX_AMT,'') =''  THEN   '0' else ISNULL(LEDGER_3_TAX_AMT,'0') end)),0) as LEDGER_3_TAX_AMT
					,ROUND(isnull((Convert(NUMERIC(25,2),CASE  WHEN ISNULL(GRAND_TOTAL,'') =''  THEN   '0' else ISNULL(GRAND_TOTAL,'0') end)),0),0) as GRAND_TOTAL	
					,HSN_CODE
					,FREIGHT_CHARGES
					,PKGS_WORDS
            from EXPORT_BL_GENERATION where JOBNO=@jobno   
            
   select   
        
      MARKS_NUMBERS  
     ,NO_OF_PKG  
     ,GOODS_DESC  
     ,GROSS_WEIGHT  
    from EXPORT_BL_GENERATION_ITEMS where JOBNO=@jobno 
    
    
       select 
ROW_NUMBER() OVER (ORDER BY ITEM_ID) as RowNumber,
CONTAINER_NO +' / '+SEAL_NO + @NewLineChar+
case when TOTAL_PKGS=''  then TOTAL_PKGS else TOTAL_PKGS+substring(UNIT_CODE,4,25) end 
+ '  '+GROSS_WEIGHT +' '+ WGT_UNIT_CODE + @NewLineChar
+'' +TYPE as CONTAINER_NO

,CONTAINER_NO as CONTAINER_NO_ONLY
,TYPE 

from EXPORT_BL_GENERATION_CONTAINER where JOBNO=@JOBNO 
   
       end  
       
       SET @Mstatus=1
