begin      
  if(@from_date <>'' and @to_date <>'')      
  begin     
  set @jobdate_cond= ' cast(convert(varchar,LOGIN_DATE,101)as datetime) between cast(''' + @from_date + ''' as datetime) and cast(''' + @to_date + ''' as datetime)'      
       set @jobdate=@from_date    
  end      
         else      
         begin      
             if(@from_date <>'')      
             begin      
                     
                 set @jobdate_cond=' cast(convert(varchar,LOGIN_DATE,101)as datetime) between cast(''' + @from_date + ''' as datetime) and getdate()'      
        set @jobdate=@from_date    
            
             end      
             if(@to_date <>'')      
             begin      
     set @jobdate_cond=' cast(CONVERT(varchar,LOGIN_DATE,101)as datetime)=cast(''' + @to_date + ''' as datetime)'      
                 set @jobdate=@to_date            
             end      
         end      
